DG.put("krisnaavtaar/60",{"n":60,"title":"ਅਥ ਖੜਗ ਸਿੰਘ ਜੁਧ ਕਥਨੰ","title_roman":"Ath kharag singh judh kathnan","page":553,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":553},{"type":"verse","number":[1370],"number_text":"੧੩੭੦।","page":553,"lines":[{"gurmukhi":"ਤਿਹ ਭੂਪਤਿ ਕੋ ਮਿਤ੍ਰ ਇਕ ਖੜਗ ਸਿੰਘ ਤਿਹ ਨਾਮ।","roman":"Tih bhoopti ko mitr ik kharag singh tih naam |","meaning_en":"","page":553},{"gurmukhi":"ਪੈਰੇ ਸਮਰ ਸਮੁਦ੍ਰ ਬਹੁ ਮਹਾ ਰਥੀ ਬਲ ਧਾਮ। ੧੩੭੦।","roman":"Paire samar samudr bahu mahaa rathee bal dhaam | 1370 |","meaning_en":"","page":553}]},{"type":"verse","number":[1371],"number_text":"੧੩੭੧।","page":554,"lines":[{"gurmukhi":"ਕ੍ਰੁਧਤ ਹ੍ਵੈ ਅਤਿ ਮਨ ਬਿਖੈ ਚਾਰ ਭੂਪ ਤਿਹ ਸਾਥ।","roman":"Krudhat hvai ati man bikhai chaar bhoop tih saath |","meaning_en":"","page":554,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਜੁਧੁ ਕਰਨਿ ਹਰਿ ਸਿਉ ਚਲਿਯੋ ਅਮਿਤ ਸੈਨ ਲੈ ਸਾਥ। ੧੩੭੧।","roman":"Judhu karni hari siu chaliyo amit sain lai saath | 1371 |","meaning_en":"","page":554}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":554},{"type":"verse","number":[1372],"number_text":"੧੩੭੨।","page":554,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਬਰ ਸਿੰਘ ਅਉਰ ਨ੍ਰਿਪ ਗਵਨ ਸਿੰਘ ਬਰ।","roman":"Kharag singh bar singh aur nrip gavan singh bar |","meaning_en":"","page":554},{"gurmukhi":"ਧਰਮ ਸਿੰਘ ਭਵ ਸਿੰਘ ਬਡੇ ਬਲਵੰਤ ਜੁਧੁ ਕਰ।","roman":"Dharam singh bhav singh bade balvant judhu kar |","meaning_en":"","page":554},{"gurmukhi":"ਰਥ ਅਨੇਕ ਸੰਗ ਲੀਏ ਸੁਭਟ ਬਹੁ ਬਾਜਤ ਸਜਤ।","roman":"Rath anek sang lee'e subhat bahu baajat sajat |","meaning_en":"","page":554},{"gurmukhi":"ਦਸ ਹਜਾਰ ਗਜ ਮਤ ਚਲੇ ਘਨੀਅਰ ਜਿਮ ਗਜਤ।","roman":"Das hajaar gaj mat chale ghaneear jim gajat |","meaning_en":"","page":554},{"gurmukhi":"ਮਿਲਿ ਘੇਰਿ ਲੀਓ ਤਿਨ ਕਉ ਤਿਨੋ ਸੁ ਕਬਿ ਸ੍ਯਾਮ ਜਸੁ ਲਖਿ ਲੀਯੋ।","roman":"Mili gheri leeo tin kau tino su kabi syaam jasu lakhi leeyo |","meaning_en":"","page":554},{"gurmukhi":"ਰਿਤੁ ਪਾਵਸ ਮੈ ਘਨ ਘਟਾ ਜਿਉ ਘੋਰ ਮਨੋ ਨਰ ਬੋਲੀਓ। ੧੩੭੨।","roman":"Ritu paavas mai ghan ghataa jiu ghor mano nar boleeo | 1372 |","meaning_en":"","page":554}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":554},{"type":"verse","number":[1373],"number_text":"੧੩੭੩।","page":554,"lines":[{"gurmukhi":"ਜਾਦਵ ਕੀ ਸੈਨਾ ਹੁਤੇ ਨਿਕਸੇ ਭੂਪ ਸੁ ਚਾਰ।","roman":"Jaadav kee sainaa hute nikse bhoop su chaar |","meaning_en":"","page":554},{"gurmukhi":"ਨਾਮ ਸਰਸ ਸਿੰਘ ਬੀਰ ਸਿੰਘ ਮਹਾ ਸਿੰਘ ਸਿੰਘ ਸਾਰ। ੧੩੭੩।","roman":"Naam saras singh beer singh mahaa singh singh saar | 1373 |","meaning_en":"","page":554}]},{"type":"verse","number":[1374],"number_text":"੧੩੭੪।","page":554,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਕੇ ਸੰਗ ਨ੍ਰਿਪ ਚਾਰਿ ਚਾਰੁ ਮਤਿ ਵੰਤ।","roman":"Kharag singh ke sang nrip chaari chaaru mati vant |","meaning_en":"","page":554},{"gurmukhi":"ਹਰਿ ਕੀ ਓਰ ਚਲੇ ਮਨੋ ਆਯੋ ਇਨ ਕੋ ਅੰਤੁ। ੧੩੭੪।","roman":"Hari kee or chale mano aayo in ko antu | 1374 |","meaning_en":"","page":554}]},{"type":"verse","number":[1375],"number_text":"੧੩੭੫।","page":554,"lines":[{"gurmukhi":"ਸਰਸ ਮਹਾ ਅਉ ਸਾਰ ਪੁਨਿ ਬੀਰ ਸਿੰਘ ਏ ਚਾਰ।","roman":"Saras mahaa au saar puni beer singh e chaar |","meaning_en":"","page":554},{"gurmukhi":"ਜਾਦਵ ਸੈਨਾ ਤੇ ਤਬੈ ਨਿਕਸੇ ਅਤਿ ਬਲੁ ਧਾਰਿ। ੧੩੭੫।","roman":"Jaadav sainaa te tabai nikse ati balu dhaari | 1375 |","meaning_en":"","page":554}]},{"type":"verse","number":[1376],"number_text":"੧੩੭੬।","page":554,"lines":[{"gurmukhi":"ਹਰਿ ਕੀ ਦਿਸ ਕੇ ਚਤੁਰ ਨ੍ਰਿਪ ਤਿਨ ਵਹ ਲੀਨੇ ਮਾਰਿ।","roman":"Hari kee dis ke chatur nrip tin vah leene maari |","meaning_en":"","page":554},{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਅਤਿ ਕੋਪ ਕਰਿ ਦੀਨੋ ਇਨਹ ਸੰਘਾਰਿ। ੧੩੭੬।","roman":"Kharag singh ati kop kari deeno inah sanghaari | 1376 |","meaning_en":"","page":554}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":554},{"type":"verse","number":[1377],"number_text":"੧੩੭੭।","page":554,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਓਰ ਤੇ ਅਉਰ ਨਰੇਸ ਚਲੇ ਤਿਨ ਸੰਗਿ ਮਹਾ ਦਲੁ ਲੀਨੋ।","roman":"Sree hari or te aur nares chale tin sangi mahaa dalu leeno |","meaning_en":"","page":554},{"gurmukhi":"ਸੂਰਤ ਸਿੰਘ ਸਪੂਰਨ ਸਿੰਘ ਚਲਿਯੋ ਬਰਸਿੰਘ ਸੁ ਕੋਪ ਪ੍ਰਬੀਨੋ।","roman":"Soorat singh sapooran singh chaliyo barsingh su kop prabeeno |","meaning_en":"","page":554},{"gurmukhi":"ਅਉ ਮਤਿ ਸਿੰਘ ਸਜਿਯੋ ਤਨ ਕਉਚ ਸੂ ਸਸਤ੍ਰਨ ਅਸਤ੍ਰਨ ਮਾਝਿ ਪ੍ਰਬੀਨੋ।","roman":"Au mati singh sajiyo tan kauch soo sastran astran maajhi prabeeno |","meaning_en":"","page":554},{"gurmukhi":"ਧਾਇ ਕੈ ਸ੍ਰੀ ਖੜਗੇਸ ਕੇ ਸੰਗਿ ਜੁ ਚਾਰ ਹੀ ਭੂਪਨ ਆਹਵ ਕੀਨੋ। ੧੩੭੭।","roman":"Dhaai kai sree kharges ke sangi ju chaar hee bhoopan aahav keeno | 1377 |","meaning_en":"","page":554}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":554},{"type":"verse","number":[1378],"number_text":"੧੩੭੮।","page":554,"lines":[{"gurmukhi":"ਇਤ ਚਾਰੋ ਭੂਪਤਿ ਲਰੈ ਖੜਗ ਸਿੰਘ ਕੇ ਸੰਗਿ।","roman":"It chaaro bhoopti larai kharag singh ke sangi |","meaning_en":"","page":554},{"gurmukhi":"ਉਤ ਦੋਊ ਦਿਸ ਕੀ ਲਰਤ ਸਬਲ ਸੈਨ ਚਤੁਰੰਗਿ। ੧੩੭੮।","roman":"Ut do'oo dis kee larat sabal sain chaturangi | 1378 |","meaning_en":"","page":554}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":554},{"type":"verse","number":[1379],"number_text":"੧੩੭੯।","page":554,"lines":[{"gurmukhi":"ਰਥੀ ਸੰਗਿ ਰਥੀ ਮਹਾਰਥੀ ਸੰਗਿ ਮਹਾਰਥੀ","roman":"Rathee sangi rathee mahaarthee sangi mahaarthee","meaning_en":"","page":554},{"gurmukhi":"ਸੁਵਾਰ ਸਿਉ ਸੁਵਾਰ ਅਤਿ ਕੋਪ ਕੈ ਕੈ ਮਨ ਮੈ।","roman":"Suvaar siu suvaar ati kop kai kai man mai |","meaning_en":"","page":554},{"gurmukhi":"ਪੈਦਲ ਸਿਉ ਪੈਦਲ ਲਰਤ ਭਏ ਰਨ ਬੀਚ","roman":"Paidal siu paidal larat bhae ran beech","meaning_en":"","page":554},{"gurmukhi":"ਜੁਧ ਹੀ ਮੈ ਰਾਖਿਓ ਮਨ ਰਾਖਿਓ ਨ ਗ੍ਰਿਹਨ ਮੈ।","roman":"Judh hee mai raakhio man raakhio na grihan mai |","meaning_en":"","page":554},{"gurmukhi":"ਸੈਥੀ ਜਮਧਾਰ ਤਰਵਾਰੈ ਘਨੀ ਸ੍ਯਾਮ ਕਹੈ","roman":"Saithee jamdhaar tarvaarai ghanee syaam kahai","meaning_en":"","page":555},{"gurmukhi":"ਮੁਸਲੀ ਤ੍ਰਿਸੂਲ ਬਾਨ ਚਲੇ ਤਾ ਹੀ ਛਿਨ ਮੈ।","roman":"Muslee trisool baan chale taa hee chhin mai |","meaning_en":"","page":555},{"gurmukhi":"ਦੰਤਨ ਸਿਉ ਦੰਤੀ ਪੈ ਬਜੰਤ੍ਰਨ ਸਿਉ ਬਜੰਤ੍ਰੀ ਲਰਿਓ","roman":"Dantan siu dantee pai bajantran siu bajantree lario","meaning_en":"","page":555},{"gurmukhi":"ਚਾਰਨ ਸਿਉ ਚਾਰਨ ਭਿਰਿਓ ਹੈ ਤਾਹੀ ਰਨ ਮੈ। ੧੩੭੯।","roman":"Chaaran siu chaaran bhirio hai taahee ran mai | 1379 |","meaning_en":"","page":555}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":555},{"type":"verse","number":[1380],"number_text":"੧੩੮੦।","page":555,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਸਰ ਸਿੰਘ ਹਤਿਓ ਰਿਸ ਕੈ ਮਹਾ ਸਿੰਘਹਿ ਮਾਰਿ ਲਇਓ ਜਬ ਹੀ।","roman":"Bahuro sar singh hatio ris kai mahaa singhhi maari laio jab hee |","meaning_en":"","page":555},{"gurmukhi":"ਪੁਨਿ ਸੂਰਤਿ ਸਿੰਘ ਸਪੂਰਨ ਸਿੰਘ ਸੁ ਸੁੰਦਰ ਸਿੰਘ ਹਨਿਓ ਤਬ ਹੀ।","roman":"Puni soorti singh sapooran singh su sundar singh hanio tab hee |","meaning_en":"","page":555},{"gurmukhi":"ਬਰ ਸ੍ਰੀ ਮਤਿ ਸਿੰਘ ਕੋ ਸੀਸ ਕਟਿਓ ਲਖਿ ਜਾਦਵ ਸੈਨ ਗਈ ਦਬ ਹੀ।","roman":"Bar sree mati singh ko sees katio lakhi jaadav sain gaee dab hee |","meaning_en":"","page":555},{"gurmukhi":"ਨਭਿ ਮੈ ਗਨ ਕਿੰਨਰ ਸ੍ਰੀ ਖੜਗੇਸ ਕੀ ਕੀਰਤਿ ਗਾਵਤ ਹੈ ਸਬ ਹੀ। ੧੩੮੦।","roman":"Nabhi mai gan kinnar sree kharges kee keerti gaavat hai sab hee | 1380 |","meaning_en":"","page":555,"flags":[{"code":"ੰੰ","reason":"same sign typed twice; written once (prints as one)"}]}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":555},{"type":"verse","number":[1381],"number_text":"੧੩੮੧।","page":555,"lines":[{"gurmukhi":"ਛਿਅ ਭੂਪਨ ਕੋ ਛੈ ਕੀਯੋ ਖੜਗ ਸਿੰਘ ਬਲ ਧਾਮ।","roman":"Chhia bhoopan ko chhai keeyo kharag singh bal dhaam |","meaning_en":"","page":555},{"gurmukhi":"ਅਉਰੋ ਭੂਪਤਿ ਤੀਨ ਬਰ ਧਾਇ ਲਰੈ ਸੰਗ੍ਰਾਮ। ੧੩੮੧।","roman":"Auro bhoopti teen bar dhaai larai sangraam | 1381 |","meaning_en":"","page":555}]},{"type":"verse","number":[1382],"number_text":"੧੩੮੨।","page":555,"lines":[{"gurmukhi":"ਕਰਨ ਸਿੰਘ ਪੁਨਿ ਅਰਨ ਸੀ ਸਿੰਘ ਬਰਨ ਸੁਕੁਮਾਰ।","roman":"Karan singh puni aran see singh baran sukumaar |","meaning_en":"","page":555},{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਰੁਪਿ ਰਨਿ ਰਹਿਓ ਏ ਤੀਨੋ ਸੰਘਾਰਿ। ੧੩੮੨।","roman":"Kharag singh rupi rani rahio e teeno sanghaari | 1382 |","meaning_en":"","page":555}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":555},{"type":"verse","number":[1383],"number_text":"੧੩੮੩।","page":555,"lines":[{"gurmukhi":"ਮਾਰ ਕੈ ਭੂਪ ਬਡੇ ਰਨ ਮੈ ਰਿਸ ਕੈ ਬਹੁਰੋ ਧਨ ਬਾਨ ਲੀਯੋ।","roman":"Maar kai bhoop bade ran mai ris kai bahuro dhan baan leeyo |","meaning_en":"","page":555},{"gurmukhi":"ਸਿਰ ਕਾਟਿ ਦਏ ਬਹੁ ਸਤ੍ਰਨ ਕੇ ਕਰਿ ਅਤ੍ਰਨ ਲੈ ਪੁਨਿ ਜੁਧੁ ਕੀਯੋ।","roman":"Sir kaati dae bahu satran ke kari atran lai puni judhu keeyo |","meaning_en":"","page":555},{"gurmukhi":"ਜਿਮਿ ਰਾਵਨ ਸੈਨ ਹਤੀ ਨ੍ਰਿਪ ਰਾਘਵ ਤਿਉ ਦਲੁ ਮਾਰਿ ਬਿਦਾਰ ਦੀਯੋ।","roman":"Jimi raavan sain hatee nrip raaghav tiu dalu maari bidaar deeyo |","meaning_en":"","page":555},{"gurmukhi":"ਗਨ ਭੂਤ ਪਿਸਾਚ ਸ੍ਰਿੰਗਾਲਨ ਗੀਧਨ ਜੋਗਿਨ ਸ੍ਰਉਨ ਅਘਾਇ ਪੀਯੋ। ੧੩੮੩।","roman":"Gan bhoot pisaach sringaalan geedhan jogin sraun aghaai peeyo | 1383 |","meaning_en":"","page":555,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":555},{"type":"verse","number":[1384],"number_text":"੧੩੮੪।","page":555,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਕਰਿ ਖੜਗ ਲੈ ਰੁਦ੍ਰ ਰਸਹਿ ਅਨੁਰਾਗ।","roman":"Kharag singh kari kharag lai rudr rashi anuraag |","meaning_en":"","page":555},{"gurmukhi":"ਯੌ ਡੋਲਤ ਰਨਿ ਨਿਡਰ ਹੁਇ ਮਾਨੋ ਖੇਲਤ ਫਾਗੁ। ੧੩੮੪।","roman":"Yau dolat rani nidar hui maano khelat phaagu | 1384 |","meaning_en":"","page":555}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":555},{"type":"verse","number":[1385],"number_text":"੧੩੮੫।","page":555,"lines":[{"gurmukhi":"ਬਾਨ ਚਲੇ ਤੇਈ ਕੁੰਕਮ ਮਾਨਹੁ ਮੂਠ ਗੁਲਾਲ ਕੀ ਸਾਂਗ ਪ੍ਰਹਾਰੀ।","roman":"Baan chale te'ee kunkam maanhu mooth gulaal kee saang prahaaree |","meaning_en":"","page":555},{"gurmukhi":"ਢਾਲ ਮਨੋ ਡਫ ਮਾਲ ਬਨੀ ਹਥ ਨਾਲ ਬੰਦੂਕ ਛੁਟੇ ਪਿਚਕਾਰੀ।","roman":"Dhaal mano daph maal banee hath naal bandook chhute pichkaaree |","meaning_en":"","page":555},{"gurmukhi":"ਸ੍ਰਉਨ ਭਰੇ ਪਟ ਬੀਰਨ ਕੇ ਉਪਮਾ ਜਨੁ ਘੋਰ ਕੈ ਕੇਸਰ ਡਾਰੀ।","roman":"Sraun bhare pat beeran ke upmaa janu ghor kai kesar daaree |","meaning_en":"","page":555},{"gurmukhi":"ਖੇਲਤ ਫਾਗੁ ਕਿ ਬੀਰ ਲਰੈ ਨਵਲਾਸੀ ਲੀਏ ਕਰਵਾਰ ਕਟਾਰੀ। ੧੩੮੫।","roman":"Khelat phaagu ki beer larai navlaasee lee'e karvaar kataaree | 1385 |","meaning_en":"","page":555}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":556},{"type":"verse","number":[1386],"number_text":"੧੩੮੬।","page":556,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਅਤਿ ਲਰਤ ਹੈ ਰਸ ਰੁਦ੍ਰਹਿ ਅਨੁਰਾਗਿ।","roman":"Kharag singh ati larat hai ras rudrahi anuraagi |","meaning_en":"","page":556},{"gurmukhi":"ਰਨ ਚੰਚਲਤਾ ਬਹੁ ਕਰਤ ਜਨ ਨਟੂਆ ਬਡਭਾਗਿ। ੧੩੮੬।","roman":"Ran chanchaltaa bahu karat jan natooaa badbhaagi | 1386 |","meaning_en":"","page":556}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":556},{"type":"verse","number":[1387],"number_text":"੧੩੮੭।","page":556,"lines":[{"gurmukhi":"ਸਾਰਥੀ ਆਪਨੇ ਸੋ ਕਹਿ ਕੈ ਸੁ ਧਵਾਇ ਤਹੀ ਰਥ ਜੁਧੁ ਮਚਾਵੈ।","roman":"Saarthee aapne so kahi kai su dhavaai tahee rath judhu machaavai |","meaning_en":"","page":556},{"gurmukhi":"ਸਸਤ੍ਰ ਪ੍ਰਹਾਰਤ ਸੂਰਨ ਪੈ ਕਰਿ ਹਾਥਨ ਕੋ ਅਰਥਾਵ ਦਿਖਾਵੈ।","roman":"Sasatr prahaarat sooran pai kari haathan ko arthaav dikhaavai |","meaning_en":"","page":556},{"gurmukhi":"ਦੁੰਦਭਿ ਢੋਲ ਮ੍ਰਿਦੰਗ ਬਜੈ ਕਰਵਾਰ ਕਟਾਰਨ ਤਾਲ ਬਜਾਵੈ।","roman":"Dundbhi dhol mridang bajai karvaar kataaran taal bajaavai |","meaning_en":"","page":556},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਉਚਾਰ ਕਰੈ ਮੁਖਿ ਯੌ ਕਰਿ ਨ੍ਰਿਤ ਅਉ ਗਾਨ ਸੁਨਾਵੈ। ੧੩੮੭।","roman":"Maar hee maar uchaar karai mukhi yau kari nrit au gaan sunaavai | 1387 |","meaning_en":"","page":556}]},{"type":"verse","number":[1388],"number_text":"੧੩੮੮।","page":556,"lines":[{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਅਲਾਪ ਉਚਾਰਤ ਦੁੰਦਭਿ ਢੋਲ ਮ੍ਰਿਦੰਗ ਅਪਾਰਾ।","roman":"Maar hee maar alaap uchaarat dundbhi dhol mridang apaaraa |","meaning_en":"","page":556},{"gurmukhi":"ਸਤ੍ਰਨ ਕੇ ਸਿਰ ਅਤ੍ਰ ਤਰਾਕ ਲਗੈ ਤਿਹਿ ਤਾਲਨ ਕੋ ਠਨਕਾਰਾ।","roman":"Satran ke sir atr taraak lagai tihi taalan ko thankaaraa |","meaning_en":"","page":556},{"gurmukhi":"ਜੂਝਿ ਗਿਰੇ ਧਰਿ ਰੀਝ ਕੈ ਦੇਤ ਹੈ ਪ੍ਰਾਨਨ ਦਾਨ ਬਡੇ ਰਿਝਿਵਾਰਾ।","roman":"Joojhi gire dhari reejh kai det hai praanan daan bade rijhivaaraa |","meaning_en":"","page":556},{"gurmukhi":"ਨਿਰਤ ਕਰੈ ਨਟ ਕੋਪ ਲਰੈ ਭਟ ਜੁਧ ਕੀ ਠਉਰ ਕਿ ਨ੍ਰਿਤ ਅਖਾਰਾ। ੧੩੮੮।","roman":"Nirat karai nat kop larai bhat judh kee thaur ki nrit akhaaraa | 1388 |","meaning_en":"","page":556}]},{"type":"verse","number":[1389],"number_text":"੧੩੮੯।","page":556,"lines":[{"gurmukhi":"ਰਨ ਭੂਮਿ ਭਈ ਰੰਗ ਭੂਮਿ ਮਨੋ ਧੁਨਿ ਦੁੰਦਭਿ ਬਾਜੇ ਮ੍ਰਿਦੰਗ ਹੀਯੋ।","roman":"Ran bhoomi bhaee rang bhoomi mano dhuni dundbhi baaje mridang heeyo |","meaning_en":"","page":556},{"gurmukhi":"ਸਿਰ ਸਤ੍ਰਨ ਕੇ ਪਰ ਅਤ੍ਰ ਲਗੈ ਤਤਕਾਰ ਤਰਾਕਨਿ ਤਾਲ ਲੀਯੋ।","roman":"Sir satran ke par atr lagai tatkaar taraakni taal leeyo |","meaning_en":"","page":556},{"gurmukhi":"ਅਸਿ ਲਾਗਤ ਝੂਮਿ ਗਿਰੈ ਮਰਿ ਕੈ ਭਟ ਪ੍ਰਾਨਨ ਮਾਨਹੁ ਦਾਨ ਕੀਯੋ।","roman":"Asi laagat jhoomi girai mari kai bhat praanan maanhu daan keeyo |","meaning_en":"","page":556},{"gurmukhi":"ਬਰ ਨ੍ਰਿਤ ਕਰੈ ਕਿ ਲਰੈ ਨਟ ਜ੍ਯੋ ਨ੍ਰਿਪ ਮਾਰ ਹੀ ਮਾਰ ਸੁ ਰਾਗ ਕੀਯੋ। ੧੩੮੯।","roman":"Bar nrit karai ki larai nat jyo nrip maar hee maar su raag keeyo | 1389 |","meaning_en":"","page":556}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":556},{"type":"verse","number":[1390],"number_text":"੧੩੯੦।","page":556,"lines":[{"gurmukhi":"ਇਤੋ ਜੁਧ ਹਰਿ ਹੇਰਿ ਕੈ ਸਬਹਨਿ ਕਹਿਯੋ ਸੁਨਾਇ।","roman":"Ito judh hari heri kai sabahni kahiyo sunaai |","meaning_en":"","page":556},{"gurmukhi":"ਕੋ ਭਟ ਲਾਇਕ ਸੈਨ ਮੈ ਲਰੈ ਜੁ ਯਾ ਸੰਗਿ ਜਾਇ। ੧੩੯੦।","roman":"Ko bhat laaik sain mai larai ju yaa sangi jaai | 1390 |","meaning_en":"","page":556}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":556},{"type":"verse","number":[1391],"number_text":"੧੩੯੧।","page":556,"lines":[{"gurmukhi":"ਘਨ ਸਿੰਘ ਘਾਤ ਸਿੰਘ ਦੋਊ ਜੋਧੇ। ਜਾਤ ਨ ਕਿਸੀ ਸੁਭਟ ਤੇ ਸੋਧੇ।","roman":"Ghan singh ghaat singh do'oo jodhe | jaat na kisee subhat te sodhe |","meaning_en":"","page":556},{"gurmukhi":"ਘਨਸੁਰ ਸਿੰਘ ਘਮੰਡ ਸਿੰਘ ਧਾਏ। ਮਾਨਹੁ ਚਾਰੋ ਕਾਲ ਪਠਾਏ। ੧੩੯੧।","roman":"Ghansur singh ghamand singh dhaae | maanhu chaaro kaal pathaae | 1391 |","meaning_en":"","page":556}]},{"type":"verse","number":[1392],"number_text":"੧੩੯੨।","page":556,"lines":[{"gurmukhi":"ਤਬ ਤਿਹ ਤਕਿ ਚਹੂੰਅਨ ਸਰ ਮਾਰੇ। ਚਾਰੋ ਪ੍ਰਾਨ ਬਿਨਾ ਕਰਿ ਡਾਰੇ।","roman":"Tab tih taki chahoonan sar maare | chaaro praan binaa kari daare |","meaning_en":"","page":556},{"gurmukhi":"ਸ੍ਯੰਦਨ ਅਸ੍ਵ ਸੂਤ ਸਬ ਘਾਏ। ਸੈਨ ਸਹਿਤ ਜਮ ਲੋਕਿ ਪਠਾਏ। ੧੩੯੨।","roman":"Syandan asv soot sab ghaae | sain sahit jam loki pathaae | 1392 |","meaning_en":"","page":556}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":557},{"type":"verse","number":[1393],"number_text":"੧੩੯੩।","page":557,"lines":[{"gurmukhi":"ਚਪਲ ਸਿੰਘ ਅਰੁ ਚਤਰ ਸਿੰਘ ਚੰਚਲ ਸ੍ਰੀ ਬਲਵਾਨ।","roman":"Chapal singh aru chatar singh chanchal sree balvaan |","meaning_en":"","page":557},{"gurmukhi":"ਚਿਤ੍ਰ ਸਿੰਘ ਅਰ ਚਉਪ ਸਿੰਘ ਮਹਾ ਰਥੀ ਸੁਰ ਗ੍ਯਾਨ। ੧੩੯੩।","roman":"Chitr singh ar chaup singh mahaa rathee sur gyaan | 1393 |","meaning_en":"","page":557}]},{"type":"verse","number":[1394],"number_text":"੧੩੯੪।","page":557,"lines":[{"gurmukhi":"ਛਤ੍ਰ ਸਿੰਘ ਅਰੁ ਮਾਨ ਸਿੰਘ ਸਤ੍ਰ ਸਿੰਘ ਬਲਬੰਡ।","roman":"Chhatr singh aru maan singh satr singh balband |","meaning_en":"","page":557},{"gurmukhi":"ਸਿੰਘ ਚਮੂੰ ਪਤਿ ਅਤਿ ਬਲੀ ਭੁਜ ਬਲਿ ਤਾਹਿ ਅਖੰਡ। ੧੩੯੪।","roman":"Singh chamoon pati ati balee bhuj bali taahi akhand | 1394 |","meaning_en":"","page":557}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":557},{"type":"verse","number":[1395],"number_text":"੧੩੯੫।","page":557,"lines":[{"gurmukhi":"ਭੂਪ ਦਸੋ ਰਿਸਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਖੜਗੇਸ ਕੇ ਊਪਰ ਧਾਏ।","roman":"Bhoop daso risi kai kabi syaam kahai kharges ke oopar dhaae |","meaning_en":"","page":557},{"gurmukhi":"ਆਵਤ ਹੀ ਬਲਿ ਕੈ ਧਨੁ ਲੈ ਸੁ ਨਿਖੰਗਨ ਤੇ ਬਹੁ ਬਾਨ ਚਲਾਏ।","roman":"Aavat hee bali kai dhanu lai su nikhangan te bahu baan chalaae |","meaning_en":"","page":557},{"gurmukhi":"ਬਾਜ ਹਨੇ ਸਤਿ ਦੁਇ ਅਰੁ ਗੈ ਸਤਿ ਤ੍ਰੈ ਸਤਿ ਬੀਰ ਮਹਾ ਤਬ ਘਾਏ।","roman":"Baaj hane sati dui aru gai sati trai sati beer mahaa tab ghaae |","meaning_en":"","page":557},{"gurmukhi":"ਬੀਸ ਰਥੀ ਅਉ ਮਹਾਰਥਿ ਤੀਸ ਅਯੋਧਨ ਮੈ ਜਮਲੋਕਿ ਪਠਾਏ। ੧੩੯੫।","roman":"Bees rathee au mahaarthi tees ayodhan mai jamloki pathaae | 1395 |","meaning_en":"","page":557}]},{"type":"verse","number":[1396],"number_text":"੧੩੯੬।","page":557,"lines":[{"gurmukhi":"ਪੁਨਿ ਧਾਇ ਹਨੇ ਸਤਿ ਗੈ ਹਯ ਦੁਇ ਸਤਿ ਅਯੁਤ ਪਦਾਤ ਹਨੇ ਰਨ ਮੈ।","roman":"Puni dhaai hane sati gai hay dui sati ayut padaat hane ran mai |","meaning_en":"","page":557},{"gurmukhi":"ਸੁ ਮਹਾਰਥੀ ਅਉਰ ਪਚਾਸ ਹਨੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਸੁ ਤਹੀ ਛਿਨ ਮੈ।","roman":"Su mahaarthee aur pachaas hane kabi syaam kahai su tahee chhin mai |","meaning_en":"","page":557},{"gurmukhi":"ਦਸ ਹੂੰ ਨ੍ਰਿਪ ਕੀ ਬਹੁ ਸੈਨ ਭਜੀ ਲਖਿ ਜਿਉ ਮ੍ਰਿਗ ਕੇਹਰਿ ਕਉ ਬਨ ਮੈ।","roman":"Das hoon nrip kee bahu sain bhajee lakhi jiu mrig kehri kau ban mai |","meaning_en":"","page":557},{"gurmukhi":"ਤਿਹ ਸੰਘਰ ਮੈ ਖੜਗੇਸ ਬਲੀ ਰੁਪਿ ਠਾਢੋ ਰਹਿਓ ਰਿਸ ਕੈ ਮਨ ਮੈ। ੧੩੯੬।","roman":"Tih sanghar mai kharges balee rupi thaadho rahio ris kai man mai | 1396 |","meaning_en":"","page":557}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":557},{"type":"verse","number":[1397],"number_text":"੧੩੯੭।","page":557,"lines":[{"gurmukhi":"ਦਸੋ ਭੂਪ ਰਨ ਪਾਰਿਯੋ ਸੈਨ ਕਉ ਬਿਪਤ ਡਾਰਿਓ","roman":"Daso bhoop ran paariyo sain kau bipat daario","meaning_en":"","page":557},{"gurmukhi":"ਬੀਰ ਪ੍ਰਨ ਧਾਰਿਓ ਨ ਡਰੈ ਹੈ ਕਾਹੂੰ ਆਨ ਸੋ।","roman":"Beer pran dhaario na darai hai kaahoon aan so |","meaning_en":"","page":557},{"gurmukhi":"ਏ ਈ ਦਸ ਭੂਪਤਿ ਰਿਸਾਇ ਸਮੁਹਾਇ ਗਏ","roman":"E ee das bhoopti risaai samuhaai gae","meaning_en":"","page":557},{"gurmukhi":"ਉਤ ਆਇ ਸਉਹੇ ਭਯੋ ਮਹਾ ਸੂਰ ਮਾਨ ਸੋ।","roman":"Ut aai sauhe bhayo mahaa soor maan so |","meaning_en":"","page":557},{"gurmukhi":"ਕਹੈ ਕਬਿ ਸ੍ਯਾਮ ਅਤਿ ਕ੍ਰੁਧ ਹੁਇ ਖੜਗ ਸਿੰਘ","roman":"Kahai kabi syaam ati krudh hui kharag singh","meaning_en":"","page":557},{"gurmukhi":"ਤਾਨ ਕੈ ਕਮਾਨ ਕੋ ਲਗਾਈ ਕੋ ਲਗਾਈ ਜਿਹ ਕਾਨ ਸੋ।","roman":"Taan kai kamaan ko lagaaee ko lagaaee jih kaan so |","meaning_en":"","page":557},{"gurmukhi":"ਗਜਰਾਜ ਭਾਰੇ ਅਰੁ ਜੁਧ ਕੇ ਕਰਾਰੇ","roman":"Gajraaj bhaare aru judh ke karaare","meaning_en":"","page":557},{"gurmukhi":"ਦਸੋ ਮਾਰਿ ਡਾਰੇ ਤਿਨ ਦਸ ਦਸ ਬਾਨ ਸੋ। ੧੩੯੭।","roman":"Daso maari daare tin das das baan so | 1397 |","meaning_en":"","page":557}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":557},{"type":"verse","number":[1398],"number_text":"੧੩੯੮।","page":557,"lines":[{"gurmukhi":"ਪਾਚ ਬੀਰ ਜਦੁਬੀਰ ਕੇ ਗਏ ਸੁ ਅਰਿ ਪਰ ਦਉਰਿ।","roman":"Paach beer jadubeer ke gae su ari par dauri |","meaning_en":"","page":557},{"gurmukhi":"ਛਕਤ ਸਿੰਘ ਅਰੁ ਛਤ੍ਰ ਸਿੰਘ ਛੋਹ ਸਿੰਘ ਸਿੰਘ ਗਉਰ। ੧੩੯੮।","roman":"Chhakat singh aru chhatr singh chhoh singh singh gaur | 1398 |","meaning_en":"","page":557}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":557},{"type":"verse","number":[1399],"number_text":"੧੩੯੯।","page":557,"lines":[{"gurmukhi":"ਛਲਬਲ ਸਿੰਘ ਜਿਹ ਨਾਮ ਮਹਾਬੀਰ ਬਲ ਬੀਰ ਕੋ।","roman":"Chhalbal singh jih naam mahaabeer bal beer ko |","meaning_en":"","page":557},{"gurmukhi":"ਲਏ ਖੜਗ ਕਰਿ ਚਾਮ ਖੜਗ ਸਿੰਘ ਪਰ ਸੋ ਚਲਿਓ। ੧੩੯੯।","roman":"Lae kharag kari chaam kharag singh par so chalio | 1399 |","meaning_en":"","page":557}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":558},{"type":"verse","number":[1400],"number_text":"੧੪੦੦।","page":558,"lines":[{"gurmukhi":"ਜਬਹੀ ਪਾਚ ਬੀਰ ਮਿਲਿ ਧਾਏ। ਖੜਗ ਸਿੰਘ ਕੇ ਊਪਰ ਆਏ।","roman":"Jabhee paach beer mili dhaae | kharag singh ke oopar aae |","meaning_en":"","page":558},{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਤਬ ਸਸਤ੍ਰ ਸੰਭਾਰੇ। ਸਬ ਹੀ ਪ੍ਰਾਨ ਬਿਨਾ ਕਰਿ ਡਾਰੇ। ੧੪੦੦।","roman":"Kharag singh tab sasatr sanbhaare | sab hee praan binaa kari daare | 1400 |","meaning_en":"","page":558}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":558},{"type":"verse","number":[1401],"number_text":"੧੪੦੧।","page":558,"lines":[{"gurmukhi":"ਦੁਆਦਸ ਜੋਧੇ ਕ੍ਰਿਸਨ ਕੇ ਅਤਿ ਬਲਬੰਡ ਅਖੰਡ।","roman":"Duaadas jodhe krisan ke ati balband akhand |","meaning_en":"","page":558},{"gurmukhi":"ਜੀਤ ਲਯੋ ਹੈ ਜਗਤ ਜਿਨ ਬਲ ਕਰਿ ਭੁਜਾ ਪ੍ਰਚੰਡ। ੧੪੦੧।","roman":"Jeet layo hai jagat jin bal kari bhujaa prachand | 1401 |","meaning_en":"","page":558}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":558},{"type":"verse","number":[1402],"number_text":"੧੪੦੨।","page":558,"lines":[{"gurmukhi":"ਬਾਲਮ ਸਿੰਘ ਮਹਾਮਤਿ ਸਿੰਘ ਜਗਾਜਤ ਸਿੰਘ ਲਏ ਅਸਿ ਧਾਯੋ।","roman":"Baalam singh mahaamti singh jagaajat singh lae asi dhaayo |","meaning_en":"","page":558},{"gurmukhi":"ਸਿੰਘ ਧਨੇਸ ਕ੍ਰਿਪਾਵਤ ਸਿੰਘ ਸੁ ਜੋਬਨ ਸਿੰਘ ਮਹਾ ਬਰ ਪਾਯੋ।","roman":"Singh dhanes kripaavat singh su joban singh mahaa bar paayo |","meaning_en":"","page":558},{"gurmukhi":"ਜੀਵਨ ਸਿੰਘ ਚਲਿਯੋ ਜਗ ਸਿੰਘ ਸਦਾ ਸਿੰਘ ਲੈ ਜਸ ਸਿੰਘ ਰਸਾਯੋ।","roman":"Jeevan singh chaliyo jag singh sadaa singh lai jas singh rasaayo |","meaning_en":"","page":558},{"gurmukhi":"ਬੀਰਮ ਸਿੰਘ ਲਏ ਸਕਤੀ ਕਰ ਮੈ ਖੜਗੇਸ ਸੋ ਜੁਧੁ ਮਚਾਯੋ। ੧੪੦੨।","roman":"Beeram singh lae saktee kar mai kharges so judhu machaayo | 1402 |","meaning_en":"","page":558}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":558},{"type":"verse","number":[1403],"number_text":"੧੪੦੩।","page":558,"lines":[{"gurmukhi":"ਮੋਹਨ ਸਿੰਘ ਜਿਹਿ ਨਾਮ ਭਟ ਸੋਊ ਭਯੋ ਤਿਨ ਸੰਗਿ।","roman":"Mohan singh jihi naam bhat so'oo bhayo tin sangi |","meaning_en":"","page":558},{"gurmukhi":"ਸਸਤ੍ਰ ਧਾਰਿ ਕਰ ਮੈ ਲੀਏ ਸਾਜਿਯੋ ਕਵਚ ਨਿਖੰਗ। ੧੪੦੩।","roman":"Sasatr dhaari kar mai lee'e saajiyo kavach nikhang | 1403 |","meaning_en":"","page":558}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":558},{"type":"verse","number":[1404],"number_text":"੧੪੦੪।","page":558,"lines":[{"gurmukhi":"ਖੜਗੇਸ ਬਲੀ ਕਹੁ ਰਾਮ ਭਨੈ ਸਭ ਭੂਪਨ ਬਾਨ ਪ੍ਰਹਾਰ ਕਰਿਓ ਹੈ।","roman":"Kharges balee kahu raam bhanai sabh bhoopan baan prahaar kario hai |","meaning_en":"","page":558},{"gurmukhi":"ਠਾਢੋ ਰਹਿਓ ਦ੍ਰਿੜ ਭੂ ਪਰ ਮੇਰੁ ਸੋ ਆਹਵ ਤੇ ਨਹੀ ਨੈਕੁ ਡਰਿਓ ਹੈ।","roman":"Thaadho rahio drir bhoo par meru so aahav te nahee naiku dario hai |","meaning_en":"","page":558},{"gurmukhi":"ਕੋਪ ਸਿਉ ਓਪ ਬਢੀ ਤਿਹ ਆਨਨ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਭਾਉ ਧਰਿਓ ਹੈ।","roman":"Kop siu op badhee tih aanan taa chhabi ko kabi bhaau dhario hai |","meaning_en":"","page":558},{"gurmukhi":"ਰੋਸਿ ਕੀ ਆਗ ਪ੍ਰਚੰਡ ਭਈ ਸਰ ਪੁੰਜ ਛੁਟੇ ਮਾਨੋ ਘੀਉ ਪਰਿਓ ਹੈ। ੧੪੦੪।","roman":"Rosi kee aag prachand bhaee sar punj chhute maano gheeu pario hai | 1404 |","meaning_en":"","page":558}]},{"type":"verse","number":[1405],"number_text":"੧੪੦੫।","page":558,"lines":[{"gurmukhi":"ਜੋ ਦਲ ਹੋ ਹਰਿ ਬੀਰਨਿ ਕੇ ਸੰਗ ਸੋ ਤੋ ਕਛੂ ਅਰਿ ਮਾਰਿ ਲਯੋ ਹੈ।","roman":"Jo dal ho hari beerni ke sang so to kachhoo ari maari layo hai |","meaning_en":"","page":558},{"gurmukhi":"ਫੇਰਿ ਅਯੋਧਨ ਮੈ ਰੁਪ ਕੈ ਅਸਿ ਲੈ ਜੀਯ ਮੈ ਪੁਨਿ ਕੋਪੁ ਭਯੋ ਹੈ।","roman":"Pheri ayodhan mai rup kai asi lai jeey mai puni kopu bhayo hai |","meaning_en":"","page":558},{"gurmukhi":"ਮਾਰਿ ਬਿਦਾਰ ਦਯੋ ਘਟ ਗਯੋ ਦਲ ਸੋ ਕਬਿ ਕੇ ਮਨ ਭਾਉ ਨਯੋ ਹੈ।","roman":"Maari bidaar dayo ghat gayo dal so kabi ke man bhaau nayo hai |","meaning_en":"","page":558},{"gurmukhi":"ਮਾਨਹੁ ਸੂਰ ਪ੍ਰਲੈ ਕੋ ਚੜਿਯੋ ਜਲੁ ਸਾਗਰ ਕੋ ਸਬ ਸੂਕਿ ਗਯੋ ਹੈ। ੧੪੦੫।","roman":"Maanhu soor pralai ko chariyo jalu saagar ko sab sooki gayo hai | 1405 |","meaning_en":"","page":558}]},{"type":"verse","number":[1406],"number_text":"੧੪੦੬।","page":558,"lines":[{"gurmukhi":"ਪ੍ਰਥਮੇ ਤਿਨ ਕੀ ਭੁਜ ਕਾਟਿ ਦਈ ਫਿਰ ਕੈ ਤਿਨ ਕੇ ਸਿਰ ਕਾਟਿ ਦਏ।","roman":"Prathme tin kee bhuj kaati daee phir kai tin ke sir kaati dae |","meaning_en":"","page":558},{"gurmukhi":"ਰਥ ਬਾਜਨ ਸੂਤ ਸਮੇਤ ਸਬੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਰਨ ਬੀਚ ਛਏ।","roman":"Rath baajan soot samet sabai kabi syaam kahai ran beech chhae |","meaning_en":"","page":558},{"gurmukhi":"ਜਿਨ ਕੀ ਸੁਖ ਕੇ ਸੰਗ ਆਯੁ ਕਟੀ ਤਿਨ ਕੀ ਲੁਥ ਜੰਬੁਕ ਗੀਧ ਖਏ।","roman":"Jin kee sukh ke sang aayu katee tin kee luth janbuk geedh khae |","meaning_en":"","page":559},{"gurmukhi":"ਜਿਨ ਸਤ੍ਰ ਘਨੇ ਰਨ ਮਾਝਿ ਹਨੇ ਸੋਊ ਸੰਘਰ ਮੈ ਬਿਨੁ ਪ੍ਰਾਨ ਭਏ। ੧੪੦੬।","roman":"Jin satr ghane ran maajhi hane so'oo sanghar mai binu praan bhae | 1406 |","meaning_en":"","page":559}]},{"type":"verse","number":[1407],"number_text":"੧੪੦੭।","page":559,"lines":[{"gurmukhi":"ਦ੍ਵਾਦਸ ਭੂਪਨ ਕੋ ਹਨਿ ਕੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਰਨ ਮੈ ਨ੍ਰਿਪ ਛਾਜਿਯੋ।","roman":"Dvaadas bhoopan ko hani kai kabi syaam kahai ran mai nrip chhaajiyo |","meaning_en":"","page":559},{"gurmukhi":"ਮਾਨਹੁ ਦੂਰ ਘਨੋ ਤਮੁ ਕੈ ਦਿਨ ਆਧਿਕ ਮੈ ਦਿਵਰਾਜ ਬਿਰਾਜਿਯੋ।","roman":"Maanhu door ghano tamu kai din aadhik mai divraaj biraajiyo |","meaning_en":"","page":559},{"gurmukhi":"ਗਾਜਤ ਹੈ ਖੜਗੇਸ ਬਲੀ ਧੁਨਿ ਜਾ ਸੁਨਿ ਕੈ ਘਨ ਸਾਵਨ ਲਾਜਿਯੋ।","roman":"Gaajat hai kharges balee dhuni jaa suni kai ghan saavan laajiyo |","meaning_en":"","page":559},{"gurmukhi":"ਕਾਲ ਪ੍ਰਲੈ ਜਿਉ ਕਿਰਾਰਨ ਤੇ ਬਢਿ ਮਾਨਹੁ ਨੀਰਧ ਕੋਪ ਕੈ ਗਾਜਿਯੋ। ੧੪੦੭।","roman":"Kaal pralai jiu kiraaran te badhi maanhu neeradh kop kai gaajiyo | 1407 |","meaning_en":"","page":559}]},{"type":"verse","number":[1408],"number_text":"੧੪੦੮।","page":559,"lines":[{"gurmukhi":"ਅਉਰ ਕਿਤੀ ਜਦੁਬੀਰ ਚਮੂੰ ਨ੍ਰਿਪ ਇਉ ਪੁਰਖਤਿ ਦਿਖਾਇ ਭਜਾਈ।","roman":"Aur kitee jadubeer chamoon nrip iu purakhti dikhaai bhajaaee |","meaning_en":"","page":559},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਭਟ ਆਇ ਭਿਰੇ ਤਿਨ ਪ੍ਰਾਨਨ ਕੀ ਸਬ ਆਸ ਚੁਕਾਈ।","roman":"Aur jite bhat aai bhire tin praanan kee sab aas chukaaee |","meaning_en":"","page":559},{"gurmukhi":"ਲੈ ਕਰ ਮੈ ਅਸਿ ਸ੍ਯਾਮ ਭਨੇ ਜਿਨ ਧਾਇ ਕੈ ਆਇ ਕੈ ਕੀਨੀ ਲਰਾਈ।","roman":"Lai kar mai asi syaam bhane jin dhaai kai aai kai keenee laraaee |","meaning_en":"","page":559},{"gurmukhi":"ਅੰਤ ਕੋ ਅੰਤ ਕੇ ਧਾਮਿ ਗਏ ਤਿਨ ਨਾਹਕ ਆਪਨੀ ਦੇਹ ਗਵਾਈ। ੧੪੦੮।","roman":"Ant ko ant ke dhaami gae tin naahak aapnee deh gavaaee | 1408 |","meaning_en":"","page":559}]},{"type":"verse","number":[1409],"number_text":"੧੪੦੯।","page":559,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਰਨ ਮੈ ਰਿਸ ਕੈ ਦਸ ਸੈ ਗਜ ਐਤ ਤੁਰੰਗ ਚਮੂੰ ਹਨਿ ਡਾਰੀ।","roman":"Bahuro ran mai ris kai das sai gaj ait turang chamoon hani daaree |","meaning_en":"","page":559},{"gurmukhi":"ਦੁਇ ਸਤਿ ਸਿਯੰਦਨ ਕਾਟਿ ਦਏ ਬਹੁ ਬੀਰ ਹਨੇ ਬਲੁ ਕੈ ਅਸਿ ਧਾਰੀ।","roman":"Dui sati siyandan kaati dae bahu beer hane balu kai asi dhaaree |","meaning_en":"","page":559},{"gurmukhi":"ਬੀਸ ਹਜ਼ਾਰ ਪਦਾਤ ਹਨੇ ਦ੍ਰੁਮ ਸੇ ਗਿਰ ਹੈ ਰਨ ਭੂਮਿ ਮੰਝਾਰੀ।","roman":"Bees hazaar padaat hane drum se gir hai ran bhoomi manjhaaree |","meaning_en":"","page":559},{"gurmukhi":"ਮਾਨੋ ਹਨੂੰ ਰਿਸਿ ਰਾਵਨ ਬਾਗ ਕੀ ਮੂਲ ਹੂੰ ਤੇ ਜਰ ਮੇਖ ਉਚਾਰੀ। ੧੪੦੯।","roman":"Maano hanoon risi raavan baag kee mool hoon te jar mekh uchaaree | 1409 |","meaning_en":"","page":559}]},{"type":"verse","number":[1410],"number_text":"੧੪੧੦।","page":559,"lines":[{"gurmukhi":"ਰਾਛਸ ਅਭ ਹੁਤੋ ਹਰਿ ਕੀ ਦਿਸਿ ਸੋ ਬਲੁ ਕੈ ਨ੍ਰਿਪ ਊਪਰ ਧਾਯੋ।","roman":"Raachhas abh huto hari kee disi so balu kai nrip oopar dhaayo |","meaning_en":"","page":559},{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਸਬੈ ਅਪੁਨੇ ਚਪਲਾ ਸਮ ਲੈ ਅਸਿ ਕੋਪ ਬਢਾਯੋ।","roman":"Sasatr sanbhaari sabai apune chaplaa sam lai asi kop badhaayo |","meaning_en":"","page":559},{"gurmukhi":"ਗਾਜਤ ਹੀ ਬਰਖਿਯੋ ਬਰਖਾ ਸਰ ਸ੍ਯਾਮ ਕਬੀਸਰ ਯੋ ਗੁਨ ਗਾਯੋ।","roman":"Gaajat hee barkhiyo barkhaa sar syaam kabeesar yo gun gaayo |","meaning_en":"","page":559},{"gurmukhi":"ਮਾਨਹੁ ਗੋਪਨ ਕੇ ਗਨ ਪੈ ਅਤਿ ਕੋਪ ਕੀਏ ਮਘਵਾ ਚਢਿ ਆਯੋ। ੧੪੧੦।","roman":"Maanhu gopan ke gan pai ati kop kee'e maghvaa chadhi aayo | 1410 |","meaning_en":"","page":559}]},{"type":"verse","number":[1411],"number_text":"੧੪੧੧।","page":559,"lines":[{"gurmukhi":"ਦੈਤ ਚਮੂੰ ਘਨ ਜਿਉ ਉਮਡੀ ਮਨ ਮੈ ਨ ਕਛੂ ਨ੍ਰਿਪ ਹੂੰ ਡਰੁ ਕੀਨੋ।","roman":"Dait chamoon ghan jiu umdee man mai na kachhoo nrip hoon daru keeno |","meaning_en":"","page":559},{"gurmukhi":"ਕੋਪ ਬਢਾਇ ਘਨੋ ਚਿਤ ਮੈ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਭਲੇ ਕਰ ਲੀਨੋ।","roman":"Kop badhaai ghano chit mai dhanu baan sanbhaari bhale kar leeno |","meaning_en":"","page":559},{"gurmukhi":"ਖੈਚ ਕੈ ਕਾਨ ਪ੍ਰਮਾਨ ਕਮਾਨ ਸੁ ਛੇਦ ਹ੍ਰਿਦਾ ਸਰ ਸੋ ਅਰਿ ਦੀਨੋ।","roman":"Khaich kai kaan pramaan kamaan su chhed hridaa sar so ari deeno |","meaning_en":"","page":559},{"gurmukhi":"ਮਾਨਹੁ ਬਾਂਬੀ ਮੈ ਸਾਪ ਧਸਿਓ ਕਬਿ ਨੇ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਇਮਿ ਚੀਨੋ। ੧੪੧੧।","roman":"Maanhu baanbee mai saap dhasio kabi ne jasu taa chhabi ko imi cheeno | 1411 |","meaning_en":"","page":559}]},{"type":"verse","number":[1412],"number_text":"੧੪੧੨।","page":559,"lines":[{"gurmukhi":"ਬਾਨਨ ਸੰਗਿ ਸੁ ਮਾਰਿ ਕੈ ਸਤ੍ਰਨ ਰਾਮ ਭਨੇ ਅਸਿ ਸੋ ਪੁਨਿ ਮਾਰਿਓ।","roman":"Baanan sangi su maari kai satran raam bhane asi so puni maario |","meaning_en":"","page":559},{"gurmukhi":"ਸ੍ਰਉਨ ਸਮੂਹ ਪਰਿਓ ਤਿਹ ਤੇ ਧਰਿ ਪ੍ਰਾਨ ਬਿਨਾ ਕਰਿ ਭੂ ਪਰ ਡਾਰਿਓ।","roman":"Sraun samooh pario tih te dhari praan binaa kari bhoo par daario |","meaning_en":"","page":559},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਉਪਮਾ ਲਖਿ ਕੈ ਕਬਿ ਨੇ ਮੁਖਿ ਤੇ ਇਹ ਭਾਤਿ ਉਚਾਰਿਓ।","roman":"Taa chhabi kee upmaa lakhi kai kabi ne mukhi te ih bhaati uchaario |","meaning_en":"","page":559,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ੁ; attached to the next consonant"}]},{"gurmukhi":"ਖਗ ਲਗਿਯੋ ਤਿਹ ਕੋ ਨਹੀ ਮਾਨਹੁ ਲੈ ਕਰ ਮੈ ਜਮ ਦੰਡ ਪ੍ਰਹਾਰਿਓ। ੧੪੧੨।","roman":"Khag lagiyo tih ko nahee maanhu lai kar mai jam dand prahaario | 1412 |","meaning_en":"","page":559}]},{"type":"verse","number":[1413],"number_text":"੧੪੧੩।","page":560,"lines":[{"gurmukhi":"ਰਾਛਸ ਮਾਰਿ ਲਯੋ ਜਬ ਹੀ ਤਬ ਰਾਛਸ ਕੋ ਰਿਸ ਕੈ ਦਲੁ ਧਾਯੋ।","roman":"Raachhas maari layo jab hee tab raachhas ko ris kai dalu dhaayo |","meaning_en":"","page":560},{"gurmukhi":"ਆਵਤ ਹੀ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬਿਬਿਧਾਯੁਧ ਲੈ ਅਤਿ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Aavat hee kabi syaam kahai bibidhaayudh lai ati judhu machaayo |","meaning_en":"","page":560},{"gurmukhi":"ਦੈਤ ਘਨੇ ਤਹ ਘਾਇਲ ਹੈ ਬਹੁ ਘਾਇਨ ਸੋ ਖੜਗੇਸਹਿ ਘਾਯੋ।","roman":"Dait ghane tah ghaail hai bahu ghaain so khargeshi ghaayo |","meaning_en":"","page":560},{"gurmukhi":"ਸੋ ਸਹਿ ਕੈ ਅਸਿ ਕੋ ਗਹਿ ਕੈ ਨ੍ਰਿਪ ਜੁਧ ਕੀਯੋ ਨਹੀ ਘਾਉ ਜਤਾਯੋ। ੧੪੧੩।","roman":"So sahi kai asi ko gahi kai nrip judh keeyo nahee ghaau jataayo | 1413 |","meaning_en":"","page":560}]},{"type":"verse","number":[1414],"number_text":"੧੪੧੪।","page":560,"lines":[{"gurmukhi":"ਧਾਇ ਪਰੇ ਸਬ ਰਾਛਸਿ ਯਾ ਪਰ ਹੈ ਤਿਨ ਕੈ ਮਨਿ ਕੋਪੁ ਬਢਿਓ।","roman":"Dhaai pare sab raachhsi yaa par hai tin kai mani kopu badhio |","meaning_en":"","page":560},{"gurmukhi":"ਗਹਿ ਬਾਨ ਕਮਾਨ ਗਦਾ ਬਰਛੀ ਤਿਨ ਮਿਆਨਹੁ ਤੇ ਕਰਵਾਰ ਕਢਿਓ।","roman":"Gahi baan kamaan gadaa barchhee tin miaanhu te karvaar kadhio |","meaning_en":"","page":560},{"gurmukhi":"ਸਬ ਦਾਨਵ ਤੇਜ ਪ੍ਰਚੰਡ ਕੀਯੋ ਰਿਸ ਪਾਵਕ ਮੈ ਤਿਨ ਅੰਗ ਡਢਿਓ।","roman":"Sab daanav tej prachand keeyo ris paavak mai tin ang dadhio |","meaning_en":"","page":560},{"gurmukhi":"ਇਹ ਭਾਤਿ ਪ੍ਰਹਾਰਤ ਹੈ ਨ੍ਰਿਪ ਕਉ ਤਨ ਕੰਚਨ ਮਾਨੋ ਸੁਨਾਰ ਗਢਿਓ। ੧੪੧੪।","roman":"Ih bhaati prahaarat hai nrip kau tan kanchan maano sunaar gadhio | 1414 |","meaning_en":"","page":560}]},{"type":"verse","number":[1415],"number_text":"੧੪੧੫।","page":560,"lines":[{"gurmukhi":"ਜਿਨ ਹੂੰ ਨ੍ਰਿਪ ਕੇ ਸੰਗਿ ਜੁਧ ਕੀਯੋ ਸੁ ਸਬੈ ਇਨ ਹੂੰ ਹਤਿ ਕੈ ਤਬ ਦੀਨੇ।","roman":"Jin hoon nrip ke sangi judh keeyo su sabai in hoon hati kai tab deene |","meaning_en":"","page":560},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਅਰਿ ਜੀਤ ਬਚੈ ਤਿਨ ਕੇ ਬਧ ਕਉ ਕਰਿ ਆਯੁਧ ਲੀਨੇ।","roman":"Aur jite ari jeet bachai tin ke badh kau kari aayudh leene |","meaning_en":"","page":560},{"gurmukhi":"ਤਉ ਇਨ ਭੂਪ ਸਰਾਸਨ ਲੈ ਕੀਏ ਸਤ੍ਰਨ ਕੇ ਤਨ ਮੁੰਡਨ ਹੀਨੇ।","roman":"Tau in bhoop saraasan lai kee'e satran ke tan mundan heene |","meaning_en":"","page":560},{"gurmukhi":"ਜੋ ਨ ਡਰੇ ਸੁ ਲਰੇ ਪੁਨਿ ਧਾਇ ਨਿਦਾਨ ਵਹੀ ਨ੍ਰਿਪ ਖੰਡਨ ਕੀਨੇ। ੧੪੧੫।","roman":"Jo na dare su lare puni dhaai nidaan vahee nrip khandan keene | 1415 |","meaning_en":"","page":560}]},{"type":"verse","number":[1416],"number_text":"੧੪੧੬।","page":560,"lines":[{"gurmukhi":"ਬੀਰ ਬਡੋ ਇਕ ਦੈਤ ਹੁਤੋ ਤਿਨਿ ਕੋਪ ਕੀਯੋ ਅਤਿ ਹੀ ਮਨ ਮੈ।","roman":"Beer bado ik dait huto tini kop keeyo ati hee man mai |","meaning_en":"","page":560},{"gurmukhi":"ਇਹ ਭਾਤਿ ਸੋ ਭੂਪ ਕਉ ਬਾਨ ਹਨੇ ਸਬ ਫੋਕਨ ਲਉ ਗਡਗੇ ਤਨ ਮੈ।","roman":"Ih bhaati so bhoop kau baan hane sab phokan lau gadge tan mai |","meaning_en":"","page":560},{"gurmukhi":"ਤਬ ਭੂਪਤਿ ਸਾਗ ਹਨੀ ਰਿਪੁ ਕੋ ਧਸ ਗੀ ਉਰਿ ਜਿਉ ਚਪਲਾ ਘਨ ਮੈ।","roman":"Tab bhoopti saag hanee ripu ko dhas gee uri jiu chaplaa ghan mai |","meaning_en":"","page":560},{"gurmukhi":"ਸੁ ਮਨੋ ਉਰਗੇਸ ਖਗੇਸ ਕੇ ਤ੍ਰਾਸ ਤੇ ਧਾਇ ਕੈ ਜਾਇ ਦੁਰਿਓ ਬਨ ਮੈ। ੧੪੧੬।","roman":"Su mano urges khages ke traas te dhaai kai jaai durio ban mai | 1416 |","meaning_en":"","page":560}]},{"type":"verse","number":[1417],"number_text":"੧੪੧੭।","page":560,"lines":[{"gurmukhi":"ਲਾਗਤ ਸਾਂਗ ਕੈ ਪ੍ਰਾਨ ਤਜੇ ਤਿਹ ਅਉਰ ਹੁਤੋ ਤਿਹ ਕੋ ਅਸਿ ਝਾਰਿਓ।","roman":"Laagat saang kai praan taje tih aur huto tih ko asi jhaario |","meaning_en":"","page":560},{"gurmukhi":"ਕੋਪ ਅਯੋਧਨ ਮੈ ਖੜਗੇਸ ਕਹੈ ਕਬਿ ਰਾਮ ਮਹਾ ਬਲ ਧਾਰਿਓ।","roman":"Kop ayodhan mai kharges kahai kabi raam mahaa bal dhaario |","meaning_en":"","page":560},{"gurmukhi":"ਰਾਛਸ ਤੀਸ ਰਹੋ ਤਿਹ ਠਾ ਤਿਹ ਕੋ ਤਬ ਹੀ ਤਿਹ ਠਉਰ ਸੰਘਾਰਿਓ।","roman":"Raachhas tees raho tih thaa tih ko tab hee tih thaur sanghaario |","meaning_en":"","page":560},{"gurmukhi":"ਪ੍ਰਾਨ ਬਿਨਾ ਇਹ ਭਾਤਿ ਪਰਿਓ ਮਘਵਾ ਮਨੋ ਬਜ੍ਰ ਭਏ ਨਗੁ ਮਾਰਿਓ। ੧੪੧੭।","roman":"Praan binaa ih bhaati pario maghvaa mano bajr bhae nagu maario | 1417 |","meaning_en":"","page":560}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":560},{"type":"verse","number":[1418],"number_text":"੧੪੧੮।","page":560,"lines":[{"gurmukhi":"ਕੇਤੇ ਰਾਛਸਨ ਹੂੰ ਕੀ ਭੁਜਨ ਕਉ ਕਾਟਿ ਦਯੋ","roman":"Kete raachhsan hoon kee bhujan kau kaati dayo","meaning_en":"","page":560},{"gurmukhi":"ਕੇਤੇ ਸਿਰ ਸਤ੍ਰਨ ਕੇ ਖੰਡਨ ਕਰਤ ਹੈ।","roman":"Kete sir satran ke khandan karat hai |","meaning_en":"","page":560},{"gurmukhi":"ਕੇਤੇ ਭਾਜਿ ਗਏ ਅਰਿ ਕੇਤੇ ਮਾਰਿ ਲਏ ਬੀਰ","roman":"Kete bhaaji gae ari kete maari lae beer","meaning_en":"","page":560},{"gurmukhi":"ਰਨ ਹੂੰ ਕੀ ਭੂਮਿ ਹੂੰ ਤੇ ਪੈਗੁ ਨ ਟਰਤ ਹੈ।","roman":"Ran hoon kee bhoomi hoon te paigu na tarat hai |","meaning_en":"","page":560},{"gurmukhi":"ਸੈਥੀ ਜਮਦਾਰ ਲੈ ਸਰਾਸਨ ਗਦਾ ਤ੍ਰਿਸੂਲ","roman":"Saithee jamdaar lai saraasan gadaa trisool","meaning_en":"","page":560},{"gurmukhi":"ਦੁਜਨ ਕੀ ਸੈਨਾ ਬੀਚ ਐਸੇ ਬਿਚਰਤ ਹੈ।","roman":"Dujan kee sainaa beech aise bichrat hai |","meaning_en":"","page":560},{"gurmukhi":"ਆਗੇ ਹੁਇ ਲਰਤ ਪਗ ਪਾਛੇ ਨ ਕਰਤ ਡਗ","roman":"Aage hui larat pag paachhe na karat dag","meaning_en":"","page":560},{"gurmukhi":"ਕਬੂੰ ਦੇਖੀਯਤ ਕਬੂੰ ਦੇਖਿਓ ਨ ਪਰਤ ਹੈ। ੧੪੧੮।","roman":"Kaboon dekheeyat kaboon dekhio na parat hai | 1418 |","meaning_en":"","page":560}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋਬਾਚ","gurmukhi":"ਕਬਿਯੋਬਾਚ","roman":"Kabiyobaach","meaning_en":"","page":561},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":561},{"type":"verse","number":[1419],"number_text":"੧੪੧੯।","page":561,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਬਹੁ ਰਾਛਸ ਮਾਰੇ ਕੋਪ ਹੁਇ।","roman":"Kharag singh bahu raachhas maare kop hui |","meaning_en":"","page":561},{"gurmukhi":"ਰਹੇ ਮਨੋ ਮਤਵਾਰੇ ਰਨ ਕੀ ਭੂਮਿ ਸੁਇ।","roman":"Rahe mano matvaare ran kee bhoomi sui |","meaning_en":"","page":561},{"gurmukhi":"ਜੀਅਤ ਬਚੇ ਤੇ ਭਾਜੇ ਤ੍ਰਾਸ ਬਢਾਇ ਕੈ।","roman":"Jeeat bache te bhaaje traas badhaai kai |","meaning_en":"","page":561},{"gurmukhi":"ਹੋ ਜਦੁਪਤਿ ਤੀਰ ਪੁਕਾਰੇ ਸਬ ਹੀ ਆਇ ਕੈ। ੧੪੧੯।","roman":"Ho jadupti teer pukaare sab hee aai kai | 1419 |","meaning_en":"","page":561}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":561},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":561},{"type":"verse","number":[1420],"number_text":"੧੪੨੦।","page":561,"lines":[{"gurmukhi":"ਤਬ ਬ੍ਰਿਜਪਤਿ ਸਬ ਸੈਨ ਕਉ ਐਸੇ ਕਹਿਯੋ ਸੁਨਾਇ।","roman":"Tab brijapti sab sain kau aise kahiyo sunaai |","meaning_en":"","page":561},{"gurmukhi":"ਕੋ ਲਾਇਕ ਭਟ ਕਟਕ ਮੈ ਲਰੈ ਜੁ ਯਾ ਸੰਗ ਜਾਇ। ੧੪੨੦।","roman":"Ko laaik bhat katak mai larai ju yaa sang jaai | 1420 |","meaning_en":"","page":561}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":561},{"type":"verse","number":[1421],"number_text":"੧੪੨੧।","page":561,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਪਤਿ ਕੇ ਬੀਰ ਦੁਇ ਨਿਕਸੇ ਅਤਿ ਕੋਪ ਹੁਇ।","roman":"Sree jadupti ke beer dui nikse ati kop hui |","meaning_en":"","page":561},{"gurmukhi":"ਮਹਾਰਥੀ ਰਨਧੀਰ ਇੰਦ੍ਰ ਤੁਲਿ ਬਿਕ੍ਰਮ ਜਿਨੈ। ੧੪੨੧।","roman":"Mahaarthee randheer indr tuli bikram jinai | 1421 |","meaning_en":"","page":561}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":561},{"type":"verse","number":[1422],"number_text":"੧੪੨੨।","page":561,"lines":[{"gurmukhi":"ਸਿੰਘ ਝੜਾਝੜ ਝੂਝਨ ਸਿੰਘ ਗਏ ਤਿਹ ਸਾਮੁਹੇ ਲੈ ਸੁ ਘਨੋ ਦਲੁ।","roman":"Singh jharaajhar jhoojhan singh gae tih saamuhe lai su ghano dalu |","meaning_en":"","page":561},{"gurmukhi":"ਘੋਰਨ ਕੀ ਖੁਰ ਬਾਰ ਬਜੈ ਭੂਅ ਕੰਪ ਉਠੀ ਅਰੁ ਸਤਿ ਰਸਾਤਲੁ।","roman":"Ghoran kee khur baar bajai bhooa kanp uthee aru sati rasaatlu |","meaning_en":"","page":561},{"gurmukhi":"ਯੌ ਖੜਗੇਸ ਰਹਿਓ ਥਿਰੁ ਹ੍ਵੈ ਜਿਮ ਪਉਨ ਲਗੈ ਨ ਹਲੇ ਕਨਕਾਚਲੁ।","roman":"Yau kharges rahio thiru hvai jim paun lagai na hale kankaachlu |","meaning_en":"","page":561},{"gurmukhi":"ਤਾ ਪੈ ਬਸਾਵਤੁ ਹੈ ਨ ਕਛੁ ਸਬ ਹੀ ਜਦੁ ਬੀਰਨ ਕੋ ਘਟਿ ਗਯੋ ਬਲੁ। ੧੪੨੨।","roman":"Taa pai basaavtu hai na kachhu sab hee jadu beeran ko ghati gayo balu | 1422 |","meaning_en":"","page":561}]},{"type":"verse","number":[1423],"number_text":"੧੪੨੩।","page":561,"lines":[{"gurmukhi":"ਕੋਪ ਕੀਯੋ ਧਨੁ ਲੈ ਕਰ ਮੈ ਜੁਗ ਭੂਪਨ ਕੀ ਬਹੁ ਸੈਨ ਹਨੀ ਹੈ।","roman":"Kop keeyo dhanu lai kar mai jug bhoopan kee bahu sain hanee hai |","meaning_en":"","page":561},{"gurmukhi":"ਬਾਜ ਘਨੇ ਰਥਪਤਿ ਕਰੀ ਅਨੀ ਜੋ ਬਿਧਿ ਤੇ ਨਹੀ ਜਾਤ ਗਨੀ ਹੈ।","roman":"Baaj ghane rathapti karee anee jo bidhi te nahee jaat ganee hai |","meaning_en":"","page":561},{"gurmukhi":"ਤਾ ਛਬਿ ਕੀ ਉਪਮਾ ਮਨ ਮੈ ਲਖ ਕੇ ਮੁਖ ਤੇ ਕਬਿ ਸ੍ਯਾਮ ਭਨੀ ਹੈ।","roman":"Taa chhabi kee upmaa man mai lakh ke mukh te kabi syaam bhanee hai |","meaning_en":"","page":561},{"gurmukhi":"ਜੁਧ ਕੀ ਠਉਰ ਨ ਹੋਇ ਮਨੋ ਰਸ ਰੁਦ੍ਰ ਕੇ ਖੇਲ ਕੋ ਠਉਰ ਬਨੀ ਹੈ। ੧੪੨੩।","roman":"Judh kee thaur na hoi mano ras rudr ke khel ko thaur banee hai | 1423 |","meaning_en":"","page":561}]},{"type":"verse","number":[1424],"number_text":"੧੪੨੪।","page":561,"lines":[{"gurmukhi":"ਲੈ ਧਨੁ ਬਾਨ ਧਸਿਓ ਰਨ ਮੈ ਤਿਹ ਕੇ ਮਨ ਮੈ ਅਤਿ ਕੋਪ ਬਢਿਓ।","roman":"Lai dhanu baan dhasio ran mai tih ke man mai ati kop badhio |","meaning_en":"","page":561},{"gurmukhi":"ਜੁ ਹੁਤੋ ਦਲ ਬੈਰਨ ਕੋ ਸਬ ਹੀ ਰਿਸ ਤੇਜ ਕੇ ਸੰਗਿ ਪ੍ਰਤਛ ਡਢਿਓ।","roman":"Ju huto dal bairan ko sab hee ris tej ke sangi pratachh dadhio |","meaning_en":"","page":561},{"gurmukhi":"ਅਰਿ ਸੈਨ ਕੋ ਨਾਸ ਕੀਓ ਛਿਨ ਮੈ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਸ੍ਯਾਮ ਪਢਿਓ।","roman":"Ari sain ko naas keeo chhin mai jasu taa chhabi ko kabi syaam padhio |","meaning_en":"","page":561},{"gurmukhi":"ਤਮ ਜਿਉ ਡਰ ਕੇ ਅਰਿ ਭਾਜਿ ਗਏ ਇਹ ਸੂਰ ਨਹੀ ਮਾਨੋ ਸੂਰ ਚਢਿਓ। ੧੪੨੪।","roman":"Tam jiu dar ke ari bhaaji gae ih soor nahee maano soor chadhio | 1424 |","meaning_en":"","page":561}]},{"type":"verse","number":[1425],"number_text":"੧੪੨੫।","page":562,"lines":[{"gurmukhi":"ਕੋਪਿ ਝਝਾਝੜ ਸਿੰਘ ਤਬੈ ਅਸਿ ਤੀਛਨ ਲੈ ਕਰਿ ਤਾਹਿ ਪ੍ਰਹਾਰਿਓ।","roman":"Kopi jhajhaajhar singh tabai asi teechhan lai kari taahi prahaario |","meaning_en":"","page":562},{"gurmukhi":"ਭੂਪ ਛਿਨਾਇ ਲੀਯੋ ਕਰ ਤੇ ਬਰ ਕੈ ਅਰਿ ਕੇ ਤਨ ਊਪਰਿ ਝਾਰਿਓ।","roman":"Bhoop chhinaai leeyo kar te bar kai ari ke tan oopri jhaario |","meaning_en":"","page":562},{"gurmukhi":"ਲਾਗਤ ਹੀ ਕਟਿ ਮੂੰਡ ਗਿਰਿਓ ਧਰਿ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਭਾਉ ਨਿਹਾਰਿਓ।","roman":"Laagat hee kati moond girio dhari taa chhabi ko kabi bhaau nihaario |","meaning_en":"","page":562},{"gurmukhi":"ਮਾਨਹੁ ਈਸ੍ਵਰ ਕੋਪ ਭਯੋ ਸਿਰ ਪੂਤ ਕੋ ਕਾਟਿ ਜੁਦਾ ਕਰਿ ਡਾਰਿਓ। ੧੪੨੫।","roman":"Maanhu eesvar kop bhayo sir poot ko kaati judaa kari daario | 1425 |","meaning_en":"","page":562}]},{"type":"verse","number":[1426],"number_text":"੧੪੨੬।","page":562,"lines":[{"gurmukhi":"ਬੀਰ ਹਨਿਓ ਜਬ ਹੀ ਰਨ ਮੈ ਤਬ ਦੂਸਰ ਕੇ ਮਨਿ ਕੋਪ ਛਯੋ।","roman":"Beer hanio jab hee ran mai tab doosar ke mani kop chhayo |","meaning_en":"","page":562},{"gurmukhi":"ਸੁ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਤਾਹੀ ਕੀ ਓਰ ਗਯੋ ਅਸਿ ਤੀਛਨ ਪਾਨਿ ਲਯੋ।","roman":"Su dhavaai kai syandan taahee kee or gayo asi teechhan paani layo |","meaning_en":"","page":562},{"gurmukhi":"ਤਬ ਭੂਪ ਸਰਾਸਨੁ ਬਾਨ ਲਯੋ ਅਰਿ ਕੋ ਅਸਿ ਮੂਠ ਤੇ ਕਾਟਿ ਦਯੋ।","roman":"Tab bhoop saraasnu baan layo ari ko asi mooth te kaati dayo |","meaning_en":"","page":562},{"gurmukhi":"ਮਾਨੋ ਜੀਹ ਨਿਕਾਰਿ ਕੈ ਧਾਇਓ ਹੁਤੋ ਜਮੁ ਜੀਭ ਕਟੀ ਬਿਨੁ ਆਸ ਭਯੋ। ੧੪੨੬।","roman":"Maano jeeh nikaari kai dhaaio huto jamu jeebh katee binu aas bhayo | 1426 |","meaning_en":"","page":562}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋਬਾਚ","gurmukhi":"ਕਬਿਯੋਬਾਚ","roman":"Kabiyobaach","meaning_en":"","page":562},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":562},{"type":"verse","number":[1427],"number_text":"੧੪੨੭।","page":562,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਕਰਿ ਕੋ ਅਸਿ ਕਾਟਿ ਦਯੋ ਭਟ ਜੇਊ ਭਜੇ ਹੁਤੇ ਤੇ ਸਭ ਧਾਏ।","roman":"Jab hee kari ko asi kaati dayo bhat jeoo bhaje hute te sabh dhaae |","meaning_en":"","page":562},{"gurmukhi":"ਆਯੁਧ ਲੈ ਅਪੁਨੇ ਅਪੁਨੇ ਕਰਿ ਚਿਤ ਬਿਖੈ ਅਤਿ ਕੋਪੁ ਬਢਾਏ।","roman":"Aayudh lai apune apune kari chit bikhai ati kopu badhaae |","meaning_en":"","page":562},{"gurmukhi":"ਬੀਰ ਬਨੈਤ ਬਨੇ ਸਿਗਰੇ ਤਿਮ ਕੇ ਗੁਨ ਸ੍ਯਾਮ ਕਬੀਸਰ ਗਾਏ।","roman":"Beer banait bane sigre tim ke gun syaam kabeesar gaae |","meaning_en":"","page":562},{"gurmukhi":"ਮਾਨਹੁ ਭੂਪ ਸੁਅੰਬਰ ਜੁਧੁ ਰਚਿਓ ਭਟ ਏਨ ਬਡੇ ਨ੍ਰਿਪ ਆਏ। ੧੪੨੭।","roman":"Maanhu bhoop suanbar judhu rachio bhat en bade nrip aae | 1427 |","meaning_en":"","page":562}]},{"type":"verse","number":[1428],"number_text":"੧੪੨੮।","page":562,"lines":[{"gurmukhi":"ਜੇ ਨ੍ਰਿਪ ਸਾਮੁਹੇ ਆਇ ਭਿਰੇ ਅਰਿ ਬਾਨਨ ਸੋ ਸੋਈ ਮਾਰਿ ਲਏ ਹੈ।","roman":"Je nrip saamuhe aai bhire ari baanan so soee maari lae hai |","meaning_en":"","page":562},{"gurmukhi":"ਕੇਤਕਿ ਜੋਰਿ ਭਿਰੇ ਹਠਿ ਕੈ ਕਿਤਨੇ ਰਨ ਕੋ ਲਖਿ ਭਾਜਿ ਗਏ ਹੈ।","roman":"Ketki jori bhire hathi kai kitne ran ko lakhi bhaaji gae hai |","meaning_en":"","page":562},{"gurmukhi":"ਕੇਤਕਿ ਹੋਇ ਇਕਤ੍ਰ ਰਹੇ ਜਸੁ ਤਾ ਛਬਿ ਕੋ ਕਬਿ ਚੀਨ ਲਏ ਹੈ।","roman":"Ketki hoi ikatr rahe jasu taa chhabi ko kabi cheen lae hai |","meaning_en":"","page":562},{"gurmukhi":"ਮਾਨਹੁ ਆਗ ਲਗੀ ਬਨ ਮੈ ਮਦਮਤ ਕਰੀ ਇਕ ਠਉਰ ਭਏ ਹੈ। ੧੪੨੮।","roman":"Maanhu aag lagee ban mai madmat karee ik thaur bhae hai | 1428 |","meaning_en":"","page":562}]},{"type":"verse","number":[1429],"number_text":"੧੪੨੯।","page":562,"lines":[{"gurmukhi":"ਬੀਰ ਘਨੇ ਰਨ ਮਾਝ ਹਨੇ ਮਨ ਮੈ ਨ੍ਰਿਪ ਰੰਚਕ ਕੋਪ ਭਰਿਓ ਹੈ।","roman":"Beer ghane ran maajh hane man mai nrip ranchak kop bhario hai |","meaning_en":"","page":562},{"gurmukhi":"ਬਾਜ ਕਰੀ ਰਥ ਕਾਟਿ ਦਏ ਜਬ ਹੀ ਕਰ ਮੈ ਕਰਵਾਰ ਧਰਿਓ ਹੈ।","roman":"Baaj karee rath kaati dae jab hee kar mai karvaar dhario hai |","meaning_en":"","page":562},{"gurmukhi":"ਪੇਖ ਕੈ ਸਤ੍ਰ ਇਕਤ੍ਰ ਭਏ ਨ੍ਰਿਪ ਮਾਰਬੇ ਕੋ ਬਿਨ ਮੰਤ੍ਰ ਕਰਿਓ ਹੈ।","roman":"Pekh kai satr ikatr bhae nrip maarbe ko bin mantr kario hai |","meaning_en":"","page":562},{"gurmukhi":"ਕੇਹਰਿ ਕੋ ਬਧ ਜਿਉ ਚਿਤਵੈ ਮ੍ਰਿਗ ਸੋ ਤੋ ਬ੍ਰਿਥਾ ਕਬਹੂੰ ਨ ਡਰਿਓ ਹੈ। ੧੪੨੯।","roman":"Kehri ko badh jiu chitvai mrig so to brithaa kabhoon na dario hai | 1429 |","meaning_en":"","page":562}]},{"type":"verse","number":[1430],"number_text":"੧੪੩੦।","page":562,"lines":[{"gurmukhi":"ਭੂਪ ਬਲੀ ਬਹੁਰੋ ਰਿਸ ਕੈ ਜਬ ਹਾਥਨ ਮੈ ਹਥਿਯਾਰ ਗਹੇ ਹੈ।","roman":"Bhoop balee bahuro ris kai jab haathan mai hathiyaar gahe hai |","meaning_en":"","page":562},{"gurmukhi":"ਸੂਰ ਹਨੇ ਬਲਬੰਡ ਘਨੇ ਕਬਿ ਰਾਮ ਭਨੈ ਚਿਤ ਮੈ ਜੁ ਚਹੇ ਹੈ।","roman":"Soor hane balband ghane kabi raam bhanai chit mai ju chahe hai |","meaning_en":"","page":562},{"gurmukhi":"ਸੀਸ ਪਰੇ ਕਟਿ ਬੀਰਨ ਕੇ ਧਰਨੀ ਖੜਗੇਸ ਸੁ ਸੀਸ ਛਹੇ ਹੈ।","roman":"Sees pare kati beeran ke dharnee kharges su sees chhahe hai |","meaning_en":"","page":563},{"gurmukhi":"ਮਾਨਹੁ ਸ੍ਰਉਨ ਸਰੋਵਰ ਮੈ ਸਿਰ ਸਤ੍ਰਨ ਕੰਜ ਸੇ ਮੂੰਦ ਰਹੇ ਹੈ। ੧੪੩੦।","roman":"Maanhu sraun sarovar mai sir satran kanj se moond rahe hai | 1430 |","meaning_en":"","page":563}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":563},{"type":"verse","number":[1431],"number_text":"੧੪੩੧।","page":563,"lines":[{"gurmukhi":"ਤਕਿ ਝੂਝ ਸਿੰਘ ਕੋ ਖੜਗ ਸੀ ਖੜਗ ਲੀਓ ਕਰਿ ਕੋਪ।","roman":"Taki jhoojh singh ko kharag see kharag leeo kari kop |","meaning_en":"","page":563},{"gurmukhi":"ਹਨਿਓ ਤਬੈ ਸਿਰ ਸਤ੍ਰ ਕੋ ਜਨੁ ਦੀਨੀ ਅਸਿ ਓਪ। ੧੪੩੧।","roman":"Hanio tabai sir satr ko janu deenee asi op | 1431 |","meaning_en":"","page":563}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":563},{"type":"verse","number":[1432],"number_text":"੧੪੩੨।","page":563,"lines":[{"gurmukhi":"ਪੁਨਿ ਸਿੰਘ ਜੁਝਾਰ ਮਹਾ ਰਨ ਮੈ ਲਰਿ ਕੈ ਮਰਿ ਕੈ ਸੁਰਲੋਕਿ ਬਿਹਾਰਿਓ।","roman":"Puni singh jujhaar mahaa ran mai lari kai mari kai surloki bihaario |","meaning_en":"","page":563},{"gurmukhi":"ਸੈਨ ਜਿਤੋ ਤਿਹ ਸੰਗ ਹੁਤੋ ਤਬ ਹੀ ਅਸਿ ਲੈ ਨ੍ਰਿਪ ਮਾਰਿ ਬਿਦਾਰਿਓ।","roman":"Sain jito tih sang huto tab hee asi lai nrip maari bidaario |","meaning_en":"","page":563},{"gurmukhi":"ਜੇਤੇ ਰਹੇ ਸੁ ਭਜੇ ਰਨ ਤੇ ਕਿਨ ਹੂੰ ਨਹੀ ਲਾਜ ਕੀ ਓਰਿ ਨਿਹਾਰਿਓ।","roman":"Jete rahe su bhaje ran te kin hoon nahee laaj kee ori nihaario |","meaning_en":"","page":563},{"gurmukhi":"ਮਾਨਹੁ ਦੰਡ ਲੀਏ ਕਰ ਮੈ ਜਮ ਕੇ ਸਮ ਭੂਪ ਮਹਾ ਅਸਿ ਧਾਰਿਓ। ੧੪੩੨।","roman":"Maanhu dand lee'e kar mai jam ke sam bhoop mahaa asi dhaario | 1432 |","meaning_en":"","page":563}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":563},{"type":"verse","number":[1433],"number_text":"੧੪੩੩।","page":563,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਸਰੁ ਧਨੁ ਗਹਿਓ ਕਿਨਹੁ ਰਹਿਯੋ ਨ ਧੀਰ।","roman":"Kharag singh saru dhanu gahio kinhu rahiyo na dheer |","meaning_en":"","page":563},{"gurmukhi":"ਚਲੇ ਤਿਆਗ ਕੈ ਰਨ ਰਥੀ ਮਹਾ ਰਥੀ ਬਲਬੀਰ। ੧੪੩੩।","roman":"Chale tiaag kai ran rathee mahaa rathee balbeer | 1433 |","meaning_en":"","page":563}]},{"type":"verse","number":[1434],"number_text":"੧੪੩੪।","page":563,"lines":[{"gurmukhi":"ਜਬ ਭਾਜੀ ਜਾਦਵ ਚਮੂੰ ਕ੍ਰਿਸਨ ਬਿਲੋਕੀ ਨੈਨਿ।","roman":"Jab bhaajee jaadav chamoon krisan bilokee naini |","meaning_en":"","page":563},{"gurmukhi":"ਸਾਤਕਿ ਸਿਉ ਹਰਿ ਯੌ ਕਹਿਓ ਤੁਮ ਧਾਵਹੁ ਲੈ ਸੈਨ। ੧੪੩੪।","roman":"Saatki siu hari yau kahio tum dhaavhu lai sain | 1434 |","meaning_en":"","page":563}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":563},{"type":"verse","number":[1435],"number_text":"੧੪੩੫।","page":563,"lines":[{"gurmukhi":"ਸਾਤਕਿ ਅਉ ਬਰਮਾਕ੍ਰਿਤ ਊਧਵ ਸ੍ਰੀ ਮੁਸਲੀ ਕਰ ਮੈ ਹਲੁ ਲੈ।","roman":"Saatki au barmaakrit oodhav sree muslee kar mai halu lai |","meaning_en":"","page":563},{"gurmukhi":"ਬਸੁਦੇਵ ਤੇ ਆਦਿਕ ਬੀਰ ਜਿਤੇ ਤਿਹ ਆਗੇ ਕੀਯੋ ਬਲਿ ਕਉ ਦਲੁ ਦੈ।","roman":"Basudev te aadik beer jite tih aage keeyo bali kau dalu dai |","meaning_en":"","page":563},{"gurmukhi":"ਸਬ ਹੂੰ ਨ੍ਰਿਪ ਊਪਰਿ ਬਾਨਨ ਬ੍ਰਿਸਟ ਕਰੀ ਮਨ ਮੈ ਤਕਿ ਕੇ ਖਲੁ ਛੈ।","roman":"Sab hoon nrip oopri baanan brisat karee man mai taki ke khalu chhai |","meaning_en":"","page":563},{"gurmukhi":"ਸੁਰਰਾਜ ਪਠੇ ਗਿਰਿ ਗੋਧਨ ਪੈ ਰਿਸਿ ਮੇਘ ਮਨੋ ਬਰਖੈ ਬਲੁ ਕੈ। ੧੪੩੫।","roman":"Surraaj pathe giri godhan pai risi megh mano barkhai balu kai | 1435 |","meaning_en":"","page":563}]},{"type":"verse","number":[1436],"number_text":"੧੪੩੬।","page":563,"lines":[{"gurmukhi":"ਸਰ ਜਾਲ ਕਰਾਲ ਸਬੈ ਸਹਿ ਕੈ ਗਹਿ ਕੈ ਬਹੁਰੋ ਧਨੁ ਬਾਨ ਚਲਾਏ।","roman":"Sar jaal karaal sabai sahi kai gahi kai bahuro dhanu baan chalaae |","meaning_en":"","page":563},{"gurmukhi":"ਬਾਜ ਕਰੇ ਸਭਹੂੰਨ ਕੇ ਘਾਇਲ ਸੂਤ ਸਬੈ ਤਿਨ ਕੇ ਰਨਿ ਘਾਏ।","roman":"Baaj kare sabhhoonn ke ghaail soot sabai tin ke rani ghaae |","meaning_en":"","page":563},{"gurmukhi":"ਪੈਦਲ ਕੇ ਦਲ ਮਾਝਿ ਪਰਿਓ ਤੇਈ ਬਾਨਨ ਸੋ ਜਮੁਲੋਕਿ ਪਠਾਏ।","roman":"Paidal ke dal maajhi pario te'ee baanan so jamuloki pathaae |","meaning_en":"","page":563},{"gurmukhi":"ਸ੍ਯੰਦਨ ਕਾਟਿ ਦਯੋ ਬਹੁਰੋ ਸਭ ਹ੍ਵੈ ਬਿਰਥੀ ਜਦੁਬੰਸ ਪਰਾਏ। ੧੪੩੬।","roman":"Syandan kaati dayo bahuro sabh hvai birthee jadubans paraae | 1436 |","meaning_en":"","page":563}]},{"type":"verse","number":[1437],"number_text":"੧੪੩੭।","page":564,"lines":[{"gurmukhi":"ਕਾਹੇ ਕਉ ਭਜਤ ਹੋ ਰਨ ਤੇ ਬਲਿ ਜੁਧ ਸਮੋ ਪੁਨਿ ਐਸੇ ਨ ਪੈ ਹੈ।","roman":"Kaahe kau bhajat ho ran te bali judh samo puni aise na pai hai |","meaning_en":"","page":564},{"gurmukhi":"ਸਾਤਕਿ ਸੋ ਖੜਗੇਸ ਕਹਿਓ ਅਬ ਭਾਜਹੁ ਤੈ ਕਛੁ ਲਾਜ ਰਹੈ ਹੈ।","roman":"Saatki so kharges kahio ab bhaajhu tai kachhu laaj rahai hai |","meaning_en":"","page":564},{"gurmukhi":"ਜਉ ਕਹੂੰ ਅਉਰ ਸਮਾਜ ਮੈ ਜਾਇ ਹੋ ਸੋ ਵਹੁ ਕਾਇਰ ਰਾਜ ਵਹੈ ਹੈ।","roman":"Jau kahoon aur samaaj mai jaai ho so vahu kaair raaj vahai hai |","meaning_en":"","page":564},{"gurmukhi":"ਤਾ ਤੇ ਬਿਚਾਰ ਕੈ ਆਨਿ ਭਿਰੋ ਕਿਨ ਭਾਜ ਕੈ ਕਾ ਮੁਖੁ ਲੈ ਘਰਿ ਜੈ ਹੈ। ੧੪੩੭।","roman":"Taa te bichaar kai aani bhiro kin bhaaj kai kaa mukhu lai ghari jai hai | 1437 |","meaning_en":"","page":564}]},{"type":"verse","number":[1438],"number_text":"੧੪੩੮।","page":564,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਸੂਰ ਨ ਕੋਊ ਫਿਰਿਯੋ ਰਿਸ ਕੈ ਅਰਿ ਕੈ ਨ੍ਰਿਪ ਪਾਛੈ ਧਯੋ ਹੈ।","roman":"Yau suni soor na ko'oo phiriyo ris kai ari kai nrip paachhai dhayo hai |","meaning_en":"","page":564},{"gurmukhi":"ਜਾਦਵ ਭਾਜਤ ਜੈਸੇ ਅਜਾ ਖੜਗੇਸ ਮਨੋ ਮ੍ਰਿਗਰਾਜ ਭਯੋ ਹੈ।","roman":"Jaadav bhaajat jaise ajaa kharges mano mrigraaj bhayo hai |","meaning_en":"","page":564},{"gurmukhi":"ਧਾਇ ਮਿਲਿਓ ਮੁਸਲੀਧਰ ਕੋ ਤਨਿ ਕੰਠ ਬਿਖੈ ਧਨੁ ਡਾਰ ਲਯੋ ਹੈ।","roman":"Dhaai milio musleedhar ko tani kanth bikhai dhanu daar layo hai |","meaning_en":"","page":564},{"gurmukhi":"ਤਉ ਹਸਿ ਕੈ ਅਪਨੇ ਬਸ ਕੈ ਬਲਦੇਵਹਿ ਕਉ ਤਬ ਛਾਡਿ ਦਯੋ ਹੈ। ੧੪੩੮।","roman":"Tau hasi kai apne bas kai baldevhi kau tab chhaadi dayo hai | 1438 |","meaning_en":"","page":564}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":564},{"type":"verse","number":[1439],"number_text":"੧੪੩੯।","page":564,"lines":[{"gurmukhi":"ਜਬ ਸਬ ਹੀ ਭਟ ਭਾਜ ਕੈ ਗਏ ਸਰਨਿ ਬ੍ਰਿਜ ਰਾਇ।","roman":"Jab sab hee bhat bhaaj kai gae sarni brij raai |","meaning_en":"","page":564},{"gurmukhi":"ਤਬ ਜਦੁਪਤਿ ਸਬ ਜਾਦਵਨ ਕੀਨੋ ਏਕ ਉਪਾਇ। ੧੪੩੯।","roman":"Tab jadupti sab jaadvan keeno ek upaai | 1439 |","meaning_en":"","page":564}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":564},{"type":"verse","number":[1440],"number_text":"੧੪੪੦।","page":564,"lines":[{"gurmukhi":"ਘੇਰਹਿ ਯਾਹਿ ਸਬੈ ਮਿਲਿ ਕੈ ਹਮ ਐਸੇ ਬਿਚਾਰਿ ਸਬੈ ਭਟ ਧਾਏ।","roman":"Gherhi yaahi sabai mili kai ham aise bichaari sabai bhat dhaae |","meaning_en":"","page":564},{"gurmukhi":"ਆਗੇ ਕੀਓ ਬ੍ਰਿਜ ਭੂਖਨ ਕਉ ਸਬ ਪਾਛੇ ਭਏ ਮਨ ਕੋਪੁ ਬਢਾਏ।","roman":"Aage keeo brij bhookhan kau sab paachhe bhae man kopu badhaae |","meaning_en":"","page":564},{"gurmukhi":"ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਤਾਨ ਕਮਾਨਨ ਯੌ ਨ੍ਰਿਪ ਊਪਰਿ ਬਾਨ ਚਲਾਏ।","roman":"Kaan pramaan lau taan kamaanan yau nrip oopri baan chalaae |","meaning_en":"","page":564},{"gurmukhi":"ਮਾਨਹੁ ਪਾਵਸ ਕੀ ਰਿਤੁ ਮੈ ਘਨ ਬੂੰਦਨ ਜਿਉ ਸਰ ਤਿਉ ਬਰਖਾਏ। ੧੪੪੦।","roman":"Maanhu paavas kee ritu mai ghan boondan jiu sar tiu barkhaae | 1440 |","meaning_en":"","page":564}]},{"type":"verse","number":[1441],"number_text":"੧੪੪੧।","page":564,"lines":[{"gurmukhi":"ਕਾਟਿ ਕੈ ਬਾਨ ਸਬੈ ਤਿਨ ਕੇ ਅਪੁਨੇ ਸਰ ਸ੍ਰੀ ਹਰਿ ਕੇ ਤਨ ਘਾਏ।","roman":"Kaati kai baan sabai tin ke apune sar sree hari ke tan ghaae |","meaning_en":"","page":564},{"gurmukhi":"ਘਾਇਨ ਤੇ ਬਹੁ ਸ੍ਰਉਨ ਬਹਿਓ ਤਬ ਸ੍ਰੀਪਤਿ ਕੇ ਪਗ ਨ ਠਹਰਾਏ।","roman":"Ghaain te bahu sraun bahio tab sreepti ke pag na thahraae |","meaning_en":"","page":564},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਬਰਬੀਰ ਹੁਤੇ ਰਨ ਦੇਖਿ ਕੈ ਭੂਪਤਿ ਕੋ ਬਿਸਮਾਏ।","roman":"Aur jite barbeer hute ran dekhi kai bhoopti ko bismaae |","meaning_en":"","page":564},{"gurmukhi":"ਧੀਰ ਨ ਕਾਹੂੰ ਸਰੀਰ ਰਹਿਓ ਜਦੁਬੀਰ ਤੇ ਆਦਿਕ ਬੀਰ ਪਰਾਏ। ੧੪੪੧।","roman":"Dheer na kaahoon sareer rahio jadubeer te aadik beer paraae | 1441 |","meaning_en":"","page":564}]},{"type":"verse","number":[1442],"number_text":"੧੪੪੨।","page":564,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੇ ਭਾਜਤ ਹੀ ਛੁਟ ਧੀਰ ਗਯੋ ਬਰ ਬੀਰਨ ਕੋ।","roman":"Sree jadubeer ke bhaajat hee chhut dheer gayo bar beeran ko |","meaning_en":"","page":564},{"gurmukhi":"ਅਤਿ ਬਿਆਕੁਲ ਬੁਧਿ ਨਿਰਾਕੁਲ ਹ੍ਵੈ ਲਖਿ ਲਾਗੇ ਹੈ ਘਾਇ ਸਰੀਰਨ ਕੋ।","roman":"Ati biaakul budhi niraakul hvai lakhi laage hai ghaai sareeran ko |","meaning_en":"","page":564},{"gurmukhi":"ਸੁ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਭਾਜਿ ਚਲੇ ਡਰੁ ਮਾਨਿ ਘਨੋ ਅਰਿ ਤੀਰਨ ਕੋ।","roman":"Su dhavaai kai syandan bhaaji chale daru maani ghano ari teeran ko |","meaning_en":"","page":564},{"gurmukhi":"ਮਨ ਆਪਨੇ ਕੋ ਸਮਝਾਵਤ ਸਿਆਮ ਤੈ ਕੀਨੋ ਹੈ ਕਾਮੁ ਅਹੀਰਨ ਕੋ। ੧੪੪੨।","roman":"Man aapne ko samjhaavat siaam tai keeno hai kaamu aheeran ko | 1442 |","meaning_en":"","page":564}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":564},{"type":"verse","number":[1443],"number_text":"੧੪੪੩।","page":564,"lines":[{"gurmukhi":"ਨਿਜ ਮਨ ਕੋ ਸਮਝਾਇ ਕੈ ਬਹੁਰਿ ਫਿਰੇ ਘਨ ਸ੍ਯਾਮ।","roman":"Nij man ko samjhaai kai bahuri phire ghan syaam |","meaning_en":"","page":564},{"gurmukhi":"ਜਾਦਵ ਸੈਨਾ ਸੰਗਿ ਲੈ ਪੁਨਿ ਆਏ ਰਨ ਧਾਮ। ੧੪੪੩।","roman":"Jaadav sainaa sangi lai puni aae ran dhaam | 1443 |","meaning_en":"","page":564}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","gurmukhi":"ਕਾਨ੍ਹ ਜੂ ਬਾਚ","roman":"Kaanh joo baach","meaning_en":"","page":565},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":565},{"type":"verse","number":[1444],"number_text":"੧੪੪੪।","page":565,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਕੋ ਹਰਿ ਕਹਿਓ ਅਬ ਤੂ ਖੜਗ ਸੰਭਾਰੁ।","roman":"Kharag singh ko hari kahio ab too kharag sanbhaaru |","meaning_en":"","page":565},{"gurmukhi":"ਜਾਮ ਦਿਵਸ ਕੇ ਰਹਤ ਹੀ ਡਾਰੋ ਤੋਹਿ ਸੰਘਾਰਿ। ੧੪੪੪।","roman":"Jaam divas ke rahat hee daaro tohi sanghaari | 1444 |","meaning_en":"","page":565}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":565},{"type":"verse","number":[1445],"number_text":"੧੪੪੫।","page":565,"lines":[{"gurmukhi":"ਕੋਪ ਕੈ ਬੈਨ ਕਹੈ ਖੜਗੇਸ ਕੋ ਸ੍ਰੀ ਹਰਿ ਜੂ ਧਨੁ ਬਾਨਨ ਲੈ ਕੈ।","roman":"Kop kai bain kahai kharges ko sree hari joo dhanu baanan lai kai |","meaning_en":"","page":565},{"gurmukhi":"ਚਾਮ ਕੇ ਦਾਮ ਚਲਾਇ ਲਏ ਤੁਮ ਹੂੰ ਰਨ ਮੈ ਮਨ ਕੋ ਨਿਰਭੈ ਕੈ।","roman":"Chaam ke daam chalaai lae tum hoon ran mai man ko nirbhai kai |","meaning_en":"","page":565},{"gurmukhi":"ਮਤਿ ਕਰੀ ਗਰਬੈ ਤਬ ਲਉ ਜਬ ਲਉ ਮ੍ਰਿਗਰਾਜ ਗਹਿਓ ਨ ਰਿਸੈ ਕੈ।","roman":"Mati karee garbai tab lau jab lau mrigraaj gahio na risai kai |","meaning_en":"","page":565},{"gurmukhi":"ਕਾਹੇ ਕਉ ਪ੍ਰਾਨਨ ਸੋ ਧਨ ਖੋਵਤ ਜਾਹੁ ਭਲੇ ਹਥਿਯਾਰਨ ਦੈ ਕੈ। ੧੪੪੫।","roman":"Kaahe kau praanan so dhan khovat jaahu bhale hathiyaaran dai kai | 1445 |","meaning_en":"","page":565}]},{"type":"verse","number":[1446],"number_text":"੧੪੪੬।","page":565,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਹਰਿ ਕੀ ਬਤੀਆ ਤਬ ਹੀ ਨ੍ਰਿਪ ਉਤਰ ਦੇਤ ਭਯੋ ਹੈ।","roman":"Yau suni kai hari kee bateeaa tab hee nrip utar det bhayo hai |","meaning_en":"","page":565},{"gurmukhi":"ਕਾਹੇ ਕਉ ਸੋਰ ਕਰੈ ਰਨ ਮੈ ਬਨ ਮੈ ਜਨੁ ਕਾਹੂ ਨੇ ਲੂਟਿ ਲਯੋ ਹੈ।","roman":"Kaahe kau sor karai ran mai ban mai janu kaahoo ne looti layo hai |","meaning_en":"","page":565},{"gurmukhi":"ਬੋਲਤ ਹੋ ਹਠਿ ਕੈ ਸਠਿ ਜਿਉ ਹਮ ਤੇ ਕਈ ਬਾਰਨ ਭਾਜ ਗਯੋ ਹੈ।","roman":"Bolat ho hathi kai sathi jiu ham te kaee baaran bhaaj gayo hai |","meaning_en":"","page":565},{"gurmukhi":"ਨਾਮ ਪਰਿਓ ਬ੍ਰਿਜਰਾਜ ਬ੍ਰਿਥਾ ਬਿਨ ਲਾਜ ਸਮਾਜ ਮੈ ਆਜੁ ਖਯੋ ਹੈ। ੧੪੪੬।","roman":"Naam pario brijraaj brithaa bin laaj samaaj mai aaju khayo hai | 1446 |","meaning_en":"","page":565}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ","roman":"Kharges baach","meaning_en":"","page":565},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":565},{"type":"verse","number":[1447],"number_text":"੧੪੪੭।","page":565,"lines":[{"gurmukhi":"ਕਾਹੇ ਕਉ ਕ੍ਰੋਧ ਸੋ ਜੁਧੁ ਕਰੋ ਹਰਿ ਜਾਹੁ ਭਲੇ ਦਿਨ ਕੋ ਇਕੁ ਜੀਜੈ।","roman":"Kaahe kau krodh so judhu karo hari jaahu bhale din ko iku jeejai |","meaning_en":"","page":565},{"gurmukhi":"ਬੈਸ ਕਿਸੋਰ ਮਨੋਹਰਿ ਮੂਰਤਿ ਆਨਨ ਮੈ ਅਬ ਹੀ ਮਸ ਭੀਜੈ।","roman":"Bais kisor manohri moorti aanan mai ab hee mas bheejai |","meaning_en":"","page":565},{"gurmukhi":"ਜਾਈਐ ਧਾਮਿ ਸੁਨੋ ਘਨਿ ਸ੍ਯਾਮ ਬਿਸ੍ਰਾਮ ਕਰੋ ਸੁਖ ਅੰਮ੍ਰਿਤ ਪੀਜੈ।","roman":"Jaaeeai dhaami suno ghani syaam bisraam karo sukh anmrit peejai |","meaning_en":"","page":565},{"gurmukhi":"ਨਾਹਕ ਪ੍ਰਾਨ ਤਜੋ ਰਨ ਮੈ ਅਪੁਨੇ ਪਿਤ ਮਾਤ ਅਨਾਥ ਨ ਕੀਜੈ। ੧੪੪੭।","roman":"Naahak praan tajo ran mai apune pit maat anaath na keejai | 1447 |","meaning_en":"","page":565}]},{"type":"verse","number":[1448],"number_text":"੧੪੪੮।","page":565,"lines":[{"gurmukhi":"ਕਾਹੇ ਕਉ ਕਾਨ੍ਹ ਅਯੋਧਨ ਮੈ ਹਠ ਕੈ ਹਮ ਸੋ ਰਨ ਦੁੰਦ ਮਚੈ ਹੋ।","roman":"Kaahe kau kaanh ayodhan mai hath kai ham so ran dund machai ho |","meaning_en":"","page":565},{"gurmukhi":"ਜੁਧ ਕੀ ਬਾਤ ਬੁਰੀ ਸਬ ਤੇ ਹਰਿ ਕ੍ਰੁਧ ਕੀਏ ਨ ਕਛੂ ਫਲੁ ਪੈ ਹੋ।","roman":"Judh kee baat buree sab te hari krudh kee'e na kachhoo phalu pai ho |","meaning_en":"","page":565},{"gurmukhi":"ਜਾਨਤ ਹੋ ਅਬ ਯਾ ਰਨ ਮੈ ਹਮ ਸੋ ਲਰਿ ਕੈ ਤੁਮ ਜੀਤ ਨ ਜੈ ਹੋ।","roman":"Jaanat ho ab yaa ran mai ham so lari kai tum jeet na jai ho |","meaning_en":"","page":565},{"gurmukhi":"ਜਾਹੁ ਤੋ ਭਾਜ ਕੈ ਜਾਹੁ ਅਬੈ ਨਹੀ ਅੰਤ ਕੋ ਅੰਤ ਕੇ ਧਾਮਿ ਸਿਧੈ ਹੋ। ੧੪੪੮।","roman":"Jaahu to bhaaj kai jaahu abai nahee ant ko ant ke dhaami sidhai ho | 1448 |","meaning_en":"","page":565}]},{"type":"verse","number":[1449],"number_text":"੧੪੪੯।","page":565,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਹਰਿ ਚਾਪ ਲਯੋ ਕਰਿ ਤਾਨ ਕੈ ਬਾਨ ਕਉ ਖੈਚ ਚਲਾਯੋ।","roman":"Yau suni kai hari chaap layo kari taan kai baan kau khaich chalaayo |","meaning_en":"","page":565},{"gurmukhi":"ਭੂਪਤਿ ਕਉ ਹਰਿ ਘਾਇਲ ਕੀਨੋ ਹੈ ਸ੍ਰੀਪਤ ਕਉ ਨ੍ਰਿਪ ਘਾਇ ਲਗਾਯੋ।","roman":"Bhoopti kau hari ghaail keeno hai sreepat kau nrip ghaai lagaayo |","meaning_en":"","page":565},{"gurmukhi":"ਬੀਰ ਦੁਹੂੰ ਤਿਹ ਠਉਰ ਬਿਖੈ ਕਬਿ ਰਾਮ ਭਨੈ ਅਤਿ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Beer duhoon tih thaur bikhai kabi raam bhanai ati judhu machaayo |","meaning_en":"","page":565},{"gurmukhi":"ਬਾਨ ਅਪਾਰ ਚਲੇ ਦੁਹੂੰ ਓਰ ਤੇ ਅਭ੍ਰਨ ਜਿਉ ਦਿਵ ਮੰਡਲ ਛਾਯੋ। ੧੪੪੯।","roman":"Baan apaar chale duhoon or te abhran jiu div mandal chhaayo | 1449 |","meaning_en":"","page":565}]},{"type":"verse","number":[1450],"number_text":"੧੪੫੦।","page":566,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਸਹਾਇ ਕੇ ਕਾਜ ਜਿਨੋ ਬਰ ਬੀਰਨ ਤੀਰ ਚਲਾਏ।","roman":"Sree jadubeer sahaai ke kaaj jino bar beeran teer chalaae |","meaning_en":"","page":566},{"gurmukhi":"ਭੂਪਤਿ ਏਕ ਨ ਬਾਨ ਲਗਿਯੋ ਲਖਿ ਦੂਰਿ ਤੇ ਬਾਨਨ ਸੋ ਬਹੁ ਘਾਏ।","roman":"Bhoopti ek na baan lagiyo lakhi doori te baanan so bahu ghaae |","meaning_en":"","page":566},{"gurmukhi":"ਧਾਇ ਪਰੀ ਬਹੁ ਜਾਦਵ ਸੈਨ ਧਵਾਇ ਕੈ ਸ੍ਯੰਦਨ ਚਾਪ ਚਢਾਏ।","roman":"Dhaai paree bahu jaadav sain dhavaai kai syandan chaap chadhaae |","meaning_en":"","page":566},{"gurmukhi":"ਆਵਤ ਸ੍ਯਾਮ ਭਨੈ ਰਿਸ ਕੈ ਨ੍ਰਿਪ ਸੋ ਪਲ ਮੈ ਦਲ ਪੈਦਲ ਘਾਏ। ੧੪੫੦।","roman":"Aavat syaam bhanai ris kai nrip so pal mai dal paidal ghaae | 1450 |","meaning_en":"","page":566}]},{"type":"verse","number":[1451],"number_text":"੧੪੫੧।","page":566,"lines":[{"gurmukhi":"ਏਕ ਗਿਰੇ ਤਜਿ ਪ੍ਰਾਨਨ ਕੋ ਰਨ ਕੀ ਛਿਤ ਮੈ ਅਤਿ ਜੁਧੁ ਮਚੈ ਕੈ।","roman":"Ek gire taji praanan ko ran kee chhit mai ati judhu machai kai |","meaning_en":"","page":566},{"gurmukhi":"ਏਕ ਗਏ ਭਜਿ ਕੈ ਇਕ ਘਾਇਲ ਏਕ ਲਰੇ ਮਨਿ ਕੋਪੁ ਬਢੈ ਕੈ।","roman":"Ek gae bhaji kai ik ghaail ek lare mani kopu badhai kai |","meaning_en":"","page":566},{"gurmukhi":"ਤਉ ਨ੍ਰਿਪ ਲੈ ਕਰ ਮੈ ਕਰਵਾਰ ਦੀਯੋ ਬਹੁ ਖੰਡਨ ਖੰਡਨ ਕੈ ਕੈ।","roman":"Tau nrip lai kar mai karvaar deeyo bahu khandan khandan kai kai |","meaning_en":"","page":566},{"gurmukhi":"ਭੂਪ ਕੋ ਪਉਰਖ ਹੈ ਮਹਬੂਬ ਨਿਹਾਰ ਰਹੇ ਸਬ ਆਸਿਕ ਹ੍ਵੈ ਕੈ। ੧੪੫੧।","roman":"Bhoop ko paurakh hai mahboob nihaar rahe sab aasik hvai kai | 1451 |","meaning_en":"","page":566}]},{"type":"verse","number":[1452],"number_text":"੧੪੫੨।","page":566,"lines":[{"gurmukhi":"ਅਉਰ ਕਿਤੇ ਬਲਬੰਡ ਹੁਤੇ ਕਬਿ ਸ੍ਯਾਮ ਜਿਤੇ ਨ੍ਰਿਪ ਕੋਪਿ ਪਛਾਰੇ।","roman":"Aur kite balband hute kabi syaam jite nrip kopi pachhaare |","meaning_en":"","page":566},{"gurmukhi":"ਜੁਧ ਪ੍ਰਬੀਨ ਸੁ ਬੀਰ ਬਡੇ ਰਿਸਿ ਸਾਥ ਸੋਊ ਛਿਨ ਮਾਹਿ ਸੰਘਾਰੇ।","roman":"Judh prabeen su beer bade risi saath so'oo chhin maahi sanghaare |","meaning_en":"","page":566},{"gurmukhi":"ਸ੍ਯੰਦਨ ਕਾਟਿ ਦਏ ਤਿਨ ਕੇ ਗਜ ਬਾਜ ਘਨੇ ਸੰਗਿ ਬਾਨਨ ਮਾਰੇ।","roman":"Syandan kaati dae tin ke gaj baaj ghane sangi baanan maare |","meaning_en":"","page":566},{"gurmukhi":"ਰੁਦ੍ਰ ਕੋ ਖੇਲੁ ਕੀਯੋ ਰਨ ਮੈ ਜੇਊ ਜੀਵਤ ਤੇ ਤਜਿ ਜੁਧੁ ਪਧਾਰੇ। ੧੪੫੨।","roman":"Rudr ko khelu keeyo ran mai jeoo jeevat te taji judhu padhaare | 1452 |","meaning_en":"","page":566}]},{"type":"verse","number":[1453],"number_text":"੧੪੫੩।","page":566,"lines":[{"gurmukhi":"ਸੈਨ ਭਜਾਇ ਕੈ ਧਾਇ ਕੈ ਆਇ ਕੈ ਰਾਮ ਅਉ ਸ੍ਯਾਮ ਕੇ ਸਾਥ ਅਰਿਓ ਹੈ।","roman":"Sain bhajaai kai dhaai kai aai kai raam au syaam ke saath ario hai |","meaning_en":"","page":566},{"gurmukhi":"ਲੈ ਬਰਛਾ ਜਮਧਾਰ ਗਦਾ ਅਸਿ ਕ੍ਰੁਧ ਹ੍ਵੈ ਜੁਧ ਨਿਸੰਗ ਕਰਿਓ ਹੈ।","roman":"Lai barchhaa jamdhaar gadaa asi krudh hvai judh nisang kario hai |","meaning_en":"","page":566},{"gurmukhi":"ਤਉ ਬਹੁਰੋ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਧਨੁ ਬਾਨ ਸੰਭਾਰ ਕੈ ਪਾਨਿ ਧਰਿਓ ਹੈ।","roman":"Tau bahuro kabi syaam bhanai dhanu baan sanbhaar kai paani dhario hai |","meaning_en":"","page":566},{"gurmukhi":"ਜਿਉ ਘਨ ਬੂੰਦਨ ਤਿਉ ਸਰ ਸਿਉ ਕਮਲਾਪਤਿ ਕੋ ਤਨ ਤਾਲ ਭਰਿਓ ਹੈ। ੧੪੫੩।","roman":"Jiu ghan boondan tiu sar siu kamlaapti ko tan taal bhario hai | 1453 |","meaning_en":"","page":566}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":566},{"type":"verse","number":[1454],"number_text":"੧੪੫੪।","page":566,"lines":[{"gurmukhi":"ਬੇਧਿਓ ਜਬ ਤਨ ਕ੍ਰਿਸਨ ਰਿਸਿ ਇੰਦ੍ਰਾਸਤ੍ਰ ਸੰਧਾਨ।","roman":"Bedhio jab tan krisan risi indraasatr sandhaan |","meaning_en":"","page":566},{"gurmukhi":"ਮੰਤ੍ਰਨ ਸਿਉ ਅਭਿਮੰਤ੍ਰ ਕਰਿ ਗਹਿ ਧਨੁ ਛਾਡਿਓ ਬਾਨ। ੧੪੫੪।","roman":"Mantran siu abhimantr kari gahi dhanu chhaadio baan | 1454 |","meaning_en":"","page":566}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":566},{"type":"verse","number":[1455],"number_text":"੧੪੫੫।","page":566,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਤੇ ਆਦਿਕ ਬੀਰ ਜਿਤੇ ਤਬ ਹੀ ਸਰ ਛੂਟਤ ਭੂ ਪਰ ਆਏ।","roman":"Indr te aadik beer jite tab hee sar chhootat bhoo par aae |","meaning_en":"","page":566},{"gurmukhi":"ਰਾਮ ਭਨੈ ਅਗਨਾਯੁਧ ਲੈ ਨ੍ਰਿਪ ਕੋ ਲਖ ਕੈ ਕਰਿ ਕੋਪ ਚਲਾਏ।","roman":"Raam bhanai agnaayudh lai nrip ko lakh kai kari kop chalaae |","meaning_en":"","page":566},{"gurmukhi":"ਭੂਪ ਸਰਾਸਨ ਲੈ ਸੁ ਕਟੇ ਅਪਨੇ ਸਰ ਲੈ ਸੁਰ ਕੇ ਤਨ ਲਾਏ।","roman":"Bhoop saraasan lai su kate apne sar lai sur ke tan laae |","meaning_en":"","page":566},{"gurmukhi":"ਘਾਇਲ ਸ੍ਰਉਨ ਭਰੇ ਲਖਿ ਕੈ ਸੁਰ ਰਾਜ ਡਰੇ ਮਿਲਿ ਕੈ ਸਬ ਧਾਏ। ੧੪੫੫।","roman":"Ghaail sraun bhare lakhi kai sur raaj dare mili kai sab dhaae | 1455 |","meaning_en":"","page":566}]},{"type":"verse","number":[1456],"number_text":"੧੪੫੬।","page":567,"lines":[{"gurmukhi":"ਦੇਵ ਰਵਾਦਿਕ ਬੀਰ ਘਨੇ ਕਬਿ ਸ੍ਯਾਮ ਭਨੇ ਅਤਿ ਕੋਪ ਤਏ ਹੈ।","roman":"Dev ravaadik beer ghane kabi syaam bhane ati kop tae hai |","meaning_en":"","page":567},{"gurmukhi":"ਲੈ ਬਰਛੀ ਕਰਵਾਰ ਗਦਾ ਸੁ ਸਬੈ ਰਿਸਿ ਭੂਪ ਸੋ ਆਇ ਖਏ ਹੈ।","roman":"Lai barchhee karvaar gadaa su sabai risi bhoop so aai khae hai |","meaning_en":"","page":567},{"gurmukhi":"ਆਨਿ ਇਕਤ੍ਰ ਭਏ ਰਨ ਮੈ ਜਸੁ ਤਾ ਛਬਿ ਕੇ ਕਬਿ ਭਾਖ ਦਏ ਹੈ।","roman":"Aani ikatr bhae ran mai jasu taa chhabi ke kabi bhaakh dae hai |","meaning_en":"","page":567},{"gurmukhi":"ਭੂਪ ਕੇ ਬਾਨ ਸੁਗੰਧਿ ਕੇ ਲੈਬੇ ਕਉ ਭਉਰ ਮਨੋ ਇਕ ਠਉਰ ਭਏ ਹੈ। ੧੪੫੬।","roman":"Bhoop ke baan sugandhi ke laibe kau bhaur mano ik thaur bhae hai | 1456 |","meaning_en":"","page":567}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":567},{"type":"verse","number":[1457],"number_text":"੧੪੫੭।","page":567,"lines":[{"gurmukhi":"ਦੇਵਨ ਮਿਲਿ ਖੜਗੇਸ ਕਉ ਘੇਰਿ ਚਹੂੰ ਦਿਸਿ ਲੀਨ।","roman":"Devan mili kharges kau gheri chahoon disi leen |","meaning_en":"","page":567},{"gurmukhi":"ਤਬ ਭੂਪਤਿ ਧਨੁ ਬਾਨ ਲੈ ਕਹੋ ਜੁ ਪਉਰਖ ਕੀਨ। ੧੪੫੭।","roman":"Tab bhoopti dhanu baan lai kaho ju paurakh keen | 1457 |","meaning_en":"","page":567}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":567},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":567},{"type":"verse","number":[1458],"number_text":"੧੪੫੮।","page":567,"lines":[{"gurmukhi":"ਸੂਰ ਕੋ ਦ੍ਵਾਦਸ ਬਾਨਨ ਬੇਧਿ ਕੈ ਅਉ ਸਸਿ ਕੋ ਦਸ ਬਾਨ ਲਗਾਏ।","roman":"Soor ko dvaadas baanan bedhi kai au sasi ko das baan lagaae |","meaning_en":"","page":567},{"gurmukhi":"ਔਰ ਸਚੀਪਤਿ ਕਉ ਸਰ ਸਉ ਸੁ ਲਗੇ ਤਨ ਭੇਦ ਕੈ ਪਾਰ ਪਰਾਏ।","roman":"Aur sacheepti kau sar sau su lage tan bhed kai paar paraae |","meaning_en":"","page":567},{"gurmukhi":"ਜਛ ਜਿਤੇ ਸੁਰ ਕਿੰਨਰ ਗੰਧ੍ਰਬ ਤੇ ਸਬ ਤੀਰਨ ਸੋ ਨ੍ਰਿਪ ਘਾਏ।","roman":"Jachh jite sur kinnar gandhrab te sab teeran so nrip ghaae |","meaning_en":"","page":567},{"gurmukhi":"ਕੇਤਕ ਭਾਜਿ ਗਏ ਤੇ ਡਰਿ ਕੇਤਕਿ ਤਉ ਰਨ ਮੈ ਠਹਰਾਏ। ੧੪੫੮।","roman":"Ketak bhaaji gae te dari ketki tau ran mai thahraae | 1458 |","meaning_en":"","page":567}]},{"type":"verse","number":[1459],"number_text":"੧੪੫੯।","page":567,"lines":[{"gurmukhi":"ਜੁਧੁ ਭਯੋ ਸੁ ਘਨੋ ਜਬ ਹੀ ਤਬ ਇੰਦ੍ਰ ਰਿਸੇ ਕਰਿ ਸਾਂਗ ਲਈ ਹੈ।","roman":"Judhu bhayo su ghano jab hee tab indr rise kari saang laee hai |","meaning_en":"","page":567},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਬਲ ਕੋ ਕਰਿ ਕੈ ਤਿਹ ਭੂਪ ਕੈ ਊਪਰਿ ਡਾਰ ਦਈ ਹੈ।","roman":"Syaam bhanai bal ko kari kai tih bhoop kai oopri daar daee hai |","meaning_en":"","page":567},{"gurmukhi":"ਸ੍ਰੀ ਖੜਗੇਸ ਸਰਾਸਨ ਲੈ ਸਰ ਕਾਟਿ ਦਈ ਉਪਮਾ ਸੁ ਭਈ ਹੈ।","roman":"Sree kharges saraasan lai sar kaati daee upmaa su bhaee hai |","meaning_en":"","page":567},{"gurmukhi":"ਬਾਨ ਭਯੋ ਖਗਰਾਜ ਮਨੋ ਬਰਛੀ ਜਨੋ ਨਾਗਨਿ ਭਛ ਗਈ ਹੈ। ੧੪੫੯।","roman":"Baan bhayo khagraaj mano barchhee jano naagni bhachh gaee hai | 1459 |","meaning_en":"","page":567}]},{"type":"verse","number":[1460],"number_text":"੧੪੬੦।","page":567,"lines":[{"gurmukhi":"ਪੀੜਤ ਕੈ ਸਬ ਬਾਨਨ ਸੋ ਪੁਨਿ ਇੰਦ੍ਰ ਤੇ ਆਦਿਕ ਬੀਰ ਭਜਾਏ।","roman":"Peerat kai sab baanan so puni indr te aadik beer bhajaae |","meaning_en":"","page":567},{"gurmukhi":"ਸੂਰ ਸਸੀ ਰਨ੍ ਤ੍ਯਾਗਿ ਭਜੈ ਅਪਨੇ ਮਨ ਮੈ ਅਤਿ ਤ੍ਰਾਸ ਬਢਾਏ।","roman":"Soor sasee ran tyaagi bhajai apne man mai ati traas badhaae |","meaning_en":"","page":567},{"gurmukhi":"ਖਾਇ ਕੈ ਘਾਇ ਘਨੇ ਤਨ ਮੈ ਭਜ ਗੇ ਸਬ ਹੀ ਨ ਕੋਊ ਠਹਰਾਏ।","roman":"Khaai kai ghaai ghane tan mai bhaj ge sab hee na ko'oo thahraae |","meaning_en":"","page":567},{"gurmukhi":"ਜਾਇ ਬਸੇ ਅਪੁਨੇ ਪੁਰ ਮੈ ਸੁਰ ਸੋਕ ਭਰੇ ਸਬ ਲਾਜ ਲਜਾਏ। ੧੪੬੦।","roman":"Jaai base apune pur mai sur sok bhare sab laaj lajaae | 1460 |","meaning_en":"","page":567}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":567},{"type":"verse","number":[1461],"number_text":"੧੪੬੧।","page":567,"lines":[{"gurmukhi":"ਜਬੈ ਸਕਲ ਸੁਰ ਭਜਿ ਗਏ ਤਬ ਨ੍ਰਿਪ ਕੀਨੋ ਮਾਨ।","roman":"Jabai sakal sur bhaji gae tab nrip keeno maan |","meaning_en":"","page":567},{"gurmukhi":"ਧਨੁਖ ਤਾਨਿ ਕਰ ਮੈ ਪ੍ਰਬਲ ਹਰਿ ਪਰ ਮਾਰੇ ਬਾਨ। ੧੪੬੧।","roman":"Dhanukh taani kar mai prabal hari par maare baan | 1461 |","meaning_en":"","page":567}]},{"type":"verse","number":[1462],"number_text":"੧੪੬੨।","page":567,"lines":[{"gurmukhi":"ਤਬ ਹਰਿ ਰਿਸਿ ਕੈ ਕਰਿ ਲਯੋ ਰਾਛਸ ਅਸਤ੍ਰ ਸੰਧਾਨ।","roman":"Tab hari risi kai kari layo raachhas asatr sandhaan |","meaning_en":"","page":567},{"gurmukhi":"ਮੰਤ੍ਰਨ ਸਿਉ ਅਭਿਮੰਤ੍ਰ ਕਰਿ ਛਾਡਿਓ ਅਦਭੁਤ ਬਾਨ। ੧੪੬੨।","roman":"Mantran siu abhimantr kari chhaadio adbhut baan | 1462 |","meaning_en":"","page":567}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":568},{"type":"verse","number":[1463],"number_text":"੧੪੬੩।","page":568,"lines":[{"gurmukhi":"ਦੈਤ ਅਨੇਕ ਭਏ ਤਿਹ ਤੇ ਬਲਵੰਡ ਕੁਰੂਪ ਭਯਾਨਕ ਕੀਨੇ।","roman":"Dait anek bhae tih te balvand kuroop bhayaanak keene |","meaning_en":"","page":568},{"gurmukhi":"ਚਕ੍ਰ ਧਰੇ ਜਮਦਾਰ ਛੁਰੀ ਅਸਿ ਢਾਲ ਗਦਾ ਬਰਛੀ ਕਰਿ ਲੀਨੇ।","roman":"Chakr dhare jamdaar chhuree asi dhaal gadaa barchhee kari leene |","meaning_en":"","page":568},{"gurmukhi":"ਮੂਸਲ ਔਰ ਪਹਾਰ ਉਖਾਰਿ ਲੀਏ ਕਰ ਮੈ ਦ੍ਰੁਮ ਪਾਤਿ ਬਿਹੀਨੇ।","roman":"Moosal aur pahaar ukhaari lee'e kar mai drum paati biheene |","meaning_en":"","page":568},{"gurmukhi":"ਦਾਤਿ ਬਢਾਇ ਕੈ ਨੈਨ ਤਚਾਇ ਕੈ ਆਇ ਕੈ ਭੂਪਤਿ ਕੋ ਭਯ ਦੀਨੇ। ੧੪੬੩।","roman":"Daati badhaai kai nain tachaai kai aai kai bhoopti ko bhay deene | 1463 |","meaning_en":"","page":568}]},{"type":"verse","number":[1464],"number_text":"੧੪੬੪।","page":568,"lines":[{"gurmukhi":"ਕੇਸ ਬਡੇ ਸਿਰਿ ਬੇਸ ਬੁਰੇ ਅਰੁ ਦੇਹ ਮੈ ਰੋਮ ਬਡੇ ਜਿਨ ਕੇ।","roman":"Kes bade siri bes bure aru deh mai rom bade jin ke |","meaning_en":"","page":568},{"gurmukhi":"ਮੁਖ ਸੋ ਨਰ ਹਾਡਨ ਚਾਬਤ ਹੈ ਪੁਨਿ ਦਾਤ ਸੇ ਦਾਤ ਬਜੇ ਤਿਨ ਕੇ।","roman":"Mukh so nar haadan chaabat hai puni daat se daat baje tin ke |","meaning_en":"","page":568},{"gurmukhi":"ਸਰ ਸ੍ਰਉਨਤ ਕੇ ਅਖੀਆ ਜਿਨ ਕੀ ਸੰਗ ਕੌਨ ਭਿਰੈ ਬਲ ਕੈ ਇਨ ਕੇ।","roman":"Sar sraunat ke akheeaa jin kee sang kaun bhirai bal kai in ke |","meaning_en":"","page":568},{"gurmukhi":"ਸਰ ਚਾਪ ਚਢਾਇ ਕੈ ਰੈਨ ਫਿਰੈ ਸਬ ਕਾਮ ਕਰੈ ਨਿਤ ਪਾਪਨ ਕੇ। ੧੪੬੪।","roman":"Sar chaap chadhaai kai rain phirai sab kaam karai nit paapan ke | 1464 |","meaning_en":"","page":568}]},{"type":"verse","number":[1465],"number_text":"੧੪੬੫।","page":568,"lines":[{"gurmukhi":"ਧਾਇ ਪਰੇ ਮਿਲ ਕੈ ਉਤਰ ਰਾਛਸ ਭੂਪ ਇਤੇ ਥਿਰ ਠਾਢੋ ਰਹਿਓ ਹੈ।","roman":"Dhaai pare mil kai utar raachhas bhoop ite thir thaadho rahio hai |","meaning_en":"","page":568},{"gurmukhi":"ਡਾਢ ਸੁ ਕੈ ਅਪਨੇ ਮਨ ਕੋ ਰਿਸਿ ਸਤ੍ਰਨ ਕੋ ਇਹ ਭਾਤਿ ਕਹਿਓ ਹੈ।","roman":"Daadh su kai apne man ko risi satran ko ih bhaati kahio hai |","meaning_en":"","page":568},{"gurmukhi":"ਆਜ ਸਬੈ ਹਨਿ ਹੋ ਰਨ ਮੈ ਕਹਿ ਯੌ ਬਤੀਯਾ ਧਨੁ ਬਾਨ ਗਹਿਓ ਹੈ।","roman":"Aaj sabai hani ho ran mai kahi yau bateeyaa dhanu baan gahio hai |","meaning_en":"","page":568},{"gurmukhi":"ਯੌ ਨ੍ਰਿਪ ਕੋ ਅਤਿ ਧੀਰਜ ਪੇਖ ਕੈ ਦਾਨਵ ਕੋ ਦਲ ਰੀਝਿ ਰਹਿਓ ਹੈ। ੧੪੬੫।","roman":"Yau nrip ko ati dheeraj pekh kai daanav ko dal reejhi rahio hai | 1465 |","meaning_en":"","page":568}]},{"type":"verse","number":[1466],"number_text":"੧੪੬੬।","page":568,"lines":[{"gurmukhi":"ਤਾਨਿ ਕਮਾਨ ਮਹਾ ਬਲਵਾਨ ਸੁ ਸਤ੍ਰਨ ਕੋ ਬਹੁ ਬਾਨ ਚਲਾਏ।","roman":"Taani kamaan mahaa balvaan su satran ko bahu baan chalaae |","meaning_en":"","page":568},{"gurmukhi":"ਏਕਨ ਕੀ ਭੁਜ ਕਾਟਿ ਦਈ ਰਿਸਿ ਏਕਨ ਕੇ ਉਰ ਮੈ ਸਰ ਲਾਏ।","roman":"Ekan kee bhuj kaati daee risi ekan ke ur mai sar laae |","meaning_en":"","page":568},{"gurmukhi":"ਘਾਇਲ ਏਕ ਗਿਰੇ ਰਨ ਮੋ ਲਖਿ ਕਾਇਰ ਛਾਡਿ ਕੈ ਖੇਤ ਪਰਾਏ।","roman":"Ghaail ek gire ran mo lakhi kaair chhaadi kai khet paraae |","meaning_en":"","page":568},{"gurmukhi":"ਏਕ ਮਹਾ ਬਲਵੰਤ ਦਯੰਤ ਰਹੇ ਥਿਰ ਹ੍ਵੈ ਤਿਨ ਬੈਨ ਸੁਨਾਏ। ੧੪੬੬।","roman":"Ek mahaa balvant dayant rahe thir hvai tin bain sunaae | 1466 |","meaning_en":"","page":568}]},{"type":"verse","number":[1467],"number_text":"੧੪੬੭।","page":568,"lines":[{"gurmukhi":"ਕਾਹੇ ਕੋ ਜੂਝ ਕਰੇ ਸੁਨ ਰੇ ਨ੍ਰਿਪ ਤੋਹੂ ਕੋ ਜੀਵਤ ਜਾਨ ਨ ਦੈ ਹੈ।","roman":"Kaahe ko joojh kare sun re nrip tohoo ko jeevat jaan na dai hai |","meaning_en":"","page":568},{"gurmukhi":"ਦੀਰਘ ਦੇਹ ਸਲੋਨੀ ਸੀ ਮੂਰਤਿ ਤੋ ਸਮ ਭਛ ਕਹਾ ਹਮ ਪੈ ਹੈ।","roman":"Deeragh deh salonee see moorti to sam bhachh kahaa ham pai hai |","meaning_en":"","page":568},{"gurmukhi":"ਤੂ ਨਹੀ ਜਾਨਤ ਹੈ ਸੁਨ ਰੇ ਸਠ ਤੋ ਕਹੁ ਦਾਤਨ ਸਾਥ ਚਬੈ ਹੈ।","roman":"Too nahee jaanat hai sun re sath to kahu daatan saath chabai hai |","meaning_en":"","page":568},{"gurmukhi":"ਤੋਹੀ ਕੇ ਮਾਸ ਕੇ ਖੰਡਨ ਖੰਡ ਕੈ ਪਾਵਕ ਬਾਨ ਮੈ ਭੁੰਜ ਕੈ ਖੈ ਹੈ। ੧੪੬੭।","roman":"Tohee ke maas ke khandan khand kai paavak baan mai bhunj kai khai hai | 1467 |","meaning_en":"","page":568}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":568},{"type":"verse","number":[1468],"number_text":"੧੪੬੮।","page":568,"lines":[{"gurmukhi":"ਯੌ ਸੁਨ ਕੈ ਤਿਹ ਬੈਨ ਕੋ ਨ੍ਰਿਪ ਬੋਲਿਓ ਰਿਸ ਖਾਇ।","roman":"Yau sun kai tih bain ko nrip bolio ris khaai |","meaning_en":"","page":568},{"gurmukhi":"ਜੋ ਹਮ ਤੇ ਭਜਿ ਜਾਇ ਤਿਹ ਮਾਤਾ ਦੂਧ ਅਪਾਇ। ੧੪੬੮।","roman":"Jo ham te bhaji jaai tih maataa doodh apaai | 1468 |","meaning_en":"","page":568}]},{"type":"verse","number":[1469],"number_text":"੧੪੬੯।","page":568,"lines":[{"gurmukhi":"ਏਕੁ ਬੈਨ ਸੁਨਿ ਦਾਨਵੀ ਸੈਨ ਪਰੀ ਸਬ ਧਾਇ।","roman":"Eku bain suni daanvee sain paree sab dhaai |","meaning_en":"","page":568},{"gurmukhi":"ਚਹੂੰ ਓਰ ਘੇਰਿਓ ਨ੍ਰਿਪਤਿ ਖੇਤ ਬਾਰ ਕੀ ਨਿਆਇ। ੧੪੬੯।","roman":"Chahoon or gherio nripti khet baar kee niaai | 1469 |","meaning_en":"","page":568}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":569},{"type":"verse","number":[1470],"number_text":"੧੪੭੦।","page":569,"lines":[{"gurmukhi":"ਅਸੁਰਨ ਘੇਰ ਖੜਗ ਸਿੰਘ ਲੀਨੋ। ਤਬ ਨ੍ਰਿਪ ਕੋਪ ਘਨੋ ਮਨਿ ਕੀਨੋ।","roman":"Asuran gher kharag singh leeno | tab nrip kop ghano mani keeno |","meaning_en":"","page":569},{"gurmukhi":"ਧਨੁਖ ਬਾਨ ਕਰ ਬੀਚ ਸੰਭਾਰੇ। ਸਤ੍ਰ ਅਨੇਕ ਮਾਰ ਹੀ ਡਾਰੈ। ੧੪੭੦।","roman":"Dhanukh baan kar beech sanbhaare | satr anek maar hee daarai | 1470 |","meaning_en":"","page":569}]},{"type":"verse","number":[1471],"number_text":"੧੪੭੧।","page":569,"lines":[{"gurmukhi":"ਕ੍ਰੂਰ ਕਰਮ ਇਕ ਰਾਛਸ ਨਾਮਾ। ਜਿਨ ਜੀਤੇ ਆਗੇ ਸੰਗ੍ਰਾਮਾ।","roman":"Kroor karam ik raachhas naamaa | jin jeete aage sangraamaa |","meaning_en":"","page":569},{"gurmukhi":"ਸੋ ਤਬ ਹੀ ਨ੍ਰਿਪ ਸਾਮੁਹੇ ਗਯੋ। ਅਤਿ ਹੀ ਜੂਝ ਦੁਹੁਨ ਕੋ ਭਯੋ। ੧੪੭੧।","roman":"So tab hee nrip saamuhe gayo | ati hee joojh duhun ko bhayo | 1471 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":569},{"type":"verse","number":[1472],"number_text":"੧੪੭੨।","page":569,"lines":[{"gurmukhi":"ਆਯੁਧ ਲੈ ਸਬ ਹੀ ਆਪਣੇ ਜਬ ਹੀ ਵਹ ਭੂਪਤਿ ਸੰਗ ਅਰਿਓ ਹੈ।","roman":"Aayudh lai sab hee aapne jab hee vah bhoopti sang ario hai |","meaning_en":"","page":569},{"gurmukhi":"ਜੁਧ ਅਨੇਕ ਪ੍ਰਕਾਰ ਕੀਯੋ ਰਨ ਕੀ ਛਿਤ ਤੇ ਕੋਊ ਨਹਿ ਟਰਿਓ ਹੈ।","roman":"Judh anek prakaar keeyo ran kee chhit te ko'oo nahi tario hai |","meaning_en":"","page":569},{"gurmukhi":"ਤੌ ਨ੍ਰਿਪ ਲੈ ਕਰ ਮੈ ਅਸਿ ਕੋ ਰਿਪੁ ਮੂੰਡ ਕਟਿਓ ਗਿਰ ਭੂਮਿ ਪਰਿਓ ਹੈ।","roman":"Tau nrip lai kar mai asi ko ripu moond katio gir bhoomi pario hai |","meaning_en":"","page":569},{"gurmukhi":"ਦੇਹ ਛੁਟਿਯੋ ਨਹੀ ਕੋਪ ਹਟਿਓ ਨਿਜ ਓਠ ਕੇ ਦਾਤਨ ਸੋ ਪਕਰਿਓ ਹੈ। ੧੪੭੨।","roman":"Deh chhutiyo nahee kop hatio nij oth ke daatan so pakrio hai | 1472 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":569},{"type":"verse","number":[1473],"number_text":"੧੪੭੩।","page":569,"lines":[{"gurmukhi":"ਕ੍ਰ�ਰ ਕਰਮ ਕੋ ਖੜਗ ਸਿੰਘ ਜਬ ਮਾਰਿਓ ਰਨ ਠੌਰ।","roman":"Kra(?)ra karam ko kharag singh jab maario ran thaur |","meaning_en":"","page":569,"flags":[{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"}]},{"gurmukhi":"ਅਸੁਰਨ ਕੀ ਸੈਨਾ ਹੁਤੀ ਦਾਨਵ ਨਿਕਸਿਓ ਔਰ। ੧੪੭੩।","roman":"Asuran kee sainaa hutee daanav niksio aur | 1473 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":569},{"type":"verse","number":[1474],"number_text":"੧੪੭੪।","page":569,"lines":[{"gurmukhi":"ਕ੍ਰੂਰ ਦੈਤ ਜਿਹ ਨਾਮ ਵਡੋ ਦੈਤ ਬਲਵੰਡ ਅਤਿ।","roman":"Kroor dait jih naam vado dait balvand ati |","meaning_en":"","page":569},{"gurmukhi":"ਆਗੇ ਬਹੁ ਸੰਗ੍ਰਾਮ ਲਰਿਓ ਅਰਿਓ ਨਾਹਿਨ ਡਰਿਓ। ੧੪੭੪।","roman":"Aage bahu sangraam lario ario naahin dario | 1474 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":569},{"type":"verse","number":[1475],"number_text":"੧੪੭੫।","page":569,"lines":[{"gurmukhi":"ਕ੍ਰੂਰ ਕਰਮ ਬਧ ਨੈਨ ਨਿਹਾਰਿਓ। ਤਬ ਹੀ ਅਪਨੋ ਖੜਗ ਸੰਭਾਰਿਓ।","roman":"Kroor karam badh nain nihaario | tab hee apno kharag sanbhaario |","meaning_en":"","page":569},{"gurmukhi":"ਕ੍ਰੂਰ ਦੈਤ ਰਿਸਿ ਨ੍ਰਿਪ ਪਰ ਧਾਯੋ। ਮਾਨੋ ਕਾਲ ਮੇਘ ਉਮਡਾਯੋ। ੧੪੭੫।","roman":"Kroor dait risi nrip par dhaayo | maano kaal megh umdaayo | 1475 |","meaning_en":"","page":569}]},{"type":"verse","number":[1476],"number_text":"੧੪੭੬।","page":569,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਤਿਹ ਭੂਪ ਪਚਾਰਿਓ। ਜਾਹੁ ਕਹਾ ਮੁਝ ਬੰਧੁ ਪਛਾਰਿਓ।","roman":"Aavat hee tih bhoop pachaario | jaahu kahaa mujh bandhu pachhaario |","meaning_en":"","page":569},{"gurmukhi":"ਹਉ ਤੁਮ ਸੋ ਅਬ ਜੁਧ ਮਚੈ ਹੋ। ਭ੍ਰਾਤ ਗਯੋ ਜਹਿ ਤੋਹਿ ਪਠੈ ਹੋ। ੧੪੭੬।","roman":"Hau tum so ab judh machai ho | bhraat gayo jahi tohi pathai ho | 1476 |","meaning_en":"","page":569}]},{"type":"verse","number":[1477],"number_text":"੧੪੭੭।","page":569,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਤਬ ਖੜਗ ਸੰਭਾਰਿਓ। ਅਤਿ ਪ੍ਰਚੰਡ ਬਲ ਕੋਪਿ ਪ੍ਰਹਾਰਿਓ।","roman":"Yau kahi kai tab kharag sanbhaario | ati prachand bal kopi prahaario |","meaning_en":"","page":569},{"gurmukhi":"ਭੂਪਤਿ ਲਖਿਓ ਕਾਟਿ ਅਸਿ ਦੀਨੋ। ਸੋਊ ਮਾਰਿ ਰਨ ਭੀਤਰਿ ਲੀਨੋ। ੧੪੭੭।","roman":"Bhoopti lakhio kaati asi deeno | so'oo maari ran bheetri leeno | 1477 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":569},{"type":"verse","number":[1478],"number_text":"੧੪੭੮।","page":569,"lines":[{"gurmukhi":"ਕ੍ਰ�ਰ ਕਰਮ ਅਰੁ ਕ੍ਰ�ਰ ਦੈਤ ਦੋਊ ਗਏ ਜਹ ਧਾਮਿ।","roman":"Kra(?)ra karam aru kra(?)ra dait do'oo gae jah dhaami |","meaning_en":"","page":569,"flags":[{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"},{"code":"0xad","reason":"unresolved: draws an empty box in the PDF itself: the source font lacks this glyph"}]},{"gurmukhi":"ਸੈਨਾ ਤਿਨ ਕੀ ਸਸਤ੍ਰ ਲੈ ਘੇਰਿਓ ਨ੍ਰਿਪ ਸੰਗ੍ਰਾਮਿ। ੧੪੭੮।","roman":"Sainaa tin kee sasatr lai gherio nrip sangraami | 1478 |","meaning_en":"","page":569}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":570},{"type":"verse","number":[1479],"number_text":"੧੪੭੯।","page":570,"lines":[{"gurmukhi":"ਰੋਸ ਕੀਓ ਤਿਨ ਹੂੰ ਮਨ ਮੈ ਜੋਉ ਦੈਤ ਬਚੇ ਨ੍ਰਿਪ ਊਪਰ ਧਾਏ।","roman":"Ros keeo tin hoon man mai jou dait bache nrip oopar dhaae |","meaning_en":"","page":570},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਗਦਾ ਬਰਛੀ ਅਗਨਾਯੁਧ ਲੈ ਕਰਿ ਕੋਪ ਬਢਾਏ।","roman":"Baan kamaan gadaa barchhee agnaayudh lai kari kop badhaae |","meaning_en":"","page":570},{"gurmukhi":"ਤੌ ਨ੍ਰਿਪ ਤੀਰ ਸਰਾਸਨੁ ਲੈ ਸਭ ਆਵਤ ਬਾਟ ਮੈ ਕਾਟਿ ਗਿਰਾਏ।","roman":"Tau nrip teer saraasnu lai sabh aavat baat mai kaati giraae |","meaning_en":"","page":570},{"gurmukhi":"ਆਪਨੇ ਕਾਢਿ ਨਿਖੰਗਹੁ ਤੇ ਸਰ ਸਤ੍ਰਨ ਕੇ ਉਰ ਬੀਚ ਲਗਾਏ। ੧੪੭੯।","roman":"Aapne kaadhi nikhanghu te sar satran ke ur beech lagaae | 1479 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":570},{"type":"verse","number":[1480],"number_text":"੧੪੮੦।","page":570,"lines":[{"gurmukhi":"ਤਬ ਸਭ ਸਤ੍ਰ ਭਾਜ ਕੈ ਗਏ। ਕੋਊ ਸਨਮੁਖ ਹੋਤ ਨ ਪਏ।","roman":"Tab sabh satr bhaaj kai gae | ko'oo sanmukh hot na pae |","meaning_en":"","page":570},{"gurmukhi":"ਅਧਿਕ ਦੈਤ ਜਮ ਲੋਕਿ ਪਠਾਏ। ਜੀਅਤਿ ਰਹੇ ਰਨ ਤ੍ਯਾਗਿ ਪਰਾਏ। ੧੪੮੦।","roman":"Adhik dait jam loki pathaae | jeeati rahe ran tyaagi paraae | 1480 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":570},{"type":"verse","number":[1481],"number_text":"੧੪੮੧।","page":570,"lines":[{"gurmukhi":"ਭਾਜ ਗਏ ਸਬ ਦੈਤ ਜਬੈ ਤਬ ਭੂਪ ਰਿਸਿਓ ਹਰਿ ਕੋ ਸਰ ਮਾਰੇ।","roman":"Bhaaj gae sab dait jabai tab bhoop risio hari ko sar maare |","meaning_en":"","page":570},{"gurmukhi":"ਲਾਗਤ ਹੀ ਕਵਿ ਸ੍ਯਾਮ ਕਹੈ ਤਨ ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੋ ਚੀਰ ਪਧਾਰੇ।","roman":"Laagat hee kavi syaam kahai tan sree jadubeer ko cheer padhaare |","meaning_en":"","page":570},{"gurmukhi":"ਬੇਧਿ ਕੈ ਔਰਨ ਕੇ ਤਨ ਕੋ ਪੁਨਿ ਔਰਨ ਜਾਇ ਲਗੇ ਸੁ ਸੰਘਾਰੇ।","roman":"Bedhi kai auran ke tan ko puni auran jaai lage su sanghaare |","meaning_en":"","page":570},{"gurmukhi":"ਦੇਖਹੁ ਪਉਰਖ ਭੂਪਤਿ ਕੋ ਅਬ ਆਪ ਹੈ ਏਕ ਅਨੇਕ ਬਿਦਾਰੇ। ੧੪੮੧।","roman":"Dekhhu paurakh bhoopti ko ab aap hai ek anek bidaare | 1481 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":570},{"type":"verse","number":[1482],"number_text":"੧੪੮੨।","page":570,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਜਲ ਕੋ ਅਸਤ੍ਰ ਚਲਾਯੋ। ਸੋ ਛੁਟ ਕੈ ਨ੍ਰਿਪ ਊਪਰ ਆਯੋ।","roman":"Sree hari jal ko asatr chalaayo | so chhut kai nrip oopar aayo |","meaning_en":"","page":570},{"gurmukhi":"ਬਰੁਨ ਸਿੰਘ ਮੂਰਤਿ ਧਰਿ ਆਏ। ਸਰਿਤਨ ਕੀ ਸੈਨਾ ਸੰਗਿ ਲਿਯਾਏ। ੧੪੮੨।","roman":"Barun singh moorti dhari aae | saritan kee sainaa sangi liyaae | 1482 |","meaning_en":"","page":570}]},{"type":"verse","number":[1483],"number_text":"੧੪੮੩।","page":570,"lines":[{"gurmukhi":"ਆਵਤ ਸਿੰਘਨ ਸਬਦ ਸੁਨਾਯੋ। ਬਾਰਿ ਰਾਜ ਅਤਿ ਰਿਸ ਕਰਿ ਧਾਯੋ।","roman":"Aavat singhan sabad sunaayo | baari raaj ati ris kari dhaayo |","meaning_en":"","page":570},{"gurmukhi":"ਸੁਨਤ ਸਬਦ ਕਾਪੇ ਪੁਰ ਤੀਨੋ। ਇਨ ਨ੍ਰਿਪ ਮਨ ਮੈ ਤ੍ਰਾਸ ਨ ਕੀਨੋ। ੧੪੮੩।","roman":"Sunat sabad kaape pur teeno | in nrip man mai traas na keeno | 1483 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":570},{"type":"verse","number":[1484],"number_text":"੧੪੮੪।","page":570,"lines":[{"gurmukhi":"ਬਾਨਨ ਸੰਗ ਜਲਾਧਿਪ ਕੋ ਕਵਿ ਸ੍ਯਾਮ ਭਨੇ ਤਨ ਤਾੜਨ ਕੀਨੋ।","roman":"Baanan sang jalaadhip ko kavi syaam bhane tan taaran keeno |","meaning_en":"","page":570},{"gurmukhi":"ਸਾਤਹੁ ਸਿੰਧਨ ਕੋ ਰਿਸ ਕੈ ਸਰ ਜਾਲਨ ਸਿਉ ਉਰ ਛੇਦ ਕੈ ਦੀਨੋ।","roman":"Saathu sindhan ko ris kai sar jaalan siu ur chhed kai deeno |","meaning_en":"","page":570},{"gurmukhi":"ਘਾਇਲ ਹੈ ਸਰਿਤਾ ਸਗਰੀ ਬਹੁ ਸ੍ਰੋਨਤ ਸੋ ਤਿਹ ਕੋ ਅੰਗ ਭੀਨੋ।","roman":"Ghaail hai saritaa sagree bahu sronat so tih ko ang bheeno |","meaning_en":"","page":570},{"gurmukhi":"ਨੈਕੁ ਨ ਠਾਢੋ ਰਹਿਓ ਰਣ ਮੈ ਜਲ ਰਾਜ ਭਜਿਓ ਗ੍ਰਿਹ ਕੋ ਮਗੁ ਲੀਨੋ। ੧੪੮੪।","roman":"Naiku na thaadho rahio ran mai jal raaj bhajio grih ko magu leeno | 1484 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":570},{"type":"verse","number":[1485],"number_text":"੧੪੮੫।","page":570,"lines":[{"gurmukhi":"ਜਬੈ ਜਲਾਧਿਪ ਧਾਮਿ ਸਿਧਾਰੇ। ਤਬ ਹਰਿ ਕੋ ਨ੍ਰਿਪ ਪੁਨਿ ਸਰ ਮਾਰੇ।","roman":"Jabai jalaadhip dhaami sidhaare | tab hari ko nrip puni sar maare |","meaning_en":"","page":570},{"gurmukhi":"ਤਬ ਜਮ ਕੋ ਹਰਿ ਅਸਤ੍ਰ ਚਲਾਯੋ। ਹੈ ਪ੍ਰਤਛ ਜਮ ਨ੍ਰਿਪ ਪਰ ਧਾਯੋ। ੧੪੮੫।","roman":"Tab jam ko hari asatr chalaayo | hai pratachh jam nrip par dhaayo | 1485 |","meaning_en":"","page":570}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":571},{"type":"verse","number":[1486],"number_text":"੧੪੮੬।","page":571,"lines":[{"gurmukhi":"ਬੀਰ ਬਡੋ ਬਿਕ੍ਰਤ ਦੈਤ ਸੁ ਨਾਮਹਿ ਕੋਪ ਹੁਇ ਸ੍ਰੀ ਖੜਗੇਸ ਪੈ ਧਾਯੋ।","roman":"Beer bado bikrat dait su naamhi kop hui sree kharges pai dhaayo |","meaning_en":"","page":571},{"gurmukhi":"ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਬਰਛੀ ਕਰਿ ਲੈ ਅਤਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Baan kamaan kripaan gadaa barchhee kari lai ati judh machaayo |","meaning_en":"","page":571},{"gurmukhi":"ਤੀਰ ਚਲਾਵਤ ਭਯੋ ਬਹੁਰੋ ਤਬ ਤਾ ਛਬਿ ਕੋ ਕਵਿ ਭਾਵ ਸੁਨਾਯੋ।","roman":"Teer chalaavat bhayo bahuro tab taa chhabi ko kavi bhaav sunaayo |","meaning_en":"","page":571},{"gurmukhi":"ਭੂਪ ਕੋ ਬਾਨ ਮਨੋ ਖਗਰਾਜ ਕਟਿਓ ਅਰਿ ਕੋ ਸਰ ਨਾਗ ਗਿਰਾਯੋ। ੧੪੮੬।","roman":"Bhoop ko baan mano khagraaj katio ari ko sar naag giraayo | 1486 |","meaning_en":"","page":571}]},{"type":"verse","number":[1487],"number_text":"੧੪੮੭।","page":571,"lines":[{"gurmukhi":"ਬਿਕ੍ਰਤ ਦੈਤ ਕੋ ਨ੍ਰਿਪ ਮਾਰਿ ਲਯੋ ਜਮੁ ਕੋ ਰਿਸ ਕੈ ਪੁਨਿ ਉਤਰ ਦੀਨੋ।","roman":"Bikrat dait ko nrip maari layo jamu ko ris kai puni utar deeno |","meaning_en":"","page":571},{"gurmukhi":"ਕਾ ਭਯੋ ਜੋ ਜੀਅ ਮਾਰੇ ਘਨੇ ਅਰੁ ਦੰਡ ਬਡੋ ਕਰ ਮੈ ਤੁਮ ਲੀਨੋ।","roman":"Kaa bhayo jo jeea maare ghane aru dand bado kar mai tum leeno |","meaning_en":"","page":571},{"gurmukhi":"ਤੋਹਿ ਨ ਜੀਅਤ ਛਾਡਤ ਹੋ ਸੁਨ ਰੇ ਅਬ ਮੋਹਿ ਇਹੈ ਪ੍ਰਨ ਕੀਨੋ।","roman":"Tohi na jeeat chhaadat ho sun re ab mohi ihai pran keeno |","meaning_en":"","page":571},{"gurmukhi":"ਮਾਰਤ ਹੋ ਕਰ ਲੈ ਕਰਨੋ ਕਛੁ ਮੋ ਬਲ ਜਾਨਤ ਹੈ ਪੁਰ ਤੀਨੋ। ੧੪੮੭।","roman":"Maarat ho kar lai karno kachhu mo bal jaanat hai pur teeno | 1487 |","meaning_en":"","page":571}]},{"type":"verse","number":[1488],"number_text":"੧੪੮੮।","page":571,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਬਤੀਯਾ ਜਮ ਕੋ ਕਵਿ ਰਾਮ ਕਹੈ ਪੁਨਿ ਜੁਧ ਕੀਯੋ ਹੈ।","roman":"Yau kahi kai bateeyaa jam ko kavi raam kahai puni judh keeyo hai |","meaning_en":"","page":571},{"gurmukhi":"ਭੂਤ ਸ੍ਰਿਗਾਲਨ ਕਾਕਨ ਝਾਕਨਿ ਡਾਕਨਿ ਸ੍ਰੌਨ ਅਘਾਇ ਪੀਓ ਹੈ।","roman":"Bhoot srigaalan kaakan jhaakni daakni sraun aghaai peeo hai |","meaning_en":"","page":571},{"gurmukhi":"ਮਾਰਿਓ ਮਰੈ ਨ ਕਹੂੰ ਜਮ ਤੇ ਨ੍ਰਿਪ ਮਾਨਹੁ ਅਮ੍ਰਿਤ ਪਾਨ ਕੀਓ ਹੈ।","roman":"Maario marai na kahoon jam te nrip maanhu amrit paan keeo hai |","meaning_en":"","page":571},{"gurmukhi":"ਪਾਨਿ ਲੀਓ ਧਨੁ ਬਾਨ ਜਬੈ ਤਿਨ ਅੰਤਕ ਅੰਤ ਭਜਾਇ ਦੀਯੋ ਹੈ। ੧੪੮੮।","roman":"Paani leeo dhanu baan jabai tin antak ant bhajaai deeyo hai | 1488 |","meaning_en":"","page":571}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":571},{"type":"verse","number":[1489],"number_text":"੧੪੮੯।","page":571,"lines":[{"gurmukhi":"ਜਬ ਜਮ ਦੀਓ ਭਜਾਇ ਕ੍ਰਿਸਨ ਹੇਰਿ ਨ੍ਰਿਪ ਯੌ ਕਹਿਯੋ।","roman":"Jab jam deeo bhajaai krisan heri nrip yau kahiyo |","meaning_en":"","page":571},{"gurmukhi":"ਲਰਤੇ ਕਿਉ ਨਹੀ ਆਇ ਮਹਾਰਥੀ ਰਨ ਧੀਰ ਤੁਮ। ੧੪੮੯।","roman":"Larte kiu nahee aai mahaarthee ran dheer tum | 1489 |","meaning_en":"","page":571}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":571},{"type":"verse","number":[1490],"number_text":"੧੪੯੦।","page":571,"lines":[{"gurmukhi":"ਜੋ ਹਰਿ ਮੰਤ੍ਰ ਅਰਾਧਤ ਹੈ ਤਪ ਸਾਧਤ ਹੈ ਮਨ ਮੈ ਨਹੀ ਆਯੋ।","roman":"Jo hari mantr araadhat hai tap saadhat hai man mai nahee aayo |","meaning_en":"","page":571},{"gurmukhi":"ਜਗ੍ਯ ਕੀਏ ਬਹੁ ਦਾਨ ਦੀਏ ਸਬ ਖੋਜਤ ਹੈ ਕਿਨ ਹੂੰ ਨਹੀ ਪਾਯੋ।","roman":"Jagy kee'e bahu daan dee'e sab khojat hai kin hoon nahee paayo |","meaning_en":"","page":571},{"gurmukhi":"ਬ੍ਰਹਮ ਸਚੀਪਤਿ ਨਾਰਦ ਸਾਰਦ ਬਿਯਾਸ ਪਰਾਸੁਰ ਸ੍ਰੀ ਸੁਕ ਗਾਯੋ।","roman":"Braham sacheepti naarad saarad biyaas paraasur sree suk gaayo |","meaning_en":"","page":571},{"gurmukhi":"ਸੋ ਬ੍ਰਿਜਰਾਜ ਸਮਾਜ ਮੈ ਆਜ ਹਕਾਰ ਕੈ ਜੁਧ ਕੇ ਕਾਜ ਬੁਲਾਯੋ। ੧੪੯੦।","roman":"So brijraaj samaaj mai aaj hakaar kai judh ke kaaj bulaayo | 1490 |","meaning_en":"","page":571}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":571},{"type":"verse","number":[1491],"number_text":"੧੪੯੧।","page":571,"lines":[{"gurmukhi":"ਤਬ ਹਰਿ ਜਛ ਅਸਤ੍ਰ ਕਰਿ ਲੀਨੋ। ਐਚ ਕਮਾਨ ਛਾਡਿ ਸਰ ਦੀਨੋ।","roman":"Tab hari jachh asatr kari leeno | aich kamaan chhaadi sar deeno |","meaning_en":"","page":571},{"gurmukhi":"ਨਲ ਕੂਬਰ ਮਨਗ੍ਰੀਵ ਸੁ ਧਾਏ। ਸੁਤ ਕੁਬੇਰ ਕੇ ਦ੍ਵੈ ਇਹ ਆਏ। ੧੪੯੧।","roman":"Nal koobar mangreev su dhaae | sut kuber ke dvai ih aae | 1491 |","meaning_en":"","page":571}]},{"type":"verse","number":[1492],"number_text":"੧੪੯੨।","page":571,"lines":[{"gurmukhi":"ਧਨਦ ਜਛ ਕਿੰਨਰ ਸੰਗ ਲੀਨੇ। ਏ ਆਏ ਮਨ ਮੈ ਰਿਸ ਕੀਨੇ।","roman":"Dhanad jachh kinnar sang leene | e aae man mai ris keene |","meaning_en":"","page":571},{"gurmukhi":"ਸਗਲ ਸੈਨ ਤਿਨ ਕੈ ਸੰਗ ਆਈ। ਧਾਇ ਭੂਪ ਸੋ ਕਰੀ ਲਰਾਈ। ੧੪੯੨।","roman":"Sagal sain tin kai sang aaee | dhaai bhoop so karee laraaee | 1492 |","meaning_en":"","page":571}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":572},{"type":"verse","number":[1493],"number_text":"੧੪੯੩।","page":572,"lines":[{"gurmukhi":"ਕੋਪ ਕੀਏ ਸਬ ਸਸਤ੍ਰ ਲੀਏ ਕਰ ਮੈ ਮਿਲ ਕੈ ਤਿਹ ਪੈ ਤਬ ਆਏ।","roman":"Kop kee'e sab sasatr lee'e kar mai mil kai tih pai tab aae |","meaning_en":"","page":572},{"gurmukhi":"ਭੂਪ ਨਿਖੰਗ ਤੇ ਕਾਢ ਕੈ ਬਾਨ ਕਮਾਨ ਕੋ ਤਾਨਿ ਸੁ ਖੈਚ ਚਲਾਏ।","roman":"Bhoop nikhang te kaadh kai baan kamaan ko taani su khaich chalaae |","meaning_en":"","page":572},{"gurmukhi":"ਹੋਤ ਭਏ ਬਿਰਥੀ ਬਿਨੁ ਸੂਤ ਘਨੇ ਤਬ ਹੀ ਜਮਲੋਕਿ ਪਠਾਏ।","roman":"Hot bhae birthee binu soot ghane tab hee jamloki pathaae |","meaning_en":"","page":572},{"gurmukhi":"ਠਾਢੋ ਨ ਕੋਊ ਰਹਿਓ ਤਿਹ ਠੌਰ ਸਬੈ ਗਨ ਕਿੰਨਰ ਜਛ ਪਰਾਏ। ੧੪੯੩।","roman":"Thaadho na ko'oo rahio tih thaur sabai gan kinnar jachh paraae | 1493 |","meaning_en":"","page":572}]},{"type":"verse","number":[1494],"number_text":"੧੪੯੪।","page":572,"lines":[{"gurmukhi":"ਰੋਸ ਘਨੋ ਨਲ ਕੂਬਰ ਕੈ ਸੁ ਫਿਰਿਯੋ ਲਰਬੇ ਕਹੁ ਬੀਰ ਬੁਲਾਏ।","roman":"Ros ghano nal koobar kai su phiriyo larbe kahu beer bulaae |","meaning_en":"","page":572},{"gurmukhi":"ਸਉਹੇ ਕੁਬੇਰ ਭਯੋ ਧਨੁ ਲੈ ਸਰ ਜਛ ਜਿਤੇ ਮਿਲ ਕੈ ਪੁਨਿ ਆਏ।","roman":"Sauhe kuber bhayo dhanu lai sar jachh jite mil kai puni aae |","meaning_en":"","page":572},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰੇ ਸਬ ਹੀ ਕਰ ਮੈ ਅਸਿ ਲੈ ਚਮਕਾਏ।","roman":"Maar hee maar pukaari pare sab hee kar mai asi lai chamkaae |","meaning_en":"","page":572},{"gurmukhi":"ਮਾਨਹੁ ਸ੍ਰੀ ਖੜਗੇਸ ਕੇ ਊਪਰਿ ਦੰਡ ਲੀਏ ਜਮ ਕੇ ਗਨ ਧਾਏ। ੧੪੯੪।","roman":"Maanhu sree kharges ke oopri dand lee'e jam ke gan dhaae | 1494 |","meaning_en":"","page":572}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":572},{"type":"verse","number":[1495],"number_text":"੧੪੯੫।","page":572,"lines":[{"gurmukhi":"ਜਬ ਕੁਬੇਰ ਕੋ ਸਬ ਦਲੁ ਆਯੋ। ਤਬ ਨ੍ਰਿਪ ਮਨ ਮੈ ਕੋਪ ਬਢਾਯੋ।","roman":"Jab kuber ko sab dalu aayo | tab nrip man mai kop badhaayo |","meaning_en":"","page":572},{"gurmukhi":"ਨਿਜ ਕਰ ਮੈ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿਓ। ਅਗਨਤ ਦਲੁ ਇਕ ਪਲ ਮੈ ਮਾਰਿਓ। ੧੪੯੫।","roman":"Nij kar mai dhanu baan sanbhaario | agnat dalu ik pal mai maario | 1495 |","meaning_en":"","page":572}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":572},{"type":"verse","number":[1496],"number_text":"੧੪੯੬।","page":572,"lines":[{"gurmukhi":"ਜਛ ਸੈਨ ਬਲਬੰਡ ਨ੍ਰਿਪ ਜਮ ਪੁਰ ਦਈ ਪਠਾਇ।","roman":"Jachh sain balband nrip jam pur daee pathaai |","meaning_en":"","page":572},{"gurmukhi":"ਨਲ ਕੂਬਰ ਘਾਇਲ ਕੀਓ ਅਤਿ ਜੀਯ ਕੋਪੁ ਬਢਾਇ। ੧੪੯੬।","roman":"Nal koobar ghaail keeo ati jeey kopu badhaai | 1496 |","meaning_en":"","page":572}]},{"type":"verse","number":[1497],"number_text":"੧੪੯੭।","page":572,"lines":[{"gurmukhi":"ਜਬ ਕੁਬੇਰ ਕੇ ਉਰ ਬਿਖੈ ਮਾਰਿਓ ਤੀਛਨ ਬਾਨ।","roman":"Jab kuber ke ur bikhai maario teechhan baan |","meaning_en":"","page":572},{"gurmukhi":"ਲਾਗਤ ਸਰ ਕੇ ਸਟਕਿਓ ਛੂਟਿ ਗਯੋ ਸਬ ਮਾਨ। ੧੪੯੭।","roman":"Laagat sar ke satkio chhooti gayo sab maan | 1497 |","meaning_en":"","page":572}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":572},{"type":"verse","number":[1498],"number_text":"੧੪੯੮।","page":572,"lines":[{"gurmukhi":"ਸੈਨਾ ਸਹਿਤ ਸਬੈ ਭਜ ਗਯੋ। ਠਾਢੋ ਨ ਕੋ ਰਨ ਭੀਤਰ ਭਯੋ।","roman":"Sainaa sahit sabai bhaj gayo | thaadho na ko ran bheetar bhayo |","meaning_en":"","page":572},{"gurmukhi":"ਮਨਿ ਕੁਬੇਰ ਅਤਿ ਤ੍ਰਾਸ ਬਢਾਯੋ। ਜੁਧ ਕਰਨ ਚਿਤਿ ਬਹੁਰ ਨ ਭਾਯੋ। ੧੪੯੮।","roman":"Mani kuber ati traas badhaayo | judh karan chiti bahur na bhaayo | 1498 |","meaning_en":"","page":572}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":572},{"type":"verse","number":[1499],"number_text":"੧੪੯੯।","page":572,"lines":[{"gurmukhi":"ਭਾਜਿ ਜਛ ਸਬ ਗਏ ਤਬਹਿ ਹਰਿ ਮਹਾ ਬਲ।","roman":"Bhaaji jachh sab gae tabhi hari mahaa bal |","meaning_en":"","page":572},{"gurmukhi":"ਰੁਦ੍ਰ ਅਸਤ੍ਰ ਦੀਓ ਛਾਡ ਸੁ ਕੰਪਿਯੋ ਤਲ ਬਿਤਲ।","roman":"Rudr asatr deeo chhaad su kanpiyo tal bital |","meaning_en":"","page":572},{"gurmukhi":"ਤਬ ਸਿਵ ਜੂ ਉਠਿ ਧਾਏ ਸੂਲ ਸੰਭਾਰ ਕੈ।","roman":"Tab siv joo uthi dhaae sool sanbhaar kai |","meaning_en":"","page":572},{"gurmukhi":"ਹੋ ਕਿਉ ਹਰਿ ਸਿਮਰਿਓ ਹਮੈ ਇਹੈ ਜੀਅ ਧਾਰ ਕੈ। ੧੪੯੯।","roman":"Ho kiu hari simrio hamai ihai jeea dhaar kai | 1499 |","meaning_en":"","page":572}]},{"type":"verse","number":[1500],"number_text":"੧੫੦੦।","page":572,"lines":[{"gurmukhi":"ਸੰਗ ਰੁਦ੍ਰ ਕੈ ਰੁਦ੍ਰ ਚਲੇ ਭਟ ਉਠਿ ਤਬੈ।","roman":"Sang rudr kai rudr chale bhat uthi tabai |","meaning_en":"","page":572},{"gurmukhi":"ਏਕ ਰਦਨ ਜੂ ਚਲੇ ਸੰਗ ਲੈ ਦਲ ਸਬੈ।","roman":"Ek radan joo chale sang lai dal sabai |","meaning_en":"","page":572},{"gurmukhi":"ਔਰ ਸਕਲ ਗਨ ਚਲੈ ਸੁ ਸਸਤ੍ਰ ਸੰਭਾਰ ਕੈ।","roman":"Aur sakal gan chalai su sasatr sanbhaar kai |","meaning_en":"","page":572},{"gurmukhi":"ਹੈ ਕੌਨ ਅਜਿਤ ਪ੍ਰਗਟਿਓ ਭਵ ਕਹੈ ਬਿਚਾਰ ਕੈ। ੧੫੦੦।","roman":"Hai kaun ajit pragtio bhav kahai bichaar kai | 1500 |","meaning_en":"","page":572}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":573},{"type":"verse","number":[1501],"number_text":"੧੫੦੧।","page":573,"lines":[{"gurmukhi":"ਕੋ ਭਟ ਉਪਜਿਯੋ ਜਗਤ ਮੈ ਸਬ ਯੌ ਕਰਤ ਬਿਚਾਰ।","roman":"Ko bhat upjiyo jagat mai sab yau karat bichaar |","meaning_en":"","page":573},{"gurmukhi":"ਸਿਵ ਸਿਖਿ ਬਾਹਨ ਗਨ ਸਹਿਤ ਆਏ ਰਨਿ ਰਿਸਿ ਧਾਰਿ। ੧੫੦੧।","roman":"Siv sikhi baahan gan sahit aae rani risi dhaari | 1501 |","meaning_en":"","page":573}]},{"type":"verse","number":[1502],"number_text":"੧੫੦੨।","page":573,"lines":[{"gurmukhi":"ਪ੍ਰਲੈ ਕਾਲ ਕਰਤਾ ਜਹੀ ਆਏ ਤਿਹ ਠਾ ਦੌਰਿ।","roman":"Pralai kaal kartaa jahee aae tih thaa dauri |","meaning_en":"","page":573},{"gurmukhi":"ਰਨ ਨਿਹਾਰਿ ਮਨ ਮੈ ਕਹਿਯੋ ਇਹ ਚਿੰਤਾ ਕੀ ਠੌਰ। ੧੫੦੨।","roman":"Ran nihaari man mai kahiyo ih chintaa kee thaur | 1502 |","meaning_en":"","page":573}]},{"type":"verse","number":[1503],"number_text":"੧੫੦੩।","page":573,"lines":[{"gurmukhi":"ਗਨ ਗਨੇਸ ਸਿਵ ਖਟਬਦਨ ਦੇਖੈ ਨੈਨ ਨਿਹਾਰਿ।","roman":"Gan ganes siv khatabdan dekhai nain nihaari |","meaning_en":"","page":573},{"gurmukhi":"ਸੋ ਰਿਸ ਭੂਪਤਿ ਜੁਧ ਹਿਤ ਲੀਨੇ ਆਪ ਹਕਾਰਿ। ੧੫੦੩।","roman":"So ris bhoopti judh hit leene aap hakaari | 1503 |","meaning_en":"","page":573}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":573},{"type":"verse","number":[1504],"number_text":"੧੫੦੪।","page":573,"lines":[{"gurmukhi":"ਰੇ ਸਿਵ ਆਜ ਅਯੋਧਨ ਮੈ ਲਰਿ ਲੈ ਹਮ ਸੋ ਕਰ ਲੈ ਬਲ ਜੇਤੋ।","roman":"Re siv aaj ayodhan mai lari lai ham so kar lai bal jeto |","meaning_en":"","page":573},{"gurmukhi":"ਐ ਰੇ ਗਨੇਸ ਲਰੈ ਹਮਰੇ ਸੰਗ ਹੈ ਤੁਮਰੇ ਤਨ ਮੈ ਬਲ ਏਤੋ।","roman":"Ai re ganes larai hamre sang hai tumre tan mai bal eto |","meaning_en":"","page":573},{"gurmukhi":"ਕਿਉ ਰੇ ਖੜਾਨਨ ਤੂ ਗਰਬੈ ਮਰ ਹੈ ਅਬ ਹੀ ਇਕ ਬਾਨ ਲਗੈ ਤੋ।","roman":"Kiu re kharaanan too garbai mar hai ab hee ik baan lagai to |","meaning_en":"","page":573},{"gurmukhi":"ਕਾਹੇ ਕਉ ਜੂਝ ਮਰੋ ਰਨ ਮੈ ਅਬ ਲਉ ਨ ਗਯੋ ਕਛੁ ਜੀਅ ਮਹਿ ਚੇਤੋ। ੧੫੦੪।","roman":"Kaahe kau joojh maro ran mai ab lau na gayo kachhu jeea mahi cheto | 1504 |","meaning_en":"","page":573}]},{"type":"heading","kind":"speaker","name":"ਸਿਵ ਜੂ ਬਾਚ ਖੜਗੇਸ ਸੋ","gurmukhi":"ਸਿਵ ਜੂ ਬਾਚ ਖੜਗੇਸ ਸੋ","roman":"Siv joo baach kharges so","meaning_en":"","page":573},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":573},{"type":"verse","number":[1505],"number_text":"੧੫੦੫।","page":573,"lines":[{"gurmukhi":"ਬੋਲਿ ਉਠਿਯੋ ਰਿਸਿ ਕੈ ਸਿਵ ਜੂ ਅਰੇ ਕਿਉ ਸੁਨ ਤੂ ਗਰਬਾਤੁ ਹੈ ਏਤੋ।","roman":"Boli uthiyo risi kai siv joo are kiu sun too garbaatu hai eto |","meaning_en":"","page":573},{"gurmukhi":"ਏਤਨ ਸਿਉ ਜਿਨਿ ਰਾਰਿ ਮੰਡੋ ਅਬਿ ਹੀ ਲਖਿ ਹੈ ਹਮ ਮੈ ਬਲੁ ਜੇਤੋ।","roman":"Etan siu jini raari mando abi hee lakhi hai ham mai balu jeto |","meaning_en":"","page":573},{"gurmukhi":"ਜੌ ਤੁਮ ਮੈ ਅਤਿ ਪਉਰਖ ਹੈ ਅਬ ਢੀਲ ਕਹਾ ਧਨੁ ਬਾਨਹਿ ਲੇਤੋ।","roman":"Jau tum mai ati paurakh hai ab dheel kahaa dhanu baanhi leto |","meaning_en":"","page":573},{"gurmukhi":"ਜੇਤੋ ਹੈ ਦੀਰਘ ਗਾਤ ਤਿਹਾਰੋ ਸੁ ਬਾਨਨ ਸੋ ਕਰਿ ਹੋ ਲਹੁ ਤੇਤੋ। ੧੫੦੫।","roman":"Jeto hai deeragh gaat tihaaro su baanan so kari ho lahu teto | 1505 |","meaning_en":"","page":573}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ ਸਿਵ ਸੋ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ ਸਿਵ ਸੋ","roman":"Kharges baach siv so","meaning_en":"","page":573},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":573},{"type":"verse","number":[1506],"number_text":"੧੫੦੬।","page":573,"lines":[{"gurmukhi":"ਕਿਉ ਸਿਵ ਮਾਨ ਕਰੈ ਇਤਨੋ ਭਜਿ ਹੈ ਤਬ ਹੀ ਜਬ ਮਾਰ ਮਚੈਗੀ।","roman":"Kiu siv maan karai itno bhaji hai tab hee jab maar machaigee |","meaning_en":"","page":573},{"gurmukhi":"ਏਕ ਹੀ ਬਾਨ ਲਗੈ ਕਪਿ ਜਿਉ ਸਿਗਰੀ ਤੁਮਰੀ ਅਬ ਸੈਨ ਨਚੈਗੀ।","roman":"Ek hee baan lagai kapi jiu sigree tumree ab sain nachaigee |","meaning_en":"","page":573},{"gurmukhi":"ਭੂਤ ਪਿਸਾਚਨ ਕੀ ਧੁਜਨੀ ਮਰਿ ਹੈ ਰਨ ਮੈ ਨਹੀ ਨੈਕੁ ਬਚੈਗੀ।","roman":"Bhoot pisaachan kee dhujnee mari hai ran mai nahee naiku bachaigee |","meaning_en":"","page":573},{"gurmukhi":"ਤੇਰੇ ਹੀ ਸ੍ਰਉਨਤ ਸੋ ਸੁਨਿ ਆਜੁ ਧਰਾ ਇਹ ਆਰੁਨ ਬੇਖ ਰਚੈਗੀ। ੧੫੦੬।","roman":"Tere hee sraunat so suni aaju dharaa ih aarun bekh rachaigee | 1506 |","meaning_en":"","page":573}]},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"","page":573},{"type":"verse","number":[1507],"number_text":"੧੫੦੭।","page":573,"lines":[{"gurmukhi":"ਸਿਵ ਯੌ ਸੁਨਿ ਕੈ ਧਨੁ ਬਾਨ ਲੀਓ। ਕਸਿ ਕਾਨ ਪ੍ਰਮਾਨ ਲਉ ਛਾਡਿ ਦੀਓ।","roman":"Siv yau suni kai dhanu baan leeo | kasi kaan pramaan lau chhaadi deeo |","meaning_en":"","page":573},{"gurmukhi":"ਨ੍ਰਿਪ ਕੇ ਮੁਖ ਲਾਗ ਬਿਰਾਜ ਰਹਿਓ। ਖਗਰਾਜ ਮਨੋ ਅਹਿ ਰਾਜ ਗਹਿਓ। ੧੫੦੭।","roman":"Nrip ke mukh laag biraaj rahio | khagraaj mano ahi raaj gahio | 1507 |","meaning_en":"","page":573}]},{"type":"verse","number":[1508],"number_text":"੧੫੦੮।","page":574,"lines":[{"gurmukhi":"ਬਰਛੀ ਤਬ ਭੂਪ ਚਲਾਇ ਦਈ। ਸਿਵ ਕੇ ਉਰ ਮੈ ਲਗ ਕ੍ਰਾਤਿ ਭਈ।","roman":"Barchhee tab bhoop chalaai daee | siv ke ur mai lag kraati bhaee |","meaning_en":"","page":574},{"gurmukhi":"ਉਪਮਾ ਕਬਿ ਨੇ ਇਹ ਭਾਤਿ ਕਹੀ। ਰਵਿ ਕੀ ਕਰ ਕੰਜ ਪੈ ਮੰਡਿ ਰਹੀ। ੧੫੦੮।","roman":"Upmaa kabi ne ih bhaati kahee | ravi kee kar kanj pai mandi rahee | 1508 |","meaning_en":"","page":574}]},{"type":"verse","number":[1509],"number_text":"੧੫੦੯।","page":574,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਹਰਿ ਦ੍ਵੈ ਕਰਿ ਖੈਚਿ ਨਿਕਾਰੀ। ਗਹਿ ਡਾਰ ਦਈ ਮਨੋ ਨਾਗਨਿ ਕਾਰੀ।","roman":"Tab hee hari dvai kari khaichi nikaaree | gahi daar daee mano naagni kaaree |","meaning_en":"","page":574},{"gurmukhi":"ਬਹੁਰੋ ਨ੍ਰਿਪ ਮ੍ਯਾਨ ਤੇ ਖਗੁ ਨਿਕਾਰਿਓ। ਕਰਿ ਕੈ ਬਲੁ ਕੋ ਸਿਵ ਊਪਰ ਡਾਰਿਓ। ੧੫੦੯।","roman":"Bahuro nrip myaan te khagu nikaario | kari kai balu ko siv oopar daario | 1509 |","meaning_en":"","page":574}]},{"type":"verse","number":[1510],"number_text":"੧੫੧੦।","page":574,"lines":[{"gurmukhi":"ਹਰ ਮੋਹਿ ਰਹਿਓ ਗਿਰ ਭੂਮਿ ਪਰਿਓ। ਮਨੋ ਬਜ੍ਰ ਪਰਿਓ ਗਿਰਿ ਸ੍ਰਿੰਗ ਝਰਿਓ।","roman":"Har mohi rahio gir bhoomi pario | mano bajr pario giri sring jhario |","meaning_en":"","page":574},{"gurmukhi":"ਇਹ ਰੁਦ੍ਰ ਦਸਾ ਸਬ ਸੈਨ ਨਿਹਾਰੀ। ਬਰਛੀ ਤਬ ਹੀ ਸਿਵ ਪੂਤ ਸੰਭਾਰੀ। ੧੫੧੦।","roman":"Ih rudr dasaa sab sain nihaaree | barchhee tab hee siv poot sanbhaaree | 1510 |","meaning_en":"","page":574}]},{"type":"verse","number":[1511],"number_text":"੧੫੧੧।","page":574,"lines":[{"gurmukhi":"ਜਬ ਕਰ ਬੀਚ ਸਕਤਿ ਕੋ ਲਇਓ। ਤਬ ਆਇ ਨ੍ਰਿਪਤਿ ਕੇ ਸਾਮੁਹਿ ਭਇਓ।","roman":"Jab kar beech sakti ko laio | tab aai nripti ke saamuhi bhaio |","meaning_en":"","page":574},{"gurmukhi":"ਕਰ ਕੇ ਬਲ ਕੈ ਨ੍ਰਿਪ ਓਰ ਚਲਾਈ। ਬਰਛੀ ਨਹੀ ਮਾਨੋ ਮ੍ਰਿਤ ਪਠਾਈ। ੧੫੧੧।","roman":"Kar ke bal kai nrip or chalaaee | barchhee nahee maano mrit pathaaee | 1511 |","meaning_en":"","page":574}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":574},{"type":"verse","number":[1512],"number_text":"੧੫੧੨।","page":574,"lines":[{"gurmukhi":"ਨ੍ਰਿਪ ਆਵਤ ਕਾਟਿ ਦਈ ਬਰਛੀ ਸਰ ਤੀਛਨ ਸੋ ਅਰਿ ਕੇ ਉਰਿ ਮਾਰਿਓ।","roman":"Nrip aavat kaati daee barchhee sar teechhan so ari ke uri maario |","meaning_en":"","page":574},{"gurmukhi":"ਸੋ ਸਰ ਸੋ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਬਾਹਨ ਕਉ ਪ੍ਰਤਿਅੰਗ ਪ੍ਰਹਾਰਿਓ।","roman":"So sar so kabi syaam kahai tih baahan kau pratiang prahaario |","meaning_en":"","page":574},{"gurmukhi":"ਏਕ ਗਨੇਸ ਲਿਲਾਟ ਬਿਖੈ ਸਰ ਲਾਗ ਰਹਿਓ ਤਿਰਛੋ ਛਬਿ ਧਾਰਿਓ।","roman":"Ek ganes lilaat bikhai sar laag rahio tirchho chhabi dhaario |","meaning_en":"","page":574},{"gurmukhi":"ਮਾਨ ਬਢਿਯੋ ਗਜਆਨਨ ਦੀਹ ਮਨੋ ਸਰ ਅੰਕੁਸ ਸਾਥਿ ਉਤਾਰਿਓ। ੧੫੧੨।","roman":"Maan badhiyo gaja'aanan deeh mano sar ankus saathi utaario | 1512 |","meaning_en":"","page":574}]},{"type":"verse","number":[1513],"number_text":"੧੫੧੩।","page":574,"lines":[{"gurmukhi":"ਚੇਤ ਭਯੋ ਚਢਿ ਬਾਹਨ ਪੈ ਸਿਵ ਲੈ ਧਨੁ ਬਾਨ ਚਲਾਇ ਦਯੋ ਹੈ।","roman":"Chet bhayo chadhi baahan pai siv lai dhanu baan chalaai dayo hai |","meaning_en":"","page":574},{"gurmukhi":"ਸੋ ਸਰ ਤੀਛਨ ਹੈ ਅਤਿ ਹੀ ਇਹ ਭੂਪਤਿ ਕੇ ਉਰਿ ਲਾਗ ਗਯੋ ਹੈ।","roman":"So sar teechhan hai ati hee ih bhoopti ke uri laag gayo hai |","meaning_en":"","page":574},{"gurmukhi":"ਫੂਲ ਗਯੋ ਜੀਅ ਜਾਨ ਨਰੇਸ ਹਨਿਯੋ ਨਹੀ ਰੰਚਕ ਤ੍ਰਾਸ ਭਯੋ ਹੈ।","roman":"Phool gayo jeea jaan nares haniyo nahee ranchak traas bhayo hai |","meaning_en":"","page":574},{"gurmukhi":"ਚਾਪ ਤਨਾਇ ਲੀਯੋ ਕਰ ਮੈ ਸੁ ਨਿਖੰਗ ਤੇ ਬਾਨ ਨਿਕਾਸ ਲਯੋ ਹੈ। ੧੫੧੩।","roman":"Chaap tanaai leeyo kar mai su nikhang te baan nikaas layo hai | 1513 |","meaning_en":"","page":574}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":574},{"type":"verse","number":[1514],"number_text":"੧੫੧੪।","page":574,"lines":[{"gurmukhi":"ਤਬ ਤਿਨ ਭੂਪਤਿ ਬਾਨ ਇਕ ਕਾਨ ਪ੍ਰਮਾਨ ਸੁ ਤਾਨਿ।","roman":"Tab tin bhoopti baan ik kaan pramaan su taani |","meaning_en":"","page":574},{"gurmukhi":"ਲਖਿ ਮਾਰਿਓ ਸਿਵ ਉਰ ਬਿਖੈ ਅਰਿ ਬਧ ਹਿਤ ਹੀਯ ਜਾਨਿ। ੧੫੧੪।","roman":"Lakhi maario siv ur bikhai ari badh hit heey jaani | 1514 |","meaning_en":"","page":574}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":574},{"type":"verse","number":[1515],"number_text":"੧੫੧੫।","page":574,"lines":[{"gurmukhi":"ਜਬ ਹਰ ਕੇ ਉਰਿ ਤਿਨਿ ਸਰ ਮਾਰਿਓ। ਇਹ ਬਿਕ੍ਰਮ ਸਿਵ ਸੈਨ ਨਿਹਾਰਿਓ।","roman":"Jab har ke uri tini sar maario | ih bikram siv sain nihaario |","meaning_en":"","page":574},{"gurmukhi":"ਕਾਰਤਕੇਯ ਨਿਜ ਦਲੁ ਲੈ ਧਾਇਓ। ਪੁਨਿ ਗਨੇਸ ਮਨ ਕੋਪ ਬਢਾਇਓ। ੧੫੧੫।","roman":"Kaaratkey nij dalu lai dhaaio | puni ganes man kop badhaaio | 1515 |","meaning_en":"","page":574}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":574},{"type":"verse","number":[1516],"number_text":"੧੫੧੬।","page":574,"lines":[{"gurmukhi":"ਆਵਤ ਹੀ ਦੁਹ ਕੋ ਲਖਿ ਭੂਪਤਿ ਜੀ ਅਪੁਨੇ ਅਤਿ ਕ੍ਰੋਧ ਬਢਾਇਓ।","roman":"Aavat hee duh ko lakhi bhoopti jee apune ati krodh badhaaio |","meaning_en":"","page":574},{"gurmukhi":"ਪਉਰਖ ਕੈ ਭੁਜਦੰਡਨ ਕੋ ਸਿਖਿ ਬਾਹਨ ਕੋ ਇਕੁ ਬਾਨ ਲਗਾਇਓ।","roman":"Paurakh kai bhujdandan ko sikhi baahan ko iku baan lagaaio |","meaning_en":"","page":574},{"gurmukhi":"ਅਉਰ ਜਿਤੋ ਗਨ ਕੋ ਦਲੁ ਆਵਤ ਸੋ ਛਿਨ ਮੈ ਜਮ ਧਾਮਿ ਪਠਾਇਓ।","roman":"Aur jito gan ko dalu aavat so chhin mai jam dhaami pathaaio |","meaning_en":"","page":575},{"gurmukhi":"ਆਇ ਖੜਾਨਨ ਕੋ ਜਬ ਹੀ ਗਜ ਆਨਨ ਛਾਡਿ ਕੈ ਖੇਤ ਪਰਾਇਓ। ੧੫੧੬।","roman":"Aai kharaanan ko jab hee gaj aanan chhaadi kai khet paraaio | 1516 |","meaning_en":"","page":575}]},{"type":"verse","number":[1517],"number_text":"੧੫੧੭।","page":575,"lines":[{"gurmukhi":"ਮੋਦ ਭਯੋ ਨ੍ਰਿਪ ਕੇ ਮਨ ਮੈ ਜਬ ਹੀ ਸਿਵ ਕੋ ਦਲੁ ਮਾਰਿ ਭਜਾਯੋ।","roman":"Mod bhayo nrip ke man mai jab hee siv ko dalu maari bhajaayo |","meaning_en":"","page":575},{"gurmukhi":"ਕਾਹੇ ਕਉ ਭਾਜਤ ਰੇ ਡਰ ਕੈ ਜਿਨਿ ਭਾਜਹੁ ਇਉ ਤਿਹ ਟੇਰਿ ਸੁਨਾਯੋ।","roman":"Kaahe kau bhaajat re dar kai jini bhaajhu iu tih teri sunaayo |","meaning_en":"","page":575},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੇ ਖੜਗੇਸ ਤਬੈ ਅਪੁਨੇ ਕਰਿ ਲੈ ਬਰ ਸੰਖ ਬਜਾਯੋ।","roman":"Syaam bhane kharges tabai apune kari lai bar sankh bajaayo |","meaning_en":"","page":575},{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਸਬੈ ਤਬ ਹੀ ਮਨੋ ਅੰਤਕ ਰੂਪ ਕੀਏ ਰਨਿ ਆਯੋ। ੧੫੧੭।","roman":"Sasatr sanbhaari sabai tab hee mano antak roop kee'e rani aayo | 1517 |","meaning_en":"","page":575}]},{"type":"verse","number":[1518],"number_text":"੧੫੧੮।","page":575,"lines":[{"gurmukhi":"ਟੇਰ ਸੁਨੇ ਸਬ ਫੇਰਿ ਫਿਰੇ ਕਰਿ ਲੈ ਕਰਵਾਰਨ ਕੋਪ ਹੁਇ ਧਾਏ।","roman":"Ter sune sab pheri phire kari lai karvaaran kop hui dhaae |","meaning_en":"","page":575},{"gurmukhi":"ਲਾਜ ਭਰੇ ਸੁ ਟਰੇ ਨ ਡਰੇ ਤਿਨ ਹੂੰ ਮਿਲਿ ਕੈ ਸਬ ਸੰਖ ਬਜਾਏ।","roman":"Laaj bhare su tare na dare tin hoon mili kai sab sankh bajaae |","meaning_en":"","page":575},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਪਰੇ ਲਲਕਾਰਿ ਕਹੈ ਅਰੇ ਤੈ ਬਹੁ ਘਾਏ।","roman":"Maar hee maar pukaari pare lalkaari kahai are tai bahu ghaae |","meaning_en":"","page":575},{"gurmukhi":"ਮਾਰਤ ਹੈ ਅਬ ਤੋਹਿ ਨ ਛਾਡ ਯੌ ਕਹਿ ਕੈ ਸਰ ਓਘ ਚਲਾਏ। ੧੫੧੮।","roman":"Maarat hai ab tohi na chhaad yau kahi kai sar ogh chalaae | 1518 |","meaning_en":"","page":575}]},{"type":"verse","number":[1519],"number_text":"੧੫੧੯।","page":575,"lines":[{"gurmukhi":"ਜਬ ਆਨਿ ਨਿਦਾਨ ਕੀ ਮਾਰੁ ਮਚੀ ਤਬ ਹੀ ਨ੍ਰਿਪ ਆਪਨੇ ਸਸਤ੍ਰ ਸੰਭਾਰੇ।","roman":"Jab aani nidaan kee maaru machee tab hee nrip aapne sasatr sanbhaare |","meaning_en":"","page":575},{"gurmukhi":"ਖਗ ਗਦਾ ਬਰਛੀ ਜਮਧਾਰ ਸੁ ਲੈ ਕਰਵਾਰ ਹੀ ਸਤ੍ਰੁ ਪਚਾਰੇ।","roman":"Khag gadaa barchhee jamdhaar su lai karvaar hee satru pachaare |","meaning_en":"","page":575},{"gurmukhi":"ਪਾਨਿ ਲੀਓ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਨਿਹਾਰਿ ਕਈ ਅਰਿ ਕੋਟਿ ਸੰਘਾਰੇ।","roman":"Paani leeo dhanu baan sanbhaari nihaari kaee ari koti sanghaare |","meaning_en":"","page":575},{"gurmukhi":"ਭੂਪ ਨ ਮੋਰਤਿ ਸੰਘਰ ਤੇ ਮੁਖ ਅੰਤ ਕੋ ਅੰਤਕ ਸੇ ਭਟ ਹਾਰੇ। ੧੫੧੯।","roman":"Bhoop na morti sanghar te mukh ant ko antak se bhat haare | 1519 |","meaning_en":"","page":575}]},{"type":"verse","number":[1520],"number_text":"੧੫੨੦।","page":575,"lines":[{"gurmukhi":"ਲੈ ਅਪੁਨੇ ਸਿਵ ਪਾਨਿ ਸਰਾਸਨ ਜੀ ਅਪੁਨੇ ਅਤਿ ਕੋਪ ਬਢਾਯੋ।","roman":"Lai apune siv paani saraasan jee apune ati kop badhaayo |","meaning_en":"","page":575},{"gurmukhi":"ਭੂਪਤਿ ਕੋ ਚਿਤਿਯੋ ਚਿਤ ਮੈ ਬਧ ਬਾਹਨ ਆਪੁਨ ਕੋ ਸੁ ਧਵਾਯੋ।","roman":"Bhoopti ko chitiyo chit mai badh baahan aapun ko su dhavaayo |","meaning_en":"","page":575},{"gurmukhi":"ਮਾਰਤ ਹੋ ਅਬ ਯਾ ਰਨ ਮੈ ਕਹਿ ਕੈ ਨ੍ਰਿਪ ਕਉ ਇਹ ਭਾਤਿ ਸੁਨਾਯੋ।","roman":"Maarat ho ab yaa ran mai kahi kai nrip kau ih bhaati sunaayo |","meaning_en":"","page":575},{"gurmukhi":"ਯੌ ਕਹਿ ਨਾਦ ਬਜਾਵਤ ਭਯੋ ਮਨੋ ਅੰਤ ਭਯੋ ਪਰਲੈ ਘਨ ਆਯੋ। ੧੫੨੦।","roman":"Yau kahi naad bajaavat bhayo mano ant bhayo parlai ghan aayo | 1520 |","meaning_en":"","page":575}]},{"type":"verse","number":[1521],"number_text":"੧੫੨੧।","page":575,"lines":[{"gurmukhi":"ਨਾਦ ਸੁ ਨਾਦ ਰਹਿਓ ਭਰਪੂਰ ਸੁਨਿਯੋ ਪੁਰਹੂਤ ਮਹਾ ਬਿਸਮਾਯੋ।","roman":"Naad su naad rahio bharpoor suniyo purhoot mahaa bismaayo |","meaning_en":"","page":575},{"gurmukhi":"ਸਾਤ ਸਮੁਦ੍ਰ ਨਦੀ ਨਦ ਅਉ ਸਰ ਬਿੰਧ ਸੁਮੇਰ ਮਹਾ ਗਰਜਾਯੋ।","roman":"Saat samudr nadee nad au sar bindh sumer mahaa garjaayo |","meaning_en":"","page":575},{"gurmukhi":"ਕਾਪ ਉਠਿਓ ਸੁਨਿ ਯੌ ਸਹਸਾਨਨ ਚਉਦਹ ਲੋਕਨ ਚਾਲ ਜਨਾਯੋ।","roman":"Kaap uthio suni yau sahsaanan chaudah lokan chaal janaayo |","meaning_en":"","page":575},{"gurmukhi":"ਸੰਕਤ ਹ੍ਵੈ ਸੁਨ ਕੈ ਜਗ ਕੇ ਜਨ ਭੂਪ ਨਹੀ ਮਨ ਮੈ ਡਰ ਪਾਯੋ। ੧੫੨੧।","roman":"Sankat hvai sun kai jag ke jan bhoop nahee man mai dar paayo | 1521 |","meaning_en":"","page":575}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ ਸਿਵ ਸੋ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ ਸਿਵ ਸੋ","roman":"Kharges baach siv so","meaning_en":"","page":575},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":575},{"type":"verse","number":[1522],"number_text":"੧੫੨੨।","page":575,"lines":[{"gurmukhi":"ਰੁਦ੍ਰ ਕੇ ਆਨਨ ਕੋ ਅਵਿਲੋਕ ਕੈ ਯੌ ਕਹਿ ਕੈ ਨ੍ਰਿਪ ਬਾਤ ਸੁਨਾਈ।","roman":"Rudr ke aanan ko avilok kai yau kahi kai nrip baat sunaaee |","meaning_en":"","page":575},{"gurmukhi":"ਕਾ ਭਯੋ ਜੋ ਜੁਗੀਯਾ ਕਰਿ ਲੈ ਕਰ ਡਿੰਭ ਕੇ ਕਾਰਨ ਨਾਦ ਬਜਾਈ।","roman":"Kaa bhayo jo jugeeyaa kari lai kar dinbh ke kaaran naad bajaaee |","meaning_en":"","page":575},{"gurmukhi":"ਤੰਦੁਲ ਮਾਗਨ ਹੈ ਤੁਯ ਕਾਰਜ ਮੈ ਨ ਡਰੋ ਤੁਹਿ ਚਾਪ ਚਢਾਈ।","roman":"Tandul maagan hai tuy kaaraj mai na daro tuhi chaap chadhaaee |","meaning_en":"","page":576},{"gurmukhi":"ਜੂਝਬੋ ਕਾਮ ਹੈ ਛਤ੍ਰਿਨ ਕੋ ਕਛੁ ਜੋਗਿਨ ਕੋ ਨਹੀ ਕਾਮ ਲਰਾਈ। ੧੫੨੨।","roman":"Joojhbo kaam hai chhatrin ko kachhu jogin ko nahee kaam laraaee | 1522 |","meaning_en":"","page":576}]},{"type":"verse","number":[1523],"number_text":"੧੫੨੩।","page":576,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਬਤੀਯਾ ਸਿਵ ਸੋ ਨ੍ਰਿਪ ਪਾਨ ਬਿਖੈ ਰਿਸਿ ਖੜਗ ਬਡੋ ਲੈ।","roman":"Yau kahi kai bateeyaa siv so nrip paan bikhai risi kharag bado lai |","meaning_en":"","page":576},{"gurmukhi":"ਮਾਰਤ ਤੇ ਹਰ ਕੇ ਤਨ ਮੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਜੀਯ ਕੋਪ ਮਹਾ ਕੈ।","roman":"Maarat te har ke tan mai kabi syaam kahai jeey kop mahaa kai |","meaning_en":"","page":576},{"gurmukhi":"ਘਾਉ ਕੈ ਸੁੰਭ ਕੈ ਗਾਤ ਬਿਖੈ ਇਮ ਬੋਲਿ ਉਠਿਓ ਹਸਿ ਸਿੰਧ ਜਰਾ ਜੈ।","roman":"Ghaau kai sunbh kai gaat bikhai im boli uthio hasi sindh jaraa jai |","meaning_en":"","page":576},{"gurmukhi":"ਰੁਦ੍ਰ ਗਿਰਿਓ ਸਿਰ ਮਾਲ ਕਹੂੰ ਕਹੂੰ ਬੈਲ ਗਿਰਿਓ ਗਿਰਿਯੋ ਸੂਲ ਕਹੂੰ ਹ੍ਵੈ। ੧੫੨੩।","roman":"Rudr girio sir maal kahoon kahoon bail girio giriyo sool kahoon hvai | 1523 |","meaning_en":"","page":576}]},{"type":"verse","number":[1524],"number_text":"੧੫੨੪।","page":576,"lines":[{"gurmukhi":"ਘੇਰ ਲੀਯੋ ਮਿਲ ਕੈ ਨ੍ਰਿਪ ਕਉ ਜਬ ਹੀ ਸਿਵ ਕੇ ਦਲ ਕੋਪ ਕਰਿਓ ਹੈ।","roman":"Gher leeyo mil kai nrip kau jab hee siv ke dal kop kario hai |","meaning_en":"","page":576},{"gurmukhi":"ਆਗੇ ਹ੍ਵੈ ਭੂਪ ਅਯੋਧਨ ਮੈ ਦਿਢ ਠਾਢੋ ਰਹਿਓ ਨਹੀ ਪੈਗ ਟਰਿਓ ਹੈ।","roman":"Aage hvai bhoop ayodhan mai didh thaadho rahio nahee paig tario hai |","meaning_en":"","page":576},{"gurmukhi":"ਤਾਲ ਜਹਾ ਰਥ ਰੂਖ ਧੁਜਾ ਭਟ ਪੰਛਨ ਸਿਉ ਰਨ ਬਾਗ ਭਰਿਓ ਹੈ।","roman":"Taal jahaa rath rookh dhujaa bhat panchhan siu ran baag bhario hai |","meaning_en":"","page":576},{"gurmukhi":"ਭਾਗ ਗਏ ਗਨ ਜੈਸੇ ਬਿਹੰਗ ਮਨੋ ਨ੍ਰਿਪ ਟੂਟ ਕੈ ਬਾਜ ਪਰਿਓ ਹੈ। ੧੫੨੪।","roman":"Bhaag gae gan jaise bihang mano nrip toot kai baaj pario hai | 1524 |","meaning_en":"","page":576}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":576},{"type":"verse","number":[1525],"number_text":"੧੫੨੫।","page":576,"lines":[{"gurmukhi":"ਏ ਸਿਵ ਕੇ ਗਨ ਥਿਰੁ ਰਹੇ ਅਤਿ ਮਨ ਕੋਪ ਬਢਾਇ।","roman":"E siv ke gan thiru rahe ati man kop badhaai |","meaning_en":"","page":576},{"gurmukhi":"ਗਨ ਛਉਨਾ ਗਨ ਰਾਜ ਸ੍ਰੀ ਮਹਾਬੀਰ ਮਨ ਰਾਇ। ੧੫੨੫।","roman":"Gan chhaunaa gan raaj sree mahaabeer man raai | 1525 |","meaning_en":"","page":576}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":576},{"type":"verse","number":[1526],"number_text":"੧੫੨੬।","page":576,"lines":[{"gurmukhi":"ਬੀਰਨ ਕੀ ਮਨਿ ਸ੍ਰੀ ਗਨਰਾਇ ਮਹਾ ਬਰਬੀਰ ਫਿਰਿਓ ਗਨ ਛਉਨਾ।","roman":"Beeran kee mani sree ganraai mahaa barbeer phirio gan chhaunaa |","meaning_en":"","page":576},{"gurmukhi":"ਲੋਹਤ ਨੈਨ ਚਲਿਓ ਸਿਸ ਹੋਤ ਕੀਓ ਗਹਿ ਜਾ ਜਮਰਾਜ ਖਿਲਉਨਾ।","roman":"Lohat nain chalio sis hot keeo gahi jaa jamraaj khilaunaa |","meaning_en":"","page":576},{"gurmukhi":"ਆਵਤ ਭੂਪ ਬਿਲੋਕ ਕੈ ਸਤ੍ਰਨ ਆਪ ਕੀਯੋ ਮਨ ਰੰਚਕ ਭਉ ਨਾ।","roman":"Aavat bhoop bilok kai satran aap keeyo man ranchak bhau naa |","meaning_en":"","page":576},{"gurmukhi":"ਮਾਰਿ ਲਏ ਛਿਨ ਮੈ ਗਨ ਕੋ ਗਨ ਜੁਧ ਕੀਓ ਕਿ ਕੀਓ ਕਛੁ ਟਉਨਾ। ੧੫੨੬।","roman":"Maari lae chhin mai gan ko gan judh keeo ki keeo kachhu taunaa | 1526 |","meaning_en":"","page":576}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":576},{"type":"verse","number":[1527],"number_text":"੧੫੨੭।","page":576,"lines":[{"gurmukhi":"ਤਬ ਅਰਿ ਲਖਿ ਕੈ ਸਰ ਸੋ ਮਾਰਿਓ। ਜਿਹ ਕੁਦ੍ਰਿਸਟਿ ਨ੍ਰਿਪ ਓਰਿ ਨਿਹਾਰਿਓ।","roman":"Tab ari lakhi kai sar so maario | jih kudristi nrip ori nihaario |","meaning_en":"","page":576},{"gurmukhi":"ਪੁਨਿ ਗਨੇਸ ਕੋ ਨ੍ਰਿਪ ਲਲਕਾਰਿਓ। ਤ੍ਰਸਤ ਭਯੋ ਤਜਿ ਜੁਧ ਪਧਾਰਿਓ। ੧੫੨੭।","roman":"Puni ganes ko nrip lalkaario | trasat bhayo taji judh padhaario | 1527 |","meaning_en":"","page":576}]},{"type":"verse","number":[1528],"number_text":"੧੫੨੮।","page":576,"lines":[{"gurmukhi":"ਜਬ ਸਿਵ ਜੂ ਕਛੁ ਸੰਗਿਆ ਪਾਈ। ਭਾਜਿ ਗਯੋ ਤਜ ਦਈ ਲਰਾਈ।","roman":"Jab siv joo kachhu sangiaa paaee | bhaaji gayo taj daee laraaee |","meaning_en":"","page":576},{"gurmukhi":"ਅਉਰ ਸਗਲ ਛਡ ਕੈ ਗਨ ਭਾਗੇ। ਐਸੋ ਕੋ ਭਟ ਆਵੈ ਆਗੇ। ੧੫੨੮।","roman":"Aur sagal chhad kai gan bhaage | aiso ko bhat aavai aage | 1528 |","meaning_en":"","page":576}]},{"type":"verse","number":[1529],"number_text":"੧੫੨੯।","page":576,"lines":[{"gurmukhi":"ਜਬਹਿ ਕ੍ਰਿਸਨ ਸਿਵ ਭਜਤ ਨਿਹਾਰਿਓ। ਇਹੈ ਆਪਨੇ ਹ੍ਰਿਦੇ ਬਿਚਾਰਿਓ।","roman":"Jabhi krisan siv bhajat nihaario | ihai aapne hride bichaario |","meaning_en":"","page":576},{"gurmukhi":"ਅਬ ਹਉ ਆਪਨ ਇਹ ਸੰਗ ਲਰੋ। ਕੈ ਅਰਿ ਮਾਰੋ ਕੈ ਲਰਿ ਮਰੋ। ੧੫੨੯।","roman":"Ab hau aapan ih sang laro | kai ari maaro kai lari maro | 1529 |","meaning_en":"","page":576}]},{"type":"verse","number":[1530],"number_text":"੧੫੩੦।","page":577,"lines":[{"gurmukhi":"ਤਬ ਤਿਹ ਸਉਹੇ ਹਰਿ ਜੂ ਗਯੋ। ਰਾਮ ਭਨੈ ਅਤਿ ਜੁਧ ਮਚਯੋ।","roman":"Tab tih sauhe hari joo gayo | raam bhanai ati judh machyo |","meaning_en":"","page":577},{"gurmukhi":"ਤਬ ਤਿਨੈ ਤਕਿ ਤਿਹ ਬਾਨ ਲਗਾਯੋ। ਸ੍ਯੰਦਨ ਤੇ ਹਰਿ ਭੂਮਿ ਗਿਰਾਯੋ। ੧੫੩੦।","roman":"Tab tinai taki tih baan lagaayo | syandan te hari bhoomi giraayo | 1530 |","meaning_en":"","page":577}]},{"type":"heading","kind":"speaker","name":"ਕਬਿਯੋ ਬਾਚ","gurmukhi":"ਕਬਿਯੋ ਬਾਚ","roman":"Kabiyo baach","meaning_en":"","page":577},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":577},{"type":"verse","number":[1531],"number_text":"੧੫੩੧।","page":577,"lines":[{"gurmukhi":"ਜਾ ਪ੍ਰਭ ਕਉ ਨਿਤ ਬ੍ਰਹਮ ਸਚੀ ਪਤਿ ਸ੍ਰੀ ਸਨਕਾਦਿਕ ਹੂੰ ਜਪੁ ਕੀਨੋ।","roman":"Jaa prabh kau nit braham sachee pati sree sankaadik hoon japu keeno |","meaning_en":"","page":577},{"gurmukhi":"ਸੂਰ ਸਸੀ ਸੁਰ ਨਾਰਦ ਸਾਰਦ ਤਾਹੀ ਕੇ ਧਿਆਨ ਬਿਖੈ ਮਨੁ ਦੀਨੋ।","roman":"Soor sasee sur naarad saarad taahee ke dhiaan bikhai manu deeno |","meaning_en":"","page":577},{"gurmukhi":"ਖੋਜਤ ਹੈ ਜਿਹ ਸਿਧ ਮਹਾ ਮੁਨਿ ਬਿਆਸ ਪਰਾਸੁਰ ਭੇਦ ਨ ਚੀਨੋ।","roman":"Khojat hai jih sidh mahaa muni biaas paraasur bhed na cheeno |","meaning_en":"","page":577},{"gurmukhi":"ਸੋ ਖੜਗੇਸ ਅਯੋਧਨ ਮੈ ਕਰਿ ਮੋਹਿਤ ਕੇਸਨ ਤੇ ਗਹਿ ਲੀਨੋ। ੧੫੩੧।","roman":"So kharges ayodhan mai kari mohit kesan te gahi leeno | 1531 |","meaning_en":"","page":577}]},{"type":"verse","number":[1532],"number_text":"੧੫੩੨।","page":577,"lines":[{"gurmukhi":"ਮਾਰਿ ਬਕੀ ਬਕ ਅਉਰ ਅਘਾਸੁਰ ਧੇਨਕ ਕੋ ਪਲ ਮੈ ਬਧ ਕੀਨੋ।","roman":"Maari bakee bak aur aghaasur dhenak ko pal mai badh keeno |","meaning_en":"","page":577},{"gurmukhi":"ਕੇਸੀ ਬਛਾਸੁਰ ਮੁਸਟ ਚੰਡੂਰ ਕੀਏ ਚਕਚੂਰ ਸੁਨਿਯੋ ਪੁਰ ਤੀਨੋ।","roman":"Kesee bachhaasur musat chandoor kee'e chakchoor suniyo pur teeno |","meaning_en":"","page":577},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਸਤ੍ਰ ਅਨੇਕ ਹਨੇ ਤਿਹ ਕਉਨ ਗਨੇ ਕਬਿ ਸ੍ਯਾਮ ਪ੍ਰਬੀਨੋ।","roman":"Sree hari satr anek hane tih kaun gane kabi syaam prabeeno |","meaning_en":"","page":577},{"gurmukhi":"ਕੰਸ ਕਉ ਕੇਸਨ ਤੇ ਗਹਿ ਕੇਸਵ ਭੂਪ ਮਨੋ ਬਦਲੋ ਵਹੁ ਲੀਨੋ। ੧੫੩੨।","roman":"Kans kau kesan te gahi kesav bhoop mano badlo vahu leeno | 1532 |","meaning_en":"","page":577}]},{"type":"verse","number":[1533],"number_text":"੧੫੩੩।","page":577,"lines":[{"gurmukhi":"ਚਿੰਤ ਕਰੀ ਚਿਤ ਮੈ ਤਿਹ ਭੂਪਤਿ ਜੋ ਇਹ ਕਉ ਅਬ ਹਉ ਬਧ ਕੈ ਹਉ।","roman":"Chint karee chit mai tih bhoopti jo ih kau ab hau badh kai hau |","meaning_en":"","page":577},{"gurmukhi":"ਸੈਨ ਸਭੈ ਭਜ ਹੈ ਜਬ ਹੀ ਤਬ ਕਾ ਸੰਗ ਜਾਇ ਕੈ ਜੁਧੁ ਮਚੈ ਹਉ।","roman":"Sain sabhai bhaj hai jab hee tab kaa sang jaai kai judhu machai hau |","meaning_en":"","page":577},{"gurmukhi":"ਹਉ ਕਿਹ ਪੈ ਕਰਿ ਹੋ ਬਹੁ ਘਾਇਨ ਕਾ ਕੇ ਹਉ ਘਾਇਨ ਸਨਮੁਖ ਖੈ ਹਉ।","roman":"Hau kih pai kari ho bahu ghaain kaa ke hau ghaain sanmukh khai hau |","meaning_en":"","page":577},{"gurmukhi":"ਛਾਡਿ ਦਯੋ ਕਹਿਓ ਜਾਹੁ ਚਲੇ ਹਰਿ ਤੋ ਸਮ ਸੂਰ ਕਹੂੰ ਨਹੀ ਪੈ ਹਉ। ੧੫੩੩।","roman":"Chhaadi dayo kahio jaahu chale hari to sam soor kahoon nahee pai hau | 1533 |","meaning_en":"","page":577}]},{"type":"verse","number":[1534],"number_text":"੧੫੩੪।","page":577,"lines":[{"gurmukhi":"ਪਉਰਖ ਜੈਸੋ ਬਡੋ ਕੀਯੋ ਭੂਪ ਨ ਆਗੈ ਕਿਸੀ ਨ੍ਰਿਪ ਐਸੋ ਕੀਯੋ।","roman":"Paurakh jaiso bado keeyo bhoop na aagai kisee nrip aiso keeyo |","meaning_en":"","page":577},{"gurmukhi":"ਭਟ ਪੇਖਿ ਕੈ ਭਾਜਿ ਗਏ ਸਿਗਰੇ ਕਿਨਹੂੰ ਧਨੁ ਬਾਨ ਨ ਪਾਨਿ ਲੀਓ।","roman":"Bhat pekhi kai bhaaji gae sigre kinhoon dhanu baan na paani leeo |","meaning_en":"","page":577},{"gurmukhi":"ਹਥਿਯਾਰ ਉਤਾਰ ਚਲੇ ਬਿਸੰਭਾਰਿ ਰਥੀ ਰਥ ਟਾਰਿ ਡਰਾਤ ਹੀਓ।","roman":"Hathiyaar utaar chale bisanbhaari rathee rath taari daraat heeo |","meaning_en":"","page":577},{"gurmukhi":"ਰਨ ਮੈ ਖੜਗੇਸ ਬਲੀ ਬਲੁ ਕੈ ਅਪੁਨੋ ਕਰ ਕੈ ਹਰਿ ਛਾਡਿ ਦੀਯੋ। ੧੫੩੪।","roman":"Ran mai kharges balee balu kai apuno kar kai hari chhaadi deeyo | 1534 |","meaning_en":"","page":577}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":577},{"type":"verse","number":[1535],"number_text":"੧੫੩੫।","page":577,"lines":[{"gurmukhi":"ਛਾਡਿ ਕੇਸ ਤੇ ਜਬ ਹਰਿ ਦਯੋ। ਲਜਤ ਭਯੋ ਬਿਸਰਿ ਬਲੁ ਗਯੋ।","roman":"Chhaadi kes te jab hari dayo | lajat bhayo bisri balu gayo |","meaning_en":"","page":577},{"gurmukhi":"ਤਬ ਬ੍ਰਹਮਾ ਪ੍ਰਤਛ ਹੁਇ ਆਯੋ। ਕ੍ਰਿਸਨ ਤਾਪ ਤਿਨਿ ਸਕਲ ਮਿਟਾਯੋ। ੧੫੩੫।","roman":"Tab brahmaa pratachh hui aayo | krisan taap tini sakal mitaayo | 1535 |","meaning_en":"","page":577}]},{"type":"verse","number":[1536],"number_text":"੧੫੩੬।","page":577,"lines":[{"gurmukhi":"ਕਹੇ ਕ੍ਰਿਸਨ ਸਿਉ ਇਹ ਬਿਧਿ ਬੈਨਾ। ਲਾਜ ਕਰੋ ਨਹਿ ਪੰਕਜ ਨੈਨਾ।","roman":"Kahe krisan siu ih bidhi bainaa | laaj karo nahi pankaj nainaa |","meaning_en":"","page":577},{"gurmukhi":"ਇਹ ਪਉਰਖ ਹਉ ਤੋਹਿ ਸੁਨਾਊ। ਤਿਹ ਤੇ ਤੋ ਕਹੁ ਅਬਹਿ ਰਿਝਾਊ। ੧੫੩੬।","roman":"Ih paurakh hau tohi sunaaoo | tih te to kahu abhi rijhaaoo | 1536 |","meaning_en":"","page":577}]},{"type":"heading","kind":"speaker","name":"ਬ੍ਰਹਮਾ ਬਾਚ","gurmukhi":"ਬ੍ਰਹਮਾ ਬਾਚ","roman":"Brahmaa baach","meaning_en":"","page":578},{"type":"heading","kind":"chhand","name":"ਤੋਟਕ ਛੰਦ","gurmukhi":"ਤੋਟਕ ਛੰਦ","roman":"Totak chhand","meaning_en":"","page":578},{"type":"verse","number":[1537],"number_text":"੧੫੩੭।","page":578,"lines":[{"gurmukhi":"ਜਬ ਹੀ ਇਹ ਭੂਪਤਿ ਜਨਮ ਲੀਓ। ਤਜਿ ਧਾਮ ਤਬੈ ਬਨਿਬਾਸੁ ਕੀਓ।","roman":"Jab hee ih bhoopti janam leeo | taji dhaam tabai banibaasu keeo |","meaning_en":"","page":578},{"gurmukhi":"ਤਪਸਾ ਕਰਿ ਕੈ ਜਗ ਮਾਤ ਰਿਝਾਯੋ। ਤਹ ਤੇ ਅਰਿ ਜੀਤਨ ਕੋ ਬਰੁ ਪਾਯੋ। ੧੫੩੭।","roman":"Tapsaa kari kai jag maat rijhaayo | tah te ari jeetan ko baru paayo | 1537 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":578},{"type":"verse","number":[1538],"number_text":"੧੫੩੮।","page":578,"lines":[{"gurmukhi":"ਇਹ ਕੇ ਬਧ ਕੋ ਏਕੁ ਉਪਾਈ। ਸੋ ਪ੍ਰਭ ਤੋ ਕਹਿ ਕਹਤ ਸੁਨਾਈ।","roman":"Ih ke badh ko eku upaaee | so prabh to kahi kahat sunaaee |","meaning_en":"","page":578},{"gurmukhi":"ਬਿਸਨ ਆਇ ਜੋ ਯਾ ਸੰਗਿ ਲਰੈ। ਤਾਹਿ ਭਜਾਵੈ ਬਿਲਮੁ ਨ ਕਰੈ। ੧੫੩੮।","roman":"Bisan aai jo yaa sangi larai | taahi bhajaavai bilmu na karai | 1538 |","meaning_en":"","page":578}]},{"type":"verse","number":[1539],"number_text":"੧੫੩੯।","page":578,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਦ੍ਵਾਦਸ ਭਾਨ ਬੁਲਾਵਹੁ। ਰੁਦ੍ਰ ਗਿਆਰਹ ਮਿਲ ਕਰਿ ਧਾਵਹੁ।","roman":"Indr dvaadas bhaan bulaavhu | rudr giaarah mil kari dhaavhu |","meaning_en":"","page":578},{"gurmukhi":"ਸੋਮ ਸੁ ਜਮ ਆਠੋ ਬਸ ਜੋਧੇ। ਐਸੀ ਬਿਧਿ ਬਿਧਿ ਹਰਹਿੰ ਪ੍ਰਬੋਧੇ। ੧੫੩੯।","roman":"Som su jam aatho bas jodhe | aisee bidhi bidhi harhin prabodhe | 1539 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":578},{"type":"verse","number":[1540],"number_text":"੧੫੪੦।","page":578,"lines":[{"gurmukhi":"ਏ ਸਭ ਸੁਭਟ ਬੁਲਾਇ ਜੁਧ ਕਾਜ ਰਨਿ ਪ੍ਰਗਟਹੀ।","roman":"E sabh subhat bulaai judh kaaj rani pragathee |","meaning_en":"","page":578},{"gurmukhi":"ਆਪੁਨੇ ਦਲਹਿੰ ਜਗਾਇ ਕਹੋ ਜੂਝ ਏਊ ਕਰਹਿੰ। ੧੫੪੦।","roman":"Aapune dalhin jagaai kaho joojh eoo karhin | 1540 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":578},{"type":"verse","number":[1541],"number_text":"੧੫੪੧।","page":578,"lines":[{"gurmukhi":"ਪੁਨਿ ਅਪਛਰਾ ਸਕਲ ਬੁਲਾਵਹੁ। ਇਹ ਕੀ ਅਗ੍ਰਜ ਦ੍ਰਿਸਟਿ ਨਚਾਵਹੁ।","roman":"Puni apachhraa sakal bulaavhu | ih kee agraj dristi nachaavhu |","meaning_en":"","page":578},{"gurmukhi":"ਕਾਮਦੇਵ ਕਉ ਆਇਸ ਦੀਜੈ। ਯਾ ਕੋ ਚਿਤ ਮੋਹਿ ਕਰਿ ਲੀਜੈ। ੧੫੪੧।","roman":"Kaamdev kau aais deejai | yaa ko chit mohi kari leejai | 1541 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":578},{"type":"verse","number":[1542],"number_text":"੧੫੪੨।","page":578,"lines":[{"gurmukhi":"ਤਬਹਿ ਕ੍ਰਿਸਨ ਸੋਊ ਕੀਓ ਜੋ ਬ੍ਰਹਮਾ ਸਿਖ ਦੀਨ।","roman":"Tabhi krisan so'oo keeo jo brahmaa sikh deen |","meaning_en":"","page":578},{"gurmukhi":"ਇੰਦ੍ਰ ਸੂਰ ਸਬ ਰੁਦ੍ਰ ਬਸ ਜਮਹਿ ਬੋਲਿ ਕਰ ਲੀਨ। ੧੫੪੨।","roman":"Indr soor sab rudr bas jamhi boli kar leen | 1542 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":578},{"type":"verse","number":[1543],"number_text":"੧੫੪੩।","page":578,"lines":[{"gurmukhi":"ਨਿਕਟਿ ਸ੍ਯਾਮ ਕੇ ਤਬ ਸਬ ਆਏ। ਕ੍ਰੋਧ ਹੋਇ ਮਨ ਜੁਧਹਿ ਧਾਏ।","roman":"Nikti syaam ke tab sab aae | krodh hoi man judhhi dhaae |","meaning_en":"","page":578},{"gurmukhi":"ਇਤ ਸਬ ਮਿਲ ਕੈ ਜੁਧ ਮਚਾਯੋ। ਉਤ ਅਪਛਰਾ ਨਭਿ ਝਰਲਾਯੋ। ੧੫੪੩।","roman":"It sab mil kai judh machaayo | ut apachhraa nabhi jharlaayo | 1543 |","meaning_en":"","page":578}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":578},{"type":"verse","number":[1544],"number_text":"੧੫੪੪।","page":578,"lines":[{"gurmukhi":"ਕੈ ਕੈ ਕਟਾਛ ਨਚੈ ਤੇਊ ਭਾਮਿਨ ਗੀਤ ਸਬੈ ਮਿਲ ਕੈ ਸੁਰ ਗਾਵੈ।","roman":"Kai kai kataachh nachai teoo bhaamin geet sabai mil kai sur gaavai |","meaning_en":"","page":578},{"gurmukhi":"ਬੀਨ ਪਖਾਵਜ ਤਾਲ ਬਜੈ ਡਫ ਭਾਤਿ ਅਨੇਕਨ ਭਾਉ ਦਿਖਾਵੈ।","roman":"Been pakhaavaj taal bajai daph bhaati anekan bhaau dikhaavai |","meaning_en":"","page":578},{"gurmukhi":"ਸਾਰੰਗ ਸੋਰਠਿ ਮਾਲਸਿਰੀ ਅਰੁ ਰਾਮਕਲੀ ਨਟ ਸੰਗ ਮਿਲਾਵੈ।","roman":"Saarang sorthi maalsiree aru raamaklee nat sang milaavai |","meaning_en":"","page":578},{"gurmukhi":"ਭੋਗਨਿ ਮੋਹਿ ਕੀ ਬਾਤ ਕਿਤੀ ਸੁਨਿ ਕੈ ਮਨ ਜੋਗਨ ਕੇ ਦ੍ਰਵ ਜਾਵੈ। ੧੫੪੪।","roman":"Bhogni mohi kee baat kitee suni kai man jogan ke drav jaavai | 1544 |","meaning_en":"","page":578}]},{"type":"verse","number":[1545],"number_text":"੧੫੪੫।","page":579,"lines":[{"gurmukhi":"ਉਤ ਸੁੰਦਰ ਨਿਰਤ ਕਰੈ ਨਭ ਮੈ ਇਤ ਬੀਰ ਸਬੈ ਮਿਲਿ ਜੁਧ ਕਰੈ।","roman":"Ut sundar nirat karai nabh mai it beer sabai mili judh karai |","meaning_en":"","page":579},{"gurmukhi":"ਬਰਛੀ ਕਰਵਾਰ ਕਟਾਰਨ ਸਿਉ ਜਬ ਹੀ ਮਨ ਮੈ ਅਤਿ ਕ੍ਰੁਧ ਭਰੈ।","roman":"Barchhee karvaar kataaran siu jab hee man mai ati krudh bharai |","meaning_en":"","page":579},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਅਯੋਧਨ ਮੈ ਰਦਨ ਛਦ ਪੀਸ ਕੈ ਆਨਿ ਪਰੈ ਨ ਡਰੈ।","roman":"Kabi syaam ayodhan mai radan chhad pees kai aani parai na darai |","meaning_en":"","page":579},{"gurmukhi":"ਲਰਿ ਕੈ ਮਰਿ ਕੈ ਜੁ ਕਬੰਧ ਉਠੈ ਅਰਿ ਕੈ ਸੁ ਅਪਛਰ ਤਾਹਿ ਬਰੈ। ੧੫੪੫।","roman":"Lari kai mari kai ju kabandh uthai ari kai su apchhar taahi barai | 1545 |","meaning_en":"","page":579}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":579},{"type":"verse","number":[1546],"number_text":"੧੫੪੬।","page":579,"lines":[{"gurmukhi":"ਬਡੋ ਜੁਧੁ ਭੂਪਤਿ ਕੀਓ ਮਨ ਮੈ ਕੋਪ ਬਢਾਇ।","roman":"Bado judhu bhoopti keeo man mai kop badhaai |","meaning_en":"","page":579},{"gurmukhi":"ਸਬ ਦੇਵਨ ਕੋ ਦਿਨ ਪਰੈ ਸੋ ਕਬਿ ਕਹਤ ਸੁਨਾਇ। ੧੫੪੬।","roman":"Sab devan ko din parai so kabi kahat sunaai | 1546 |","meaning_en":"","page":579}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":579},{"type":"verse","number":[1547],"number_text":"੧੫੪੭।","page":579,"lines":[{"gurmukhi":"ਗਿਆਰਹ ਰੁਦ੍ਰਨ ਕੋ ਸਰ ਬਾਇਸ ਦ੍ਵਾਦਸ ਭਾਨਨ ਚਉਬਿਸਿ ਮਾਰੇ।","roman":"Giaarah rudran ko sar baais dvaadas bhaanan chaubisi maare |","meaning_en":"","page":579},{"gurmukhi":"ਇੰਦ੍ਰ ਸਹੰਸ੍ਰ ਖੜਾਨਨ ਕੋ ਖਟ ਪਾਚਸਿ ਕਾਨ੍ਹ ਕੋ ਕੋਪ ਪ੍ਰਹਾਰੇ।","roman":"Indr sahansr kharaanan ko khat paachsi kaanh ko kop prahaare |","meaning_en":"","page":579},{"gurmukhi":"ਸੋਮ ਕੋ ਸਾਠ ਗਨੇਸ ਕੋ ਸਤਰ ਆਠ ਬਸੂਨ ਕੋ ਚਉਸਠ ਡਾਰੇ।","roman":"Som ko saath ganes ko satar aath basoon ko chausath daare |","meaning_en":"","page":579},{"gurmukhi":"ਸਾਤ ਕੁਬੇਰ ਕੋ ਨਉ ਜਮਰਾਜਹਿ ਏਕ ਹੀ ਸੋ ਅਉਰ ਸੰਘਾਰੇ। ੧੫੪੭।","roman":"Saat kuber ko nau jamraajhi ek hee so aur sanghaare | 1547 |","meaning_en":"","page":579}]},{"type":"verse","number":[1548],"number_text":"੧੫੪੮।","page":579,"lines":[{"gurmukhi":"ਬਾਨਨ ਬੇਧਿ ਜਲਾਧਿਪਿ ਕਉ ਨਲ ਕੂਬਰ ਅਉ ਜਮ ਕੇ ਉਰਿ ਮਾਰਿਓ।","roman":"Baanan bedhi jalaadhipi kau nal koobar au jam ke uri maario |","meaning_en":"","page":579},{"gurmukhi":"ਅਉਰ ਕਹਾ ਲਗਿ ਸ੍ਯਾਮ ਗਨੈ ਜੁ ਹੁਤੇ ਰਨ ਮੈ ਸਬਹੂਨ ਪ੍ਰਹਾਰਿਓ।","roman":"Aur kahaa lagi syaam ganai ju hute ran mai sabhoon prahaario |","meaning_en":"","page":579},{"gurmukhi":"ਸੰਕਤਮਾਨ ਭਏ ਸਬ ਹੀ ਕਿਨ ਹੂੰ ਨਹੀ ਭੂਪ ਕੀ ਓਰਿ ਨਿਹਾਰਿਓ।","roman":"Sankatmaan bhae sab hee kin hoon nahee bhoop kee ori nihaario |","meaning_en":"","page":579},{"gurmukhi":"ਮਾਨੋ ਜੁਗੰਤ ਕੇ ਅੰਤ ਸਮੈ ਪ੍ਰਗਟਿਓ ਕਲਿ ਕਾਲ ਤਿਨੋ ਸੁ ਬਿਚਾਰਿਓ। ੧੫੪੮।","roman":"Maano jugant ke ant samai pragtio kali kaal tino su bichaario | 1548 |","meaning_en":"","page":579}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":579},{"type":"verse","number":[1549],"number_text":"੧੫੪੯।","page":579,"lines":[{"gurmukhi":"ਤਿਆਗਿ ਦਯੋ ਰਨ ਤ੍ਰਾਸ ਬਢਾਯੋ। ਕਿਨ ਹੂੰ ਨ ਤਿਹ ਸੋ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Tiaagi dayo ran traas badhaayo | kin hoon na tih so judhu machaayo |","meaning_en":"","page":579},{"gurmukhi":"ਚਿਤਿ ਸਬ ਹੂੰ ਇਹ ਭਾਤਿ ਬਿਚਾਰਿਓ। ਇਹ ਨਹੀ ਮਰੈ ਕਿਸੀ ਤੇ ਮਾਰਿਓ। ੧੫੪੯।","roman":"Chiti sab hoon ih bhaati bichaario | ih nahee marai kisee te maario | 1549 |","meaning_en":"","page":579}]},{"type":"verse","number":[1550],"number_text":"੧੫੫੦।","page":579,"lines":[{"gurmukhi":"ਤਬ ਬ੍ਰਹਮੇ ਹਰਿ ਨਿਕਟ ਉਚਾਰਿਓ। ਜਬ ਸਗਲੋ ਦਲ ਨ੍ਰਿਪਤਿ ਸੰਘਾਰਿਓ।","roman":"Tab brahme hari nikat uchaario | jab saglo dal nripti sanghaario |","meaning_en":"","page":579},{"gurmukhi":"ਜਬ ਲਗਿ ਇਹ ਤੇਤਾ ਕਰਿ ਮੋ ਹੈ। ਤਬ ਲਗੁ ਬਜ੍ਰ ਸੂਲ ਧਰਿ ਕੋ ਹੈ। ੧੫੫੦।","roman":"Jab lagi ih tetaa kari mo hai | tab lagu bajr sool dhari ko hai | 1550 |","meaning_en":"","page":579}]},{"type":"verse","number":[1551],"number_text":"੧੫੫੧।","page":579,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਇਹੈ ਕਾਜ ਅਬ ਕੀਜੈ। ਭਿਛਕਿ ਹੋਇ ਮਾਗਿ ਸੋ ਲੀਜੈ।","roman":"Taa te ihai kaaj ab keejai | bhichhki hoi maagi so leejai |","meaning_en":"","page":579},{"gurmukhi":"ਮੁਕਟ ਰਾਮ ਤੇ ਜੋ ਇਹ ਪਾਯੋ। ਸੋ ਇੰਦ੍ਰਾਦਿਕ ਹਾਥਿ ਨ ਆਯੋ। ੧੫੫੧।","roman":"Mukat raam te jo ih paayo | so indraadik haathi na aayo | 1551 |","meaning_en":"","page":579}]},{"type":"verse","number":[1552],"number_text":"੧੫੫੨।","page":579,"lines":[{"gurmukhi":"ਜਬ ਤੇਤਾ ਇਹ ਕਰ ਤੇ ਲੀਜੈ। ਤਬ ਯਾ ਕੋ ਬਧ ਛਿਨ ਮਹਿ ਕੀਜੈ।","roman":"Jab tetaa ih kar te leejai | tab yaa ko badh chhin mahi keejai |","meaning_en":"","page":579},{"gurmukhi":"ਜਿਹ ਉਪਾਇ ਕਰਿ ਤੇ ਪਰਹਰੈ। ਤਉ ਕਦਾਚ ਨ੍ਰਿਪ ਮਰੈ ਤੋ ਮਰੈ। ੧੫੫੨।","roman":"Jih upaai kari te parahrai | tau kadaach nrip marai to marai | 1552 |","meaning_en":"","page":579}]},{"type":"verse","number":[1553],"number_text":"੧੫੫੩।","page":580,"lines":[{"gurmukhi":"ਯੋ ਸੁਨਿ ਹਰਿ ਦਿਜ ਬੇਖ ਬਨਾਯੋ। ਮਾਗਨ ਤਿਹ ਪੈ ਹਰਿ ਬਿਧਿ ਆਯੋ।","roman":"Yo suni hari dij bekh banaayo | maagan tih pai hari bidhi aayo |","meaning_en":"","page":580},{"gurmukhi":"ਤਬ ਇਹ ਸ੍ਯਾਮ ਬ੍ਰਹਮ ਲਖਿ ਲੀਨੋ। ਸ੍ਯਾਮ ਕਹੈ ਇਮ ਉਤਰ ਦੀਨੋ। ੧੫੫੩।","roman":"Tab ih syaam braham lakhi leeno | syaam kahai im utar deeno | 1553 |","meaning_en":"","page":580}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ","roman":"Kharges baach","meaning_en":"","page":580},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":580},{"type":"verse","number":[1554],"number_text":"੧੫੫੪।","page":580,"lines":[{"gurmukhi":"ਬੇਖੁ ਕੀਓ ਹਰਿ ਬਾਮਨ ਕੋ ਬਲਿ ਬਾਵਨ ਜਿਉ ਛਲਬੇ ਕਹੁ ਆਯੋ।","roman":"Bekhu keeo hari baaman ko bali baavan jiu chhalbe kahu aayo |","meaning_en":"","page":580},{"gurmukhi":"ਰੇ ਚਤੁਰਾਨਨ ਤੂ ਬਸਿ ਕਾਨਨ ਕਾ ਕੇ ਕਹੇ ਤਪਿਸਾ ਤਜ ਧਾਯੋ।","roman":"Re chaturaanan too basi kaanan kaa ke kahe tapisaa taj dhaayo |","meaning_en":"","page":580},{"gurmukhi":"ਧੂਮ ਤੇ ਆਗ ਰਹੈ ਨ ਦੁਰੀ ਜਿਮ ਤਿਉ ਛਲ ਤੇ ਤੁਮ ਕੇ ਲਖਿ ਪਾਯੋ।","roman":"Dhoom te aag rahai na duree jim tiu chhal te tum ke lakhi paayo |","meaning_en":"","page":580},{"gurmukhi":"ਮਾਗਹੁ ਜੋ ਤੁਮਰੇ ਮਨ ਮੈ ਅਬ ਮਾਗਨਹਾਰੇ ਕੋ ਰੂਪ ਬਨਾਯੋ। ੧੫੫੪।","roman":"Maaghu jo tumre man mai ab maaganhaare ko roop banaayo | 1554 |","meaning_en":"","page":580}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":580},{"type":"verse","number":[1555],"number_text":"੧੫੫੫।","page":580,"lines":[{"gurmukhi":"ਜਬ ਇਹ ਬਿਧਿ ਸੋ ਨ੍ਰਿਪ ਕਹਿਯੋ ਕਹੀ ਬ੍ਰਹਮ ਜਸ ਲੇਹੁ।","roman":"Jab ih bidhi so nrip kahiyo kahee braham jas lehu |","meaning_en":"","page":580},{"gurmukhi":"ਜਗ ਅਨਲ ਤੇ ਜੋ ਮੁਕਟਿ ਉਪਜਿਓ ਸੋ ਮੁਹਿ ਦੇਹੁ। ੧੫੫੫।","roman":"Jag anal te jo mukti upjio so muhi dehu | 1555 |","meaning_en":"","page":580}]},{"type":"verse","number":[1556],"number_text":"੧੫੫੬।","page":580,"lines":[{"gurmukhi":"ਜਬ ਚਤੁਰਾਨਨਿ ਯੌ ਕਹੀ ਪੁਨਿ ਬੋਲਿਓ ਜਦੁਬੀਰ।","roman":"Jab chaturaanni yau kahee puni bolio jadubeer |","meaning_en":"","page":580},{"gurmukhi":"ਗਉਰਾ ਤੇਤਾ ਤੁਹਿ ਦਯੋ ਸੋ ਮੁਹਿ ਦੇ ਨ੍ਰਿਪ ਧੀਰ। ੧੫੫੬।","roman":"Gauraa tetaa tuhi dayo so muhi de nrip dheer | 1556 |","meaning_en":"","page":580}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":580},{"type":"verse","number":[1557],"number_text":"੧੫੫੭।","page":580,"lines":[{"gurmukhi":"ਤਬ ਨ੍ਰਿਪ ਮਨ ਕੋ ਇਹ ਬਿਧਿ ਕਹੈ। ਰੇ ਜੀਅ ਜੀਯਤ ਨ ਚਹੁੰ ਜੁਗ ਰਹੈ।","roman":"Tab nrip man ko ih bidhi kahai | re jeea jeeyat na chahun jug rahai |","meaning_en":"","page":580},{"gurmukhi":"ਤਾ ਤੇ ਸੁ ਧਰਮ ਢੀਲ ਨਹਿ ਕੀਜੈ। ਜੋ ਹਰਿ ਮਾਗਤ ਸੋ ਇਹ ਦੀਜੈ। ੧੫੫੭।","roman":"Taa te su dharam dheel nahi keejai | jo hari maagat so ih deejai | 1557 |","meaning_en":"","page":580}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":580},{"type":"verse","number":[1558],"number_text":"੧੫੫੮।","page":580,"lines":[{"gurmukhi":"ਕਿਉ ਤਨ ਕੀ ਮਨਿ ਸੰਕ ਕਰੈ ਥਿਰ ਤੋ ਜਗ ਮੈ ਅਬ ਤੂ ਨ ਰਹੈ ਹੈ।","roman":"Kiu tan kee mani sank karai thir to jag mai ab too na rahai hai |","meaning_en":"","page":580},{"gurmukhi":"ਯਾ ਤੇ ਭਲੋ ਨ ਕਛੂ ਇਹ ਤੇ ਜਸੁ ਲੈ ਰਨ ਅੰਤਹਿ ਮੋ ਤਜਿ ਜੈ ਹੈ।","roman":"Yaa te bhalo na kachhoo ih te jasu lai ran anthi mo taji jai hai |","meaning_en":"","page":580},{"gurmukhi":"ਰੇ ਮਨ ਢੀਲ ਰਹਿਯੋ ਗਹਿ ਕਾਹੇ ਤੇ ਅਉਸਰ ਬੀਤ ਗਏ ਪਛੁਤੈ ਹੈ।","roman":"Re man dheel rahiyo gahi kaahe te ausar beet gae pachhutai hai |","meaning_en":"","page":580},{"gurmukhi":"ਸੋਕ ਨਿਵਾਰਿ ਨਿਸੰਕ ਹੁਇ ਦੈ ਭਗਵਾਨ ਸੋ ਭਿਛਕ ਹਾਥਿ ਨ ਐ ਹੈ। ੧੫੫੮।","roman":"Sok nivaari nisank hui dai bhagvaan so bhichhak haathi na ai hai | 1558 |","meaning_en":"","page":580}]},{"type":"verse","number":[1559],"number_text":"੧੫੫੯।","page":580,"lines":[{"gurmukhi":"ਮਾਗਤ ਜੋ ਬਿਧਿ ਸ੍ਯਾਮ ਅਰੇ ਮਨ ਸੋ ਤਜਿ ਸੰਕ ਨਿਸੰਕ ਹੁਇ ਦੀਜੈ।","roman":"Maagat jo bidhi syaam are man so taji sank nisank hui deejai |","meaning_en":"","page":580},{"gurmukhi":"ਜਾਚਤ ਹੈ ਜਿਹ ਤੇ ਸਗਰੋ ਜਗ ਸੋ ਤੁਹਿ ਮਾਗਤ ਢੀਲ ਨ ਕੀਜੈ।","roman":"Jaachat hai jih te sagro jag so tuhi maagat dheel na keejai |","meaning_en":"","page":580},{"gurmukhi":"ਅਉਰ ਬਿਚਾਰ ਕਰੋ ਨ ਕਛੂ ਅਬ ਯਾ ਮਹਿ ਤੋ ਨ ਰਤੀ ਸੁਖ ਛੀਜੈ।","roman":"Aur bichaar karo na kachhoo ab yaa mahi to na ratee sukh chheejai |","meaning_en":"","page":580},{"gurmukhi":"ਦਾਨਨ ਦੇਤ ਨ ਮਾਨ ਕਰੋ ਬਸੁ ਦੈ ਅਸੁ ਦੈ ਜਗ ਮੈ ਜਸੁ ਲੀਜੈ। ੧੫੫੯।","roman":"Daanan det na maan karo basu dai asu dai jag mai jasu leejai | 1559 |","meaning_en":"","page":580}]},{"type":"verse","number":[1560],"number_text":"੧੫੬੦।","page":581,"lines":[{"gurmukhi":"ਬਾਮਨ ਬੇਖ ਕੈ ਸ੍ਯਾਮ ਜੁ ਚਾਹਤ ਸ੍ਰੀ ਹਰਿ ਕੋ ਤਿਹ ਭੂਪਤਿ ਦੀਨੋ।","roman":"Baaman bekh kai syaam ju chaahat sree hari ko tih bhoopti deeno |","meaning_en":"","page":581},{"gurmukhi":"ਜੋ ਚਤੁਰਾਨਨ ਕੇ ਚਿਤ ਮੈ ਕਬਿ ਰਾਮ ਕਹੈ ਸੁ ਵਹੈ ਨ੍ਰਿਪ ਕੀਨੋ।","roman":"Jo chaturaanan ke chit mai kabi raam kahai su vahai nrip keeno |","meaning_en":"","page":581},{"gurmukhi":"ਜੋ ਵਹ ਮਾਗਤਿ ਸੋਊ ਦਯੋ ਤਬ ਦੇਤ ਸਮੈ ਰਸ ਮੈ ਮਨ ਭੀਨੋ।","roman":"Jo vah maagti so'oo dayo tab det samai ras mai man bheeno |","meaning_en":"","page":581},{"gurmukhi":"ਦਾਨ ਕ੍ਰਿਪਾਨ ਦੁਹੁੰ ਬਿਧਿ ਹੈ ਤਿਹੁ ਲੋਕਨ ਮੈ ਅਤਿ ਹੀ ਜਸੁ ਲੀਨੋ। ੧੫੬੦।","roman":"Daan kripaan duhun bidhi hai tihu lokan mai ati hee jasu leeno | 1560 |","meaning_en":"","page":581}]},{"type":"verse","number":[1561],"number_text":"੧੫੬੧।","page":581,"lines":[{"gurmukhi":"ਬ੍ਰਹਮ ਕਰੀਟ ਤਵੀਤ ਲਯੋ ਹਰਿ ਗਾਜਿ ਉਠੇ ਤਬ ਹੀ ਸਬ ਸੂਰੇ।","roman":"Braham kareet taveet layo hari gaaji uthe tab hee sab soore |","meaning_en":"","page":581},{"gurmukhi":"ਧਾਇ ਪਰੇ ਨ੍ਰਿਪ ਪੈ ਮਿਲਿ ਕੈ ਚਿਤਿ ਮੈ ਚਪਿ ਰੋਸਿ ਕੈ ਮਾਰਿ ਮਰੂਰੈ।","roman":"Dhaai pare nrip pai mili kai chiti mai chapi rosi kai maari maroorai |","meaning_en":"","page":581},{"gurmukhi":"ਭੂਪਿ ਹਨੇ ਬਰ ਬੀਰ ਘਨੇ ਸੁ ਪਰੇ ਧਰਿ ਊਪਰਿ ਲਾਗਤਿ ਰੂਰੇ।","roman":"Bhoopi hane bar beer ghane su pare dhari oopri laagti roore |","meaning_en":"","page":581},{"gurmukhi":"ਛਾਰ ਲਗਾਇ ਕੈ ਅੰਗ ਮਲੰਗ ਰਹੇ ਮਨੋ ਸੋਇ ਕੈ ਖਾਇ ਧਤੂਰੇ। ੧੫੬੧।","roman":"Chhaar lagaai kai ang malang rahe mano soi kai khaai dhatoore | 1561 |","meaning_en":"","page":581}]},{"type":"verse","number":[1562],"number_text":"੧੫੬੨।","page":581,"lines":[{"gurmukhi":"ਹੇਰਿ ਸਬੈ ਮਿਲਿ ਘੇਰਿ ਲਯੋ ਸੁ ਭਯੋ ਮਨ ਭੂਪਤਿ ਕੋਪ ਮਈ ਹੈ।","roman":"Heri sabai mili gheri layo su bhayo man bhoopti kop maee hai |","meaning_en":"","page":581},{"gurmukhi":"ਰਾਮ ਅਯੋਧਨ ਮੈ ਫਿਰ ਕੈ ਕਰਰੀ ਕਰ ਬੀਚ ਕਮਾਨ ਲਈ ਹੈ।","roman":"Raam ayodhan mai phir kai karree kar beech kamaan laee hai |","meaning_en":"","page":581},{"gurmukhi":"ਸੂਰਜ ਕੀ ਸਸਿ ਕੀ ਜਮ ਕੀ ਹਰਿ ਕੀ ਬਹੁ ਸੈਨ ਗਿਰਾਇ ਦਈ ਹੈ।","roman":"Sooraj kee sasi kee jam kee hari kee bahu sain giraai daee hai |","meaning_en":"","page":581},{"gurmukhi":"ਮਾਨਹੁ ਫਾਗੁਨ ਮਾਸ ਕੇ ਭੀਤਰ ਪਉਨ ਬਹਿਓ ਪਤ ਝਾਰ ਭਈ ਹੈ। ੧੫੬੨।","roman":"Maanhu phaagun maas ke bheetar paun bahio pat jhaar bhaee hai | 1562 |","meaning_en":"","page":581}]},{"type":"verse","number":[1563],"number_text":"੧੫੬੩।","page":581,"lines":[{"gurmukhi":"ਪਾਨਿ ਸੰਭਾਰਿ ਬਡੋ ਧਨੁ ਭੂਪਤਿ ਰੁਦ੍ਰ ਲਿਲਾਟ ਮੈ ਬਾਨੁ ਲਗਾਯੋ।","roman":"Paani sanbhaari bado dhanu bhoopti rudr lilaat mai baanu lagaayo |","meaning_en":"","page":581},{"gurmukhi":"ਏਕ ਕੁਬੇਰ ਕੇ ਮਾਰਿਓ ਰਿਦੈ ਸਰ ਲਾਗਤਿ ਡਾਰਿ ਹਥਿਆਰ ਪਰਾਯੋ।","roman":"Ek kuber ke maario ridai sar laagti daari hathiaar paraayo |","meaning_en":"","page":581},{"gurmukhi":"ਦੇਖਿ ਜਲਾਧਿਪ ਤਾਹਿ ਦਸਾ ਰਨ ਛਾਡਿ ਭਜਿਯੋ ਮਨ ਮੈ ਡਰ ਪਾਯੋ।","roman":"Dekhi jalaadhip taahi dasaa ran chhaadi bhajiyo man mai dar paayo |","meaning_en":"","page":581},{"gurmukhi":"ਧਾਇ ਪਰਿਯੋ ਰਿਸ ਕੈ ਜਮੁ ਯਾ ਪਰ ਸੋ ਨ੍ਰਿਪ ਬਾਨ ਸੋ ਭੂਮਿ ਗਿਰਾਯੋ। ੧੫੬੩।","roman":"Dhaai pariyo ris kai jamu yaa par so nrip baan so bhoomi giraayo | 1563 |","meaning_en":"","page":581}]},{"type":"verse","number":[1564],"number_text":"੧੫੬੪।","page":581,"lines":[{"gurmukhi":"ਯੌ ਜਮਰਾਜ ਗਿਰਾਇ ਦਯੋ ਤਬ ਹੀ ਰਿਸ ਕੈ ਹਰਿ ਕੋ ਦਲ ਧਾਯੋ।","roman":"Yau jamraaj giraai dayo tab hee ris kai hari ko dal dhaayo |","meaning_en":"","page":581},{"gurmukhi":"ਆਏ ਹੈ ਕੋਪ ਭਰੈ ਪਟ ਦੁਇ ਬਿਬਿਧਾਯੁਧ ਲੈ ਤਿਨ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Aae hai kop bharai pat dui bibidhaayudh lai tin judhu machaayo |","meaning_en":"","page":581},{"gurmukhi":"ਸਿੰਘ ਹੁਤੋ ਬਲਵੰਡ ਸੋ ਜਾਦਵ ਸੋ ਰਿਸ ਸੋ ਨ੍ਰਿਪ ਮਾਰਿ ਗਿਰਾਯੋ।","roman":"Singh huto balvand so jaadav so ris so nrip maari giraayo |","meaning_en":"","page":581},{"gurmukhi":"ਬਾਹੁ ਬਲੀ ਬਰਮਾਕ੍ਰਿਤ ਬੰਧੁ ਸੋਊ ਰਨ ਤੇ ਜਮ ਲੋਕਿ ਪਠਾਯੋ। ੧੫੬੪।","roman":"Baahu balee barmaakrit bandhu so'oo ran te jam loki pathaayo | 1564 |","meaning_en":"","page":581}]},{"type":"verse","number":[1565],"number_text":"੧੫੬੫।","page":581,"lines":[{"gurmukhi":"ਅਉਰ ਮਹਾ ਬਲੀ ਸਿੰਘ ਹੁਤੋ ਸੰਗ ਤੇ ਜਸ ਸਿੰਘ ਕੋ ਮਾਰਿ ਲਯੋ।","roman":"Aur mahaa balee singh huto sang te jas singh ko maari layo |","meaning_en":"","page":581},{"gurmukhi":"ਪੁਨਿ ਬੀਰ ਮਹਾ ਜਸ ਸਿੰਘ ਹੁਤੋ ਰਿਸ ਕੈ ਇਹ ਸਾਮੁਹੇ ਆਇ ਗਯੋ।","roman":"Puni beer mahaa jas singh huto ris kai ih saamuhe aai gayo |","meaning_en":"","page":581},{"gurmukhi":"ਸੋਊ ਖਗ ਸੰਭਾਰ ਕੈ ਕੋਪ ਭਰੇ ਤਿਹ ਕੌ ਨ੍ਰਿਪ ਨੈ ਲਲਕਾਰ ਲਯੋ।","roman":"So'oo khag sanbhaar kai kop bhare tih kau nrip nai lalkaar layo |","meaning_en":"","page":581},{"gurmukhi":"ਕੀਯੋ ਏਕ ਹੀ ਬਾਰ ਪ੍ਰਹਾਰ ਕ੍ਰਿਪਾਨ ਕੋ ਅੰਤ ਕੇ ਧਾਮਿ ਪਠਾਇ ਦਯੋ। ੧੫੬੫।","roman":"Keeyo ek hee baar prahaar kripaan ko ant ke dhaami pathaai dayo | 1565 |","meaning_en":"","page":581}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":581},{"type":"verse","number":[1566],"number_text":"੧੫੬੬।","page":581,"lines":[{"gurmukhi":"ਉਤਮ ਸਿੰਘ ਪ੍ਰਲੈ ਸਿੰਘ ਧਾਏ। ਪਰਮ ਸਿੰਘ ਅਸਿ ਲੈ ਕਰਿ ਆਏ।","roman":"Utam singh pralai singh dhaae | param singh asi lai kari aae |","meaning_en":"","page":581},{"gurmukhi":"ਅਤਿ ਪਵਿਤ੍ਰ ਸਿੰਘ ਸ੍ਰੀ ਸਿੰਘ ਗਏ। ਪਾਚੋ ਭੂਪ ਮਾਰਿ ਤਿਹ ਲਏ। ੧੫੬੬।","roman":"Ati pavitr singh sree singh gae | paacho bhoop maari tih lae | 1566 |","meaning_en":"","page":581}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":582},{"type":"verse","number":[1567],"number_text":"੧੫੬੭।","page":582,"lines":[{"gurmukhi":"ਫਤੇ ਸਿੰਘ ਅਰੁ ਫਉਜ ਸਿੰਘ ਚਿਤਿ ਅਤਿ ਕੋਪ ਬਢਾਇ।","roman":"Phate singh aru phauj singh chiti ati kop badhaai |","meaning_en":"","page":582},{"gurmukhi":"ਏ ਦੋਊ ਭਟ ਆਵਤ ਹੁਤੇ ਭੂਪਤਿ ਹਨੇ ਬਜਾਇ। ੧੫੬੭।","roman":"E do'oo bhat aavat hute bhoopti hane bajaai | 1567 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":582},{"type":"verse","number":[1568],"number_text":"੧੫੬੮।","page":582,"lines":[{"gurmukhi":"ਭੀਮ ਸਿੰਘ ਭੁਜ ਸਿੰਘ ਸੁ ਕੋਪ ਬਢਾਇਓ। ਮਹਾ ਸਿੰਘ ਸਿੰਘ ਮਾਨ ਮਦਨ ਸਿੰਘ ਧਾਇਓ।","roman":"Bheem singh bhuj singh su kop badhaaio | mahaa singh singh maan madan singh dhaaio |","meaning_en":"","page":582},{"gurmukhi":"ਅਉਰ ਮਹਾ ਭਟ ਧਾਏ ਸਸਤ੍ਰ ਸੰਭਾਰ ਕੈ। ਹੋ ਤੇ ਛਿਨ ਮੈ ਤਿਹ ਭੂਪਤਿ ਦਏ ਸੰਘਾਰ ਕੈ। ੧੫੬੮।","roman":"Aur mahaa bhat dhaae sasatr sanbhaar kai | ho te chhin mai tih bhoopti dae sanghaar kai | 1568 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":582},{"type":"verse","number":[1569],"number_text":"੧੫੬੯।","page":582,"lines":[{"gurmukhi":"ਬਿਕਟਿ ਸਿੰਘ ਜਿਹ ਨਾਮ ਬਿਕਟਿ ਬੀਰ ਜਦੁਬੀਰ ਕੋ।","roman":"Bikti singh jih naam bikti beer jadubeer ko |","meaning_en":"","page":582},{"gurmukhi":"ਅਪੁਨੇ ਪ੍ਰਭ ਕੇ ਕਾਮ ਧਾਇ ਪਰਿਯੋ ਅਰਿ ਬਧ ਨਿਮਿਤ। ੧੫੬੯।","roman":"Apune prabh ke kaam dhaai pariyo ari badh nimit | 1569 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":582},{"type":"verse","number":[1570],"number_text":"੧੫੭੦।","page":582,"lines":[{"gurmukhi":"ਬਿਕਟ ਸਿੰਘ ਆਵਤ ਲਖਿਯੋ ਖੜਗ ਸਿੰਘ ਧਨੁ ਤਾਨਿ।","roman":"Bikat singh aavat lakhiyo kharag singh dhanu taani |","meaning_en":"","page":582},{"gurmukhi":"ਮਾਰਿਓ ਸਰ ਉਰਿ ਸਤ੍ਰ ਕੇ ਲਾਗਤ ਤਜੇ ਪਰਾਨ। ੧੫੭੦।","roman":"Maario sar uri satr ke laagat taje paraan | 1570 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":582},{"type":"verse","number":[1571],"number_text":"੧੫੭੧।","page":582,"lines":[{"gurmukhi":"ਰੁਦ੍ਰ ਸਿੰਘ ਇਕ ਬੀਰ ਠਾਢ ਹੁਤੋ ਜਦੁਬੀਰ ਢਿਗ।","roman":"Rudr singh ik beer thaadh huto jadubeer dhig |","meaning_en":"","page":582},{"gurmukhi":"ਮਹਾ ਰਥੀ ਰਣ ਧੀਰ ਰਿਸ ਕਰਿ ਨ੍ਰਿਪ ਸਉਹੈ ਭਯੋ। ੧੫੭੧।","roman":"Mahaa rathee ran dheer ris kari nrip sauhai bhayo | 1571 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":582},{"type":"verse","number":[1572],"number_text":"੧੫੭੨।","page":582,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਤਬ ਧਨੁਖ ਸੰਭਾਰਿਯੋ। ਰੁਦ੍ਰ ਸਿੰਘ ਜਬ ਨੈਨ ਨਿਹਾਰਿਯੋ।","roman":"Kharag singh tab dhanukh sanbhaariyo | rudr singh jab nain nihaariyo |","meaning_en":"","page":582},{"gurmukhi":"ਛਾਡਿ ਬਾਨ ਭੁਜ ਬਲ ਸੋ ਦਯੋ। ਆਵਤ ਸਤ੍ਰ ਮਾਰ ਤਿਹ ਲਯੋ। ੧੫੭੨।","roman":"Chhaadi baan bhuj bal so dayo | aavat satr maar tih layo | 1572 |","meaning_en":"","page":582}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":582},{"type":"verse","number":[1573],"number_text":"੧੫੭੩।","page":582,"lines":[{"gurmukhi":"ਹਿੰਮਤ ਸਿੰਘ ਮਹਾਰਿਸ ਸਿਉ ਇਹ ਭੂਪਤਿ ਪੈ ਤਰਵਾਰ ਚਲਾਈ।","roman":"Hinmat singh mahaaris siu ih bhoopti pai tarvaar chalaaee |","meaning_en":"","page":582},{"gurmukhi":"ਹਾਥ ਸੰਭਾਲ ਕੈ ਲਈ ਤਬ ਹੀ ਸੋਊ ਆਵਤ ਹੀ ਸੁ ਬਚਾਈ।","roman":"Haath sanbhaal kai laee tab hee so'oo aavat hee su bachaaee |","meaning_en":"","page":582},{"gurmukhi":"ਫੂਲਹੁ ਪੈ ਕਰਵਾਰ ਲਗੀ ਚਿਨਗਾਰਿ ਜਗੀ ਉਪਮਾ ਕਬਿ ਗਾਈ।","roman":"Phoolhu pai karvaar lagee chingaari jagee upmaa kabi gaaee |","meaning_en":"","page":582},{"gurmukhi":"ਬਾਸਵ ਪੈ ਸਿਵ ਕੋਪ ਕੀਓ ਮਾਨੋ ਤੀਸਰੇ ਨੈਨ ਕੀ ਜ੍ਵਾਲ ਦਿਖਾਈ। ੧੫੭੩।","roman":"Baasav pai siv kop keeo maano teesre nain kee jvaal dikhaaee | 1573 |","meaning_en":"","page":582}]},{"type":"verse","number":[1574],"number_text":"੧੫੭੪।","page":582,"lines":[{"gurmukhi":"ਪੁਨਿ ਹਿੰਮਤ ਸਿੰਘ ਮਹਾਬਲੁ ਕੈ ਇਹ ਭੂਪ ਕੇ ਊਪਰਿ ਘਾਉ ਕੀਓ।","roman":"Puni hinmat singh mahaablu kai ih bhoop ke oopri ghaau keeo |","meaning_en":"","page":582},{"gurmukhi":"ਕਰਿ ਵਾਰ ਫਿਰਿਓ ਅਪੁਨੇ ਦਲੁ ਕੋ ਨ੍ਰਿਪ ਤਉ ਲਲਕਾਰਿ ਹਕਾਰ ਲੀਓ।","roman":"Kari vaar phirio apune dalu ko nrip tau lalkaari hakaar leeo |","meaning_en":"","page":582},{"gurmukhi":"ਸਿਰ ਮਾਝ ਕ੍ਰਿਪਾਨ ਕੀ ਤਾਨ ਦਈ ਬਿਬਿ ਖੰਡ ਹੁਇ ਭੂਮਿ ਗਿਰਿਓ ਨ ਜੀਓ।","roman":"Sir maajh kripaan kee taan daee bibi khand hui bhoomi girio na jeeo |","meaning_en":"","page":583},{"gurmukhi":"ਸਿਰਿ ਤੇਗ ਬਹੀ ਚਪਲਾ ਸੀ ਮਨੋ ਅਧ ਬੀਚ ਤੇ ਭੂਧਰ ਚੀਰਿ ਦੀਓ। ੧੫੭੪।","roman":"Siri teg bahee chaplaa see mano adh beech te bhoodhar cheeri deeo | 1574 |","meaning_en":"","page":583}]},{"type":"verse","number":[1575],"number_text":"੧੫੭੫।","page":583,"lines":[{"gurmukhi":"ਹਿੰਮਤ ਸਿੰਘ ਹਨਿਓ ਜਬ ਹੀ ਤਬ ਹੀ ਸਬ ਹੀ ਭਟ ਕੋਪ ਭਰੇ।","roman":"Hinmat singh hanio jab hee tab hee sab hee bhat kop bhare |","meaning_en":"","page":583},{"gurmukhi":"ਮਹਾ ਰੁਦ੍ਰ ਤੇ ਆਦਿਕ ਬੀਰ ਜਿਤੇ ਇਹ ਪੈ ਇਕ ਬਾਰ ਹੀ ਟੂਟਿ ਪਰੇ।","roman":"Mahaa rudr te aadik beer jite ih pai ik baar hee tooti pare |","meaning_en":"","page":583},{"gurmukhi":"ਧਨੁ ਬਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਬਰਛੀਨ ਕੇ ਸ੍ਯਾਮ ਭਨੈ ਬਹੁ ਵਾਰ ਕਰੇ।","roman":"Dhanu baan kripaan gadaa barchheen ke syaam bhanai bahu vaar kare |","meaning_en":"","page":583},{"gurmukhi":"ਨ੍ਰਿਪ ਘਾਇ ਬਚਾਇ ਸਭੈ ਤਿਨ ਕੇ ਇਹ ਪਉਰਖ ਦੇਖ ਕੈ ਸਤ੍ਰ ਡਰੇ। ੧੫੭੫।","roman":"Nrip ghaai bachaai sabhai tin ke ih paurakh dekh kai satr dare | 1575 |","meaning_en":"","page":583}]},{"type":"verse","number":[1576],"number_text":"੧੫੭੬।","page":583,"lines":[{"gurmukhi":"ਰੁਦ੍ਰ ਤੇ ਆਦਿ ਜਿਤੇ ਗਨ ਦੇਵ ਤਿਤੇ ਮਿਲ ਕੈ ਨ੍ਰਿਪ ਊਪਰਿ ਧਾਏ।","roman":"Rudr te aadi jite gan dev tite mil kai nrip oopri dhaae |","meaning_en":"","page":583},{"gurmukhi":"ਤੇ ਸਬ ਆਵਤ ਦੇਖਿ ਬਲੀ ਧਨੁ ਤਾਨਿ ਹਕਾਰ ਕੈ ਬਾਨ ਲਗਾਏ।","roman":"Te sab aavat dekhi balee dhanu taani hakaar kai baan lagaae |","meaning_en":"","page":583},{"gurmukhi":"ਏਕ ਗਿਰੇ ਤਹ ਘਾਇਲ ਹੁਇ ਇਕ ਤ੍ਰਾਸ ਭਰੇ ਤਜਿ ਜੁਧੁ ਪਰਾਏ।","roman":"Ek gire tah ghaail hui ik traas bhare taji judhu paraae |","meaning_en":"","page":583},{"gurmukhi":"ਏਕ ਲਰੈ ਨ ਡਰੈ ਬਲਵਾਨ ਨਿਦਾਨ ਸੋਊ ਨ੍ਰਿਪ ਮਾਰਿ ਗਿਰਾਏ। ੧੫੭੬।","roman":"Ek larai na darai balvaan nidaan so'oo nrip maari giraae | 1576 |","meaning_en":"","page":583}]},{"type":"verse","number":[1577],"number_text":"੧੫੭੭।","page":583,"lines":[{"gurmukhi":"ਸਿਵ ਕੇ ਦਸ ਸੈ ਗਨ ਜੀਤ ਲਏ ਰਿਸ ਸੋ ਪੁਨਿ ਲਛਕ ਜਛ ਸੰਘਾਰੇ।","roman":"Siv ke das sai gan jeet lae ris so puni lachhak jachh sanghaare |","meaning_en":"","page":583},{"gurmukhi":"ਰਾਛਸ ਤੇਈਸ ਲਾਖ ਹਨੇ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਜਮ ਧਾਮ ਸਿਧਾਰੇ।","roman":"Raachhas te'ees laakh hane kabi syaam bhanai jam dhaam sidhaare |","meaning_en":"","page":583},{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਥ ਕੀਓ ਬਿਰਥੀ ਬਹੁ ਦਾਰੁਕ ਕੇ ਤਨਿ ਘਾਉ ਪ੍ਰਹਾਰੇ।","roman":"Sree brijnaath keeo birthee bahu daaruk ke tani ghaau prahaare |","meaning_en":"","page":583},{"gurmukhi":"ਦ੍ਵਾਦਸ ਸੂਰ ਨਿਹਾਰਿ ਨਿਸੇਸ ਧਨੇਸ ਜਲੇਸ ਪਸ੍ਵੇਸ ਪਧਾਰੇ। ੧੫੭੭।","roman":"Dvaadas soor nihaari nises dhanes jales pasves padhaare | 1577 |","meaning_en":"","page":583}]},{"type":"verse","number":[1578],"number_text":"੧੫੭੮।","page":583,"lines":[{"gurmukhi":"ਬਹੁਰੋ ਅਯੁਤ ਗਜ ਮਾਰਤ ਭਯੋ ਪੁਨਿ ਤੀਸ ਹਜਾਰ ਰਥੀ ਰਿਸਿ ਘਾਯੋ।","roman":"Bahuro ayut gaj maarat bhayo puni tees hajaar rathee risi ghaayo |","meaning_en":"","page":583},{"gurmukhi":"ਛਤੀਸ ਲਾਖ ਸੁ ਪਤ੍ਯ ਹਨੇ ਦਸ ਲਾਖ ਸ੍ਵਾਰਨ ਮਾਰਿ ਗਿਰਾਯੋ।","roman":"Chhatees laakh su paty hane das laakh svaaran maari giraayo |","meaning_en":"","page":583},{"gurmukhi":"ਭੂਪਤਿ ਲਛ ਹਨੇ ਬਹੁਰੋ ਦਲ ਜਛ ਪ੍ਰਤਛਹਿ ਮਾਰਿ ਭਜਾਯੋ।","roman":"Bhoopti lachh hane bahuro dal jachh pratachhhi maari bhajaayo |","meaning_en":"","page":583},{"gurmukhi":"ਦ੍ਵਾਦਸ ਸੂਰਨ ਗਿਆਰਹ ਰੁਦ੍ਰਨ ਕੇ ਦਲ ਕਉ ਹਨਿ ਕੈ ਪੁਨਿ ਧਾਯੋ। ੧੫੭੮।","roman":"Dvaadas sooran giaarah rudran ke dal kau hani kai puni dhaayo | 1578 |","meaning_en":"","page":583}]},{"type":"verse","number":[1579],"number_text":"੧੫੭੯।","page":583,"lines":[{"gurmukhi":"ਸਾਠ ਹਜਾਰ ਹਨੇ ਬਹੁਰੋ ਭਟ ਜਛ ਸੁ ਲਛ ਕਈ ਤਿਹ ਘਾਏ।","roman":"Saath hajaar hane bahuro bhat jachh su lachh kaee tih ghaae |","meaning_en":"","page":583},{"gurmukhi":"ਜਾਦਵ ਲਛ ਕੀਏ ਬਿਰਥੀ ਬਹੁ ਜਛਨ ਕੇ ਤਨ ਲਛ ਬਨਾਏ।","roman":"Jaadav lachh kee'e birthee bahu jachhan ke tan lachh banaae |","meaning_en":"","page":583},{"gurmukhi":"ਪੈਦਲ ਲਾਖ ਪਚਾਸ ਹਨੇ ਪੁਰਜੇ ਪੁਰਜੇ ਕਰਿ ਭੂਮਿ ਗਿਰਾਏ।","roman":"Paidal laakh pachaas hane purje purje kari bhoomi giraae |","meaning_en":"","page":583},{"gurmukhi":"ਅਉਰ ਹਨੇ ਬਲਵਾਨ ਕ੍ਰਿਪਾਨ ਲੈ ਜੋ ਇਹ ਭੂਪ ਕੇ ਊਪਰਿ ਆਏ। ੧੫੭੯।","roman":"Aur hane balvaan kripaan lai jo ih bhoop ke oopri aae | 1579 |","meaning_en":"","page":583}]},{"type":"verse","number":[1580],"number_text":"੧੫੮੦।","page":583,"lines":[{"gurmukhi":"ਤਾਉ ਦੇ ਮੂਛਿ ਦੁਹੂੰ ਕਰ ਭੂਪਤਿ ਸੈਨ ਨੈ ਜਾਇ ਨਿਸੰਕ ਪਰਿਯੋ।","roman":"Taau de moochhi duhoon kar bhoopti sain nai jaai nisank pariyo |","meaning_en":"","page":583},{"gurmukhi":"ਪੁਨਿ ਲਾਖ ਸੁਆਰ ਹਨੇ ਬਲਿ ਕੈ ਸਸਿ ਕੋ ਰਵਿ ਕੋ ਅਭਿਮਾਨ ਹਰਿਯੋ।","roman":"Puni laakh suaar hane bali kai sasi ko ravi ko abhimaan hariyo |","meaning_en":"","page":583},{"gurmukhi":"ਜਮ ਕੋ ਸਰ ਏਕ ਤੇ ਡਾਰਿ ਦਯੋ ਛਿਤਿ ਸ੍ਯਾਮ ਭਨੈ ਨਹੀ ਨੈਕੁ ਡਰਿਯੋ।","roman":"Jam ko sar ek te daari dayo chhiti syaam bhanai nahee naiku dariyo |","meaning_en":"","page":583},{"gurmukhi":"ਜੋਊ ਸੂਰ ਕਹਾਵਤ ਹੈ ਰਨ ਮੈ ਸਬਹੂੰ ਨ੍ਰਿਪ ਖੰਡ ਨਿਖੰਡ ਕਰਿਯੋ। ੧੫੮੦।","roman":"Jo'oo soor kahaavat hai ran mai sabhoon nrip khand nikhand kariyo | 1580 |","meaning_en":"","page":583}]},{"type":"verse","number":[1581],"number_text":"੧੫੮੧।","page":584,"lines":[{"gurmukhi":"ਰਨ ਮੈ ਦਸ ਲਛ ਹਨੇ ਪੁਨਿ ਜਛ ਜਲਾਧਿਪ ਕੋ ਭਟ ਲਛਕੁ ਮਾਰਿਓ।","roman":"Ran mai das lachh hane puni jachh jalaadhip ko bhat lachhku maario |","meaning_en":"","page":584},{"gurmukhi":"ਇੰਦ੍ਰ ਕੇ ਸੂਰ ਹਨੇ ਅਗਨੇ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਸੁ ਨਹੀ ਨ੍ਰਿਪ ਹਾਰਿਓ।","roman":"Indr ke soor hane agne kabi syaam bhanai su nahee nrip haario |","meaning_en":"","page":584},{"gurmukhi":"ਸਾਤਕਿ ਕਉ ਮੁਸਲੀਧਰ ਕਉ ਬਸੁਦੇਵਹਿ ਕਉ ਕਰਿ ਮੂਰਛ ਡਾਰਿਓ।","roman":"Saatki kau musleedhar kau basudevhi kau kari moorachh daario |","meaning_en":"","page":584},{"gurmukhi":"ਭਾਜ ਗਯੋ ਜਮ ਅਉਰ ਸਚੀਪਤਿ ਕਾਹੂੰ ਨ ਹਾਥਿ ਹਥੀਯਾਰ ਸੰਭਾਰਿਓ। ੧੫੮੧।","roman":"Bhaaj gayo jam aur sacheepti kaahoon na haathi hatheeyaar sanbhaario | 1581 |","meaning_en":"","page":584}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":584},{"type":"verse","number":[1582],"number_text":"੧੫੮੨।","page":584,"lines":[{"gurmukhi":"ਜਬ ਭੂਪਤਿ ਏਤੋ ਕੀਓ ਜੁਧੁ ਕ੍ਰੁਧ ਕੈ ਸਾਥ।","roman":"Jab bhoopti eto keeo judhu krudh kai saath |","meaning_en":"","page":584},{"gurmukhi":"ਤਬ ਬ੍ਰਿਜਪਤਿ ਆਵਤ ਭਯੋ ਧਨੁਖ ਬਾਨ ਲੈ ਹਾਥਿ। ੧੫੮੨।","roman":"Tab brijapti aavat bhayo dhanukh baan lai haathi | 1582 |","meaning_en":"","page":584}]},{"type":"heading","kind":"raag","name":"ਬਿਸਨਪਦ","gurmukhi":"ਬਿਸਨਪਦ","roman":"Bisanpad","meaning_en":"","page":584},{"type":"verse","number":[1583],"number_text":"੧੫੮੩।","page":584,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਰਿਸ ਭਰਿ ਬਲ ਕਰਿ ਅਰਿ ਪਰ ਜਬ ਧਨੁ ਧਰਿ ਕਰਿ ਧਾਯੋ।","roman":"Sree hari ris bhari bal kari ari par jab dhanu dhari kari dhaayo |","meaning_en":"","page":584},{"gurmukhi":"ਤਬ ਨ੍ਰਿਪ ਮਨ ਮੈ ਕ੍ਰੋਧ ਬਢਾਯੋ ਸ੍ਰੀ ਪਤਿ ਕੋ ਗੁਨ ਗਾਯੋ। ਰਹਾਉ।","roman":"Tab nrip man mai krodh badhaayo sree pati ko gun gaayo | rahaau |","meaning_en":"","page":584},{"gurmukhi":"ਜਾ ਕੋ ਪ੍ਰਗਟ ਪ੍ਰਤਾਪ ਤਿਹੂੰ ਪੁਰ ਸੇਸ ਅੰਤਿ ਨਹੀ ਪਾਯੋ।","roman":"Jaa ko pragat prataap tihoon pur ses anti nahee paayo |","meaning_en":"","page":584},{"gurmukhi":"ਬੇਦ ਭੇਦ ਜਾ ਕੋ ਨਹੀ ਜਾਨਤ ਸੋ ਨੰਦ ਨੰਦ ਕਹਾਯੋ।","roman":"Bed bhed jaa ko nahee jaanat so nand nand kahaayo |","meaning_en":"","page":584},{"gurmukhi":"ਕਾਲ ਰੂਪ ਨਾਥਿਓ ਜਿਹ ਕਾਲੀ ਕੰਸ ਕੇਸ ਗਹਿ ਘਾਯੋ।","roman":"Kaal roop naathio jih kaalee kans kes gahi ghaayo |","meaning_en":"","page":584},{"gurmukhi":"ਸੋ ਮੈ ਰਨ ਮਹਿ ਓਰ ਆਪਨੀ ਕੋਪਿ ਹਕਾਰਿ ਬੁਲਾਯੋ।","roman":"So mai ran mahi or aapnee kopi hakaari bulaayo |","meaning_en":"","page":584},{"gurmukhi":"ਜਾ ਕੋ ਧ੍ਯਾਨ ਰਾਮ ਨਿਤਿ ਮੁਨਿ ਜਨ ਧਰਤਿ ਹ੍ਰਿਦੈ ਨਹੀ ਆਯੋ।","roman":"Jaa ko dhyaan raam niti muni jan dharti hridai nahee aayo |","meaning_en":"","page":584},{"gurmukhi":"ਧਨਿ ਭਾਗ ਮੇਰੇ ਤਿਹ ਹਰਿ ਸੋ ਅਤਿ ਹੀ ਜੁਧ ਮਚਾਯੋ। ੧੫੮੩।","roman":"Dhani bhaag mere tih hari so ati hee judh machaayo | 1583 |","meaning_en":"","page":584}]},{"type":"verse","number":[1584],"number_text":"੧੫੮੪।","page":584,"lines":[{"gurmukhi":"ਜਦੁਪਤਿ ਮੋਹਿ ਸਨਾਥ ਕੀਯੋ।","roman":"Jadupti mohi sanaath keeyo |","meaning_en":"","page":584},{"gurmukhi":"ਦਰਸਨ ਦੇਤ ਨ ਦਰਸਨ ਹੂ ਕੋ ਮੋ ਕਉ ਦਰਸ ਦੀਯੋ। ਰਹਾਉ।","roman":"Darsan det na darsan hoo ko mo kau daras deeyo | rahaau |","meaning_en":"","page":584},{"gurmukhi":"ਜਾਨਤ ਹੋ ਜਗ ਮੈ ਸਮ ਮੋ ਸੋ ਅਉਰ ਨ ਬੀਰ ਬੀਯੋ।","roman":"Jaanat ho jag mai sam mo so aur na beer beeyo |","meaning_en":"","page":584},{"gurmukhi":"ਜਿਹ ਰਨ ਮੈ ਬ੍ਰਿਜਰਾਜ ਆਪੁਨੀ ਓਰ ਹਕਾਰਿ ਲੀਯੋ।","roman":"Jih ran mai brijraaj aapunee or hakaari leeyo |","meaning_en":"","page":584},{"gurmukhi":"ਜਾ ਕੋ ਸੁਕ ਨਾਰਦ ਮੁਨਿ ਸਾਰਦ ਗਾਵਤ ਅੰਤੁ ਨ ਪਾਯੋ।","roman":"Jaa ko suk naarad muni saarad gaavat antu na paayo |","meaning_en":"","page":584},{"gurmukhi":"ਤਾ ਕਉ ਸ੍ਯਾਮ ਆਜ ਰਿਸ ਕਰਿ ਕੈ ਭਿਰਬੇ ਹੇਤ ਬੁਲਾਯੋ। ੧੫੮੪।","roman":"Taa kau syaam aaj ris kari kai bhirbe het bulaayo | 1584 |","meaning_en":"","page":584}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":584},{"type":"verse","number":[1585],"number_text":"੧੫੮੫।","page":584,"lines":[{"gurmukhi":"ਗੁਨ ਗਾਇ ਕੈ ਯੌ ਧਨੁ ਪਾਨਿ ਗਹਿਯੋ ਪੁਨਿ ਧਾਇ ਪਰਿਓ ਬਹੁ ਬਾਨ ਚਲਾਏ।","roman":"Gun gaai kai yau dhanu paani gahiyo puni dhaai pario bahu baan chalaae |","meaning_en":"","page":584},{"gurmukhi":"ਜੇ ਭਟ ਆਨਿ ਪਰੇ ਰਨ ਮੈ ਨਹ ਜਾਨ ਦਏ ਬਹੁ ਮਾਰਿ ਗਿਰਾਏ।","roman":"Je bhat aani pare ran mai nah jaan dae bahu maari giraae |","meaning_en":"","page":584},{"gurmukhi":"ਘਾਇ ਲਗੇ ਜਿਨ ਕੇ ਤਨ ਮੈ ਤਿਨ ਮਾਰਨ ਕਉ ਨਹਿ ਹਾਥ ਉਠਾਏ।","roman":"Ghaai lage jin ke tan mai tin maaran kau nahi haath uthaae |","meaning_en":"","page":584},{"gurmukhi":"ਸੈਨ ਸੰਘਾਰ ਦਈ ਜਦਵੀ ਬ੍ਰਿਜਨਾਇਕ ਊਪਰ ਹੀ ਨ੍ਰਿਪ ਧਾਏ। ੧੫੮੫।","roman":"Sain sanghaar daee jadvee brijnaaik oopar hee nrip dhaae | 1585 |","meaning_en":"","page":584}]},{"type":"verse","number":[1586],"number_text":"੧੫੮੬।","page":584,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਨਾਇਕ ਕੋ ਸੁ ਕਿਰੀਟੁ ਗਿਰਾਇ ਕੈ ਬਾਨ ਕੈ ਸੰਗਿ ਦਯੋ ਹੈ।","roman":"Sree brijnaaik ko su kireetu giraai kai baan kai sangi dayo hai |","meaning_en":"","page":584},{"gurmukhi":"ਪੰਦ੍ਰਹਿ ਸੈ ਗਜਰਾਜ ਸਮਾਜ ਮੈ ਬਾਜ ਅਨੇਕਨ ਮਾਰਿ ਲਯੋ ਹੈ।","roman":"Pandrahi sai gajraaj samaaj mai baaj anekan maari layo hai |","meaning_en":"","page":584},{"gurmukhi":"ਦ੍ਵਾਦਸ ਲਛ ਜਿਤੇ ਪੁਨਿ ਜਛ ਸੁ ਸੈਨ ਘਨੋ ਬਿਨੁ ਪ੍ਰਾਨ ਭਯੋ ਹੈ।","roman":"Dvaadas lachh jite puni jachh su sain ghano binu praan bhayo hai |","meaning_en":"","page":584},{"gurmukhi":"ਐਸੀਓ ਭਾਤਿ ਕੋ ਜੁਧੁ ਬਿਲੋਕ ਕੈ ਸੂਰਨ ਕੋ ਅਭਿਮਾਨ ਗਯੋ ਹੈ। ੧੫੮੬।","roman":"Aiseeo bhaati ko judhu bilok kai sooran ko abhimaan gayo hai | 1586 |","meaning_en":"","page":584}]},{"type":"verse","number":[1587],"number_text":"੧੫੮੭।","page":585,"lines":[{"gurmukhi":"ਦਸ ਦਿਵਸ ਨਿਸਾ ਦਸ ਜੁਧ ਕੀਓ ਬ੍ਰਿਜਨਾਇਕ ਸੋ ਨ ਟਰਿਯੋ ਭਟ ਟਾਰਿਓ।","roman":"Das divas nisaa das judh keeo brijnaaik so na tariyo bhat taario |","meaning_en":"","page":585},{"gurmukhi":"ਚਾਰ ਅਛੂਹਨਿ ਅਉਰ ਤਹਾ ਰਿਸਿ ਠਾਨਿ ਸਤਿਕ੍ਰਿਤ ਕੋ ਦਲ ਮਾਰਿਓ।","roman":"Chaar achhoohni aur tahaa risi thaani satikrit ko dal maario |","meaning_en":"","page":585},{"gurmukhi":"ਮੂਰਛ ਹੁਇ ਭਟ ਭੂਮਿ ਗਿਰੇ ਬਹੁ ਬੀਰਨ ਕੌ ਲਰਤੇ ਬਲੁ ਹਾਰਿਓ।","roman":"Moorachh hui bhat bhoomi gire bahu beeran kau larte balu haario |","meaning_en":"","page":585},{"gurmukhi":"ਕੇਤੇ ਭਜੇ ਡਰੁ ਮਾਨਿ ਤਿਨੋ ਕਹ ਜਾਤ ਬਲੀ ਇਹ ਭਾਤਿ ਹਕਾਰਿਓ। ੧੫੮੭।","roman":"Kete bhaje daru maani tino kah jaat balee ih bhaati hakaario | 1587 |","meaning_en":"","page":585}]},{"type":"verse","number":[1588],"number_text":"੧੫੮੮।","page":585,"lines":[{"gurmukhi":"ਟੇਰ ਸੁਨੇ ਸਬ ਫੇਰਿ ਫਿਰੇ ਤਬ ਭੂਪਤਿ ਤੀਛਨ ਬਾਨ ਪ੍ਰਹਾਰੇ।","roman":"Ter sune sab pheri phire tab bhoopti teechhan baan prahaare |","meaning_en":"","page":585},{"gurmukhi":"ਆਵਤ ਹੀ ਮਗ ਬੀਚ ਗਿਰੇ ਤਿਨ ਫੋਰਿ ਜਿਰੇ ਸਰ ਪਾਰਿ ਪਧਾਰੇ।","roman":"Aavat hee mag beech gire tin phori jire sar paari padhaare |","meaning_en":"","page":585},{"gurmukhi":"ਏਕ ਬਲੀ ਤਬ ਦਉਰ ਪਰੇ ਮੁਖ ਢਾਲਨ ਲੈ ਹਥਿਯਾਰ ਉਘਾਰੇ।","roman":"Ek balee tab daur pare mukh dhaalan lai hathiyaar ughaare |","meaning_en":"","page":585},{"gurmukhi":"ਪਉਰਖ ਏਕ ਨਿਹਾਰ ਕੈ ਭੂਪ ਕੋ ਬੀਰ ਅਯੋਧਨ ਮੈ ਠਟਕਾਰੇ। ੧੫੮੮।","roman":"Paurakh ek nihaar kai bhoop ko beer ayodhan mai thatkaare | 1588 |","meaning_en":"","page":585}]},{"type":"verse","number":[1589],"number_text":"੧੫੮੯।","page":585,"lines":[{"gurmukhi":"ਏਕ ਸਤਿਕ੍ਰਿਤ ਕੋ ਗਜ ਦੀਰਘ ਕ੍ਰੁਧਤ ਹੋਇ ਨ੍ਰਿਪੁ ਊਪਰਿ ਧਾਯੋ।","roman":"Ek satikrit ko gaj deeragh krudhat hoi nripu oopri dhaayo |","meaning_en":"","page":585,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਆਵਤ ਹੀ ਘਨ ਜਿਉ ਗਰਜਿਓ ਅਪੁਨੋ ਰਨ ਨੈ ਅਤਿ ਓਜ ਜਨਾਯੋ।","roman":"Aavat hee ghan jiu garjio apuno ran nai ati oj janaayo |","meaning_en":"","page":585},{"gurmukhi":"ਭੂਪ ਨਿਹਾਰਿ ਲਯੋ ਅਸਿ ਹਾਥਿ ਕਟਿਓ ਕਰਿ ਤਾਹਿ ਤਬੈ ਸੁ ਪਰਾਯੋ।","roman":"Bhoop nihaari layo asi haathi katio kari taahi tabai su paraayo |","meaning_en":"","page":585},{"gurmukhi":"ਇਉ ਉਪਮਾ ਉਪਜੀ ਮਨ ਮੈ ਗਜ ਸੁੰਡ ਮਨੋ ਘਰਿ ਹੀ ਧਰਿ ਆਯੋ। ੧੫੮੯।","roman":"Iu upmaa upjee man mai gaj sund mano ghari hee dhari aayo | 1589 |","meaning_en":"","page":585}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":585},{"type":"verse","number":[1590],"number_text":"੧੫੯੦।","page":585,"lines":[{"gurmukhi":"ਜੁਧ ਇਤੋ ਇਤ ਹੋਤ ਭਯੋ ਉਤ ਹਰਿ ਹੇਤ ਸਹਾਇ।","roman":"Judh ito it hot bhayo ut hari het sahaai |","meaning_en":"","page":585},{"gurmukhi":"ਪਾਚੋ ਪਾਡਵ ਸ੍ਯਾਮ ਭਨਿ ਤਿਹ ਠਾ ਪਹੁਚੇ ਆਇ। ੧੫੯੦।","roman":"Paacho paadav syaam bhani tih thaa pahuche aai | 1590 |","meaning_en":"","page":585}]},{"type":"verse","number":[1591],"number_text":"੧੫੯੧।","page":585,"lines":[{"gurmukhi":"ਬਹੁਤ ਛੋਹਨੀ ਦਲੁ ਲੀਏ ਰਥ ਪੈਦਲ ਗਜ ਬਾਜ।","roman":"Bahut chhohnee dalu lee'e rath paidal gaj baaj |","meaning_en":"","page":585},{"gurmukhi":"ਆਵਤ ਹੈ ਤਹ ਸ੍ਯਾਮ ਕਹਿ ਜਦੁ ਪਤਿ ਹਿਤ ਕੇ ਕਾਜ। ੧੫੯੧।","roman":"Aavat hai tah syaam kahi jadu pati hit ke kaaj | 1591 |","meaning_en":"","page":585}]},{"type":"verse","number":[1592],"number_text":"੧੫੯੨।","page":585,"lines":[{"gurmukhi":"ਛੋਹਣ ਦੋਇ ਮਲੇਛ ਹੈ ਤਿਹ ਸੈਨਾ ਕੇ ਸੰਗਿ।","roman":"Chhohan doi malechh hai tih sainaa ke sangi |","meaning_en":"","page":585},{"gurmukhi":"ਕਵਚੀ ਖੜਗੀ ਸਕਤਿ ਧਰਿ ਕਟਿ ਮਧਿ ਕਸੇ ਨਿਖੰਗਿ। ੧੫੯੨।","roman":"Kavchee khargee sakti dhari kati madhi kase nikhangi | 1592 |","meaning_en":"","page":585}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":585},{"type":"verse","number":[1593],"number_text":"੧੫੯੩।","page":585,"lines":[{"gurmukhi":"ਮੀਰ ਅਉ ਸਯਦ ਸੇਖ ਪਠਾਨ ਸਬੈ ਤਿਹ ਭੂਪ ਕੇ ਊਪਰਿ ਧਾਏ।","roman":"Meer au sayad sekh pathaan sabai tih bhoop ke oopri dhaae |","meaning_en":"","page":585},{"gurmukhi":"ਕਉਚ ਨਿਖੰਗ ਕਸੇ ਕਟਿ ਮੈ ਸਬ ਆਯੁਧ ਲੈ ਕਰਿ ਕੋਪ ਬਢਾਏ।","roman":"Kauch nikhang kase kati mai sab aayudh lai kari kop badhaae |","meaning_en":"","page":585},{"gurmukhi":"ਨੈਨ ਨਚਾਇ ਦੋਊ ਰਦਨ ਛਦ ਪੀਸ ਕੈ ਭਉਹ ਸੋ ਭਉਹ ਚਢਾਏ।","roman":"Nain nachaai do'oo radan chhad pees kai bhauh so bhauh chadhaae |","meaning_en":"","page":585},{"gurmukhi":"ਆਇ ਹਕਾਰ ਪਰੇ ਚਹੂੰ ਓਰ ਤੇ ਵਾ ਨ੍ਰਿਪ ਕਉ ਬਹੁ ਘਾਇ ਲਗਾਏ। ੧੫੯੩।","roman":"Aai hakaar pare chahoon or te vaa nrip kau bahu ghaai lagaae | 1593 |","meaning_en":"","page":585}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":586},{"type":"verse","number":[1594],"number_text":"੧੫੯੪।","page":586,"lines":[{"gurmukhi":"ਸਕਲ ਘਾਇ ਸਹਿ ਕੈ ਨ੍ਰਿਪਤਿ ਅਤਿ ਚਿਤ ਕੋਪ ਬਢਾਇ।","roman":"Sakal ghaai sahi kai nripti ati chit kop badhaai |","meaning_en":"","page":586},{"gurmukhi":"ਧਨੁਖ ਬਾਨ ਗਹਿ ਜਮ ਸਦਨਿ ਬਹੁ ਅਰਿ ਦਏ ਪਠਾਇ। ੧੫੯੪।","roman":"Dhanukh baan gahi jam sadni bahu ari dae pathaai | 1594 |","meaning_en":"","page":586}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":586},{"type":"verse","number":[1595],"number_text":"੧੫੯੫।","page":586,"lines":[{"gurmukhi":"ਸੇਰ ਖਾਨ ਮਾਰਿਓ ਸੀਸ ਸੈਦ ਖਾਂ ਕੋ ਕਾਟਿ ਡਾਰਿਯੋ","roman":"Ser khaan maario sees said khaan ko kaati daariyo","meaning_en":"","page":586},{"gurmukhi":"ਐਸੋ ਰਨ ਪਾਰਿਓ ਪਰਿਓ ਸੈਦਨ ਮੈ ਧਾਇ ਕੈ।","roman":"Aiso ran paario pario saidan mai dhaai kai |","meaning_en":"","page":586},{"gurmukhi":"ਸੈਦ ਮੀਰੁ ਮਾਰਿਓ ਸੈਦ ਨਾਹਰਿ ਸੰਘਾਰ ਡਾਰਿਓ","roman":"Said meeru maario said naahri sanghaar daario","meaning_en":"","page":586},{"gurmukhi":"ਸੇਖਨ ਕੀ ਫਉਜਨ ਕਉ ਦੀਨੋ ਬਿਚਲਾਇ ਕੈ।","roman":"Sekhan kee phaujan kau deeno bichlaai kai |","meaning_en":"","page":586},{"gurmukhi":"ਸਾਦਿਕ ਫਰੀਦ ਸੇਖ ਭਲੇ ਬਿਧਿ ਜੁਝ ਕੀਨੋ","roman":"Saadik phareed sekh bhale bidhi jujh keeno","meaning_en":"","page":586},{"gurmukhi":"ਭੂਪ ਤਨ ਘਾਇ ਗਿਰਿਓ ਆਪ ਘਾਇ ਖਾਇ ਕੈ।","roman":"Bhoop tan ghaai girio aap ghaai khaai kai |","meaning_en":"","page":586},{"gurmukhi":"ਐਸੀ ਭਾਤਿ ਹੇਰ ਕੈ ਨਿਬੇਰ ਦੀਨੇ ਸੂਰ ਸਬੈ","roman":"Aisee bhaati her kai niber deene soor sabai","meaning_en":"","page":586},{"gurmukhi":"ਆਪ ਬ੍ਰਿਜਰਾਜ ਤਾ ਕੇ ਉਠੇ ਗੁਨ ਗਾਇ ਕੈ। ੧੫੯੫।","roman":"Aap brijraaj taa ke uthe gun gaai kai | 1595 |","meaning_en":"","page":586}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":586},{"type":"verse","number":[1596],"number_text":"੧੫੯੬।","page":586,"lines":[{"gurmukhi":"ਦੇਖਿ ਜੁਧਿਸਟਰਿ ਓਰਿ ਪ੍ਰਭੁ ਅਪਨੋ ਭਗਤਿ ਬਿਚਾਰਿ।","roman":"Dekhi judhisatri ori prabhu apno bhagti bichaari |","meaning_en":"","page":586},{"gurmukhi":"ਤਿਹ ਨ੍ਰਿਪ ਕੋ ਪਉਰਖ ਸੁ ਜਸੁ ਮੁਖ ਸੋ ਕਹਿਯੋ ਸੁਧਾਰਿ। ੧੫੯੬।","roman":"Tih nrip ko paurakh su jasu mukh so kahiyo sudhaari | 1596 |","meaning_en":"","page":586}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":586},{"type":"verse","number":[1597],"number_text":"੧੫੯੭।","page":586,"lines":[{"gurmukhi":"ਭਾਰੇ ਭਾਰੇ ਸੂਰਮਾ ਸੰਘਾਰਿ ਡਾਰੇ ਮਹਾਰਾਜਿ","roman":"Bhaare bhaare soormaa sanghaari daare mahaaraaji","meaning_en":"","page":586},{"gurmukhi":"ਜਮ ਕੀ ਜਮਨ ਕੀ ਘਨੀ ਹੀ ਸੈਨਾ ਛਈ ਹੈ।","roman":"Jam kee jaman kee ghanee hee sainaa chhaee hai |","meaning_en":"","page":586},{"gurmukhi":"ਸਸਿ ਕੀ ਸੁਰੇਸ ਕੀ ਦਿਨੇਸ ਕੀ ਧਨੇਸ ਕੀ","roman":"Sasi kee sures kee dines kee dhanes kee","meaning_en":"","page":586},{"gurmukhi":"ਲੁਕੇਸ ਹੂੰ ਕੀ ਚਮੂੰ ਮ੍ਰਿਤਲੋਕ ਕਉ ਪਠਈ ਹੈ।","roman":"Lukes hoon kee chamoon mritlok kau pathaee hai |","meaning_en":"","page":586},{"gurmukhi":"ਭਾਜ ਗੇ ਜਲੇਸ ਸੇ ਗਨੇਸ ਸੇ ਗਨਤ ਕਉਨ","roman":"Bhaaj ge jales se ganes se ganat kaun","meaning_en":"","page":586},{"gurmukhi":"ਅਉਰ ਹਉ ਕਹਾ ਕਹੋ ਪਸ੍ਵੇਸ ਪੀਠ ਦਈ ਹੈ।","roman":"Aur hau kahaa kaho pasves peeth daee hai |","meaning_en":"","page":586},{"gurmukhi":"ਜਾਦਵ ਸਬਨ ਤੇ ਨ ਡਾਰਿਓ ਰੀਝ ਲਰਿਓ ਹਾ ਹਾ","roman":"Jaadav saban te na daario reejh lario haa haa","meaning_en":"","page":586},{"gurmukhi":"ਦੇਖੋ ਨ੍ਰਿਪ ਹਮ ਤੇ ਬਜਾਇ ਬਾਜੀ ਲਈ ਹੈ। ੧੫੯੭।","roman":"Dekho nrip ham te bajaai baajee laee hai | 1597 |","meaning_en":"","page":586}]},{"type":"heading","kind":"speaker","name":"ਰਾਜਾ ਜੁਧਿਸਟਰ ਬਾਚ","gurmukhi":"ਰਾਜਾ ਜੁਧਿਸਟਰ ਬਾਚ","roman":"Raajaa judhistar baach","meaning_en":"","page":586},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":586},{"type":"verse","number":[1598],"number_text":"੧੫੯੮।","page":586,"lines":[{"gurmukhi":"ਕਹਿਓ ਜੁਧਿਸਟਰ ਨਿਮ੍ਰ ਹੁਇ ਸੁਨੀਯੈ ਸ੍ਰੀ ਬ੍ਰਿਜਰਾਜ।","roman":"Kahio judhistar nimr hui suneeyai sree brijraaj |","meaning_en":"","page":586},{"gurmukhi":"ਯਹ ਸਮਾਜੁ ਤੁਮ ਹੀ ਕੀਯੋ ਕਉਤੁਕ ਦੇਖਨ ਕਾਜ। ੧੫੯੮।","roman":"Yah samaaju tum hee keeyo kautuk dekhan kaaj | 1598 |","meaning_en":"","page":586}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":586},{"type":"verse","number":[1599],"number_text":"੧੫੯੯।","page":586,"lines":[{"gurmukhi":"ਯੌ ਨ੍ਰਿਪ ਹਰਿ ਸੇ ਬਚਨ ਸੁਨਾਏ। ਬਹੁਰੇ ਉਨਿ ਭਟ ਮਾਰਿ ਗਿਰਾਏ।","roman":"Yau nrip hari se bachan sunaae | bahure uni bhat maari giraae |","meaning_en":"","page":586},{"gurmukhi":"ਪੁਨਿ ਮਲੇਛ ਕੀ ਸੈਨਾ ਧਾਈ। ਨਾਮ ਤਿਨਹੁ ਕਬਿ ਦੇਤ ਬਤਾਈ। ੧੫੯੯।","roman":"Puni malechh kee sainaa dhaaee | naam tinhu kabi det bataaee | 1599 |","meaning_en":"","page":586}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":587},{"type":"verse","number":[1600],"number_text":"੧੬੦੦।","page":587,"lines":[{"gurmukhi":"ਨਾਹਿਰ ਖਾਨ ਝੜਾਝੜ ਖਾਂ ਬਲਬੀਰ ਬਹਾਦਰ ਖਾਨ ਤਬੈ।","roman":"Naahir khaan jharaajhar khaan balbeer bahaadar khaan tabai |","meaning_en":"","page":587},{"gurmukhi":"ਪੁਨਿ ਖਾਨ ਨਿਹੰਗ ਭੜੰਗ ਝੜੰਗ ਲਰੇ ਰਨਿ ਆਗੇ ਡਰੇ ਨ ਕਬੈ।","roman":"Puni khaan nihang bharang jharang lare rani aage dare na kabai |","meaning_en":"","page":587},{"gurmukhi":"ਜਿਹ ਰੂਪ ਨਿਹਾਰਿ ਡਰੈ ਦਿਗਪਾਲ ਮਹਾ ਭਟ ਤੇ ਕਬਹੂੰ ਨ ਦਬੈ।","roman":"Jih roop nihaari darai digpaal mahaa bhat te kabhoon na dabai |","meaning_en":"","page":587},{"gurmukhi":"ਕਰਿ ਬਾਨ ਕਮਾਨ ਧਰੇ ਅਭਿਮਾਨ ਸੋ ਆਇ ਪਰੇ ਤਬ ਖਾਨ ਸਬੈ। ੧੬੦੦।","roman":"Kari baan kamaan dhare abhimaan so aai pare tab khaan sabai | 1600 |","meaning_en":"","page":587}]},{"type":"verse","number":[1601],"number_text":"੧੬੦੧।","page":587,"lines":[{"gurmukhi":"ਜਾਹਿਦ ਖਾਨਹੁ ਜਬਰ ਖਾਨ ਸੁ ਵਾਹਿਦ ਖਾਨ ਗਏ ਸੰਗ ਸੂਰੇ।","roman":"Jaahid khaanhu jabar khaan su vaahid khaan gae sang soore |","meaning_en":"","page":587},{"gurmukhi":"ਚਉਪ ਚਹੂੰ ਦਿਸ ਤੇ ਉਮਗੇ ਚਿਤ ਮੈ ਚਪਿ ਰੋਸ ਕੇ ਮਾਰਿ ਮਰੂਰੇ।","roman":"Chaup chahoon dis te umge chit mai chapi ros ke maari maroore |","meaning_en":"","page":587},{"gurmukhi":"ਗੋਰੇ ਮਲੇਛ ਚਲੇ ਨ੍ਰਿਪ ਪੈ ਇਕ ਸਿਆਹ ਮਲੇਛ ਚਲੇ ਇਕ ਭੂਰੇ।","roman":"Gore malechh chale nrip pai ik siaah malechh chale ik bhoore |","meaning_en":"","page":587},{"gurmukhi":"ਭੂਪ ਸਰਾਸਨੁ ਲੈ ਤਬਹੀ ਸੁ ਅਚੂਰ ਬਡੇ ਛਿਨ ਭੀਤਰ ਚੂਰੇ। ੧੬੦੧।","roman":"Bhoop saraasnu lai tabhee su achoor bade chhin bheetar choore | 1601 |","meaning_en":"","page":587}]},{"type":"verse","number":[1602],"number_text":"੧੬੦੨।","page":587,"lines":[{"gurmukhi":"ਕੋਪਿ ਮਲੇਛਨ ਕੀ ਪ੍ਰਿਤਨਾ ਸੁ ਦੁਧਾ ਕਰਿ ਕੈ ਸਤਿ ਧਾ ਕਰ ਡਾਰੀ।","roman":"Kopi malechhan kee pritnaa su dudhaa kari kai sati dhaa kar daaree |","meaning_en":"","page":587},{"gurmukhi":"ਬੀਰ ਪਰੇ ਕਹੂੰ ਬਾਜ ਮਰੇ ਕਹੂੰ ਝੂਮਿ ਗਿਰੇ ਗਜ ਭੂ ਪਰਿ ਭਾਰੀ।","roman":"Beer pare kahoon baaj mare kahoon jhoomi gire gaj bhoo pari bhaaree |","meaning_en":"","page":587},{"gurmukhi":"ਘੂਮਤਿ ਹੈ ਕਹੂੰ ਘਾਇ ਲਗੇ ਭਟ ਬੋਲ ਸਕੈ ਨ ਗਏ ਬਲ ਹਾਰੀ।","roman":"Ghoomti hai kahoon ghaai lage bhat bol sakai na gae bal haaree |","meaning_en":"","page":587},{"gurmukhi":"ਆਸਨ ਲਾਇ ਮਨੋ ਮੁਨਿ ਰਾਇ ਲਗਾਵਤ ਧਿਆਨ ਬਡੇ ਬ੍ਰਤਧਾਰੀ। ੧੬੦੨।","roman":"Aasan laai mano muni raai lagaavat dhiaan bade bratdhaaree | 1602 |","meaning_en":"","page":587}]},{"type":"verse","number":[1603],"number_text":"੧੬੦੩।","page":587,"lines":[{"gurmukhi":"ਜੁਧੁ ਇਤੋ ਜਬ ਭੂਪ ਕੀਓ ਤਬ ਨਾਹਿਰ ਖਾਂ ਰਿਸਿ ਕੈ ਅਟਿਕਿਓ।","roman":"Judhu ito jab bhoop keeo tab naahir khaan risi kai atikio |","meaning_en":"","page":587},{"gurmukhi":"ਹਥਿਆਰ ਸੰਭਾਰਿ ਹਕਾਰਿ ਪਰਿਓ ਜੁ ਸਮਾਜ ਮੈ ਬਾਜਿ ਹੁਤੋ ਮਟਿਕਿਓ।","roman":"Hathiaar sanbhaari hakaari pario ju samaaj mai baaji huto matikio |","meaning_en":"","page":587},{"gurmukhi":"ਖੜਗੇਸ ਤਿਨੈ ਗਹਿ ਕੇਸਨ ਤੇ ਝਟਕਿਓ ਅਰੁ ਭੂਮਿ ਬਿਖੈ ਪਟਿਕਿਓ।","roman":"Kharges tinai gahi kesan te jhatkio aru bhoomi bikhai patikio |","meaning_en":"","page":587},{"gurmukhi":"ਤਬ ਨਾਹਿਰ ਖਾਂ ਇਹ ਦੇਖਿ ਦਸਾ ਕਹਿ ਸ੍ਯਾਮ ਕਹੈ ਭਜਿ ਗਯੋ ਨ ਟਿਕਿਓ।੧੬੦੩।","roman":"Tab naahir khaan ih dekhi dasaa kahi syaam kahai bhaji gayo na tikio | 1603 |","meaning_en":"","page":587}]},{"type":"verse","number":[1604],"number_text":"੧੬੦੪।","page":587,"lines":[{"gurmukhi":"ਨਾਹਿਰ ਖਾਂ ਭਜਿ ਗਯੋ ਜਬ ਹੀ ਤਬ ਹੀ ਰਿਸਿ ਖਾਨ ਝੜਾਝੜ ਆਏ।","roman":"Naahir khaan bhaji gayo jab hee tab hee risi khaan jharaajhar aae |","meaning_en":"","page":587},{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਸਭੈ ਅਪੁਨੇ ਜਮ ਰੂਪ ਕੀਏ ਨ੍ਰਿਪ ਊਪਰਿ ਧਾਏ।","roman":"Sasatr sanbhaari sabhai apune jam roop kee'e nrip oopri dhaae |","meaning_en":"","page":587},{"gurmukhi":"ਕੋਪਿ ਬਾਨ ਹਨੇ ਇਨ ਕਉ ਇਨ ਹੂੰ ਨ੍ਰਿਪ ਕਉ ਬਹੁ ਬਾਨ ਲਗਾਏ।","roman":"Kopi baan hane in kau in hoon nrip kau bahu baan lagaae |","meaning_en":"","page":587},{"gurmukhi":"ਕਿੰਨਰ ਜਛ ਰਰੈ ਉਪਮਾ ਰਨ ਚਾਰਨ ਜੀਤ ਕੇ ਗੀਤ ਬਨਾਏ। ੧੬੦੪।","roman":"Kinnar jachh rarai upmaa ran chaaran jeet ke geet banaae | 1604 |","meaning_en":"","page":587}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":587},{"type":"verse","number":[1605],"number_text":"੧੬੦੫।","page":587,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਲਖਿ ਬਿਕਟਿ ਭਟ ਤਿਉਰ ਚੜਾਏ ਮਾਥਿ।","roman":"Kharag singh lakhi bikti bhat tiur charaae maathi |","meaning_en":"","page":587},{"gurmukhi":"ਸੀਸ ਕਾਟਿ ਅਰਿ ਕੋ ਦਯੋ ਏਕ ਬਾਨ ਕੇ ਸਾਥਿ। ੧੬੦੫।","roman":"Sees kaati ari ko dayo ek baan ke saathi | 1605 |","meaning_en":"","page":587}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":587},{"type":"verse","number":[1606],"number_text":"੧੬੦੬।","page":587,"lines":[{"gurmukhi":"ਪੁਨਿ ਖਾਨ ਨਿਹੰਗ ਝੜੰਗ ਭੜੰਗ ਚਲੇ ਮੁਖ ਢਾਲਨਿ ਕਉ ਧਰਿ ਕੈ।","roman":"Puni khaan nihang jharang bharang chale mukh dhaalni kau dhari kai |","meaning_en":"","page":587},{"gurmukhi":"ਕਰਿ ਮੈ ਕਰਵਾਰ ਸੰਭਾਰਿ ਹਕਾਰਿ ਮੁਰਾਰ ਪੈ ਧਾਇ ਪਰੇ ਅਰਿ ਕੈ।","roman":"Kari mai karvaar sanbhaari hakaari muraar pai dhaai pare ari kai |","meaning_en":"","page":587},{"gurmukhi":"ਦਲੁ ਮਾਰਿ ਬਿਦਾਰਿ ਦਯੋ ਪਲ ਮੈ ਧਰਿ ਮੁੰਡ ਸੁ ਮੀਨਨ ਜਿਉ ਫਰਕੈ।","roman":"Dalu maari bidaari dayo pal mai dhari mund su meenan jiu pharkai |","meaning_en":"","page":588},{"gurmukhi":"ਨ ਟਰੇ ਰਨ ਭੂਮਿ ਹੂੰ ਤੇ ਤਬ ਲਉ ਜਬ ਲਉ ਛਿਤ ਪੈ ਨ ਪਰੇ ਮਰਿ ਕੈ। ੧੬੦੬।","roman":"Na tare ran bhoomi hoon te tab lau jab lau chhit pai na pare mari kai | 1606 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":588},{"type":"verse","number":[1607],"number_text":"੧੬੦੭।","page":588,"lines":[{"gurmukhi":"ਸ੍ਰੋਨਤ ਕੀ ਸਰਤਾ ਤਹਾ ਚਲੀ ਮਹਾ ਅਰਿਰਾਇ।","roman":"Sronat kee sartaa tahaa chalee mahaa ariraai |","meaning_en":"","page":588},{"gurmukhi":"ਮੇਦ ਮਾਸ ਮਜਿਯਾ ਬਹੁਤ ਬੈਤਰੁਨੀ ਕੇ ਭਾਇ। ੧੬੦੭।","roman":"Med maas majiyaa bahut baitrunee ke bhaai | 1607 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":588},{"type":"verse","number":[1608],"number_text":"੧੬੦੮।","page":588,"lines":[{"gurmukhi":"ਮਚਿਯੋ ਰਨ ਦਾਰੁਨ ਦਿਲਾਵਰ ਦਲੇਲ ਖਾਂ","roman":"Machiyo ran daarun dilaavar dalel khaan","meaning_en":"","page":588},{"gurmukhi":"ਸਿਚਾਨਨ ਕੀ ਭਾਤਿ ਰਨ ਭੂਮਿ ਝਟਪਟੀ ਸੀ।","roman":"Sichaanan kee bhaati ran bhoomi jhataptee see |","meaning_en":"","page":588},{"gurmukhi":"ਹਟੀ ਨ ਨਿਪਟ ਖਟਪਟੀ ਸੁਭਟਨ ਹੂੰ ਕੀ","roman":"Hatee na nipat khataptee subhtan hoon kee","meaning_en":"","page":588},{"gurmukhi":"ਆਨਨ ਕੀ ਆਭਾ ਤਾ ਕੀ ਲਾਗੈ ਨੈਕੁ ਲਟੀ ਸੀ।","roman":"Aanan kee aabhaa taa kee laagai naiku latee see |","meaning_en":"","page":588},{"gurmukhi":"ਭੂਪਤਿ ਸੰਭਾਰ ਕੈ ਕ੍ਰਿਪਾਨ ਪਾਨਿ ਤਾਨਿ","roman":"Bhoopti sanbhaar kai kripaan paani taani","meaning_en":"","page":588},{"gurmukhi":"ਅਭਿਮਾਨ ਕੈ ਸੰਘਾਰੀ ਸੈਨ ਬਚੀ ਫੂਟੀ ਫਟੀ ਸੀ।","roman":"Abhimaan kai sanghaaree sain bachee phootee phatee see |","meaning_en":"","page":588},{"gurmukhi":"ਕਹੂੰ ਬਾਜ ਮਾਰੇ ਕਹੂੰ ਗਿਰੇ ਗਜ ਭਾਰੇ ਭਾਰੇ","roman":"Kahoon baaj maare kahoon gire gaj bhaare bhaare","meaning_en":"","page":588},{"gurmukhi":"ਭੂਪ ਮਾਨੋ ਕਰੀ ਭਟ ਕਟੀ ਬਨ ਕਟੀ ਸੀ। ੧੬੦੮।","roman":"Bhoop maano karee bhat katee ban katee see | 1608 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":588},{"type":"verse","number":[1609],"number_text":"੧੬੦੯।","page":588,"lines":[{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਤਬ ਖੜਗ ਗਹਿ ਅਤਿ ਚਿਤਿ ਕੋਪ ਬਢਾਇ।","roman":"Kharag singh tab kharag gahi ati chiti kop badhaai |","meaning_en":"","page":588},{"gurmukhi":"ਸੈਨ ਮਲੇਛਨ ਕੀ ਹਨੀ ਜਮਪੁਰਿ ਦਈ ਪਠਾਇ। ੧੬੦੯।","roman":"Sain malechhan kee hanee jampuri daee pathaai | 1609 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":588},{"type":"verse","number":[1610],"number_text":"੧੬੧੦।","page":588,"lines":[{"gurmukhi":"ਦੋਇ ਛੂਹਨੀ ਸੈਨ ਜਬ ਮਲੇਛ ਕੀ ਨ੍ਰਿਪ ਹਨੀ।","roman":"Doi chhoohnee sain jab malechh kee nrip hanee |","meaning_en":"","page":588},{"gurmukhi":"ਅਉਰ ਸੁਭਟ ਜੇ ਐਨਿ ਚਲੇ ਨਾਮ ਕਬਿ ਦੇਤ ਕਹਿ। ੧੬੧੦।","roman":"Aur subhat je aini chale naam kabi det kahi | 1610 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":588},{"type":"verse","number":[1611],"number_text":"੧੬੧੧।","page":588,"lines":[{"gurmukhi":"ਭੀਮ ਗਦਾ ਕਰਿ ਭੀਮ ਲੀਏ ਇਖੁਧੀ ਕਟਿ ਸੋ ਕਸਿ ਪਾਰਥ ਧਾਯੋ।","roman":"Bheem gadaa kari bheem lee'e ikhudhee kati so kasi paarath dhaayo |","meaning_en":"","page":588},{"gurmukhi":"ਰਾਇ ਜੁਧਿਸਟਰ ਲੈ ਧਨੁ ਹਾਥਿ ਚਲਿਯੋ ਚਿਤ ਮੈ ਅਤਿ ਕ੍ਰੋਧ ਬਢਾਯੋ।","roman":"Raai judhistar lai dhanu haathi chaliyo chit mai ati krodh badhaayo |","meaning_en":"","page":588},{"gurmukhi":"ਭ੍ਰਾਤ ਬਲੀ ਦੋਊ ਸਾਥ ਲੀਏ ਦਲੁ ਜੇਤਕ ਸੰਗ ਹੁਤੋ ਸੁ ਬੁਲਾਯੋ।","roman":"Bhraat balee do'oo saath lee'e dalu jetak sang huto su bulaayo |","meaning_en":"","page":588},{"gurmukhi":"ਐਸੇ ਭਿਰੇ ਬ੍ਰਿਤਰਾਸੁਰ ਸਿਉ ਮਘਵਾ ਰਿਸਿ ਕੈ ਜਿਮ ਜੁਧੁ ਮਚਾਯੋ। ੧੬੧੧।","roman":"Aise bhire britraasur siu maghvaa risi kai jim judhu machaayo | 1611 |","meaning_en":"","page":588}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"","page":588},{"type":"verse","number":[1612],"number_text":"੧੬੧੨।","page":588,"lines":[{"gurmukhi":"ਮਨ ਮਹਿ ਕੋਪ ਬਢਾਇ ਸੁਭਟਨ ਸਭੈ ਸੁਨਾਇ ਕੈ।","roman":"Man mahi kop badhaai subhtan sabhai sunaai kai |","meaning_en":"","page":588},{"gurmukhi":"ਖੜਗ ਸਿੰਘ ਸਮੁਹਾਇ ਬਚਨ ਕਹਤ ਭਯੋ ਕ੍ਰਿਸਨ ਸਿਉ। ੧੬੧੨।","roman":"Kharag singh samuhaai bachan kahat bhayo krisan siu | 1612 |","meaning_en":"","page":588}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ ਸਭਨ ਭਟਨ ਸੋ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ ਸਭਨ ਭਟਨ ਸੋ","roman":"Kharges baach sabhan bhatan so","meaning_en":"","page":589},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":589},{"type":"verse","number":[1613],"number_text":"੧੬੧੩।","page":589,"lines":[{"gurmukhi":"ਪਸਚਿਮ ਸੂਰ ਚੜੈ ਕਬ ਹੂ ਅਰੁ ਗੰਗ ਬਹੀ ਉਲਟੀ ਜੀਅ ਆਵੈ।","roman":"Paschim soor charai kab hoo aru gang bahee ultee jeea aavai |","meaning_en":"","page":589},{"gurmukhi":"ਜੇਠ ਕੇ ਮਾਸ ਤੁਖਾਰ ਪਰੇ ਬਨ ਅਉਰ ਬਸੰਤ ਸਮੀਰ ਜਰਾਵੈ।","roman":"Jeth ke maas tukhaar pare ban aur basant sameer jaraavai |","meaning_en":"","page":589},{"gurmukhi":"ਲੋਕ ਹਲੈ ਧਰੂਅ ਕੋ ਜਲ ਕੋ ਥਲੁ ਹੁਇ ਥਲ ਕੋ ਕਬ ਹੂੰ ਜਲ ਜਾਵੈ।","roman":"Lok halai dharooa ko jal ko thalu hui thal ko kab hoon jal jaavai |","meaning_en":"","page":589},{"gurmukhi":"ਕੰਚਨ ਕੋ ਨਗੁ ਪੰਖਨ ਧਾਰਿ ਉਡੈ ਖੜਗੇਸ ਨ ਪੀਠ ਦਿਖਾਵੈ। ੧੬੧੩।","roman":"Kanchan ko nagu pankhan dhaari udai kharges na peeth dikhaavai | 1613 |","meaning_en":"","page":589}]},{"type":"verse","number":[1614],"number_text":"੧੬੧੪।","page":589,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਕੈ ਧਨੁ ਕੋ ਗਹਿ ਕੈ ਲਹਿ ਕੈ ਚਹਿ ਕੈ ਬਹੁ ਬੀਰ ਕਟੇ।","roman":"Yau kahi kai dhanu ko gahi kai lahi kai chahi kai bahu beer kate |","meaning_en":"","page":589},{"gurmukhi":"ਇਕ ਧਾਇ ਪਰੈ ਪੁਨਿ ਸਾਮੁਹਿ ਹ੍ਵੈ ਇਕ ਭਾਜਿ ਗਏ ਇਕ ਸੂਰ ਲਟੇ।","roman":"Ik dhaai parai puni saamuhi hvai ik bhaaji gae ik soor late |","meaning_en":"","page":589},{"gurmukhi":"ਬਲਬੰਡ ਘਨੇ ਛਿਤ ਪੈ ਪਟਕੇ ਭਟ ਐਸੀ ਦਸਾ ਬਹੁ ਹੇਰਿ ਹਟੇ।","roman":"Balband ghane chhit pai patke bhat aisee dasaa bahu heri hate |","meaning_en":"","page":589},{"gurmukhi":"ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਤਿਹ ਆਹਵ ਮੈ ਸੁ ਰਹੇ ਕੇਊ ਬੀਰ ਫਟੇ ਈ ਫਟੇ। ੧੬੧੪।","roman":"Kabi syaam bhanai tih aahav mai su rahe keoo beer phate ee phate | 1614 |","meaning_en":"","page":589}]},{"type":"verse","number":[1615],"number_text":"੧੬੧੫।","page":589,"lines":[{"gurmukhi":"ਧਨੁ ਪਾਰਥ ਕੋ ਤਿਹ ਕਾਟਿ ਦਯੋ ਪੁਨਿ ਕਾਟਿ ਕੈ ਭੀਮ ਗਦਾ ਊ ਗਿਰਾਈ।","roman":"Dhanu paarath ko tih kaati dayo puni kaati kai bheem gadaa oo giraaee |","meaning_en":"","page":589},{"gurmukhi":"ਭੂਪਤਿ ਕੀ ਕਰਵਾਰ ਕਟੀ ਕਹੂੰ ਜਾਇ ਪਰੀ ਕਛੁ ਜਾਨਿ ਨ ਜਾਈ।","roman":"Bhoopti kee karvaar katee kahoon jaai paree kachhu jaani na jaaee |","meaning_en":"","page":589},{"gurmukhi":"ਭ੍ਰਾਤ ਦੋਊ ਅਰੁ ਸੈਨ ਘਨੀ ਅਤਿ ਰੋਸ ਭਰੀ ਨ੍ਰਿਪ ਊਪਰ ਧਾਈ।","roman":"Bhraat do'oo aru sain ghanee ati ros bharee nrip oopar dhaaee |","meaning_en":"","page":589},{"gurmukhi":"ਭੂਪਤਿ ਬਾਨ ਹਨੈ ਤਿਹ ਕਉ ਤਨ ਫੋਰਿ ਦਈ ਉਹ ਓਰਿ ਦਿਖਾਈ। ੧੬੧੫।","roman":"Bhoopti baan hanai tih kau tan phori daee uh ori dikhaaee | 1615 |","meaning_en":"","page":589}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":589},{"type":"verse","number":[1616],"number_text":"੧੬੧੬।","page":589,"lines":[{"gurmukhi":"ਸੈਨ ਅਛੂਹਨਿ ਤੁਰਤ ਹੀ ਦੀਨੀ ਤਿਨਹਿ ਸੰਘਾਰਿ।","roman":"Sain achhoohni turat hee deenee tinhi sanghaari |","meaning_en":"","page":589},{"gurmukhi":"ਪੁਨਿ ਰਿਸਿ ਸਿਉ ਧਾਵਤ ਭਯੋ ਅਪੁਨੇ ਸਸਤ੍ਰ ਸੰਭਾਰਿ। ੧੬੧੬।","roman":"Puni risi siu dhaavat bhayo apune sasatr sanbhaari | 1616 |","meaning_en":"","page":589}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":589},{"type":"verse","number":[1617],"number_text":"੧੬੧੭।","page":589,"lines":[{"gurmukhi":"ਏਕ ਚਟਾਕ ਚਪੇਟ ਹਨੈ ਇਕ ਲੈ ਕਰ ਮੈ ਕਰਵਾਰ ਸੰਘਾਰੈ।","roman":"Ek chataak chapet hanai ik lai kar mai karvaar sanghaarai |","meaning_en":"","page":589},{"gurmukhi":"ਏਕਨ ਕੇ ਉਰ ਫਾਰਿ ਕਟਾਰਨ ਕੇਸਨ ਤੇ ਗਹਿ ਏਕ ਪਛਾਰੈ।","roman":"Ekan ke ur phaari kataaran kesan te gahi ek pachhaarai |","meaning_en":"","page":589},{"gurmukhi":"ਏਕ ਚਲਾਇ ਦਏ ਦਸਹੂੰ ਦਿਸ ਏਕ ਡਰੇ ਮਰ ਗੈ ਬਿਨੁ ਮਾਰੈ।","roman":"Ek chalaai dae dashoon dis ek dare mar gai binu maarai |","meaning_en":"","page":589},{"gurmukhi":"ਪੈਦਲੁ ਕੋ ਦਲੁ ਮਾਰ ਦਯੋ ਦੁਹ ਹਾਥਨ ਹਾਥੀਨ ਦਾਤ ਉਖਾਰੈ। ੧੬੧੭।","roman":"Paidlu ko dalu maar dayo duh haathan haatheen daat ukhaarai | 1617 |","meaning_en":"","page":589}]},{"type":"verse","number":[1618],"number_text":"੧੬੧੮।","page":589,"lines":[{"gurmukhi":"ਪਾਰਥ ਆਨਿ ਕਮਾਨ ਗਹੀ ਤਿਹ ਭੂਪਤਿ ਕੋ ਇਕ ਬਾਨ ਲਗਾਯੋ।","roman":"Paarath aani kamaan gahee tih bhoopti ko ik baan lagaayo |","meaning_en":"","page":589},{"gurmukhi":"ਲਾਗਤ ਹੀ ਅਵਸਾਨ ਗੁਮਾਨ ਗਯੋ ਖੜਗੇਸ ਮਹਾ ਦੁਖੁ ਪਾਯੋ।","roman":"Laagat hee avsaan gumaan gayo kharges mahaa dukhu paayo |","meaning_en":"","page":589},{"gurmukhi":"ਪਉਰਖ ਪੇਖ ਕੈ ਜੀ ਹਰਿਖਿਓ ਬਲ ਟੇਰ ਨਰੇਸ ਸੁ ਐਸ ਸੁਨਾਯੋ।","roman":"Paurakh pekh kai jee harikhio bal ter nares su ais sunaayo |","meaning_en":"","page":589},{"gurmukhi":"ਧੰਨ ਪਿਤਾ ਧੰਨ ਵੇ ਜਨਨੀ ਜੁ ਧਨੰਜੈ ਨਾਮ ਜਿਨੋ ਸੁਤ ਜਾਯੋ। ੧੬੧੮।","roman":"Dhann pitaa dhann ve jannee ju dhananjai naam jino sut jaayo | 1618 |","meaning_en":"","page":589}]},{"type":"heading","kind":"speaker","name":"ਖੜਗੇਸ ਬਾਚ ਪਾਰਥ ਸੋ","gurmukhi":"ਖੜਗੇਸ ਬਾਚ ਪਾਰਥ ਸੋ","roman":"Kharges baach paarath so","meaning_en":"","page":590},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":590},{"type":"verse","number":[1619],"number_text":"੧੬੧੯।","page":590,"lines":[{"gurmukhi":"ਆਨਨ ਮੈ ਮਸੁ ਭੀਜਤ ਹੈ ਬਰ ਬਾਰਿਜ ਸੇ ਜੁਗ ਲੋਚਨ ਤੇਰੇ।","roman":"Aanan mai masu bheejat hai bar baarij se jug lochan tere |","meaning_en":"","page":590},{"gurmukhi":"ਛੂਟਿ ਰਹੀ ਅਲਕੈ ਕਟਿ ਲਉ ਇਹ ਭਾਤਿ ਮਨੋ ਜੁਗ ਨਾਗ ਕਰੇਰੇ।","roman":"Chhooti rahee alkai kati lau ih bhaati mano jug naag karere |","meaning_en":"","page":590},{"gurmukhi":"ਆਨੰਦ ਕੰਦ ਕਿਧੋ ਮੁਖ ਚੰਦ ਕਟੇ ਦੁਖ ਫੰਧ ਚਕੋਰਨ ਕੇਰੇ।","roman":"Aanand kand kidho mukh chand kate dukh phandh chakoran kere |","meaning_en":"","page":590},{"gurmukhi":"ਸੁੰਦਰ ਸੂਰਤਿ ਕੈਸੇ ਹਨੋ ਤੁਮ ਦੇਖਿ ਦਇਆ ਉਪਜੀ ਜੀਅ ਮੇਰੇ। ੧੬੧੯।","roman":"Sundar soorti kaise hano tum dekhi daiaa upjee jeea mere | 1619 |","meaning_en":"","page":590}]},{"type":"verse","number":[1620],"number_text":"੧੬੨੦।","page":590,"lines":[{"gurmukhi":"ਪਾਰਥ ਹੇਰਿ ਹਸਿਓ ਸੁਨਿ ਬੈਨ ਚਲਿਯੋ ਮਨ ਭੀਤਰ ਕੋਪ ਭਰਿਯੋ।","roman":"Paarath heri hasio suni bain chaliyo man bheetar kop bhariyo |","meaning_en":"","page":590},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰ ਕੈ ਪਾਨਿ ਲੀਯੋ ਲਲਕਾਰਿ ਪਰਿਓ ਨ ਰਤੀ ਕੁ ਡਰਿਯੋ।","roman":"Dhanu baan sanbhaar kai paani leeyo lalkaari pario na ratee ku dariyo |","meaning_en":"","page":590},{"gurmukhi":"ਉਤ ਤੇ ਖੜਗੇਸ ਭਯੋ ਸਮੁਹੈ ਅਤਿ ਬਾਨਨ ਕੋ ਦੁਹੂੰ ਜੁਧ ਕਰਿਯੋ।","roman":"Ut te kharges bhayo samuhai ati baanan ko duhoon judh kariyo |","meaning_en":"","page":590},{"gurmukhi":"ਤਬ ਪਾਰਥ ਸਿਉ ਲਰਬੋ ਤਜਿ ਕੈ ਨ੍ਰਿਪ ਭੀਮ ਕੇ ਊਪਰਿ ਧਾਇ ਪਰਿਯੋ। ੧੬੨੦।","roman":"Tab paarath siu larbo taji kai nrip bheem ke oopri dhaai pariyo | 1620 |","meaning_en":"","page":590}]},{"type":"verse","number":[1621],"number_text":"੧੬੨੧।","page":590,"lines":[{"gurmukhi":"ਤਬ ਭੀਨ ਕੋ ਸ੍ਯੰਦਨ ਕਾਟਿ ਦਯੋ ਅਰੁ ਬੀਰ ਘਨੇ ਰਨ ਮਾਝ ਛਏ ਹੈ।","roman":"Tab bheen ko syandan kaati dayo aru beer ghane ran maajh chhae hai |","meaning_en":"","page":590},{"gurmukhi":"ਘਾਇਲ ਏਕ ਪਰੈ ਛਿਤ ਪੈ ਇਕ ਘਾਇਲ ਘਾਇਲ ਆਇ ਖਏ ਹੈ।","roman":"Ghaail ek parai chhit pai ik ghaail ghaail aai khae hai |","meaning_en":"","page":590},{"gurmukhi":"ਏਕ ਗਏ ਭਜਿ ਕੈ ਇਕ ਤੋ ਸਜਿ ਕੈ ਹਥਿਯਾਰਨ ਕੋਪ ਤਏ ਹੈ।","roman":"Ek gae bhaji kai ik to saji kai hathiyaaran kop tae hai |","meaning_en":"","page":590},{"gurmukhi":"ਏਕ ਫਿਰੈ ਭਟ ਕਾਪਤ ਹੀ ਕਰ ਤੇ ਛੁਟ ਕੈ ਕਰਵਾਰਿ ਗਏ ਹੈ। ੧੬੨੧।","roman":"Ek phirai bhat kaapat hee kar te chhut kai karvaari gae hai | 1621 |","meaning_en":"","page":590}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":590},{"type":"verse","number":[1622],"number_text":"੧੬੨੨।","page":590,"lines":[{"gurmukhi":"ਪੁਨਿ ਪਾਰਥ ਧਨੁ ਲੈ ਫਿਰਿਓ ਕਸਿ ਕੈ ਤੀਛਨ ਬਾਨ।","roman":"Puni paarath dhanu lai phirio kasi kai teechhan baan |","meaning_en":"","page":590},{"gurmukhi":"ਮਾਰਤ ਭਯੋ ਖੜਗੇਸ ਤਨ ਮਨਿ ਅਰਿ ਬਧਿ ਹਿਤ ਜਾਨਿ। ੧੬੨੨।","roman":"Maarat bhayo kharges tan mani ari badhi hit jaani | 1622 |","meaning_en":"","page":590}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":590},{"type":"verse","number":[1623],"number_text":"੧੬੨੩।","page":590,"lines":[{"gurmukhi":"ਬਾਨ ਲਗਿਯੋ ਜਬ ਹੀ ਤਿਹ ਕਉ ਤਬ ਹੀ ਰਿਸਿ ਕੈ ਕਹੀ ਭੂਪਤਿ ਬਾਤੈ।","roman":"Baan lagiyo jab hee tih kau tab hee risi kai kahee bhoopti baatai |","meaning_en":"","page":590},{"gurmukhi":"ਕਾਹੇ ਕਉ ਆਗਿ ਬਿਰਾਨੀ ਜਰੈ ਸੁਨ ਰੇ ਮ੍ਰਿਦ ਮੂਰਤਿ ਹਉ ਕਹੋ ਤਾ ਤੈ।","roman":"Kaahe kau aagi biraanee jarai sun re mrid moorti hau kaho taa tai |","meaning_en":"","page":590},{"gurmukhi":"ਤਾਹੀ ਸਮੇਤ ਹਨੋ ਤੁਮ ਕਉ ਸਿਖਈ ਜਿਹ ਬਾਨ ਚਲਾਨ ਕੀ ਘਾਤੈ।","roman":"Taahee samet hano tum kau sikhaee jih baan chalaan kee ghaatai |","meaning_en":"","page":590},{"gurmukhi":"ਜਾਹੁ ਚਲੇ ਗ੍ਰਿਹ ਛਾਡਤ ਹੋ ਤੁਝਿ ਸੁੰਦਰ ਨੈਨਨਿ ਜਾਨਿ ਕੈ ਨਾਤੈ। ੧੬੨੩।","roman":"Jaahu chale grih chhaadat ho tujhi sundar nainni jaani kai naatai | 1623 |","meaning_en":"","page":590}]},{"type":"verse","number":[1624],"number_text":"੧੬੨੪।","page":590,"lines":[{"gurmukhi":"ਯੌ ਕਹਿ ਭੂਪਤਿ ਪਾਰਥ ਕਉ ਰਨਿ ਧਾਇ ਪਰਿਓ ਕਰ ਲੈ ਅਸਿ ਪੈਨਾ।","roman":"Yau kahi bhoopti paarath kau rani dhaai pario kar lai asi painaa |","meaning_en":"","page":590},{"gurmukhi":"ਸੈਨ ਨਿਹਾਰਿ ਮਹਾ ਬਲੁ ਧਾਰਿ ਹਕਾਰਿ ਪਰਿਓ ਮਨ ਰੰਚਕ ਭੈ ਨਾ।","roman":"Sain nihaari mahaa balu dhaari hakaari pario man ranchak bhai naa |","meaning_en":"","page":590},{"gurmukhi":"ਸਤ੍ਰਨ ਕੇ ਅਵਸਾਨ ਗਏ ਛੁਟ ਕੋਊ ਸਕਿਓ ਕਰਿ ਆਯੁਧ ਲੈ ਨਾ।","roman":"Satran ke avsaan gae chhut ko'oo sakio kari aayudh lai naa |","meaning_en":"","page":590},{"gurmukhi":"ਮਾਰਿ ਅਨੇਕ ਦਏ ਰਨ ਮੈ ਇਕ ਪਾਨੀ ਹੀ ਪਾਨੀ ਰਟੈ ਕਰਿ ਸੈਨਾ। ੧੬੨੪।","roman":"Maari anek dae ran mai ik paanee hee paanee ratai kari sainaa | 1624 |","meaning_en":"","page":590}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":591},{"type":"verse","number":[1625],"number_text":"੧੬੨੫।","page":591,"lines":[{"gurmukhi":"ਭਜੀ ਸੈਨ ਜਬ ਪਾਡਵੀ ਕਿਸਨ ਬਿਲੋਕੀ ਨੈਨ।","roman":"Bhajee sain jab paadvee kisan bilokee nain |","meaning_en":"","page":591},{"gurmukhi":"ਦੁਰਜੋਧਨ ਸੋ ਯੌ ਕਹੀ ਤੁਮ ਧਾਵਹੁ ਲੈ ਸੈਨ। ੧੬੨੫।","roman":"Durjodhan so yau kahee tum dhaavhu lai sain | 1625 |","meaning_en":"","page":591}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":591},{"type":"verse","number":[1626],"number_text":"੧੬੨੬।","page":591,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਕੈ ਹਰਿ ਕੀ ਬਤੀਆ ਸਜਿ ਕੈ ਦੁਰਜੋਧਨ ਸੈਨ ਸਿਧਾਰਿਓ।","roman":"Yau suni kai hari kee bateeaa saji kai durjodhan sain sidhaario |","meaning_en":"","page":591},{"gurmukhi":"ਭੀਖਮ ਆਗੈ ਭਯੋ ਸੰਗ ਭਾਨੁਜ ਦ੍ਰੋਣ ਕ੍ਰਿਪਾ ਦਿਜ ਸਾਥ ਪਧਾਰਿਓ।","roman":"Bheekham aagai bhayo sang bhaanuj dron kripaa dij saath padhaario |","meaning_en":"","page":591},{"gurmukhi":"ਧਾਇ ਪਰੇ ਅਰਰਾਇ ਸਬੈ ਤਿਹ ਭੂਪਤਿ ਸੋ ਅਤਿ ਹੀ ਰਨ ਪਾਰਿਓ।","roman":"Dhaai pare arraai sabai tih bhoopti so ati hee ran paario |","meaning_en":"","page":591},{"gurmukhi":"ਆਗੇ ਹੁਇ ਭੂਪ ਲਰਿਓ ਨ ਡਰਿਓ ਸਭ ਕਉ ਸਰ ਏਕ ਹੀ ਏਕ ਪ੍ਰਹਾਰਿਓ। ੧੬੨੬।","roman":"Aage hui bhoop lario na dario sabh kau sar ek hee ek prahaario | 1626 |","meaning_en":"","page":591}]},{"type":"verse","number":[1627],"number_text":"੧੬੨੭।","page":591,"lines":[{"gurmukhi":"ਤਬ ਭੀਖਮ ਕੋਪ ਕੀਓ ਮਨ ਮੈ ਇਹ ਭੂਪਤਿ ਪੈ ਬਹੁ ਤੀਰ ਚਲਾਏ।","roman":"Tab bheekham kop keeo man mai ih bhoopti pai bahu teer chalaae |","meaning_en":"","page":591},{"gurmukhi":"ਆਵਤ ਬਾਨ ਸੋ ਬਾਨ ਕਟੇ ਖੜਗੇਸ ਮਹਾ ਅਸਿ ਲੈ ਕਰਿ ਧਾਏ।","roman":"Aavat baan so baan kate kharges mahaa asi lai kari dhaae |","meaning_en":"","page":591},{"gurmukhi":"ਹੋਤ ਭਯੋ ਤਹ ਜੁਧੁ ਬਡੋ ਰਿਸਿ ਭੀਖਮ ਕੋ ਨ੍ਰਿਪ ਬੈਨ ਸੁਨਾਏ।","roman":"Hot bhayo tah judhu bado risi bheekham ko nrip bain sunaae |","meaning_en":"","page":591},{"gurmukhi":"ਤਉ ਲਖਿ ਹੋ ਹਮਰੇ ਬਲ ਕਉ ਜਬ ਹੀ ਜਮ ਕੇ ਬਸਿ ਹੋ ਗ੍ਰਿਹ ਜਾਏ। ੧੬੨੭।","roman":"Tau lakhi ho hamre bal kau jab hee jam ke basi ho grih jaae | 1627 |","meaning_en":"","page":591}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":591},{"type":"verse","number":[1628],"number_text":"੧੬੨੮।","page":591,"lines":[{"gurmukhi":"ਭਜਤ ਨ ਭੀਖਮ ਜੁਧ ਤੇ ਭੂਪ ਲਖੀ ਇਹ ਗਾਥ।","roman":"Bhajat na bheekham judh te bhoop lakhee ih gaath |","meaning_en":"","page":591},{"gurmukhi":"ਸੀਸ ਕਟਿਓ ਤਿਹ ਸੂਤ ਕੋ ਏਕ ਬਾਨ ਕੇ ਸਾਥ। ੧੬੨੮।","roman":"Sees katio tih soot ko ek baan ke saath | 1628 |","meaning_en":"","page":591}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":591},{"type":"verse","number":[1629],"number_text":"੧੬੨੯।","page":591,"lines":[{"gurmukhi":"ਅਸ੍ਵ ਲੈ ਭੀਖਮ ਕੋ ਭਜਿ ਗੇ ਤਬ ਹੀ ਦੁਰਜੋਧਨ ਕੋਪ ਭਰਿਓ।","roman":"Asv lai bheekham ko bhaji ge tab hee durjodhan kop bhario |","meaning_en":"","page":591},{"gurmukhi":"ਸੰਗ ਦ੍ਰੋਣ ਕੋ ਪੁਤ੍ਰ ਕ੍ਰਿਪਾ ਬਰ ਲੈ ਬਰਮਾਕ੍ਰਿਤ ਜਾਦਵ ਜਾਇ ਪਰਿਓ।","roman":"Sang dron ko putr kripaa bar lai barmaakrit jaadav jaai pario |","meaning_en":"","page":591},{"gurmukhi":"ਧਨੁ ਬਾਨ ਲੈ ਦ੍ਰਉਣ ਹੂੰ ਆਪ ਤਬੈ ਹਠ ਠਾਨਿ ਰਹਿਓ ਨਹਿ ਨੈਕੁ ਡਰਿਓ।","roman":"Dhanu baan lai draun hoon aap tabai hath thaani rahio nahi naiku dario |","meaning_en":"","page":591},{"gurmukhi":"ਕਰਵਾਰਿ ਕਟਾਰਿਨਿ ਸੂਲਨਿ ਸਾਂਗਨਿ ਚਕ੍ਰਨਿ ਕੋ ਅਤਿ ਜੂਝ ਕਰਿਓ। ੧੬੨੯।","roman":"Karvaari kataarini soolni saangni chakrani ko ati joojh kario | 1629 |","meaning_en":"","page":591}]},{"type":"heading","kind":"speaker","name":"ਕਾਨ ਜੂ ਬਾਚ ਖੜਗੇਸ ਸੋ","gurmukhi":"ਕਾਨ ਜੂ ਬਾਚ ਖੜਗੇਸ ਸੋ","roman":"Kaan joo baach kharges so","meaning_en":"","page":591},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":591},{"type":"verse","number":[1630],"number_text":"੧੬੩੦।","page":591,"lines":[{"gurmukhi":"ਤਉ ਹੀ ਲਉ ਜਦੁਬੀਰ ਲੀਏ ਧਨੁ ਸ੍ਰੀ ਖੜਗੇਸ ਕਉ ਬੈਨ ਸੁਨਾਯੋ।","roman":"Tau hee lau jadubeer lee'e dhanu sree kharges kau bain sunaayo |","meaning_en":"","page":591},{"gurmukhi":"ਮਾਰਤ ਹਉ ਹਠਿ ਕੈ ਸਠਿ ਤੋ ਕਹੁ ਕਾ ਭਯੋ ਜੁ ਅਤਿ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Maarat hau hathi kai sathi to kahu kaa bhayo ju ati judhu machaayo |","meaning_en":"","page":591},{"gurmukhi":"ਏਕ ਘਰੀ ਲਰਿ ਲੈ ਮਰਿ ਹੈ ਅਬ ਜਾਨਤ ਹਉ ਤੁਯ ਕਾਲ ਹੀ ਆਯੋ।","roman":"Ek gharee lari lai mari hai ab jaanat hau tuy kaal hee aayo |","meaning_en":"","page":591},{"gurmukhi":"ਚੇਤ ਰੇ ਚੇਤ ਅਜਉ ਚਿਤ ਮੈ ਹਰਿ ਇਉ ਕਹਿ ਕੈ ਧਨੁ ਬਾਨ ਚਲਾਯੋ। ੧੬੩੦।","roman":"Chet re chet ajau chit mai hari iu kahi kai dhanu baan chalaayo | 1630 |","meaning_en":"","page":591}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":592},{"type":"verse","number":[1631],"number_text":"੧੬੩੧।","page":592,"lines":[{"gurmukhi":"ਆਵਤ ਸਰ ਸੋ ਕਾਟਿ ਕੈ ਰਿਸਿ ਬੋਲਿਯੋ ਖੜਗੇਸ।","roman":"Aavat sar so kaati kai risi boliyo kharges |","meaning_en":"","page":592},{"gurmukhi":"ਮੁਹਿ ਪਉਰਖ ਜਾਨਤ ਸਕਲ ਸੇਸ ਸੁਰੇਸ ਮਹੇਸ। ੧੬੩੧।","roman":"Muhi paurakh jaanat sakal ses sures mahes | 1631 |","meaning_en":"","page":592}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":592},{"type":"verse","number":[1632],"number_text":"੧੬੩੨।","page":592,"lines":[{"gurmukhi":"ਭਖ ਜੈ ਹਉ ਭੂਤਨ ਭਜਾਇ ਦੈਹੋ ਸੁਰਾਸੁਰ","roman":"Bhakh jai hau bhootan bhajaai daiho suraasur","meaning_en":"","page":592},{"gurmukhi":"ਸ੍ਯਾਮ ਪਟਿਕੈ ਹੋ ਭੂਮਿ ਭੁਜਾ ਅਸਿ ਜੋ ਗਹਉ।","roman":"Syaam patikai ho bhoomi bhujaa asi jo gahau |","meaning_en":"","page":592},{"gurmukhi":"ਭੈਰਵ ਨਚੈ ਹਉ ਭਾਰੀ ਜੁਧਹਿ ਮਚੈ ਹਉ","roman":"Bhairav nachai hau bhaaree judhhi machai hau","meaning_en":"","page":592},{"gurmukhi":"ਪੁਨਿ ਭਾਜ ਹੂੰ ਨ ਜੈ ਹਉ ਸੁਨਿ ਸਾਚੀ ਹਰਿ ਹਉ ਕਹਉ।","roman":"Puni bhaaj hoon na jai hau suni saachee hari hau kahau |","meaning_en":"","page":592},{"gurmukhi":"ਕਹਾ ਦ੍ਰਉਣ ਦਿਜ ਕਉ ਸੰਘਾਰਤ ਨ ਲਾਗੈ ਪਲ","roman":"Kahaa draun dij kau sanghaarat na laagai pal","meaning_en":"","page":592},{"gurmukhi":"ਮਾਰੋ ਦਲ ਬਲਿ ਇੰਦ੍ਰ ਜਮ ਰੁਦ੍ਰ ਜੋ ਚਹਉ।","roman":"Maaro dal bali indr jam rudr jo chahau |","meaning_en":"","page":592},{"gurmukhi":"ਰਾਧਿਕਾ ਰਵਨ ਤਉ ਤੇਰੇ ਰਨ ਜੁਰੇ ਆਜੁ","roman":"Raadhikaa ravan tau tere ran jure aaju","meaning_en":"","page":592},{"gurmukhi":"ਛਤ੍ਰੀ ਖੜਗੇਸ ਹੁਇ ਕੈ ਐਸੋ ਬੋਲ ਹਉ ਸਹਉ। ੧੬੩੨।","roman":"Chhatree kharges hui kai aiso bol hau sahau | 1632 |","meaning_en":"","page":592}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"","page":592},{"type":"verse","number":[1633],"number_text":"੧੬੩੩।","page":592,"lines":[{"gurmukhi":"ਤਬਹਿ ਦ੍ਰਉਣ ਰਿਸ ਕੋ ਬਢਾਇ ਨ੍ਰਿਪ ਸਉਹੈ ਧਾਯੋ।","roman":"Tabhi draun ris ko badhaai nrip sauhai dhaayo |","meaning_en":"","page":592},{"gurmukhi":"ਅਸਤ੍ਰ ਸਸਤ੍ਰ ਗਹਿ ਪਾਨਿ ਬਹੁਤੁ ਬਿਧਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Asatr sasatr gahi paani bahutu bidhi judh machaayo |","meaning_en":"","page":592},{"gurmukhi":"ਅਧਿਕ ਸ੍ਰਉਣ ਤਨ ਭਰੇ ਲਰੇ ਭਟ ਘਾਇਲ ਐਸੇ।","roman":"Adhik sraun tan bhare lare bhat ghaail aise |","meaning_en":"","page":592},{"gurmukhi":"ਲਾਲ ਗੁਲਾਲ ਭਰੇ ਪਟਿ ਖੇਲਤ ਚਾਚਰ ਜੈਸੇ।","roman":"Laal gulaal bhare pati khelat chaachar jaise |","meaning_en":"","page":592},{"gurmukhi":"ਤਬ ਦੇਖਿ ਸਭੈ ਸੁਰ ਯੌ ਕਹੈ ਧਨਿ ਦਿਜ ਧਨਿ ਸੁ ਭੂਪ ਤੁਅ।","roman":"Tab dekhi sabhai sur yau kahai dhani dij dhani su bhoop tua |","meaning_en":"","page":592},{"gurmukhi":"ਜੁਗ ਚਾਰਨ ਮੈ ਅਬ ਲਉ ਕਹੂੰ ਐਸੇ ਜੁਧ ਨ ਭਯੋ ਭੁਅ। ੧੬੩੩।","roman":"Jug chaaran mai ab lau kahoon aise judh na bhayo bhua | 1633 |","meaning_en":"","page":592}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":592},{"type":"verse","number":[1634],"number_text":"੧੬੩੪।","page":592,"lines":[{"gurmukhi":"ਘੇਰਿਓ ਤਬ ਖੜਗੇਸ ਕਉ ਪਾਡਵ ਸੈਨ ਰਿਸਾਇ।","roman":"Gherio tab kharges kau paadav sain risaai |","meaning_en":"","page":592},{"gurmukhi":"ਪਾਰਥ ਭੀਖਮ ਭੀਮ ਦਿਜ ਦ੍ਰਉਣ ਕ੍ਰਿਪਾ ਕੁਰ ਰਾਇ। ੧੬੩੪।","roman":"Paarath bheekham bheem dij draun kripaa kur raai | 1634 |","meaning_en":"","page":592}]},{"type":"heading","kind":"chhand","name":"ਕਬਿਤੁ","gurmukhi":"ਕਬਿਤੁ","roman":"Kabitu","meaning_en":"","page":592},{"type":"verse","number":[1635],"number_text":"੧੬੩੫।","page":592,"lines":[{"gurmukhi":"ਜੈਸੇ ਬਾਰ ਖੇਤ ਕਉ ਜੁ ਕਾਲ ਫਾਸ ਚੇਤ ਕਉ","roman":"Jaise baar khet kau ju kaal phaas chet kau","meaning_en":"","page":592},{"gurmukhi":"ਸੁ ਭਿਛ ਦਾਨ ਦੇਤ ਕਉ ਸੁ ਕੰਕਨ ਜਿਉ ਕਰ ਕੋ।","roman":"Su bhichh daan det kau su kankan jiu kar ko |","meaning_en":"","page":592},{"gurmukhi":"ਜੈਸੇ ਦੇਹ ਪ੍ਰਾਨ ਕਉ ਪ੍ਰਵੇਖ ਸਸਿ ਭਾਨੁ ਕਉ।","roman":"Jaise deh praan kau pravekh sasi bhaanu kau |","meaning_en":"","page":592},{"gurmukhi":"ਅਗਿਆਨ ਜੈਸੇ ਗਿਆਨ ਕਉ ਸੁ ਗੋਪੀ ਜੈਸੇ ਹਰਿ ਕੋ।","roman":"Agiaan jaise giaan kau su gopee jaise hari ko |","meaning_en":"","page":592},{"gurmukhi":"ਜਿਉ ਤੜਾਗ ਆਪ ਕਉ ਸੁ ਮਾਲਾ ਜੈਸੇ ਜਾਪੁ ਕਉ","roman":"Jiu taraag aap kau su maalaa jaise jaapu kau","meaning_en":"","page":592},{"gurmukhi":"ਸੋ ਪੁੰਨਿ ਜੈਸੇ ਪਾਪ ਕਉ ਜਿਉ ਆਲ ਬਾਲ ਤਰੁ ਕੋ।","roman":"So punni jaise paap kau jiu aal baal taru ko |","meaning_en":"","page":592},{"gurmukhi":"ਜੈਸੇ ਉਡ ਧ੍ਰੂਅ ਕਉ ਸਮੁਦਰ ਜੈਸੇ ਭੂਅ ਕਉ","roman":"Jaise ud dhrooa kau samudar jaise bhooa kau","meaning_en":"","page":592,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}]},{"gurmukhi":"ਸੁ ਤੈਸੇ ਘੇਰਿ ਲੀਨੋ ਹੈ ਖੜਗ ਸਿੰਘ ਬਰ ਕੋ। ੧੬੩੫।","roman":"Su taise gheri leeno hai kharag singh bar ko | 1635 |","meaning_en":"","page":592}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":593},{"type":"verse","number":[1636],"number_text":"੧੬੩੬।","page":593,"lines":[{"gurmukhi":"ਘੇਰਿ ਲਯੋ ਖੜਗੇਸ ਜਬੈ ਤਬ ਹੀ ਦੁਰਜੋਧਨ ਕੋਪ ਭਯੋ ਹੈ।","roman":"Gheri layo kharges jabai tab hee durjodhan kop bhayo hai |","meaning_en":"","page":593},{"gurmukhi":"ਪਾਰਥ ਭੀਮ ਜੁਧਿਸਟਰ ਭੀਖਮ ਅਉਰ ਹਲੀ ਹਲੁ ਪਾਨਿ ਲਯੋ ਹੈ।","roman":"Paarath bheem judhistar bheekham aur halee halu paani layo hai |","meaning_en":"","page":593},{"gurmukhi":"ਭਾਨੁਜ ਦ੍ਰਉਣ ਜੁ ਅਉਰ ਕ੍ਰਿਪਾ ਸੁ ਕ੍ਰਿਪਾਨ ਲਏ ਅਰਿ ਓਰਿ ਗਯੋ ਹੈ।","roman":"Bhaanuj draun ju aur kripaa su kripaan lae ari ori gayo hai |","meaning_en":"","page":593},{"gurmukhi":"ਅਤ੍ਰਨ ਲਾਤਨ ਮੂਕਨ ਦਾਤਨ ਕੋ ਤਹਾ ਆਹਵ ਹੋਤ ਭਯੋ ਹੈ। ੧੬੩੬।","roman":"Atran laatan mookan daatan ko tahaa aahav hot bhayo hai | 1636 |","meaning_en":"","page":593}]},{"type":"verse","number":[1637],"number_text":"੧੬੩੭।","page":593,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਖੜਗੇਸ ਲਯੋ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਕਈ ਅਰਿ ਕੋਟਿ ਸੰਘਾਰੇ।","roman":"Sree kharges layo dhanu baan sanbhaari kaee ari koti sanghaare |","meaning_en":"","page":593},{"gurmukhi":"ਬਾਜ ਪਰੇ ਕਹੂੰ ਤਾਜ ਗਿਰੇ ਗਜਰਾਜ ਗਿਰੇ ਗਿਰਿ ਸੇ ਧਰਿ ਕਾਰੇ।","roman":"Baaj pare kahoon taaj gire gajraaj gire giri se dhari kaare |","meaning_en":"","page":593},{"gurmukhi":"ਘਾਇਲ ਏਕ ਪਰੇ ਤਰਫੈ ਸੁ ਮਨੋ ਕਰਸਾਯਲ ਸਿੰਘ ਬਿਡਾਰੇ।","roman":"Ghaail ek pare tarphai su mano karsaayal singh bidaare |","meaning_en":"","page":593},{"gurmukhi":"ਏਕ ਬਲੀ ਕਰਵਾਰਨ ਸੋ ਅਰਿ ਲੋਥ ਪਰੀ ਤਿਹ ਮੂੰਡ ਉਤਾਰੇ। ੧੬੩੭।","roman":"Ek balee karvaaran so ari loth paree tih moond utaare | 1637 |","meaning_en":"","page":593}]},{"type":"verse","number":[1638],"number_text":"੧੬੩੮।","page":593,"lines":[{"gurmukhi":"ਭੂਪਤਿ ਬਾਨ ਕਮਾਨ ਗਹੀ ਜਦੁਬੀਰਨ ਕੇ ਅਭਿਮਾਨ ਉਤਾਰੇ।","roman":"Bhoopti baan kamaan gahee jadubeeran ke abhimaan utaare |","meaning_en":"","page":593},{"gurmukhi":"ਫੇਰਿ ਲਈ ਜਮਧਾਰਿ ਸੰਭਾਰਿ ਹਕਾਰ ਕੇ ਸਤ੍ਰਨ ਕੇ ਉਰ ਫਾਰੇ।","roman":"Pheri laee jamdhaari sanbhaari hakaar ke satran ke ur phaare |","meaning_en":"","page":593},{"gurmukhi":"ਘਾਇ ਏਕ ਗਿਰੇ ਰਨ ਮੈ ਅਪਨੇ ਮਨ ਮੈ ਜਗਦੀਸ ਸੰਭਾਰੇ।","roman":"Ghaai ek gire ran mai apne man mai jagdees sanbhaare |","meaning_en":"","page":593},{"gurmukhi":"ਤੇ ਵਹ ਮੋਖ ਭਏ ਤਬ ਹੀ ਭਵ ਕੋ ਤਰ ਕੈ ਹਰਿ ਲੋਕਿ ਪਧਾਰੇ। ੧੬੩੮।","roman":"Te vah mokh bhae tab hee bhav ko tar kai hari loki padhaare | 1638 |","meaning_en":"","page":593}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":593},{"type":"verse","number":[1639],"number_text":"੧੬੩੯।","page":593,"lines":[{"gurmukhi":"ਨਿਪਟ ਸੁਭਟ ਚਟਪਟ ਕਟੇ ਖਟਪਟ ਕਹੀ ਨ ਜਾਇ।","roman":"Nipat subhat chatpat kate khatpat kahee na jaai |","meaning_en":"","page":593},{"gurmukhi":"ਸਟਪਟ ਜੇ ਭਾਜੇ ਤਿਨਹੁ ਪਾਰਥ ਕਹਿਓ ਸੁਨਾਇ। ੧੬੩੯।","roman":"Satpat je bhaaje tinhu paarath kahio sunaai | 1639 |","meaning_en":"","page":593}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":593},{"type":"verse","number":[1640],"number_text":"੧੬੪੦।","page":593,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਬ੍ਰਿਜਰਾਜ ਕੈ ਕਾਜ ਕੋ ਆਜ ਕਰੋ ਸਭ ਹੀ ਭਟ ਨਾਹਿ ਟਰੋ।","roman":"Sree brijraaj kai kaaj ko aaj karo sabh hee bhat naahi taro |","meaning_en":"","page":593},{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰ ਕੈ ਪਾਨਨ ਮੈ ਅਰਿ ਭੂਪਤਿ ਕਉ ਲਲਕਾਰਿ ਪਰੋ।","roman":"Dhanu baan sanbhaar kai paanan mai ari bhoopti kau lalkaari paro |","meaning_en":"","page":593},{"gurmukhi":"ਮੁਖ ਤੇ ਮਿਲਿ ਮਾਰ ਹੀ ਮਾਰ ਰਰੋ ਅਪੁਨੇ ਅਪੁਨੇ ਹਥਿਯਾਰ ਧਰੋ।","roman":"Mukh te mili maar hee maar raro apune apune hathiyaar dharo |","meaning_en":"","page":593},{"gurmukhi":"ਤੁਮ ਤੋ ਕੁਲ ਕੀ ਕਛੁ ਲਾਜ ਕਰੋ ਖੜਗੇਸ ਕੇ ਸੰਗਿ ਲਰੋ ਨ ਡਰੋ। ੧੬੪੦।","roman":"Tum to kul kee kachhu laaj karo kharges ke sangi laro na daro | 1640 |","meaning_en":"","page":593}]},{"type":"verse","number":[1641],"number_text":"੧੬੪੧।","page":593,"lines":[{"gurmukhi":"ਭਾਨੁਜ ਕੋਪ ਭਯੋ ਚਿਤ ਮੈ ਤਿਹ ਭੂਪਤਿ ਕੇ ਹਠਿ ਸਾਮੁਹੇ ਧਾਯੋ।","roman":"Bhaanuj kop bhayo chit mai tih bhoopti ke hathi saamuhe dhaayo |","meaning_en":"","page":593},{"gurmukhi":"ਚਾਪ ਚਢਾਇ ਲਯੋ ਕਰ ਮੈ ਸਰ ਯੌ ਤਬ ਹੀ ਇਕ ਬੈਨ ਸੁਨਾਯੋ।","roman":"Chaap chadhaai layo kar mai sar yau tab hee ik bain sunaayo |","meaning_en":"","page":593},{"gurmukhi":"ਆਯੋ ਹੈ ਕੇਹਰਿ ਕੇ ਮੁਖ ਮੈ ਮ੍ਰਿਗ ਐਸੇ ਕਹਿਯੋ ਨ੍ਰਿਪ ਤਊ ਸੁਨਿ ਪਾਯੋ।","roman":"Aayo hai kehri ke mukh mai mrig aise kahiyo nrip taoo suni paayo |","meaning_en":"","page":593},{"gurmukhi":"ਭੂਪਤਿ ਹਾਥਿ ਲਯੋ ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਕਹਿਓ ਮੁਖ ਤੇ ਸਮਝਾਯੋ। ੧੬੪੧।","roman":"Bhoopti haathi layo dhanu baan sanbhaari kahio mukh te samjhaayo | 1641 |","meaning_en":"","page":593}]},{"type":"verse","number":[1642],"number_text":"੧੬੪੨।","page":593,"lines":[{"gurmukhi":"ਭਾਨੁਜ ਕਾਹੇ ਕਉ ਜੁਝਿ ਮਰੋ ਗ੍ਰਿਹ ਜਾਹੁ ਭਲੋ ਦਿਨ ਕੋਇਕ ਜੀਜੋ।","roman":"Bhaanuj kaahe kau jujhi maro grih jaahu bhalo din koik jeejo |","meaning_en":"","page":593},{"gurmukhi":"ਖਾਤ ਹਲਾਹਲ ਕਿਉ ਅਪਨੇ ਕਰਿ ਜਾਇ ਕੈ ਧਾਮੁ ਸੁਧਾ ਰਸੁ ਪੀਜੋ।","roman":"Khaat halaahal kiu apne kari jaai kai dhaamu sudhaa rasu peejo |","meaning_en":"","page":593},{"gurmukhi":"ਯੌ ਕਹਿ ਭੂਪਤਿ ਬਾਨ ਹਨਿਓ ਮੁਖ ਤੇ ਕਹਿਯੋ ਜੁਧਹਿ ਕੋ ਫਲੁ ਲੀਜੋ।","roman":"Yau kahi bhoopti baan hanio mukh te kahiyo judhhi ko phalu leejo |","meaning_en":"","page":593},{"gurmukhi":"ਲਾਗਤਿ ਬਾਨ ਗਿਰਿਓ ਮੁਰਛਾਇ ਕੈ ਸ੍ਰਉਨ ਗਿਰਿਓ ਸਗਰੋ ਅੰਗ ਭੀਜੋ। ੧੬੪੨।","roman":"Laagti baan girio murchhaai kai sraun girio sagro ang bheejo | 1642 |","meaning_en":"","page":593}]},{"type":"verse","number":[1643],"number_text":"੧੬੪੩।","page":594,"lines":[{"gurmukhi":"ਤਉ ਹੀ ਲਉ ਭੀਮ ਗਦਾ ਗਹਿ ਕੈ ਪੁਨਿ ਪਾਰਥ ਲੈ ਕਰ ਮੈ ਧਨ ਧਾਯੋ।","roman":"Tau hee lau bheem gadaa gahi kai puni paarath lai kar mai dhan dhaayo |","meaning_en":"","page":594},{"gurmukhi":"ਭੀਖਮ ਦ੍ਰੋਣ ਕ੍ਰਿਪਾ ਸਹਦੇਵ ਸੁ ਭੂਰਸ੍ਰਵਾ ਮਨਿ ਕੋਪ ਬਢਾਯੋ।","roman":"Bheekham dron kripaa sahdev su bhoorsravaa mani kop badhaayo |","meaning_en":"","page":594},{"gurmukhi":"ਸ੍ਰੀ ਦੁਰਜੋਧਨ ਰਾਇ ਜੁਧਿਸਟਰ ਸ੍ਰੀ ਬਿਜ ਨਾਇਕ ਲੈ ਦਲੁ ਆਯੋ।","roman":"Sree durjodhan raai judhistar sree bij naaik lai dalu aayo |","meaning_en":"","page":594},{"gurmukhi":"ਭੂਪ ਕੇ ਤੀਰਨ ਕੇ ਡਰ ਤੇ ਬਰ ਬੀਰਨ ਤਉ ਮਨ ਮੈ ਡਰ ਪਾਯੋ। ੧੬੪੩।","roman":"Bhoop ke teeran ke dar te bar beeran tau man mai dar paayo | 1643 |","meaning_en":"","page":594}]},{"type":"verse","number":[1644],"number_text":"੧੬੪੪।","page":594,"lines":[{"gurmukhi":"ਤਉ ਲਗਿ ਸ੍ਰੀਪਤਿ ਆਪ ਕੁਪਿਯੋ ਸਰ ਭੂਪਤਿ ਕੇ ਉਰ ਮੈ ਇਕ ਮਾਰਿਓ।","roman":"Tau lagi sreepti aap kupiyo sar bhoopti ke ur mai ik maario |","meaning_en":"","page":594},{"gurmukhi":"ਏਕ ਹੀ ਬਾਨ ਕੋ ਤਾਨ ਤਬੈ ਤਿਹ ਸਾਰਥੀ ਕੋ ਪ੍ਰਤਿਅੰਗ ਪ੍ਰਹਾਰਿਓ।","roman":"Ek hee baan ko taan tabai tih saarthee ko pratiang prahaario |","meaning_en":"","page":594},{"gurmukhi":"ਭੂਪਤਿ ਆਗੇ ਹੀ ਹੋਤ ਭਯੋ ਰਨ ਭੂਮਹਿ ਤੇ ਨ ਟਰਿਓ ਪਗ ਟਾਰਿਓ।","roman":"Bhoopti aage hee hot bhayo ran bhoomhi te na tario pag taario |","meaning_en":"","page":594},{"gurmukhi":"ਸੂਰ ਸਰਾਹਤ ਭੇ ਸਭ ਹੀ ਜਸੁ ਯੋ ਮੁਖ ਤੇ ਕਬਿ ਸ੍ਯਾਮ ਉਚਾਰਿਓ। ੧੬੪੪।","roman":"Soor saraahat bhe sabh hee jasu yo mukh te kabi syaam uchaario | 1644 |","meaning_en":"","page":594}]},{"type":"verse","number":[1645],"number_text":"੧੬੪੫।","page":594,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਕੋ ਅਵਿਲੋਕ ਕੈ ਆਨਨ ਇਉ ਕਹਿ ਕੈ ਨ੍ਰਿਪ ਬਾਤ ਸੁਨਾਈ।","roman":"Sree hari ko avilok kai aanan iu kahi kai nrip baat sunaaee |","meaning_en":"","page":594},{"gurmukhi":"ਛੂਟ ਰਹੀ ਅਲਕੈ ਕਟਿ ਲਉ ਉਪਮਾ ਮੁਖ ਕੀ ਬਰਨੀ ਨਹੀ ਜਾਈ।","roman":"Chhoot rahee alkai kati lau upmaa mukh kee barnee nahee jaaee |","meaning_en":"","page":594},{"gurmukhi":"ਚਾਰੁ ਦਿਪੈ ਅਖੀਆਨ ਦੋਊ ਉਪਮਾ ਨ ਕਛੂ ਇਨ ਤੇ ਅਧਿਕਾਈ।","roman":"Chaaru dipai akheeaan do'oo upmaa na kachhoo in te adhikaaee |","meaning_en":"","page":594},{"gurmukhi":"ਜਾਹੁ ਚਲੇ ਤੁਮ ਕਉ ਹਰਿ ਛਾਡਤਿ ਲੈਹੁ ਕਹਾ ਹਠਿ ਠਾਨਿ ਲਰਾਈ। ੧੬੪੫।","roman":"Jaahu chale tum kau hari chhaadti laihu kahaa hathi thaani laraaee | 1645 |","meaning_en":"","page":594}]},{"type":"verse","number":[1646],"number_text":"੧੬੪੬।","page":594,"lines":[{"gurmukhi":"ਧਨੁ ਬਾਨ ਸੰਭਾਰਿ ਕਹਿਯੋ ਬਹੁਰੋ ਹਮਰੀ ਬਤੀਯਾ ਹਰਿ ਜੂ ਸੁਨਿ ਲੀਜੈ।","roman":"Dhanu baan sanbhaari kahiyo bahuro hamree bateeyaa hari joo suni leejai |","meaning_en":"","page":594},{"gurmukhi":"ਕਿਉ ਹਠਿ ਠਾਨਿ ਅਯੋਧਨ ਮੈ ਹਮ ਸਿਉ ਸਮੁਹਾਇ ਕੈ ਆਹਵ ਕੀਜੈ।","roman":"Kiu hathi thaani ayodhan mai ham siu samuhaai kai aahav keejai |","meaning_en":"","page":594},{"gurmukhi":"ਮਾਰਤ ਹੋ ਤਬ ਤੋਹਿ ਨ ਛਾਡਤ ਜਾਹੁ ਭਲੇ ਅਬ ਲਉ ਨਹੀ ਛੀਜੈ।","roman":"Maarat ho tab tohi na chhaadat jaahu bhale ab lau nahee chheejai |","meaning_en":"","page":594},{"gurmukhi":"ਮਾਨ ਕਹਿਓ ਹਮਰੋ ਪੁਰ ਕੀ ਕਜਰਾਰਨਿ ਕੋ ਨ ਬ੍ਰਿਥਾ ਦੁਖ ਦੀਜੈ। ੧੬੪੬।","roman":"Maan kahio hamro pur kee kajraarni ko na brithaa dukh deejai | 1646 |","meaning_en":"","page":594}]},{"type":"verse","number":[1647],"number_text":"੧੬੪੭।","page":594,"lines":[{"gurmukhi":"ਹਉ ਹਠ ਠਾਨਿ ਅਯੋਧਨ ਮੈ ਘਨ ਸ੍ਯਾਮ ਘਨੇ ਰਨਬੀਰ ਨਿਬੇਰੇ।","roman":"Hau hath thaani ayodhan mai ghan syaam ghane ranbeer nibere |","meaning_en":"","page":594},{"gurmukhi":"ਕਾ ਕੇ ਕਹੇ ਹਮ ਸੋ ਹਰਿ ਜੂ ਸਮੁਹਾਇ ਭਯੋ ਨ ਫਿਰਿਓ ਰਨ ਹੇਰੇ।","roman":"Kaa ke kahe ham so hari joo samuhaai bhayo na phirio ran here |","meaning_en":"","page":594},{"gurmukhi":"ਮਾਰੋ ਕਹਾ ਅਬ ਤੋ ਕਹੁ ਹਉ ਕਰੁਨਾ ਅਤਿ ਹੀ ਜੀਯ ਆਵਤ ਮੇਰੇ।","roman":"Maaro kahaa ab to kahu hau karunaa ati hee jeey aavat mere |","meaning_en":"","page":594},{"gurmukhi":"ਤੋ ਕਉ ਮਰਿਓ ਸੁਨਿ ਕੈ ਛਿਨ ਮੈ ਮਰਿ ਜੈ ਹੈ ਸਖਾ ਹਰਿ ਜੇਤਕ ਤੇਰੇ। ੧੬੪੭।","roman":"To kau mario suni kai chhin mai mari jai hai sakhaa hari jetak tere | 1647 |","meaning_en":"","page":594}]},{"type":"verse","number":[1648],"number_text":"੧੬੪੮।","page":594,"lines":[{"gurmukhi":"ਹਰਿ ਇਉ ਸੁਨਿ ਕੈ ਧਨੁ ਬਾਨ ਲਯੋ ਰਿਸਿ ਕੈ ਖੜਗੇਸ ਕੇ ਸਾਮੁਹੇ ਧਾਯੋ।","roman":"Hari iu suni kai dhanu baan layo risi kai kharges ke saamuhe dhaayo |","meaning_en":"","page":594},{"gurmukhi":"ਆਵਤ ਹੀ ਕਬਿ ਸ੍ਯਾਮ ਭਨੈ ਘਟਿਕਾ ਜੁਗ ਬਾਨਨ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Aavat hee kabi syaam bhanai ghatikaa jug baanan judhu machaayo |","meaning_en":"","page":594},{"gurmukhi":"ਸ੍ਯਾਮ ਗਿਰਾਵਤ ਭਯੋ ਨ੍ਰਿਪ ਕਉ ਨ੍ਰਿਪ ਹੂੰ ਰਥ ਤੇ ਹਰਿ ਭੂਮਿ ਗਿਰਾਯੋ।","roman":"Syaam giraavat bhayo nrip kau nrip hoon rath te hari bhoomi giraayo |","meaning_en":"","page":594},{"gurmukhi":"ਕਉਤਕ ਹੇਰਿ ਸਰਾਹਤ ਭੇ ਭਟ ਸ੍ਰੀ ਹਰਿ ਕੋ ਨ੍ਰਿਪ ਕੋ ਜਸੁ ਗਾਯੋ। ੧੬੪੮।","roman":"Kautak heri saraahat bhe bhat sree hari ko nrip ko jasu gaayo | 1648 |","meaning_en":"","page":594}]},{"type":"verse","number":[1649],"number_text":"੧੬੪੯।","page":594,"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਯਾਮ ਚਢਿਯੋ ਰਥ ਆਪਨ ਪੈ ਰਥ ਪੈ ਉਤ ਸ੍ਰੀ ਖੜਗੇਸ ਚਢਿਓ।","roman":"Iti syaam chadhiyo rath aapan pai rath pai ut sree kharges chadhio |","meaning_en":"","page":594},{"gurmukhi":"ਅਤਿ ਕੋਪ ਬਢਾਇ ਮਹਾ ਚਿਤ ਮੈ ਤਿਹ ਮਯਾਨਹੁ ਤੇ ਕਰਵਾਰ ਕਢਿਓ।","roman":"Ati kop badhaai mahaa chit mai tih mayaanhu te karvaar kadhio |","meaning_en":"","page":594},{"gurmukhi":"ਸੁ ਘਨੋ ਦਲ ਪੰਡੁ ਕੇ ਪੁਤ੍ਰਨ ਕੋ ਰਿਸਿ ਤੇਜ ਕੀ ਪਾਵਕ ਸੰਗ ਡਢਿਓ।","roman":"Su ghano dal pandu ke putran ko risi tej kee paavak sang dadhio |","meaning_en":"","page":594},{"gurmukhi":"ਧੁਨਿ ਬੇਦ ਕੀ ਅਸਤ੍ਰਨਿ ਸਸਤ੍ਰਨਿ ਕੀ ਬਿਧਿ ਮਾਨਹੁ ਪਾਰਥ ਸਾਥ ਪਢਿਓ।੧੬੪੯।","roman":"Dhuni bed kee astrani sastrani kee bidhi maanhu paarath saath padhio | 1649 |","meaning_en":"","page":594}]},{"type":"verse","number":[1650],"number_text":"੧੬੫੦।","page":595,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਦੁਰਜੋਧਨ ਕੇ ਦਲ ਕੋ ਲਖਿ ਭੂਪ ਤਬੈ ਅਤਿ ਬਾਨ ਚਲਾਏ।","roman":"Sree durjodhan ke dal ko lakhi bhoop tabai ati baan chalaae |","meaning_en":"","page":595},{"gurmukhi":"ਬਾਕੇ ਕੀਏ ਬਿਰਥੀ ਤਹ ਬੀਰ ਘਨੇ ਤਬ ਹੀ ਜਮ ਧਾਮਿ ਪਠਾਏ।","roman":"Baake kee'e birthee tah beer ghane tab hee jam dhaami pathaae |","meaning_en":"","page":595},{"gurmukhi":"ਭੀਖਮ ਦ੍ਰਉਣ ਤੇ ਆਦਿਕ ਸੂਰ ਭਜੇ ਰਣ ਮੈ ਨ ਕੋਊ ਠਹਰਾਏ।","roman":"Bheekham draun te aadik soor bhaje ran mai na ko'oo thahraae |","meaning_en":"","page":595},{"gurmukhi":"ਜੀਤ ਕੀ ਆਸ ਤਜੀ ਬਹੁਰੋ ਖੜਗੇਸ ਕੇ ਸਾਮੁਹੇ ਨਾਹਿਨ ਆਏ। ੧੬੫੦।","roman":"Jeet kee aas tajee bahuro kharges ke saamuhe naahin aae | 1650 |","meaning_en":"","page":595}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":595},{"type":"verse","number":[1651],"number_text":"੧੬੫੧।","page":595,"lines":[{"gurmukhi":"ਦ੍ਰਉਣਜ ਭਾਨੁਜ ਕ੍ਰਿਪਾ ਭਜਿ ਗਏ ਨ ਬਾਧੀ ਧੀਰ।","roman":"Draunaj bhaanuj kripaa bhaji gae na baadhee dheer |","meaning_en":"","page":595},{"gurmukhi":"ਭੂਰਸ੍ਰਵਾ ਕੁਰਰਾਜ ਸਬ ਟਰੇ ਲਖੀ ਰਨ ਭੀਰ। ੧੬੫੧।","roman":"Bhoorsravaa kurraaj sab tare lakhee ran bheer | 1651 |","meaning_en":"","page":595}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":595},{"type":"verse","number":[1652],"number_text":"੧੬੫੨।","page":595,"lines":[{"gurmukhi":"ਭਾਜੇ ਸਬੈ ਲਿਖ ਕੈ ਸੁ ਜੁਧਿਸਟਰਿ ਸ੍ਰੀ ਪਤਿ ਕੇ ਤਟਿ ਐਸੇ ਉਚਾਰਿਓ।","roman":"Bhaaje sabai likh kai su judhisatri sree pati ke tati aise uchaario |","meaning_en":"","page":595},{"gurmukhi":"ਭੂਪ ਬਡੋ ਬਲਵੰਤ ਕ੍ਰਿਪਾਨਿਧਿ ਕਾਹੂੰ ਤੇ ਪੈਗ ਟਰਿਓ ਨਹੀ ਟਾਰਿਓ।","roman":"Bhoop bado balvant kripaanidhi kaahoon te paig tario nahee taario |","meaning_en":"","page":595},{"gurmukhi":"ਭਾਨੁਜ ਭੀਖਮ ਦ੍ਰਉਣ ਕ੍ਰਿਪਾ ਹਮ ਪਾਰਥ ਭੀਮ ਘਨੋ ਰਨ ਪਾਰਿਓ।","roman":"Bhaanuj bheekham draun kripaa ham paarath bheem ghano ran paario |","meaning_en":"","page":595},{"gurmukhi":"ਸੋ ਨਹਿ ਨੈਕੁ ਟਰੈ ਰਨ ਤੇ ਹਮ ਹੂੰ ਸਬ ਹੂੰ ਪ੍ਰਭ ਪਉਰਖ ਹਾਰਿਓ। ੧੬੫੨।","roman":"So nahi naiku tarai ran te ham hoon sab hoon prabh paurakh haario | 1652 |","meaning_en":"","page":595}]},{"type":"verse","number":[1653],"number_text":"੧੬੫੩।","page":595,"lines":[{"gurmukhi":"ਭੀਖਮ ਭਾਨੁਜ ਅਉ ਦੁਰਜੋਧਨ ਭੀਮ ਘਨੋ ਹਠਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Bheekham bhaanuj au durjodhan bheem ghano hathi judh machaayo |","meaning_en":"","page":595},{"gurmukhi":"ਸ੍ਰੀ ਮੁਸਲੀ ਬਰਮਾਕ੍ਰਿਤ ਸਾਤਕਿ ਕੋਪ ਘਨੋ ਚਿਤ ਮਾਝ ਬਢਾਯੋ।","roman":"Sree muslee barmaakrit saatki kop ghano chit maajh badhaayo |","meaning_en":"","page":595},{"gurmukhi":"ਹਾਰ ਰਹੇ ਰਨਧੀਰ ਸਬੈ ਅਬ ਕਾ ਪ੍ਰਭ ਜੂ ਤੁਮਰੇ ਮਨ ਆਯੋ।","roman":"Haar rahe randheer sabai ab kaa prabh joo tumre man aayo |","meaning_en":"","page":595},{"gurmukhi":"ਭਾਗਤ ਪੈਗੁ ਨ ਸੋ ਰਨ ਤੇ ਤਿਹ ਸੋ ਹਮਰੋ ਸੁ ਕਛੂ ਨ ਬਸਾਯੋ। ੧੬੫੩।","roman":"Bhaagat paigu na so ran te tih so hamro su kachhoo na basaayo | 1653 |","meaning_en":"","page":595}]},{"type":"verse","number":[1654],"number_text":"੧੬੫੪।","page":595,"lines":[{"gurmukhi":"ਰੁਦ੍ਰ ਤੇ ਆਦਿ ਜਿਤੇ ਗਨ ਦੇਵ ਤਿਤੇ ਮਿਲਿ ਕੈ ਨ੍ਰਿਪ ਊਪਰ ਧਾਏ।","roman":"Rudr te aadi jite gan dev tite mili kai nrip oopar dhaae |","meaning_en":"","page":595},{"gurmukhi":"ਤੇ ਸਬ ਆਵਤ ਦੇਖਿ ਬਲੀ ਧਨੁ ਤਾਨ ਕੈ ਬਾਨ ਹਕਾਰਿ ਲਗਾਏ।","roman":"Te sab aavat dekhi balee dhanu taan kai baan hakaari lagaae |","meaning_en":"","page":595},{"gurmukhi":"ਏਕ ਗਿਰੇ ਤਹ ਘਾਇਲ ਹ੍ਵੈ ਇਕ ਤ੍ਰਾਸ ਭਰੇ ਤਜਿ ਜੁਧ ਪਰਾਏ।","roman":"Ek gire tah ghaail hvai ik traas bhare taji judh paraae |","meaning_en":"","page":595},{"gurmukhi":"ਏਕ ਲਰੇ ਨ ਡਰੇ ਬਲਵਾਨ ਨਿਦਾਨ ਸੋਊ ਨ੍ਰਿਪ ਮਾਰਿ ਗਿਰਾਏ। ੧੬੫੪।","roman":"Ek lare na dare balvaan nidaan so'oo nrip maari giraae | 1654 |","meaning_en":"","page":595}]},{"type":"verse","number":[1655],"number_text":"੧੬੫੫।","page":595,"lines":[{"gurmukhi":"ਜੀਤਿ ਸੁਰੇਸ ਧਨੇਸ ਖਗੇਸ ਗਨੇਸ ਕੋ ਘਾਇਲ ਕੈ ਮੁਰਛਾਯੋ।","roman":"Jeeti sures dhanes khages ganes ko ghaail kai murchhaayo |","meaning_en":"","page":595},{"gurmukhi":"ਭੂਮਿ ਪਰਿਯੋ ਬਿਸੰਭਾਰਿ ਨਿਹਾਰਿ ਜਲੇਸ ਦਿਨੇਸ ਨਿਸੇਸ ਪਰਾਯੋ।","roman":"Bhoomi pariyo bisanbhaari nihaari jales dines nises paraayo |","meaning_en":"","page":595},{"gurmukhi":"ਬੀਰ ਮਹੇਸ ਤੇ ਆਦਿਕ ਭਾਜ ਗਏ ਇਹ ਸਾਮੁਹੇ ਏਕ ਨ ਆਯੋ।","roman":"Beer mahes te aadik bhaaj gae ih saamuhe ek na aayo |","meaning_en":"","page":595},{"gurmukhi":"ਕੋਪ ਕ੍ਰਿਪਾਨਿਧਿ ਆਵਤ ਜੋ ਸੁ ਚਪੇਟ ਸੋ ਮਾਰ ਕੈ ਭੂਮਿ ਗਿਰਾਯੋ। ੧੬੫੫।","roman":"Kop kripaanidhi aavat jo su chapet so maar kai bhoomi giraayo | 1655 |","meaning_en":"","page":595}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":596},{"type":"verse","number":[1656],"number_text":"੧੬੫੬।","page":596,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਸਿਉ ਹਰਿ ਏ ਕਹੀ ਬਾਤ ਧਰਮ ਕੇ ਤਾਤ।","roman":"Sree hari siu hari e kahee baat dharam ke taat |","meaning_en":"","page":596},{"gurmukhi":"ਤਿਹੀ ਸਮੈ ਸਿਵ ਜੂ ਕਹਿਯੋ ਬ੍ਰਹਮੇ ਸਿਉ ਮੁਸਕਾਤ। ੧੬੫੬।","roman":"Tihee samai siv joo kahiyo brahme siu muskaat | 1656 |","meaning_en":"","page":596}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":596},{"type":"verse","number":[1657],"number_text":"੧੬੫੭।","page":596,"lines":[{"gurmukhi":"ਆਪਨ ਸੋ ਸਬ ਹੀ ਭਟ ਜੂਝਿ ਰਹੈ ਕਰ ਕੈ ਨ ਮਰੈ ਨ੍ਰਿਪ ਮਾਰਿਓ।","roman":"Aapan so sab hee bhat joojhi rahai kar kai na marai nrip maario |","meaning_en":"","page":596},{"gurmukhi":"ਤਉ ਚਤੁਰਾਨਨ ਸਿਉ ਸਿਵ ਜੂ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਇਹ ਭਾਤਿ ਉਚਾਰਿਓ।","roman":"Tau chaturaanan siu siv joo kabi syaam kahai ih bhaati uchaario |","meaning_en":"","page":596},{"gurmukhi":"ਸਕ੍ਰ ਜਮਾਦਿਕ ਬੀਰ ਜਿਤੇ ਹਮ ਹੂੰ ਇਨ ਸੋ ਅਤਿ ਹੀ ਰਨ ਪਾਰਿਓ।","roman":"Sakr jamaadik beer jite ham hoon in so ati hee ran paario |","meaning_en":"","page":596},{"gurmukhi":"ਏ ਤੋ ਨਹੀ ਬਲ ਹਾਰਤ ਰੰਚਕ ਚਉਦਹੂੰ ਲੋਕਨਿ ਕੋ ਦਲੁ ਹਾਰਿਓ। ੧੬੫੭।","roman":"E to nahee bal haarat ranchak chaudhoon lokni ko dalu haario | 1657 |","meaning_en":"","page":596}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":596},{"type":"verse","number":[1658],"number_text":"੧੬੫੮।","page":596,"lines":[{"gurmukhi":"ਦੋਊ ਕਰਤ ਬਿਚਾਰ ਇਤ ਪੰਕਜ ਪੂਤ ਤ੍ਰਿਨੈਨ।","roman":"Do'oo karat bichaar it pankaj poot trinain |","meaning_en":"","page":596},{"gurmukhi":"ਉਤ ਰਵਿ ਅਸਤਾਚਲਿ ਗਯੋ ਸਸਿ ਪ੍ਰਗਟਿਯੋ ਭਈ ਰੈਨ। ੧੬੫੮।","roman":"Ut ravi astaachli gayo sasi pragtiyo bhaee rain | 1658 |","meaning_en":"","page":596}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":596},{"type":"verse","number":[1659],"number_text":"੧੬੫੯।","page":596,"lines":[{"gurmukhi":"ਦੋਊ ਦਲ ਅਤਿ ਹੀ ਅਕੁਲਾਨੇ। ਭੂਖ ਪਿਆਸ ਸੋ ਤਨ ਮੁਰਝਾਨੇ।","roman":"Do'oo dal ati hee akulaane | bhookh piaas so tan murjhaane |","meaning_en":"","page":596},{"gurmukhi":"ਅਰ ਤੇ ਲਰਤੇ ਹ੍ਵੈ ਗਈ ਸਾਝ। ਰਹਿ ਗਏ ਤਾ ਹੀ ਰਨ ਕੇ ਮਾਝ। ੧੬੫੯।","roman":"Ar te larte hvai gaee saajh | rahi gae taa hee ran ke maajh | 1659 |","meaning_en":"","page":596}]},{"type":"verse","number":[1660],"number_text":"੧੬੬੦।","page":596,"lines":[{"gurmukhi":"ਭੋਰ ਭਯੋ ਸਭ ਸੁਭਟ ਸੁ ਜਾਗੇ। ਦੁਹ ਦਿਸ ਮਾਰੂ ਬਾਜਨ ਲਾਗੇ।","roman":"Bhor bhayo sabh subhat su jaage | duh dis maaroo baajan laage |","meaning_en":"","page":596},{"gurmukhi":"ਸਾਜੇ ਕਵਚ ਸਸਤ੍ਰ ਕਰਿ ਧਾਰੇ। ਬਹੁਰ ਜੁਧ ਕੇ ਹੇਤ ਸਿਧਾਰੇ। ੧੬੬੦।","roman":"Saaje kavach sasatr kari dhaare | bahur judh ke het sidhaare | 1660 |","meaning_en":"","page":596}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":596},{"type":"verse","number":[1661],"number_text":"੧੬੬੧।","page":596,"lines":[{"gurmukhi":"ਸਿਵ ਕੌ ਜਮ ਕੌ ਰਵਿ ਕੌ ਸੰਗਿ ਲੈ ਬਸੁਦੇਵ ਕੋ ਨੰਦ ਚਲਿਯੋ ਰਨ ਧਾਨੀ।","roman":"Siv kau jam kau ravi kau sangi lai basudev ko nand chaliyo ran dhaanee |","meaning_en":"","page":596},{"gurmukhi":"ਮਾਰਤ ਹੋ ਅਰਿ ਕੈ ਅਰਿ ਕੋ ਹਰ ਕੋ ਹਰਿ ਭਾਖਤ ਯੌ ਮੁਖ ਬਾਨੀ।","roman":"Maarat ho ari kai ari ko har ko hari bhaakhat yau mukh baanee |","meaning_en":"","page":596},{"gurmukhi":"ਸ੍ਯਾਮ ਕੇ ਸੰਗਿ ਘਨੇ ਉਮਡੇ ਭਟ ਪਾਨਨ ਬਾਨ ਕਮਾਨਨਿ ਤਾਨੀ।","roman":"Syaam ke sangi ghane umde bhat paanan baan kamaanni taanee |","meaning_en":"","page":596},{"gurmukhi":"ਆਇ ਭਿਰੇ ਖੜਗੇਸ ਕੇ ਸੰਗਿ ਅਸੰਕ ਭਏ ਕਛੁ ਸੰਕ ਨ ਮਾਨੀ। ੧੬੬੧।","roman":"Aai bhire kharges ke sangi asank bhae kachhu sank na maanee | 1661 |","meaning_en":"","page":596}]},{"type":"verse","number":[1662],"number_text":"੧੬੬੨।","page":596,"lines":[{"gurmukhi":"ਗਿਆਰਹ ਘਾਇਲ ਕੈ ਸਿਵ ਕੇ ਗਨ ਦ੍ਵਾਦਸ ਸੂਰਨਿ ਕੇ ਰਥ ਕਾਟੇ।","roman":"Giaarah ghaail kai siv ke gan dvaadas soorni ke rath kaate |","meaning_en":"","page":596},{"gurmukhi":"ਘਾਇ ਕੀਯੋ ਜਮ ਕੋ ਬਿਰਥੀ ਬਸੁ ਆਠਨ ਕਉ ਲਲਕਾਰ ਕੇ ਡਾਟੈ।","roman":"Ghaai keeyo jam ko birthee basu aathan kau lalkaar ke daatai |","meaning_en":"","page":596},{"gurmukhi":"ਸਤ੍ਰ ਬਿਮੁੰਡਤ ਕੀਨੇ ਘਨੇ ਜੁ ਰਹੇ ਰਨ ਤੇ ਤਿਨ ਕੇ ਪਗ ਹਾਟੇ।","roman":"Satr bimundat keene ghane ju rahe ran te tin ke pag haate |","meaning_en":"","page":596},{"gurmukhi":"ਪਉਣ ਸਮਾਨ ਛੁਟੇ ਨ੍ਰਿਪ ਬਾਨ ਸਬੈ ਦਲ ਬਾਦਲ ਜਿਉ ਚਲਿ ਫਾਟੇ। ੧੬੬੨।","roman":"Paun samaan chhute nrip baan sabai dal baadal jiu chali phaate | 1662 |","meaning_en":"","page":596}]},{"type":"verse","number":[1663],"number_text":"੧੬੬੩।","page":597,"lines":[{"gurmukhi":"ਭਾਜ ਗਏ ਰਨ ਤੇ ਡਰ ਕੈ ਭਟ ਤਉ ਸਿਵ ਏਕ ਉਪਾਇ ਬਿਚਾਰਿਓ।","roman":"Bhaaj gae ran te dar kai bhat tau siv ek upaai bichaario |","meaning_en":"","page":597},{"gurmukhi":"ਮਾਟੀ ਕੋ ਮਾਨਸ ਏਕ ਕੀਯੋ ਤਿਹ ਪ੍ਰਾਨ ਪਰੇ ਜਬ ਸ੍ਯਾਮ ਨਿਹਾਰਿਓ।","roman":"Maatee ko maanas ek keeyo tih praan pare jab syaam nihaario |","meaning_en":"","page":597},{"gurmukhi":"ਸਿੰਘ ਅਜੀਤ ਧਰਿਓ ਤਿਹ ਨਾਮੁ ਦੀਓ ਬਰ ਰੁਦ੍ਰ ਮਰੈ ਨਹੀ ਮਾਰਿਓ।","roman":"Singh ajeet dhario tih naamu deeo bar rudr marai nahee maario |","meaning_en":"","page":597},{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਸੋਊ ਕਰ ਮੈ ਖੜਗੇਸ ਕੇ ਮਾਰਨ ਹੇਤ ਸਿਧਾਰਓ। ੧੬੬੩।","roman":"Sasatr sanbhaari so'oo kar mai kharges ke maaran het sidhaarao | 1663 |","meaning_en":"","page":597}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":597},{"type":"verse","number":[1664],"number_text":"੧੬੬੪।","page":597,"lines":[{"gurmukhi":"ਅਤਿ ਪ੍ਰਚੰਡ ਬਲਵੰਡ ਬਹੁਰ ਮਿਲ ਕੈ ਭਟ ਧਾਏ।","roman":"Ati prachand balvand bahur mil kai bhat dhaae |","meaning_en":"","page":597},{"gurmukhi":"ਅਪਨੇ ਸਸਤ੍ਰ ਸੰਭਾਰਿ ਲੀਏ ਕਰਿ ਸੰਖ ਬਜਾਏ।","roman":"Apne sasatr sanbhaari lee'e kari sankh bajaae |","meaning_en":"","page":597},{"gurmukhi":"ਦ੍ਵਾਦਸ ਭਾਨਨ ਤਾਨਿ ਕਮਾਨਨਿ ਬਾਨ ਚਲਾਏ।","roman":"Dvaadas bhaanan taani kamaanni baan chalaae |","meaning_en":"","page":597},{"gurmukhi":"ਯੌ ਬਰਖੈ ਸਰ ਜਾਲ ਮਨੋ ਪਰਲੇ ਘਨ ਆਏ। ੧੬੬੪।","roman":"Yau barkhai sar jaal mano parle ghan aae | 1664 |","meaning_en":"","page":597}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":597},{"type":"verse","number":[1665],"number_text":"੧੬੬੫।","page":597,"lines":[{"gurmukhi":"ਬਾਨਨ ਸੋ ਬਾਨਨ ਕਟੇ ਕੋਪ ਤਚੇ ਜੁਗ ਨੈਨ।","roman":"Baanan so baanan kate kop tache jug nain |","meaning_en":"","page":597},{"gurmukhi":"ਸ੍ਰੀ ਹਰਿ ਸੋ ਖੜਗੇਸ ਤਬ ਰਿਸ ਕਰਿ ਬੋਲਿਯੋ ਬੈਨ। ੧੬੬੫।","roman":"Sree hari so kharges tab ris kari boliyo bain | 1665 |","meaning_en":"","page":597}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":597},{"type":"verse","number":[1666],"number_text":"੧੬੬੬।","page":597,"lines":[{"gurmukhi":"ਕਿਉ ਰੇ ਗੁਮਾਨ ਕਰੈ ਘਨ ਸ੍ਯਾਮ ਅਬੇ ਰਨ ਤੇ ਪੁਨਿ ਤੋਹਿ ਭਜੈ ਹੋ।","roman":"Kiu re gumaan karai ghan syaam abe ran te puni tohi bhajai ho |","meaning_en":"","page":597},{"gurmukhi":"ਕਾਹੇ ਕੌ ਆਨਿ ਅਰਿਯੋ ਸੁਨ ਰੇ ਸਿਰ ਕੇਸਨਿ ਤੇ ਬਹੁਰੋ ਗਹਿ ਲੈਹੋ।","roman":"Kaahe kau aani ariyo sun re sir kesni te bahuro gahi laiho |","meaning_en":"","page":597},{"gurmukhi":"ਐ ਰੇ ਅਹੀਰ ਅਧੀਰ ਡਰੇ ਨਹਿ ਤੋ ਕਹਿ ਜੀਵਤ ਜਾਨ ਨ ਦੈਹੋ।","roman":"Ai re aheer adheer dare nahi to kahi jeevat jaan na daiho |","meaning_en":"","page":597},{"gurmukhi":"ਇੰਦ੍ਰ ਬਿਰੰਚ ਕੁਬੇਰ ਜਲਾਧਿਪ ਕੋ ਸਸਿ ਕੋ ਸਿਵ ਕੋ ਹਤ ਕੈ ਹੋ। ੧੬੬੬।","roman":"Indr biranch kuber jalaadhip ko sasi ko siv ko hat kai ho | 1666 |","meaning_en":"","page":597}]},{"type":"verse","number":[1667],"number_text":"੧੬੬੭।","page":597,"lines":[{"gurmukhi":"ਤਉ ਹੀ ਲਉ ਬੀਰ ਮਹੋਤ ਕਟ ਸਿੰਘ ਹੁਤੋ ਰਨ ਮੈ ਮਨਿ ਕੋਪ ਭਰਿਓ।","roman":"Tau hee lau beer mahot kat singh huto ran mai mani kop bhario |","meaning_en":"","page":597},{"gurmukhi":"ਕਰ ਮੈ ਕਰਵਾਰਿ ਲੈ ਧਾਇ ਚਲਿਓ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਨਹੀ ਨੈਕੁ ਡਰਿਓ।","roman":"Kar mai karvaari lai dhaai chalio kabi syaam kahai nahee naiku dario |","meaning_en":"","page":597},{"gurmukhi":"ਅਸਿ ਜੁਧ ਦੁਹੁੰ ਨ੍ਰਿਪ ਕੀਨ ਬਡੋ ਨ ਕੋਊ ਰਨ ਤੇ ਪਗ ਏਕ ਟਰਿਓ।","roman":"Asi judh duhun nrip keen bado na ko'oo ran te pag ek tario |","meaning_en":"","page":597},{"gurmukhi":"ਖੜਗੇਸ ਕ੍ਰਿਪਾਨ ਕੀ ਤਾਨਿ ਦਈ ਬਿਨੁ ਪ੍ਰਾਨ ਕਰਿਓ ਗਿਰ ਭੂਮਿ ਪਰਿਓ। ੧੬੬੭।","roman":"Kharges kripaan kee taani daee binu praan kario gir bhoomi pario | 1667 |","meaning_en":"","page":597}]},{"type":"verse","number":[1668],"number_text":"੧੬੬੮।","page":597,"lines":[{"gurmukhi":"ਦੇਖਿ ਦਸਾ ਤਿਹ ਸਿੰਘ ਬਚਿਤ੍ਰ ਸੁ ਠਾਢੋ ਹੁਤੋ ਰਿਸ ਕੈ ਵਹ ਧਾਯੋ।","roman":"Dekhi dasaa tih singh bachitr su thaadho huto ris kai vah dhaayo |","meaning_en":"","page":597},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਧਨੁ ਬਾਨਨ ਲੈ ਤਿਹ ਭੂਪਤਿ ਸਿਉ ਅਤਿ ਜੁਧ ਮਚਾਯੋ।","roman":"Syaam bhanai dhanu baanan lai tih bhoopti siu ati judh machaayo |","meaning_en":"","page":597},{"gurmukhi":"ਸ੍ਰੀ ਖੜਗੇਸ ਬਲੀ ਧਨ ਤਾਨਿ ਮਹਾ ਬਰ ਬਾਨ ਪ੍ਰਕੋਪ ਚਲਾਯੋ।","roman":"Sree kharges balee dhan taani mahaa bar baan prakop chalaayo |","meaning_en":"","page":597},{"gurmukhi":"ਲਾਗਿ ਗਯੋ ਤਿਹ ਕੇ ਉਰ ਮੈ ਸਰ ਘੂਮਿ ਗਿਰਿਓ ਧਰਿ ਇਉ ਅਰਿ ਘਾਯੋ। ੧੬੬੮।","roman":"Laagi gayo tih ke ur mai sar ghoomi girio dhari iu ari ghaayo | 1668 |","meaning_en":"","page":597}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":597},{"type":"verse","number":[1669],"number_text":"੧੬੬੯।","page":597,"lines":[{"gurmukhi":"ਤਬ ਅਜੀਤ ਸਿੰਘ ਆਪ ਹੀ ਧਾਯੋ। ਧਨੁਖ ਬਾਨ ਲੈ ਰਨ ਮਧਿ ਆਯੋ।","roman":"Tab ajeet singh aap hee dhaayo | dhanukh baan lai ran madhi aayo |","meaning_en":"","page":597},{"gurmukhi":"ਭੂਪਤਿ ਕੋ ਤਿਨ ਬਚਨ ਸੁਨਾਯੋ। ਤੋ ਬਧ ਹਿਤ ਸਿਵ ਮੁਹਿ ਉਪਜਾਯੋ। ੧੬੬੯।","roman":"Bhoopti ko tin bachan sunaayo | to badh hit siv muhi upjaayo | 1669 |","meaning_en":"","page":597}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":598},{"type":"verse","number":[1670],"number_text":"੧੬੭੦।","page":598,"lines":[{"gurmukhi":"ਅਜੀਤ ਸਿੰਘ ਯੌ ਬਚਨ ਉਚਾਰਿਓ। ਖੜਗ ਸਿੰਘ ਰਨ ਮਾਹਿ ਹਕਾਰਿਓ।","roman":"Ajeet singh yau bachan uchaario | kharag singh ran maahi hakaario |","meaning_en":"","page":598},{"gurmukhi":"ਨ੍ਰਿਪ ਏ ਬੈਨ ਸੁਨਤ ਨਹੀ ਡਰਿਓ। ਮਹਾਬੀਰ ਪਗੁ ਆਗੈ ਧਰਿਓ। ੧੬੭੦।","roman":"Nrip e bain sunat nahee dario | mahaabeer pagu aagai dhario | 1670 |","meaning_en":"","page":598}]},{"type":"verse","number":[1671],"number_text":"੧੬੭੧।","page":598,"lines":[{"gurmukhi":"ਅਜੀਤ ਸਿੰਘ ਰਛਾ ਹਿਤ ਧਾਏ। ਗ੍ਯਾਰਹ ਰੁਦ੍ਰ ਭਾਨ ਸਭ ਆਏ।","roman":"Ajeet singh rachhaa hit dhaae | gyaarah rudr bhaan sabh aae |","meaning_en":"","page":598},{"gurmukhi":"ਇੰਦ੍ਰ ਕ੍ਰਿਸਨ ਜਮ ਬਸੁ ਰਿਸ ਭਰੇ। ਬਰੁਨ ਕੁਬੇਰ ਘੇਰਿ ਸਭ ਖਰੇ। ੧੬੭੧।","roman":"Indr krisan jam basu ris bhare | barun kuber gheri sabh khare | 1671 |","meaning_en":"","page":598}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":598},{"type":"verse","number":[1672],"number_text":"੧੬੭੨।","page":598,"lines":[{"gurmukhi":"ਸਿੰਘ ਅਜੀਤ ਜਬੈ ਖੜਗੇਸ ਸੋ ਸ੍ਯਾਮ ਕਹੈ ਅਤਿ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Singh ajeet jabai kharges so syaam kahai ati judhu machaayo |","meaning_en":"","page":598},{"gurmukhi":"ਸੰਗਿ ਸਿਵਾਦਿਕ ਸੂਰਜਿ ਤੇ ਅਰਿ ਮਾਰਨ ਕੋ ਤਿਹ ਹਾਥ ਉਚਾਯੋ।","roman":"Sangi sivaadik soorji te ari maaran ko tih haath uchaayo |","meaning_en":"","page":598},{"gurmukhi":"ਬਾਨ ਚਲੇ ਅਤਿ ਹੀ ਰਨ ਮੈ ਨ੍ਰਿਪ ਕਾਟਿ ਸਬੈ ਮਨਿ ਰੋਸਿ ਤਚਾਯੋ।","roman":"Baan chale ati hee ran mai nrip kaati sabai mani rosi tachaayo |","meaning_en":"","page":598},{"gurmukhi":"ਲੈ ਧਨੁ ਬਾਨ ਮਹਾ ਬਲਵਾਨ ਹਨ੍ਯੋ ਭਟ ਕੋ ਕਿਨਹੂੰ ਨ ਬਚਾਯੋ। ੧੬੭੨।","roman":"Lai dhanu baan mahaa balvaan hanyo bhat ko kinhoon na bachaayo | 1672 |","meaning_en":"","page":598}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":598},{"type":"verse","number":[1673],"number_text":"੧੬੭੩।","page":598,"lines":[{"gurmukhi":"ਜਬ ਅਜੀਤ ਸਿੰਘ ਮਾਰਿ ਗਿਰਾਯੋ। ਸੁ ਭਟਨ ਮਨ ਭਟਕਿਓ ਡਰ ਪਾਯੋ।","roman":"Jab ajeet singh maari giraayo | su bhatan man bhatkio dar paayo |","meaning_en":"","page":598},{"gurmukhi":"ਬਹੁਰੋ ਭੂਪਤਿ ਖੜਗ ਸੰਭਾਰਿਓ। ਚਕ੍ਰਤ ਤੇ ਸਬਹੂੰ ਬਲੁ ਹਾਰਿਓ। ੧੬੭੩।","roman":"Bahuro bhoopti kharag sanbhaario | chakrat te sabhoon balu haario | 1673 |","meaning_en":"","page":598}]},{"type":"verse","number":[1674],"number_text":"੧੬੭੪।","page":598,"lines":[{"gurmukhi":"ਤਬ ਹਰਿ ਹਰਿ ਬਿਧਿ ਮੰਤ੍ਰ ਬਿਚਾਰਿਓ। ਮਰੈ ਨ ਜਰੈ ਅਗਨ ਤੇ ਜਾਰਿਓ।","roman":"Tab hari hari bidhi mantr bichaario | marai na jarai agan te jaario |","meaning_en":"","page":598},{"gurmukhi":"ਤਾ ਤੇ ਜਤਨ ਕਛੂ ਅਬ ਕੀਜੈ। ਯਾ ਤੇ ਮਾਰਿ ਭੂਪ ਇਹ ਲੀਜੈ। ੧੬੭੪।","roman":"Taa te jatan kachhoo ab keejai | yaa te maari bhoop ih leejai | 1674 |","meaning_en":"","page":598}]},{"type":"verse","number":[1675],"number_text":"੧੬੭੫।","page":598,"lines":[{"gurmukhi":"ਬ੍ਰਹਮੇ ਕਹਿਓ ਸੁ ਇਹ ਬਿਧਿ ਕੀਜੈ। ਮੋਹਿਤ ਹ੍ਵੈ ਮਨ ਤਬ ਬਲੁ ਛੀਜੈ।","roman":"Brahme kahio su ih bidhi keejai | mohit hvai man tab balu chheejai |","meaning_en":"","page":598},{"gurmukhi":"ਜਬ ਇਹ ਭੂਪ ਗਿਰਿਓ ਲਖਿ ਲਈਯੈ। ਤਬ ਇਹ ਜਮ ਕੋ ਧਾਮ ਪਠਈਯੈ। ੧੬੭੫।","roman":"Jab ih bhoop girio lakhi laeeyai | tab ih jam ko dhaam pathaeeyai | 1675 |","meaning_en":"","page":598}]},{"type":"verse","number":[1676],"number_text":"੧੬੭੬।","page":598,"lines":[{"gurmukhi":"ਪੁਨਿ ਅਪਛ੍ਰਨ ਆਇਸ ਦੀਜੈ। ਜਾ ਸੋ ਨ੍ਰਿਪ ਰੀਝੈ ਸੋਈ ਕੀਜੈ।","roman":"Puni apchhran aais deejai | jaa so nrip reejhai soee keejai |","meaning_en":"","page":598},{"gurmukhi":"ਕਉਤਕਿ ਹੇਰਿ ਭੂਪ ਜਬ ਲੈ ਹੈ। ਘਟਿ ਜੈ ਹੈ ਬਲ ਮਨ ਦ੍ਰਵਿ ਜੈ ਹੈ। ੧੬੭੬।","roman":"Kautki heri bhoop jab lai hai | ghati jai hai bal man dravi jai hai | 1676 |","meaning_en":"","page":598}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":598},{"type":"verse","number":[1677],"number_text":"੧੬੭੭।","page":598,"lines":[{"gurmukhi":"ਕਮਲਜ ਯੌ ਹਰਿ ਸਿਉ ਕਹਿਯੋ ਸੁਨੀ ਬਾਤ ਸੁਰਰਾਜ।","roman":"Kamlaj yau hari siu kahiyo sunee baat surraaj |","meaning_en":"","page":598},{"gurmukhi":"ਨਭਿ ਨਿਹਾਰ ਬਾਸਵ ਕਹਿਯੋ ਕਰਹੁ ਨ੍ਰਿਤ ਸੁਰਰਾਜ। ੧੬੭੭।","roman":"Nabhi nihaar baasav kahiyo karhu nrit surraaj | 1677 |","meaning_en":"","page":598}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":598},{"type":"verse","number":[1678],"number_text":"੧੬੭੮।","page":598,"lines":[{"gurmukhi":"ਉਤ ਦੇਵਬਧੂ ਮਿਲਿ ਨ੍ਰਿਤ ਕਰੈ ਇਤ ਸੂਰ ਸਬੈ ਮਿਲ ਜੁਧੁ ਮਚਾਯੋ।","roman":"Ut devabdhoo mili nrit karai it soor sabai mil judhu machaayo |","meaning_en":"","page":598},{"gurmukhi":"ਕਿੰਨਰ ਗੰਧ੍ਰਬ ਗਾਵਤ ਹੈ ਉਤ ਮਾਰੂ ਬਜੈ ਰਨ ਮੰਗਲ ਗਾਯੋ।","roman":"Kinnar gandhrab gaavat hai ut maaroo bajai ran mangal gaayo |","meaning_en":"","page":598},{"gurmukhi":"ਕਉਤੁਕ ਦੇਖਿ ਬਡੋ ਤਿਨ ਕੋ ਇਹ ਭੂਪਤਿ ਕੋ ਮਨ ਤਉ ਬਿਰਮਾਯੋ।","roman":"Kautuk dekhi bado tin ko ih bhoopti ko man tau birmaayo |","meaning_en":"","page":599},{"gurmukhi":"ਕਾਨ੍ਹ ਅਚਾਨ ਲਯੋ ਧਨੁ ਤਾਨਿ ਸੁ ਬਾਨ ਮਹਾ ਨ੍ਰਿਪ ਕੇ ਤਨਿ ਲਾਯੋ। ੧੬੭੮।","roman":"Kaanh achaan layo dhanu taani su baan mahaa nrip ke tani laayo | 1678 |","meaning_en":"","page":599}]},{"type":"verse","number":[1679],"number_text":"੧੬੭੯।","page":599,"lines":[{"gurmukhi":"ਲਾਗਤ ਹੀ ਸਰ ਮੋਹਿਤ ਭਯੋ ਤੇਊ ਤੀਰਨ ਸੋ ਬਰ ਬੀਰ ਸੰਘਾਰੇ।","roman":"Laagat hee sar mohit bhayo teoo teeran so bar beer sanghaare |","meaning_en":"","page":599},{"gurmukhi":"ਗਿਆਰਹ ਰੁਦ੍ਰਨਿ ਕੇ ਅਗਨੰ ਗਨ ਮਾਰਿ ਲਏ ਹਰਿ ਲੋਕਿ ਸਿਧਾਰੇ।","roman":"Giaarah rudrani ke agnan gan maari lae hari loki sidhaare |","meaning_en":"","page":599},{"gurmukhi":"ਦ੍ਵਾਦਸ ਭਾਨ ਜਲਾਧਿਪ ਅਉ ਸਸਿ ਇੰਦ੍ਰ ਕੁਬੇਰ ਕੇ ਅੰਗ ਪ੍ਰਹਾਰੇ।","roman":"Dvaadas bhaan jalaadhip au sasi indr kuber ke ang prahaare |","meaning_en":"","page":599},{"gurmukhi":"ਅਉਰ ਜਿਤੇ ਭਟ ਠਾਢੇ ਰਹੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਬਿਪਤੇ ਕਰਿ ਡਾਰੇ। ੧੬੭੯।","roman":"Aur jite bhat thaadhe rahe kabi syaam kahai bipte kari daare | 1679 |","meaning_en":"","page":599}]},{"type":"verse","number":[1680],"number_text":"੧੬੮੦।","page":599,"lines":[{"gurmukhi":"ਸਕ੍ਰ ਕੋ ਸਾਠ ਲਗਾਵਤ ਭਯੋ ਸਰ ਦ੍ਵੈ ਸਤਿ ਕਾਨ੍ਹ ਕੇ ਗਾਤ ਲਗਾਏ।","roman":"Sakr ko saath lagaavat bhayo sar dvai sati kaanh ke gaat lagaae |","meaning_en":"","page":599},{"gurmukhi":"ਚਉਸਠਿ ਬਾਨ ਹਨੇ ਜਮ ਕੋ ਰਵਿ ਦ੍ਵਾਦਸ ਦ੍ਵਾਦਸ ਕੇ ਸੰਗ ਘਾਏ।","roman":"Chausthi baan hane jam ko ravi dvaadas dvaadas ke sang ghaae |","meaning_en":"","page":599},{"gurmukhi":"ਸੋਮ ਕੋ ਸਉ ਸਤ ਰੁਦ੍ਰ ਕੋ ਚਾਰ ਲਗਾਵਤ ਭਯੋ ਕਬਿ ਸ੍ਯਾਮ ਸੁਨਾਏ।","roman":"Som ko sau sat rudr ko chaar lagaavat bhayo kabi syaam sunaae |","meaning_en":"","page":599},{"gurmukhi":"ਸ੍ਰੌਨ ਭਰੇ ਸਬ ਕੇ ਪਟ ਮਾਨਹੁ ਚਾਚਰ ਖੇਲਿ ਅਬੈ ਭਟ ਆਏ। ੧੬੮੦।","roman":"Sraun bhare sab ke pat maanhu chaachar kheli abai bhat aae | 1680 |","meaning_en":"","page":599}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":599},{"type":"verse","number":[1681],"number_text":"੧੬੮੧।","page":599,"lines":[{"gurmukhi":"ਅਉਰ ਸੁਭਟ ਬਹੁਤੇ ਤਿਹ ਮਾਰੇ। ਜੂਝ ਪਰੇ ਜਮ ਧਾਮਿ ਸਿਧਾਰੇ।","roman":"Aur subhat bahute tih maare | joojh pare jam dhaami sidhaare |","meaning_en":"","page":599},{"gurmukhi":"ਤਬ ਨ੍ਰਿਪ ਪੈ ਬ੍ਰਹਮਾ ਚਲ ਆਯੋ। ਸ੍ਯਾਮ ਭਨੈ ਯਹ ਬੈਨ ਸੁਨਾਯੋ। ੧੬੮੧।","roman":"Tab nrip pai brahmaa chal aayo | syaam bhanai yah bain sunaayo | 1681 |","meaning_en":"","page":599}]},{"type":"verse","number":[1682],"number_text":"੧੬੮੨।","page":599,"lines":[{"gurmukhi":"ਕਹਿਓ ਸੁ ਕਿਉ ਇਨ ਕਉ ਰਨਿ ਮਾਰੈ। ਬ੍ਰਿਥਾ ਕੋਪ ਕੈ ਕਿਉ ਸਰ ਡਾਰੈ।","roman":"Kahio su kiu in kau rani maarai | brithaa kop kai kiu sar daarai |","meaning_en":"","page":599},{"gurmukhi":"ਤਾ ਤੇ ਇਹੈ ਕਾਜ ਅਬ ਕੀਜੈ। ਦੇਹ ਸਹਿਤ ਨਭਿ ਮਾਰਗ ਲੀਜੈ। ੧੬੮੨।","roman":"Taa te ihai kaaj ab keejai | deh sahit nabhi maarag leejai | 1682 |","meaning_en":"","page":599}]},{"type":"verse","number":[1683],"number_text":"੧੬੮੩।","page":599,"lines":[{"gurmukhi":"ਜੁਧ ਕਥਾ ਨਹੀ ਰਿਦੈ ਚਿਤਾਰੋ। ਅਪਨੋ ਅਗਲੋ ਕਾਜ ਸਵਾਰੋ।","roman":"Judh kathaa nahee ridai chitaaro | apno aglo kaaj savaaro |","meaning_en":"","page":599},{"gurmukhi":"ਤਾ ਤੇ ਅਬਿ ਬਿਲੰਬ ਨਹੀ ਕੀਜੈ। ਮੇਰੋ ਕਹਿਯੋ ਮਾਨ ਕੈ ਲੀਜੈ। ੧੬੮੩।","roman":"Taa te abi bilanb nahee keejai | mero kahiyo maan kai leejai | 1683 |","meaning_en":"","page":599}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":599},{"type":"verse","number":[1684],"number_text":"੧੬੮੪।","page":599,"lines":[{"gurmukhi":"ਇੰਦ੍ਰ ਕੇ ਧਾਮ ਚਲੋ ਬਲਵਾਨ ਸੁਜਾਨ ਸੁਨੋ ਅਬ ਢੀਲ ਨ ਕੀਜੈ।","roman":"Indr ke dhaam chalo balvaan sujaan suno ab dheel na keejai |","meaning_en":"","page":599},{"gurmukhi":"ਦੇਵਬਧੂ ਜੋਊ ਚਾਹਤ ਹੈ ਤਿਨ ਕੋ ਮਿਲੀਐ ਮਿਲ ਕੈ ਸੁਖ ਲੀਜੈ।","roman":"Devabdhoo jo'oo chaahat hai tin ko mileeai mil kai sukh leejai |","meaning_en":"","page":599},{"gurmukhi":"ਤੇਰੋ ਮਨੋਰਥ ਪੂਰਨ ਹੋਤ ਹੈ ਮਾਨ ਕਹਿਓ ਨ੍ਰਿਪ ਅੰਮ੍ਰਿਤ ਪੀਜੈ।","roman":"Tero manorath pooran hot hai maan kahio nrip anmrit peejai |","meaning_en":"","page":599},{"gurmukhi":"ਰਾਜਨ ਰਾਜ ਸਮਾਜ ਤਜੋ ਇਨ ਬੀਰਨ ਕੋ ਨ ਬ੍ਰਿਥਾ ਦੁਖੁ ਦੀਜੈ। ੧੬੮੪।","roman":"Raajan raaj samaaj tajo in beeran ko na brithaa dukhu deejai | 1684 |","meaning_en":"","page":599}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":599},{"type":"verse","number":[1685],"number_text":"੧੬੮੫।","page":599,"lines":[{"gurmukhi":"ਯੌ ਸੁਨਿ ਬਤੀਆ ਬ੍ਰਹਮ ਕੀ ਭੂਪ ਸਤ੍ਰ ਦੁਖ ਦੈਨ।","roman":"Yau suni bateeaa braham kee bhoop satr dukh dain |","meaning_en":"","page":599},{"gurmukhi":"ਅਤਿ ਚਿਤਿ ਹਰਖ ਬਢਾਇ ਕੈ ਬੋਲਿਓ ਬਿਧਿ ਸੋ ਬੈਨ। ੧੬੮੫।","roman":"Ati chiti harakh badhaai kai bolio bidhi so bain | 1685 |","meaning_en":"","page":599}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":599},{"type":"verse","number":[1686],"number_text":"੧੬੮੬।","page":599,"lines":[{"gurmukhi":"ਯੌ ਬ੍ਰਹਮਾ ਸੋ ਬੈਨ ਸੁਨਾਯੋ। ਤੋ ਸਿਉ ਕਹੋ ਜੁ ਮਨ ਮੈ ਆਯੋ।","roman":"Yau brahmaa so bain sunaayo | to siu kaho ju man mai aayo |","meaning_en":"","page":599},{"gurmukhi":"ਮੋ ਸੋ ਬੀਰ ਸਸਤ੍ਰ ਜਬ ਧਰੈ। ਕਹੋ ਬਿਸਨ ਬਿਨ ਕਾਸੋ ਲਰੈ। ੧੬੮੬।","roman":"Mo so beer sasatr jab dharai | kaho bisan bin kaaso larai | 1686 |","meaning_en":"","page":599}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":600},{"type":"verse","number":[1687],"number_text":"੧੬੮੭।","page":600,"lines":[{"gurmukhi":"ਤੁਮ ਸਬ ਜਾਨਤ ਬਿਸ੍ਵ ਕਰ ਖੜਗ ਸਿੰਘ ਮੋਹਿ ਨਾਉ।","roman":"Tum sab jaanat bisv kar kharag singh mohi naau |","meaning_en":"","page":600},{"gurmukhi":"ਲਾਜ ਆਪਨੇ ਨਾਉ ਕੀ ਕਹੋ ਕਹਾ ਭਜਿ ਜਾਉ। ੧੬੮੭।","roman":"Laaj aapne naau kee kaho kahaa bhaji jaau | 1687 |","meaning_en":"","page":600}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":600},{"type":"verse","number":[1688],"number_text":"੧੬੮੮।","page":600,"lines":[{"gurmukhi":"ਚਤੁਰਾਨਨ ਮੋ ਬਤੀਆ ਸੁਨਿ ਲੈ ਚਿਤ ਦੈ ਦੁਹ ਸ੍ਰਉਨਨ ਮੈ ਧਰੀਐ।","roman":"Chaturaanan mo bateeaa suni lai chit dai duh sraunan mai dhareeai |","meaning_en":"","page":600},{"gurmukhi":"ਉਪਮਾ ਕੋ ਜਬੈ ਉਮਗੈ ਮਨ ਤਉ ਉਪਮਾ ਭਗਵਾਨ ਹੀ ਕੀ ਕਰੀਐ।","roman":"Upmaa ko jabai umgai man tau upmaa bhagvaan hee kee kareeai |","meaning_en":"","page":600},{"gurmukhi":"ਪਰੀਐ ਨਹੀ ਆਨ ਕੇ ਪਾਇਨ ਪੈ ਹਰਿ ਕੇ ਗੁਰ ਕੇ ਦਿਜ ਕੈ ਪਰੀਐ।","roman":"Pareeai nahee aan ke paain pai hari ke gur ke dij kai pareeai |","meaning_en":"","page":600},{"gurmukhi":"ਜਿਹ ਕੋ ਜੁਗ ਚਾਰ ਮੈ ਨਾਉ ਜਪੈ ਤਿਹ ਸੋ ਲਰਿ ਕੈ ਮਰੀਐ ਤਰੀਐ। ੧੬੮੮।","roman":"Jih ko jug chaar mai naau japai tih so lari kai mareeai tareeai | 1688 |","meaning_en":"","page":600}]},{"type":"verse","number":[1689],"number_text":"੧੬੮੯।","page":600,"lines":[{"gurmukhi":"ਜਾ ਸਨਕਾਦਿਕ ਸੇਸ ਤੇ ਆਦਿਕ ਖੋਜਤ ਹੈ ਕਛੁ ਅੰਤ ਨ ਪਾਯੋ।","roman":"Jaa sankaadik ses te aadik khojat hai kachhu ant na paayo |","meaning_en":"","page":600},{"gurmukhi":"ਚਉਦਹ ਲੋਕਨ ਬੀਚ ਸਦਾ ਸੁਕ ਬ੍ਯਾਸ ਮਹਾ ਕਬਿ ਸ੍ਯਾਮ ਸੁ ਗਾਯੋ।","roman":"Chaudah lokan beech sadaa suk byaas mahaa kabi syaam su gaayo |","meaning_en":"","page":600},{"gurmukhi":"ਜਾਹੀ ਕੇ ਨਾਮ ਪ੍ਰਤਾਪ ਹੂੰ ਤੇ ਧੂਅ ਸੋ ਪ੍ਰਹਲਾਦ ਅਛੈ ਪਦ ਪਾਯੋ।","roman":"Jaahee ke naam prataap hoon te dhooa so prahlaad achhai pad paayo |","meaning_en":"","page":600},{"gurmukhi":"ਸੋ ਅਬ ਮੋ ਸੰਗ ਜੁਧੁ ਕਰੈ ਜਿਹ ਸ੍ਰੀਧਰ ਸ੍ਰੀ ਹਰਿ ਨਾਮ ਕਹਾਯੋ। ੧੬੮੯।","roman":"So ab mo sang judhu karai jih sreedhar sree hari naam kahaayo | 1689 |","meaning_en":"","page":600}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":600},{"type":"verse","number":[1690],"number_text":"੧੬੯੦।","page":600,"lines":[{"gurmukhi":"ਚਤੁਰਾਨਨ ਏ ਬਚਨ ਸੁਨਤ ਚਕ੍ਰਿਤ ਭਯੋ।","roman":"Chaturaanan e bachan sunat chakrit bhayo |","meaning_en":"","page":600},{"gurmukhi":"ਬਿਸਨ ਭਗਤ ਕੋ ਤਬੈ ਭੂਪ ਚਿਤ ਮੈ ਲਯੋ।","roman":"Bisan bhagat ko tabai bhoop chit mai layo |","meaning_en":"","page":600},{"gurmukhi":"ਸਾਧ ਸਾਧ ਕਰਿ ਬੋਲਿਓ ਬਦਨ ਨਿਹਾਰ ਕੈ।","roman":"Saadh saadh kari bolio badan nihaar kai |","meaning_en":"","page":600},{"gurmukhi":"ਹੋ ਮੋਨ ਰਹਿਯੋ ਗਹਿ ਕਮਲਜ ਪ੍ਰੇਮ ਬਿਚਾਰ ਕੈ। ੧੬੯੦।","roman":"Ho mon rahiyo gahi kamlaj prem bichaar kai | 1690 |","meaning_en":"","page":600}]},{"type":"verse","number":[1691],"number_text":"੧੬੯੧।","page":600,"lines":[{"gurmukhi":"ਬਹੁਰਿ ਬਿਧਾਤਾ ਭੂਪਤਿ ਕੋ ਇਹ ਬਿਧਿ ਕਹਿਯੋ।","roman":"Bahuri bidhaataa bhoopti ko ih bidhi kahiyo |","meaning_en":"","page":600},{"gurmukhi":"ਭਗਤਿ ਗ੍ਯਾਨ ਕੋ ਤਤੁ ਭਲੀ ਬਿਧਿ ਤੈ ਲਹਿਯੋ।","roman":"Bhagti gyaan ko tatu bhalee bidhi tai lahiyo |","meaning_en":"","page":600},{"gurmukhi":"ਤਾ ਤੇ ਅਬ ਤਨ ਸਾਥਹਿ ਸੁਰਗਿ ਸਿਧਾਰੀਐ।","roman":"Taa te ab tan saathhi surgi sidhaareeai |","meaning_en":"","page":600},{"gurmukhi":"ਹੋ ਮੁਕਤ ਓਰ ਕਰਿ ਦ੍ਰਿਸਟਿ ਨ ਜੁਧ ਨਿਹਾਰੀਐ। ੧੬੯੧।","roman":"Ho mukat or kari dristi na judh nihaareeai | 1691 |","meaning_en":"","page":600}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":600},{"type":"verse","number":[1692],"number_text":"੧੬੯੨।","page":600,"lines":[{"gurmukhi":"ਕਹਿਯੋ ਨ ਮਾਨੈ ਭੂਪ ਜਬ ਤਬ ਬ੍ਰਹਮੇ ਕਹ ਕੀਨ।","roman":"Kahiyo na maanai bhoop jab tab brahme kah keen |","meaning_en":"","page":600},{"gurmukhi":"ਨਾਰਦ ਕੋ ਸਿਮਰਨਿ ਕੀਓ ਮੁਨਿ ਆਯੋ ਪਰਬੀਨ। ੧੬੯੨।","roman":"Naarad ko simarni keeo muni aayo parbeen | 1692 |","meaning_en":"","page":600}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":600},{"type":"verse","number":[1693],"number_text":"੧੬੯੩।","page":600,"lines":[{"gurmukhi":"ਤਬ ਹੀ ਮੁਨਿ ਨਾਰਦ ਆਇ ਗਯੋ ਤਿਹ ਭੂਪਤਿ ਕੋ ਇਕ ਬੈਨ ਸੁਨਾਯੋ।","roman":"Tab hee muni naarad aai gayo tih bhoopti ko ik bain sunaayo |","meaning_en":"","page":600},{"gurmukhi":"ਚਉਦਹ ਲੋਕਨ ਬੀਚ ਕਹਿਯੋ ਪ੍ਰਭਿ ਤੋ ਸਮ ਰਾਜ ਨ ਕੋਊ ਬਨਾਯੋ।","roman":"Chaudah lokan beech kahiyo prabhi to sam raaj na ko'oo banaayo |","meaning_en":"","page":600},{"gurmukhi":"ਤਾਹੀ ਤੇ ਬੀਰਨ ਕੀ ਮਨਿ ਤੈ ਸੁ ਭਲੋ ਕੀਯੋ ਸ੍ਯਾਮ ਸੋ ਜੁਧ ਮਚਾਯੋ।","roman":"Taahee te beeran kee mani tai su bhalo keeyo syaam so judh machaayo |","meaning_en":"","page":600},{"gurmukhi":"ਸ੍ਯਾਮ ਕਹੈ ਮੁਨਿ ਕੀ ਬਤੀਆ ਸੁਨਿ ਭੂਪ ਘਨੋ ਮਨ ਮੈ ਸੁਖੁ ਪਾਯੋ। ੧੬੯੩।","roman":"Syaam kahai muni kee bateeaa suni bhoop ghano man mai sukhu paayo | 1693 |","meaning_en":"","page":600}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":600},{"type":"verse","number":[1694],"number_text":"੧੬੯੪।","page":600,"lines":[{"gurmukhi":"ਅਭਿਬੰਦਨ ਭੂਪਤਿ ਕੀਯੋ ਨਾਰਦ ਕੋ ਪਹਿਚਾਨਿ।","roman":"Abhibandan bhoopti keeyo naarad ko pahichaani |","meaning_en":"","page":600},{"gurmukhi":"ਮੁਨਿ ਪਤਿ ਇਹ ਉਪਦੇਸ ਦੀਆ ਜੁਧ ਕਰੋ ਬਲਵਾਨ। ੧੬੯੪।","roman":"Muni pati ih updes deeaa judh karo balvaan | 1694 |","meaning_en":"","page":600}]},{"type":"verse","number":[1695],"number_text":"੧੬੯੫।","page":601,"lines":[{"gurmukhi":"ਇਤ ਭੂਪਤਿ ਨਾਰਦ ਮਿਲੇ ਪ੍ਰੇਮੁ ਭਗਤਿ ਕੀ ਖਾਨ।","roman":"It bhoopti naarad mile premu bhagti kee khaan |","meaning_en":"","page":601},{"gurmukhi":"ਉਤ ਮਹੇਸ ਚਲਿ ਤਹ ਗਏ ਜਹ ਠਾਢੇ ਭਗਵਾਨ। ੧੬੯੫।","roman":"Ut mahes chali tah gae jah thaadhe bhagvaan | 1695 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":601},{"type":"verse","number":[1696],"number_text":"੧੬੯੬।","page":601,"lines":[{"gurmukhi":"ਇਤੇ ਰੁਦ੍ਰ ਮਨਿ ਮੰਤ੍ਰ ਬਿਚਾਰਿਓ। ਸ੍ਰੀ ਜਦੁਪਤਿ ਕੇ ਨਿਕਟਿ ਉਚਾਰਿਓ।","roman":"Ite rudr mani mantr bichaario | sree jadupti ke nikti uchaario |","meaning_en":"","page":601},{"gurmukhi":"ਅਬ ਹੀ ਮ੍ਰਿਤਹਿ ਆਇਸ ਦੀਜੈ। ਤਬ ਇਹ ਭੂਪ ਮਾਰਿ ਕੈ ਲੀਜੈ। ੧੬੯੬।","roman":"Ab hee mrithi aais deejai | tab ih bhoop maari kai leejai | 1696 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":601},{"type":"verse","number":[1697],"number_text":"੧੬੯੭।","page":601,"lines":[{"gurmukhi":"ਸਰ ਅਪਨੇ ਮੈ ਮ੍ਰਿਤੁ ਧਰਿ ਇਹ ਤੁਮ ਕਰਹੁ ਉਪਾਇ।","roman":"Sar apne mai mritu dhari ih tum karhu upaai |","meaning_en":"","page":601},{"gurmukhi":"ਅਬ ਕਸਿ ਕੈ ਧਨੁ ਛਾਡੀਏ ਭੂਲੇ ਬਡਿ ਅਨਿਆਇ। ੧੬੯੭।","roman":"Ab kasi kai dhanu chhaadee'e bhoole badi aniaai | 1697 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":601},{"type":"verse","number":[1698],"number_text":"੧੬੯੮।","page":601,"lines":[{"gurmukhi":"ਸੋਈ ਕਾਮ ਸ੍ਯਾਮ ਜੂ ਕੀਨੋ। ਜਿਹ ਬਿਧਿ ਸੋ ਸਿਵ ਜੂ ਕਹਿ ਦੀਨੋ।","roman":"Soee kaam syaam joo keeno | jih bidhi so siv joo kahi deeno |","meaning_en":"","page":601},{"gurmukhi":"ਤਬ ਚਿਤਵਨ ਹਰਿ ਮ੍ਰਿਤ ਕੋ ਕੀਯੋ। ਮੀਚ ਆਇ ਕੈ ਦਰਸਨੁ ਦੀਯੋ। ੧੬੯੮।","roman":"Tab chitvan hari mrit ko keeyo | meech aai kai darasnu deeyo | 1698 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":601},{"type":"verse","number":[1699],"number_text":"੧੬੯੯।","page":601,"lines":[{"gurmukhi":"ਕਹਿਓ ਮ੍ਰਿਤ ਕੋ ਕ੍ਰਿਸਨ ਜੂ ਮੋ ਸਰ ਮੈ ਕਰ ਬਾਸੁ।","roman":"Kahio mrit ko krisan joo mo sar mai kar baasu |","meaning_en":"","page":601},{"gurmukhi":"ਅਬ ਛਾਡਤ ਹੋ ਸਤ੍ਰ ਪੈ ਜਾਇ ਕਰਹੁ ਤਿਹ ਨਾਸੁ। ੧੬੯੯।","roman":"Ab chhaadat ho satr pai jaai karhu tih naasu | 1699 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":601},{"type":"verse","number":[1700],"number_text":"੧੭੦੦।","page":601,"lines":[{"gurmukhi":"ਦੇਵ ਬਧੂਨ ਕੈ ਨੈਨ ਕਟਾਛ ਬਿਲੋਕਤ ਹੀ ਨ੍ਰਿਪ ਚਿਤ ਲੁਭਾਯੋ।","roman":"Dev badhoon kai nain kataachh bilokat hee nrip chit lubhaayo |","meaning_en":"","page":601},{"gurmukhi":"ਨਾਰਦ ਬ੍ਰਹਮ ਦੁਹੂੰ ਮਿਲ ਕੈ ਰਨ ਮੈ ਸੰਗਿ ਬਾਤਨ ਕੇ ਉਰਝਾਯੋ।","roman":"Naarad braham duhoon mil kai ran mai sangi baatan ke urjhaayo |","meaning_en":"","page":601},{"gurmukhi":"ਸ੍ਯਾਮ ਤਬੈ ਲਖਿ ਘਾਤ ਭਲੀ ਅਰਿ ਮਾਰਨ ਕੋ ਮ੍ਰਿਤ ਬਾਨ ਚਲਾਯੋ।","roman":"Syaam tabai lakhi ghaat bhalee ari maaran ko mrit baan chalaayo |","meaning_en":"","page":601},{"gurmukhi":"ਮੰਤ੍ਰਨਿ ਕੇ ਬਲ ਸੋ ਛਲ ਸੋ ਤਬ ਭੂਪਤਿ ਕੋ ਸਿਰੁ ਕਾਟਿ ਗਿਰਾਯੋ। ੧੭੦੦।","roman":"Mantrani ke bal so chhal so tab bhoopti ko siru kaati giraayo | 1700 |","meaning_en":"","page":601}]},{"type":"verse","number":[1701],"number_text":"੧੭੦੧।","page":601,"lines":[{"gurmukhi":"ਜਦਿਪਿ ਸੀਸ ਕਟਿਓ ਨ ਹਟਿਓ ਗਹਿ ਕੇਸਨਿ ਤੇ ਹਰਿ ਓਰਿ ਚਲਾਯੋ।","roman":"Jadipi sees katio na hatio gahi kesni te hari ori chalaayo |","meaning_en":"","page":601},{"gurmukhi":"ਮਾਨਹੁ ਪ੍ਰਾਨ ਚਲਿਯੋ ਦਿਵਿ ਆਨਨ ਕਾਜ ਬਿਦਾ ਬ੍ਰਿਜਰਾਜ ਪੈ ਆਯੋ।","roman":"Maanhu praan chaliyo divi aanan kaaj bidaa brijraaj pai aayo |","meaning_en":"","page":601},{"gurmukhi":"ਸੋ ਸਿਰੁ ਲਾਗ ਗਯੋ ਹਰਿ ਕੇ ਉਰਿ ਮੂਰਛ ਹ੍ਵੈ ਪਗੁ ਨ ਠਹਰਾਯੋ।","roman":"So siru laag gayo hari ke uri moorachh hvai pagu na thahraayo |","meaning_en":"","page":601},{"gurmukhi":"ਦੇਖਹੁ ਪਉਰਖ ਭੂਪ ਕੇ ਮੁੰਡ ਕੋ ਸ੍ਯੰਦਨ ਤੇ ਪ੍ਰਭੁ ਭੂਮਿ ਗਿਰਾਯੋ। ੧੭੦੧।","roman":"Dekhhu paurakh bhoop ke mund ko syandan te prabhu bhoomi giraayo | 1701 |","meaning_en":"","page":601}]},{"type":"verse","number":[1702],"number_text":"੧੭੦੨।","page":601,"lines":[{"gurmukhi":"ਭੂਪਤ ਜੈਸੋ ਸੁ ਪੌਰਖ ਕੀਨੋ ਹੈ ਤੈਸੀ ਕਰੀ ਨ ਕਿਸੀ ਕਰਨੀ।","roman":"Bhoopat jaiso su paurakh keeno hai taisee karee na kisee karnee |","meaning_en":"","page":601},{"gurmukhi":"ਲਖਿ ਜਛਨਿ ਕਿਨਰੀ ਰੀਝ ਰਹੀ ਨਭ ਮੈ ਸਭ ਦੇਵਨ ਕੀ ਘਰਨੀ।","roman":"Lakhi jachhni kinree reejh rahee nabh mai sabh devan kee gharnee |","meaning_en":"","page":601},{"gurmukhi":"ਮ੍ਰਿਦ ਬਾਜਤ ਬੀਨ ਮ੍ਰਿਦੰਗ ਉਪੰਗ ਮੁਚੰਗ ਲੀਏ ਉਤਰੀ ਧਰਨੀ।","roman":"Mrid baajat been mridang upang muchang lee'e utree dharnee |","meaning_en":"","page":601},{"gurmukhi":"ਨਭ ਨਾਚਤ ਗਾਵਤ ਰੀਝਿ ਰਿਝਾਵਤ ਯੌ ਉਪਮਾ ਕਬਿ ਨ ਬਰਨੀ। ੧੭੦੨।","roman":"Nabh naachat gaavat reejhi rijhaavat yau upmaa kabi na barnee | 1702 |","meaning_en":"","page":601}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":602},{"type":"verse","number":[1703],"number_text":"੧੭੦੩।","page":602,"lines":[{"gurmukhi":"ਨਭ ਤੇ ਉਤਰੀ ਸੁੰਦਰੀ ਸਕਲ ਲੀਏ ਸੁਰ ਸਾਜ।","roman":"Nabh te utree sundree sakal lee'e sur saaj |","meaning_en":"","page":602},{"gurmukhi":"ਕਵਨ ਹੇਤ ਕਬਿ ਸ੍ਯਾਮ ਕਹਿ ਭੂਪਤਿ ਬਰਬੇ ਕਾਜ। ੧੭੦੩।","roman":"Kavan het kabi syaam kahi bhoopti barbe kaaj | 1703 |","meaning_en":"","page":602}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":602},{"type":"verse","number":[1704],"number_text":"੧੭੦੪।","page":602,"lines":[{"gurmukhi":"ਮੁੰਡ ਬਿਨਾ ਤਬ ਰੁੰਡ ਸੁ ਭੂਪਤਿ ਕੋ ਚਿਤ ਮੈ ਅਤਿ ਕੋਪ ਬਢਾਯੋ।","roman":"Mund binaa tab rund su bhoopti ko chit mai ati kop badhaayo |","meaning_en":"","page":602},{"gurmukhi":"ਦ੍ਵਾਦਸ ਭਾਨੁ ਜੁ ਠਾਢੇ ਹੁਤੇ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਤਿਹ ਊਪਰਿ ਧਾਯੋ।","roman":"Dvaadas bhaanu ju thaadhe hute kabi syaam kahai tih oopri dhaayo |","meaning_en":"","page":602},{"gurmukhi":"ਭਾਜਿ ਗਏ ਕਰਿ ਤ੍ਰਾਸ ਸੋਊ ਸਿਵ ਠਾਢੋ ਰਹਿਯੋ ਤਿਹ ਊਪਰ ਆਯੋ।","roman":"Bhaaji gae kari traas so'oo siv thaadho rahiyo tih oopar aayo |","meaning_en":"","page":602},{"gurmukhi":"ਸੋ ਨ੍ਰਿਪ ਬੀਰ ਮਹਾ ਰਨਧੀਰ ਚਟਾਕਿ ਚਪੇਟ ਦੈ ਭੂਮਿ ਗਿਰਾਯੋ। ੧੭੦੪।","roman":"So nrip beer mahaa randheer chataaki chapet dai bhoomi giraayo | 1704 |","meaning_en":"","page":602}]},{"type":"verse","number":[1705],"number_text":"੧੭੦੫।","page":602,"lines":[{"gurmukhi":"ਏਕਨ ਮਾਰਿ ਚਪੇਟਨ ਸਿਉ ਅਰੁ ਏਕਨ ਕੋ ਧਮਕਾਰ ਗਿਰਾਵੈ।","roman":"Ekan maari chapetan siu aru ekan ko dhamkaar giraavai |","meaning_en":"","page":602},{"gurmukhi":"ਚੀਰ ਕੈ ਏਕਨਿ ਡਾਰਿ ਦਏ ਗਹਿ ਏਕਨ ਕੋ ਨਭਿ ਓਰਿ ਚਲਾਵੈ।","roman":"Cheer kai ekni daari dae gahi ekan ko nabhi ori chalaavai |","meaning_en":"","page":602},{"gurmukhi":"ਬਾਜ ਸਿਉ ਬਾਜਨ ਲੈ ਰਥ ਸਿਉ ਰਥ ਅਉ ਗਜ ਸਿਉ ਗਜਰਾਜ ਬਜਾਵੈ।","roman":"Baaj siu baajan lai rath siu rath au gaj siu gajraaj bajaavai |","meaning_en":"","page":602},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੈ ਰਨ ਯਾ ਬਿਧਿ ਭੂਪਤਿ ਸਤ੍ਰਨਿ ਕੋ ਜਮ ਧਾਮਿ ਪਠਾਵੈ। ੧੭੦੫।","roman":"Syaam bhanai ran yaa bidhi bhoopti satrani ko jam dhaami pathaavai | 1705 |","meaning_en":"","page":602}]},{"type":"verse","number":[1706],"number_text":"੧੭੦੬।","page":602,"lines":[{"gurmukhi":"ਹ੍ਵੈ ਕੈ ਸੁਚੇਤ ਚਢਿਯੋ ਰਥਿ ਸ੍ਯਾਮ ਮਹਾ ਮਨ ਭੀਤਰ ਕੋਪ ਬਢਿਯੋ ਹੈ।","roman":"Hvai kai suchet chadhiyo rathi syaam mahaa man bheetar kop badhiyo hai |","meaning_en":"","page":602},{"gurmukhi":"ਆਪਨ ਪਉਰਖ ਸੋਊ ਸੰਭਾਰ ਕੈ ਮ੍ਯਾਨਹੁ ਤੇ ਕਰਵਾਰਿ ਕਢਿਯੋ ਹੈ।","roman":"Aapan paurakh so'oo sanbhaar kai myaanhu te karvaari kadhiyo hai |","meaning_en":"","page":602},{"gurmukhi":"ਧਾਇ ਪਰੇ ਰਿਸ ਖਾਇ ਘਨੀ ਅਰਿਰਾਇ ਮਨੋ ਨਿਧਿ ਨੀਰ ਹਢਿਯੋ ਹੈ।","roman":"Dhaai pare ris khaai ghanee ariraai mano nidhi neer hadhiyo hai |","meaning_en":"","page":602},{"gurmukhi":"ਤਾਨਿ ਕਮਾਨਨਿ ਮਾਰਤ ਬਾਨਨ ਸੂਰਨ ਕੇ ਚਿਤ ਚਉਪ ਚਢਿਯੋ ਹੈ। ੧੭੦੬।","roman":"Taani kamaanni maarat baanan sooran ke chit chaup chadhiyo hai | 1706 |","meaning_en":"","page":602}]},{"type":"verse","number":[1707],"number_text":"੧੭੦੭।","page":602,"lines":[{"gurmukhi":"ਬੀਰਨ ਘਾਇ ਕਰੇ ਜਬ ਹੀ ਤਬ ਪਉਰਖ ਭੂਪ ਕਬੰਧ ਸਮਾਰਿਓ।","roman":"Beeran ghaai kare jab hee tab paurakh bhoop kabandh samaario |","meaning_en":"","page":602},{"gurmukhi":"ਸਸਤ੍ਰ ਸੰਭਾਰ ਤਬੈ ਅਪੁਨੇ ਇਨ ਨਾਸੁ ਕਰੋ ਚਿਤ ਬੀਚ ਬਿਚਾਰਿਓ।","roman":"Sasatr sanbhaar tabai apune in naasu karo chit beech bichaario |","meaning_en":"","page":602},{"gurmukhi":"ਧਾਇ ਪਰਿਓ ਰਿਸਿ ਸਿਉ ਰਨ ਮੈ ਅਰਿ ਭਾਜਿ ਗਏ ਜਸੁ ਰਾਮ ਉਚਾਰਿਓ।","roman":"Dhaai pario risi siu ran mai ari bhaaji gae jasu raam uchaario |","meaning_en":"","page":602},{"gurmukhi":"ਤਾਰਨ ਕੋ ਮਨੋ ਮੰਡਲ ਭੀਤਰ ਸੂਰ ਚਢਿਓ ਅੰਧਿਆਰਿ ਸਿਧਾਰਿਓ। ੧੭੦੭।","roman":"Taaran ko mano mandal bheetar soor chadhio andhiaari sidhaario | 1707 |","meaning_en":"","page":602}]},{"type":"verse","number":[1708],"number_text":"੧੭੦੮।","page":602,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਤੇ ਆਦਿਕ ਬੀਰ ਗਏ ਭਜਿ ਕੈ ਨ ਕੋਊ ਠਹਿਰਾਨਿਓ।","roman":"Sree jadubeer te aadik beer gae bhaji kai na ko'oo thahiraanio |","meaning_en":"","page":602},{"gurmukhi":"ਆਹਵ ਭੂਮਿ ਮੈ ਭੂਪਤਿ ਕੋ ਸਬ ਸੂਰਨ ਮਾਨਹੁ ਕਾਲ ਪਛਾਨਿਓ।","roman":"Aahav bhoomi mai bhoopti ko sab sooran maanhu kaal pachhaanio |","meaning_en":"","page":602},{"gurmukhi":"ਭੂਪ ਕਮਾਨ ਤੇ ਬਾਨ ਚਲੇ ਮਨੋ ਅੰਤਿ ਪ੍ਰਲੈ ਘਨ ਸਿਉ ਬਰਖਾਨਿਓ।","roman":"Bhoop kamaan te baan chale mano anti pralai ghan siu barkhaanio |","meaning_en":"","page":602},{"gurmukhi":"ਇਉ ਲਖਿ ਭਾਜਿ ਗਏ ਸਿਗਰੇ ਕਿਨਹੂੰ ਨ੍ਰਿਪ ਕੇ ਸੰਗ ਜੁਧੁ ਨ ਠਾਨਿਓ। ੧੭੦੮।","roman":"Iu lakhi bhaaji gae sigre kinhoon nrip ke sang judhu na thaanio | 1708 |","meaning_en":"","page":602}]},{"type":"verse","number":[1709],"number_text":"੧੭੦੯।","page":602,"lines":[{"gurmukhi":"ਸਬ ਹੀ ਭਟ ਭਾਜਿ ਗਏ ਜਬ ਹੀ ਪ੍ਰਭ ਕੋ ਤਬ ਭੂਪ ਭਯੋ ਅਨੁਰਾਗੀ।","roman":"Sab hee bhat bhaaji gae jab hee prabh ko tab bhoop bhayo anuraagee |","meaning_en":"","page":602},{"gurmukhi":"ਜੂਝ ਤਬੈ ਤਿਨ ਛਾਡਿ ਦਯੋ ਹਰਿ ਧਿਆਨ ਕੀ ਤਾਹਿ ਸਮਾਧਿ ਸੀ ਲਾਗੀ।","roman":"Joojh tabai tin chhaadi dayo hari dhiaan kee taahi samaadhi see laagee |","meaning_en":"","page":602},{"gurmukhi":"ਰਾਜ ਨ ਰਾਜ ਸਮਾਜ ਬਿਖੈ ਕਬਿ ਸ੍ਯਾਮ ਕਹੈ ਹਰਿ ਮੈ ਮਤਿ ਪਾਗੀ।","roman":"Raaj na raaj samaaj bikhai kabi syaam kahai hari mai mati paagee |","meaning_en":"","page":602},{"gurmukhi":"ਧੀਰ ਗਹਿਓ ਧਰਿ ਠਾਢੋ ਰਹਿਓ ਕਹੋ ਭੂਪਤਿ ਤੇ ਅਬ ਕੋ ਬਡਭਾਗੀ। ੧੭੦੯।","roman":"Dheer gahio dhari thaadho rahio kaho bhoopti te ab ko badbhaagee | 1709 |","meaning_en":"","page":602}]},{"type":"verse","number":[1710],"number_text":"੧੭੧੦।","page":603,"lines":[{"gurmukhi":"ਸ੍ਰੀ ਜਦੁਬੀਰ ਕੋ ਬੀਰ ਸਭੋ ਧਰਿ ਡਾਰਨਿ ਕੋ ਜਬ ਘਾਤ ਬਨਾਯੋ।","roman":"Sree jadubeer ko beer sabho dhari daarni ko jab ghaat banaayo |","meaning_en":"","page":603},{"gurmukhi":"ਸ੍ਯਾਮ ਭਨੇ ਮਿਲਿ ਕੈ ਫਿਰਿ ਕੈ ਇਹ ਪੈ ਪੁਨਿ ਬਾਨਨਿ ਓਘ ਚਲਾਯੋ।","roman":"Syaam bhane mili kai phiri kai ih pai puni baanni ogh chalaayo |","meaning_en":"","page":603},{"gurmukhi":"ਦੇਵਬਧੂ ਮਿਲ ਕੈ ਸਬਹੂੰ ਇਹ ਭੂਪ ਕਬੰਧ ਬਿਵਾਨਿ ਚਢਾਯੋ।","roman":"Devabdhoo mil kai sabhoon ih bhoop kabandh bivaani chadhaayo |","meaning_en":"","page":603},{"gurmukhi":"ਕੂਦ ਪਰਿਓ ਨ ਬਿਵਾਨਿ ਚਢਿਯੋ ਪੁਨਿ ਸਸਤ੍ਰ ਲੀਏ ਰਨ ਭੂ ਮਧਿ ਆਯੋ। ੧੭੧੦।","roman":"Kood pario na bivaani chadhiyo puni sasatr lee'e ran bhoo madhi aayo | 1710 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":603},{"type":"verse","number":[1711],"number_text":"੧੭੧੧।","page":603,"lines":[{"gurmukhi":"ਧਨੁਖ ਬਾਨ ਲੈ ਪਾਨ ਮੈ ਆਨਿ ਪਰਿਓ ਰਨ ਬੀਚ।","roman":"Dhanukh baan lai paan mai aani pario ran beech |","meaning_en":"","page":603},{"gurmukhi":"ਸੂਰਬੀਰ ਬਹੁ ਬਿਧਿ ਹਨੇ ਲਲਕਾਰਿਯੋ ਤਬ ਮੀਚ। ੧੭੧੧।","roman":"Soorbeer bahu bidhi hane lalkaariyo tab meech | 1711 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"","page":603},{"type":"verse","number":[1712],"number_text":"੧੭੧੨।","page":603,"lines":[{"gurmukhi":"ਅੰਤਕ ਜਮ ਜਬ ਲੈਨੇ ਆਵੈ। ਲਖਿ ਤਿਹ ਕੋ ਤਬ ਬਾਨ ਚਲਾਵੈ।","roman":"Antak jam jab laine aavai | lakhi tih ko tab baan chalaavai |","meaning_en":"","page":603},{"gurmukhi":"ਮ੍ਰਿਤੁ ਪੇਖ ਕੈ ਇਤ ਉਤ ਟਰੈ। ਮਾਰਿਓ ਕਾਲ ਹੂੰ ਕੋ ਨਹੀ ਮਰੈ। ੧੭੧੨।","roman":"Mritu pekh kai it ut tarai | maario kaal hoon ko nahee marai | 1712 |","meaning_en":"","page":603}]},{"type":"verse","number":[1713],"number_text":"੧੭੧੩।","page":603,"lines":[{"gurmukhi":"ਪੁਨਿ ਸਤ੍ਰਨਿ ਦਿਸਿ ਰਿਸਿ ਕਰਿ ਧਾਯੋ। ਮਾਨਹੁ ਜਮ ਮੂਰਤਿ ਧਰਿ ਆਯੋ।","roman":"Puni satrani disi risi kari dhaayo | maanhu jam moorti dhari aayo |","meaning_en":"","page":603},{"gurmukhi":"ਇਉ ਸੁ ਜੁਧੁ ਬੈਰਿਨ ਸੰਗਿ ਕਰਿਓ। ਹਰਿ ਹਰ ਬਿਧਿ ਸੁਭਟਨਿ ਮਨੁ ਡਰਿਓ। ੧੭੧੩।","roman":"Iu su judhu bairin sangi kario | hari har bidhi subhatni manu dario | 1713 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":603},{"type":"verse","number":[1714],"number_text":"੧੭੧੪।","page":603,"lines":[{"gurmukhi":"ਹਾਰਿ ਪਰੈ ਮਨੁਹਾਰਿ ਕਰੈ ਕਹੈ ਇਉ ਨ੍ਰਿਪ ਜੁਧ ਬ੍ਰਿਥਾ ਨ ਕਰਈਯੈ।","roman":"Haari parai manuhaari karai kahai iu nrip judh brithaa na karaeeyai |","meaning_en":"","page":603},{"gurmukhi":"ਡਾਰਿ ਦੈ ਹਾਥਨ ਤੇ ਹਥੀਆਰਨ ਕੋਪ ਤਜੋ ਸੁਖ ਸਾਤਿ ਸਮਈਯੈ।","roman":"Daari dai haathan te hatheeaaran kop tajo sukh saati samaeeyai |","meaning_en":"","page":603},{"gurmukhi":"ਸੂਰ ਨ ਕੋਊ ਭਯੋ ਤੁਮਰੇ ਸਮ ਤੇਰੋ ਪ੍ਰਤਾਪ ਤਿਹੂੰ ਪੁਰਿ ਗਈਯੈ।","roman":"Soor na ko'oo bhayo tumre sam tero prataap tihoon puri gaeeyai |","meaning_en":"","page":603},{"gurmukhi":"ਛਾਡਤਿ ਹੈ ਹਮ ਸਸਤ੍ਰ ਸਬੈ ਸੁ ਬਿਵਾਨ ਚਢੋ ਸੁਰ ਧਾਮਿ ਸਿਧਈਯੈ। ੧੭੧੪।","roman":"Chhaadti hai ham sasatr sabai su bivaan chadho sur dhaami sidhaeeyai | 1714 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"","page":603},{"type":"verse","number":[1715],"number_text":"੧੭੧੫।","page":603,"lines":[{"gurmukhi":"ਸਬ ਦੇਵਨ ਅਰੁ ਕ੍ਰਿਸਨ ਦੀਨ ਹ੍ਵੈ ਜਬ ਕਹਿਓ।","roman":"Sab devan aru krisan deen hvai jab kahio |","meaning_en":"","page":603},{"gurmukhi":"ਹਟੋ ਜੁਧ ਤੇ ਭੂਪ ਹਮੋ ਮੁਖਿ ਤ੍ਰਿਨ ਗਹਿਓ।","roman":"Hato judh te bhoop hamo mukhi trin gahio |","meaning_en":"","page":603},{"gurmukhi":"ਨ੍ਰਿਪ ਸੁਨਿ ਆਤੁਰ ਬੈਨ ਸੁ ਕੋਪੁ ਨਿਵਾਰਿਓ।","roman":"Nrip suni aatur bain su kopu nivaario |","meaning_en":"","page":603},{"gurmukhi":"ਹੋ ਧਨੁਖ ਬਾਨ ਦਿਓ ਡਾਰਿ ਰਾਮ ਮਨੁ ਧਾਰਿਓ। ੧੭੧੫।","roman":"Ho dhanukh baan dio daari raam manu dhaario | 1715 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"","page":603},{"type":"verse","number":[1716],"number_text":"੧੭੧੬।","page":603,"lines":[{"gurmukhi":"ਕਿੰਨਰ ਜਛ ਅਪਛਰਨਿ ਲਯੋ ਬਿਵਾਨ ਚਢਾਇ।","roman":"Kinnar jachh apchharni layo bivaan chadhaai |","meaning_en":"","page":603},{"gurmukhi":"ਜੈ ਜੈ ਕਾਰ ਅਪਾਰ ਸੁਨਿ ਹਰਖੇ ਮੁਨਿ ਸੁਰ ਰਾਇ। ੧੭੧੬।","roman":"Jai jai kaar apaar suni harkhe muni sur raai | 1716 |","meaning_en":"","page":603}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"","page":603},{"type":"verse","number":[1717],"number_text":"੧੭੧੭।","page":603,"lines":[{"gurmukhi":"ਭੂਪ ਗਯੋ ਸੁਰਲੋਕਿ ਜਬੈ ਤਬ ਸੂਰ ਪ੍ਰਸੰਨਿ ਭਏ ਸਬ ਹੀ।","roman":"Bhoop gayo surloki jabai tab soor prasanni bhae sab hee |","meaning_en":"","page":603},{"gurmukhi":"ਇਹ ਭਾਤ ਕਹੈ ਰਨੁ ਮੈ ਸਿਗਰੇ ਮੁਖਿ ਕਾਲ ਕੇ ਜਾਇ ਬਚੇ ਅਬ ਹੀ।","roman":"Ih bhaat kahai ranu mai sigre mukhi kaal ke jaai bache ab hee |","meaning_en":"","page":603},{"gurmukhi":"ਸਸਿ ਭਾਨੁ ਧਨਾਧਿਪ ਰੁਦ੍ਰ ਬਿਰੰਚ ਸਬੈ ਹਰਿ ਤੀਰ ਗਏ ਜਬ ਹੀ।","roman":"Sasi bhaanu dhanaadhip rudr biranch sabai hari teer gae jab hee |","meaning_en":"","page":604},{"gurmukhi":"ਹਰਖੇ ਬਰਖੇ ਨਭ ਤੇ ਸੁਰ ਫੂਲ ਸੁ ਜੀਤ ਕੀ ਬੰਬ ਬਜੀ ਤਬ ਹੀ। ੧੭੧੭।","roman":"Harkhe barkhe nabh te sur phool su jeet kee banb bajee tab hee | 1717 |","meaning_en":"","page":604}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਬਚਿਤ੍ਰ ਨਾਟਕ ਗ੍ਰੰਥੇ ਕ੍ਰਿਸਨਾਵਤਾਰੇ ਜੁਧ ਪ੍ਰਬੰਧੇ ਖੜਗ ਸਿੰਘ","roman":"Iti sree bachitr naatak granthe krisnaavtaare judh prabandhe kharag singh","meaning_en":"","page":604},{"gurmukhi":"ਬਧਹਿ ਧਿਆਇ ਸਮਾਪਤੰ।","roman":"Badhhi dhiaai samaaptan |","meaning_en":"","page":604}],"page":604}});
